    ~Impl() override
    {
        stopTimer();
        if (browserScan) browserScan->cancelled.store (true);
        browserScan.reset();
        session.removeChangeListener (this);
        session.knownPlugins().removeChangeListener (this);
        session.closePluginEditors();
        for (auto& window : automationWindows) if (window != nullptr) delete window.getComponent();
        if (preferencesWindow != nullptr) delete preferencesWindow.getComponent();
        if (undoHistoryWindow != nullptr) delete undoHistoryWindow.getComponent();
        for (auto& dialog : dialogs) if (dialog != nullptr) delete dialog.getComponent();
        for (auto& alert : alerts) if (alert != nullptr) delete alert.getComponent();
       #if JUCE_MAC
        juce::MenuBarModel::setMacMainMenu (nullptr);
       #endif
        browserList.setModel (nullptr);
        horizontalScroll.removeListener (this);
        viewport.setViewedComponent (nullptr, false);
        setLookAndFeel (nullptr);
    }

    void paint (juce::Graphics& g) override
    {
        g.fillAll (background);
        g.setColour (panel);
        g.fillRect (browserBounds);
        g.fillRect (toolbarBounds);
        g.setColour (line);
        g.drawHorizontalLine (toolbarBounds.getBottom(), 0.0f, (float) getWidth());
        g.drawVerticalLine (browserBounds.getRight(), (float) browserBounds.getY(), (float) browserBounds.getBottom());
        g.setColour (themes::colour (0xff121212)); g.fillRect (dividerBounds);
        // Control bar: tempo/meter on the left, transport and loop in the centre, status on the right.
        g.setFont (font (11.0f));
        g.setColour (muted); g.setFont (font (10.0f));
        g.drawText ("CPU " + juce::String (juce::roundToInt (state.cpu * 100.0)) + "%", cpuBounds, juce::Justification::centredRight);
        g.setFont (font (10.0f, true)); g.setColour (muted);
        const auto indexText = mapping() ? juce::String() : browserIndexText();
        const int indexWidth = indexText.isEmpty() ? 0 : 118;
        if (! mapping()) // The mapping list replaces the browser in MIDI and Key Map Modes.
        g.drawText (browserCategory == BrowserCategory::instruments ? "INSTRUMENTS" : browserCategory == BrowserCategory::audioEffects ? "AUDIO EFFECTS"
                        : browserCategory == BrowserCategory::midiEffects ? "MIDI EFFECTS" : pluginBrowser() ? "PLUG-INS"
                        : browserCategory == BrowserCategory::grooves ? "GROOVES" : browserCategory == BrowserCategory::templates ? "TEMPLATES" : browserCategory == BrowserCategory::packs ? "PACKS"
                        : browserCategory == BrowserCategory::place && similarFile == juce::File() && browserFolder == browserPlaceRoot ? placeName (browserPlace).toUpperCase()
                        : browserFolder == juce::File() ? "SAMPLES"
                        : similarFile != juce::File() ? "SIMILAR TO " + similarFile.getFileNameWithoutExtension().toUpperCase() : browserFolder.getFileName().toUpperCase(),
                    browserList.getX() + 4, browserList.getY() - 22, browserList.getWidth() - 8 - indexWidth, 20, juce::Justification::centredLeft, true);
        if (indexWidth > 0)
        {
            g.setFont (font (10.0f));
            g.drawText (indexText, browserList.getRight() - 4 - indexWidth, browserList.getY() - 22, indexWidth, 20, juce::Justification::centredRight, true);
            g.setFont (font (10.0f, true));
        }
        if (! mapping() && (pluginBrowser() || sampleBrowser() || browserCategory == BrowserCategory::packs || browserCategory == BrowserCategory::templates) && getNumRows() == 0)
        {
            g.setFont (font (12.0f));
            juce::String message;
            if (pluginBrowser()) message = "No scanned plug-ins.\nUse Manage to scan your\nAudio Units and VST3 library.";
            else if (browserCategory == BrowserCategory::packs) message = "No packs installed.\nInstall one with\nFile > Install Pack...";
            else if (browserCategory == BrowserCategory::templates) message = "No templates yet.\nSave one with\nFile > Save as Template...";
            else if (browserCategory == BrowserCategory::place && browserPlace == currentProjectPlace && ! projectMediaThere)
                message = "This project has no audio\nfiles yet. Its recordings\nand saved media show here.";
            else if (browserCategory == BrowserCategory::place && ! placeAvailable (browserPlace))
                message = "This folder has moved or is\nnot connected. Right-click it\nin Places to locate it, or\nremove it from the sidebar.";
            else if (browserFolder == juce::File()) message = "Choose an audio folder,\nor import audio to begin.\nYou can also drop files\ninto the arrangement.";
            else if (browserError.isNotEmpty()) message = "Cannot read this folder.\n" + browserError;
            else if (browserLoading)
                message = juce::Time::getMillisecondCounterHiRes() - browserScanStarted > 5000.0
                    ? "This folder is taking longer\nto respond. You can choose\nanother folder to continue."
                    : "Loading audio folder...";
            else if (browserSearch.getText().isNotEmpty() && shownIndex.indexing) message = "Searching this folder and\nthe folders in it...";
            else message = browserSearch.getText().isEmpty() ? "No audio files here.\nChoose another folder or drag\naudio into the arrangement." : "No matching audio files here\nor in the folders in it.\nTry another search.";
            g.drawFittedText (message, browserList.getBounds().reduced (14).withHeight (150), juce::Justification::centred, 7);
        }
        g.setColour (line);
        g.drawHorizontalLine (getHeight() - statusHeight, 0.0f, (float) getWidth());
        g.setColour (muted);
        g.setFont (font (10.5f));
        auto message = status.isNotEmpty() ? status
            : showPiano && drawMode ? "Draw Mode: drag to draw notes    Alt: one pitch    Click a note: delete    B: leave Draw Mode"
            : showPiano ? "Double-click: add or delete a note    Drag: select    Shift: add to the selection    Ruler: insertion point    B: Draw Mode" : "Space: play / pause     Click ruler: seek     Shift-drag ruler: loop     Double-click MIDI clip: edit notes";
        if (status.isEmpty() && showSession && ! showPiano) message = "Click triangle: launch     Double-click MIDI slot: edit     Enter: launch slot     Shift+Enter: launch scene     Tab: switch view";
        g.drawText (message, 13, getHeight() - statusHeight, getWidth() - 280, statusHeight, juce::Justification::centredLeft, true);
        auto* device = session.audioDeviceManager().getCurrentAudioDevice();
        const auto deviceText = device != nullptr
            ? juce::String (device->getCurrentSampleRate() / 1000.0, 1) + " kHz  /  " + juce::String (device->getCurrentBufferSizeSamples()) + " smp"
            : "Audio device offline";
        g.drawText (deviceText, getWidth() - 265,
                    getHeight() - statusHeight, 252, statusHeight, juce::Justification::centredRight);
    }

    void resized() override
    {
        auto area = getLocalBounds();
       #if ! JUCE_MAC
        menu.setBounds (area.removeFromTop (23));
       #endif
        toolbarBounds = area.removeFromTop (38);
        auto bar = toolbarBounds.reduced (8, 7);
        extButton.setVisible (session.hasSyncInputs() || session.isExternalSync());
        if (extButton.isVisible()) { extButton.setBounds (bar.removeFromLeft (36)); bar.removeFromLeft (3); }
        tapButton.setBounds (bar.removeFromLeft (36)); bar.removeFromLeft (3);
        tempo.setBounds (bar.removeFromLeft (58)); bar.removeFromLeft (1);
        nudgeDown.setBounds (bar.removeFromLeft (12)); nudgeUp.setBounds (bar.removeFromLeft (12)); bar.removeFromLeft (1);
        meterBounds = bar.removeFromLeft (40); bar.removeFromLeft (8); meterLabel.setBounds (meterBounds);
        clickButton.setBounds (bar.removeFromLeft (46)); clickSettingsButton.setBounds (bar.removeFromLeft (20));
        bar.removeFromLeft (8); quantisation.setBounds (bar.removeFromLeft (64));
        audioButton.setBounds (bar.removeFromRight (52)); bar.removeFromRight (6);
        midiMapButton.setBounds (bar.removeFromRight (40)); bar.removeFromRight (4);
        keyMapButton.setBounds (bar.removeFromRight (34)); bar.removeFromRight (4);
        keysButton.setBounds (bar.removeFromRight (40)); bar.removeFromRight (4);
        drawButton.setBounds (bar.removeFromRight (26)); bar.removeFromRight (6);
        arrangementTab.setBounds (bar.removeFromRight (58)); sessionTab.setBounds (bar.removeFromRight (58));
        pianoTab.setBounds (bar.removeFromRight (40)); bar.removeFromRight (10);
        cpuBounds = bar.removeFromRight (50); bar.removeFromRight (8);
        // Transport is centred on the window, independent of the side groups, and kept clear of them.
        // In a narrow window the less essential sections give way first, as the reference's do.
        struct Section { std::vector<juce::Component*> parts; int width; };
        const Section punch { { &punchInButton, &punchOutButton }, 30 + 2 + 30 }, loop { { &loopStartLabel, &loopButton, &loopLengthLabel }, 72 + 3 + 48 + 3 + 72 + 2 },
                      follow { { &followButton }, 48 + 8 }, capture { { &captureButton, &sessionRecordButton }, 50 + 2 + 28 + 4 },
                      automation { { &overdubButton, &automationArmButton, &reEnableButton }, 3 * 28 + 4 };
        int transportWidth = 86 + 6 + 3 * 28 + 2 + automation.width + capture.width + follow.width + punch.width + loop.width;
        std::set<const Section*> dropped;
        for (const auto* section : { &punch, &loop, &follow, &capture, &automation })
            if (transportWidth > bar.getWidth()) { dropped.insert (section); transportWidth -= section->width; }
        for (const auto* section : { &punch, &loop, &follow, &capture, &automation })
            for (auto* part : section->parts) part->setVisible (! dropped.count (section));
        const auto x = juce::jlimit (bar.getX(), juce::jmax (bar.getX(), bar.getRight() - transportWidth), getWidth() / 2 - transportWidth / 2);
        auto centre = juce::Rectangle<int> (x, bar.getY(), transportWidth, bar.getHeight());
        positionLabel.setBounds (centre.removeFromLeft (86)); centre.removeFromLeft (6);
        playButton.setBounds (centre.removeFromLeft (28));
        stopButton.setBounds (centre.removeFromLeft (28));
        recordButton.setBounds (centre.removeFromLeft (28)); centre.removeFromLeft (2);
        if (! dropped.count (&automation))
        {
            overdubButton.setBounds (centre.removeFromLeft (28));
            automationArmButton.setBounds (centre.removeFromLeft (28)); reEnableButton.setBounds (centre.removeFromLeft (28)); centre.removeFromLeft (4);
        }
        if (! dropped.count (&capture)) { captureButton.setBounds (centre.removeFromLeft (50)); centre.removeFromLeft (2); sessionRecordButton.setBounds (centre.removeFromLeft (28)); centre.removeFromLeft (4); }
        if (! dropped.count (&follow)) { followButton.setBounds (centre.removeFromLeft (48)); centre.removeFromLeft (8); }
        if (! dropped.count (&punch)) { punchInButton.setBounds (centre.removeFromLeft (30)); centre.removeFromLeft (2); }
        if (! dropped.count (&loop))
        {
            loopStartLabel.setBounds (centre.removeFromLeft (72)); centre.removeFromLeft (3);
            loopButton.setBounds (centre.removeFromLeft (48)); centre.removeFromLeft (3);
            loopLengthLabel.setBounds (centre.removeFromLeft (72)); centre.removeFromLeft (2);
        }
        if (! dropped.count (&punch)) punchOutButton.setBounds (centre.removeFromLeft (30));
        auto status = bar.withLeft (centre.getRight() + 12);
        backToArrangement.setBounds (status.removeFromLeft (124)); status.removeFromLeft (8);
        projectLabel.setBounds (status);
        // Creation and zoom live in menus, keys and context menus, as in the reference workflow.
        for (auto* hidden : std::initializer_list<juce::Component*> { &importButton, &newMidiClipButton, &addTrackButton, &addMidiButton, &zoomIn, &zoomOut, &fitButton })
            hidden->setVisible (false);
        area.removeFromBottom (statusHeight);
        // MIDI Map Mode shows its mappings in the browser's place, so the browser shows meanwhile.
        const bool browserShown = showBrowser || mapping();
        browserBounds = browserShown ? area.removeFromLeft (juce::jlimit (minimumBrowserWidth, maximumBrowserWidth(), browserWidth)) : juce::Rectangle<int>();
        // The Info View sits under the browser, as in the reference, and without it keeps the corner
        // beside the detail view.
        info.setVisible (showInfo);
        if (showInfo && browserShown) info.setBounds (browserBounds.removeFromBottom (infoHeight).reduced (6, 4));
        // MIDI Map Mode covers the working area and shows the mappings in place of the browser.
        mapOverlay.setVisible (mapping()); mappingList.setVisible (mapping());
        if (mapping()) { mapOverlay.setBounds (area); mappingList.setBounds (browserBounds.reduced (6)); mapOverlay.toFront (false); }
        // The detail view shows either the device chain or, for an open clip, its editor; View > Hide
        // Detail View hides it, as the reference's does.
        const int detailHeight = ! showDetail ? 0
                               : showPiano ? juce::jlimit (minimumClipViewHeight, juce::jmax (minimumClipViewHeight, area.getHeight() - 140),
                                                           juce::roundToInt (area.getHeight() * clipViewFraction))
                                           : deviceHeight;
        auto detail = area.removeFromBottom (detailHeight);
        // Without the browser, the Info View keeps its corner beside the detail view, or below the view without either.
        if (showInfo && ! browserShown) info.setBounds ((showDetail ? detail : area.removeFromBottom (infoHeight)).removeFromLeft (infoCornerWidth).removeFromBottom (infoHeight).reduced (6, 4));
        dividerBounds = showDetail ? detail.removeFromTop (dividerHeight) : juce::Rectangle<int>();
        deviceChain.setBounds (detail); deviceChain.setVisible (! showPiano && showDetail);
        auto browser = browserBounds.reduced (6, 6);
        browserSearch.setBounds (browser.removeFromTop (24));
        browser.removeFromTop (6);
        browserSidebar.setBounds (browser.removeFromLeft (categoryWidth));
        {
            const int rowsHeight = browserCategories.contentHeight();
            const bool scrolls = rowsHeight > browserSidebar.getHeight();
            browserCategories.setSize (categoryWidth - (scrolls ? browserSidebar.getScrollBarThickness() : 0), juce::jmax (rowsHeight, browserSidebar.getHeight()));
        }
        browser.removeFromLeft (4);
        auto actions = browser.removeFromBottom (24);
        upButton.setVisible (sampleBrowser()); folderButton.setVisible (browserCategory == BrowserCategory::samples || pluginBrowser());
        previewButton.setVisible (sampleBrowser()); previewVolume.setVisible (sampleBrowser());
        if (sampleBrowser())
        {
            auto previewRow = browser.removeFromBottom (22); browser.removeFromBottom (4);
            previewButton.setBounds (previewRow.removeFromLeft (66)); previewRow.removeFromLeft (4); previewVolume.setBounds (previewRow);
        }
        if (sampleBrowser()) upButton.setBounds (actions.removeFromLeft (29));
        folderButton.setBounds (actions);
        browser.removeFromBottom (4); browser.removeFromTop (22);
        browserList.setBounds (browser);
        for (auto* part : std::initializer_list<juce::Component*> { &browserSearch, &browserSidebar, &browserList })
            part->setVisible (browserShown && ! mapping());
        if (! browserShown) for (auto* part : std::initializer_list<juce::Component*> { &folderButton, &upButton, &previewButton, &previewVolume }) part->setVisible (false);
        if (mapping()) for (auto* part : std::initializer_list<juce::Component*> { &folderButton, &upButton, &previewButton, &previewVolume }) part->setVisible (false);
        launcher.setBounds (area);
        launcher.setVisible (showSession);
        const bool clipShown = showPiano && showDetail, audioClip = clipShown && selectedAudioClip() != nullptr;
        // A Session MIDI clip shows its Launch box to the left of the note editor.
        const auto* launchClip = clipShown && ! audioClip ? sessionMidiClip() : nullptr;
        auto editor = deviceChain.getBounds();
        midiLaunch.setVisible (launchClip != nullptr);
        if (launchClip != nullptr) { midiLaunch.setBounds (editor.removeFromLeft (LaunchBox::width).reduced (0, 6).withTrimmedLeft (6)); midiLaunch.setClip (*launchClip); }
        // Every MIDI clip shows its Loop box: Start, End, Loop, Position and Length.
        const auto* loopClip = clipShown && ! audioClip ? currentMidiClip() : nullptr;
        clipLoop.setVisible (loopClip != nullptr);
        if (loopClip != nullptr) { clipLoop.setBounds (editor.removeFromLeft (LoopBox::width).reduced (0, 6).withTrimmedLeft (6)); clipLoop.setClip (*loopClip); }
        // Every MIDI clip shows its Groove section beside the note editor.
        const auto* grooveClip = clipShown && ! audioClip ? currentMidiClip() : nullptr;
        clipGroove.setVisible (grooveClip != nullptr);
        if (grooveClip != nullptr) { clipGroove.setBounds (editor.removeFromLeft (GrooveBox::width).reduced (0, 6).withTrimmedLeft (6)); clipGroove.setClip (*grooveClip); }
        pianoRoll.setBounds (editor);
        pianoRoll.setVisible (clipShown && ! audioClip);
        audioClipView.setBounds (deviceChain.getBounds());
        audioClipView.setVisible (audioClip);
        if (audioClip) audioClipView.sync();
        viewport.setVisible (! showSession);
        ruler.setVisible (! showSession);
        horizontalScroll.setVisible (! showSession); gridReadout.setVisible (! showSession);
        sessionTab.setToggleState (showSession, juce::dontSendNotification);
        arrangementTab.setToggleState (! showSession, juce::dontSendNotification);
        pianoTab.setToggleState (showPiano, juce::dontSendNotification);
        const auto foot = area.removeFromBottom (12);
        timeRuler.setVisible (! showSession);
        timeRuler.setBounds (area.removeFromBottom (TimeRuler::height));
        horizontalScroll.setBounds (foot.withTrimmedRight (trackWidth + 10));
        gridReadout.setBounds (foot.withTrimmedLeft (horizontalScroll.getWidth() + 6).withWidth (60).expanded (0, 1));
        overview.setVisible (! showSession && state.arrangementOverview);
        if (overview.isVisible()) overview.setBounds (area.removeFromTop (Overview::height));
        ruler.setBounds (area.removeFromTop (rulerHeight + (meterLaneShown() ? meterLaneHeight : 0)));
        viewport.setBounds (area);
        canvas.setSize (juce::jmax (1, viewport.getWidth() - 10), juce::jmax (area.getHeight(), lanesHeight));
        canvas.resized();
        ruler.resized(); // Place controls using the final timeline width after window resizing.
        updateScroll();
    }

    void mouseDown (const juce::MouseEvent& e) override
    {
        draggingBrowserEdge = onBrowserEdge (e.getPosition());
        draggingDivider = ! draggingBrowserEdge && showPiano && dividerBounds.expanded (0, 3).contains (e.getPosition());
    }
    void mouseDrag (const juce::MouseEvent& e) override
    {
        if (draggingBrowserEdge) { browserWidth = juce::jlimit (minimumBrowserWidth, maximumBrowserWidth(), e.x - browserBounds.getX()); resized(); repaint(); return; }
        if (! draggingDivider) return;
        const auto main = getLocalBounds().withTrimmedTop (toolbarBounds.getBottom()).withTrimmedBottom (statusHeight);
        clipViewFraction = juce::jlimit (.25, .85, (main.getBottom() - e.y) / (double) juce::jmax (1, main.getHeight()));
        resized();
    }
    void mouseUp (const juce::MouseEvent&) override { draggingDivider = draggingBrowserEdge = false; }
    juce::MouseCursor getMouseCursor() override
    {
        if (onBrowserEdge (getMouseXYRelative())) return juce::MouseCursor::LeftRightResizeCursor;
        return showPiano ? juce::MouseCursor::UpDownResizeCursor : juce::MouseCursor::NormalCursor;
    }
    bool draggingDivider = false, draggingBrowserEdge = false;
    // The browser's right edge drags to resize it, as the reference's does; the width lasts while the window is open.
    int browserWidth = defaultBrowserWidth;
    static constexpr int defaultBrowserWidth = 300, minimumBrowserWidth = 220;
    int maximumBrowserWidth() const { return juce::jmax (minimumBrowserWidth, juce::jmin (640, getWidth() / 2)); }
    bool onBrowserEdge (juce::Point<int> p) const
    { return ! browserBounds.isEmpty() && std::abs (p.x - browserBounds.getRight()) <= 4 && p.y >= browserBounds.getY() && p.y < getHeight() - statusHeight; }
    bool handleKey (const juce::KeyPress& key)
    {
        if (session.isExporting()) return true;
        if (mappedKey (key)) return true;
        if (computerKeyboardKey (key)) return true;
        if (const auto repeat = latchKey (key)) return *repeat;
        const auto code = key.getKeyCode();
        const auto cmd = key.getModifiers().isCommandDown();
        const auto shift = key.getModifiers().isShiftDown();
        // In the browser, 1 to 7 put the selected item in a collection or take it out.
        if (! cmd && ! shift && ! key.getModifiers().isAltDown() && code >= '1' && code <= '7' && browserList.hasKeyboardFocus (true) && browserList.getSelectedRow() >= 0)
        { toggleBrowserCollection (browserList.getSelectedRow(), code - '1'); return true; }
        if (browserList.hasKeyboardFocus (true) && browserListKey (key)) return true;
        if (cmd)
        {
            // The reference's grid commands, for the Arrangement.
            if (! shift && code >= '1' && code <= '5') if (const auto place = focusedGrid()) { gridCommand (code - '0', *place); return true; }
            // The global launch quantization, as the reference's keys set it: Cmd+6 to 9 for 1/16, 1/8, 1/4
            // and 1 Bar, and Cmd+0 for None.
            if (! shift && ! key.getModifiers().isAltDown() && (code == '0' || (code >= '6' && code <= '9')))
            {
                using Q = Session::LaunchQuantisation;
                const Q grids[] { Q::sixteenth, Q::eighth, Q::beat, Q::bar };
                report (session.setLaunchQuantisation (code == '0' ? Q::none : grids[code - '6'])); refresh(); return true;
            }
            // View > Mixer, as in the reference, before MIDI Map Mode's Cmd/Ctrl+M.
            if ((code == 'M' || code == 'm') && key.getModifiers().isAltDown() && showSession) { menuItemSelected (109, 3); return true; }
            if (code == 'M' && ! shift && ! key.getModifiers().isAltDown()) { setMidiMapMode (! midiMapMode); return true; }
            if (code == 'K' && ! shift) { setKeyMapMode (! keyMapMode); return true; }
            if (code == 'O' && ! shift && ! key.getModifiers().isAltDown()) { openDialog(); return true; }
            if (code == 'N') { ensureSaved ([safe = juce::Component::SafePointer<Impl> (this)] { if (safe != nullptr) safe->startNewProject(); }); return true; }
            if (code == 'T') { if (key.getModifiers().isAltDown()) addReturnTrack(); else if (shift) addMidiTrack(); else { showPiano = false; addTrack(); resized(); } return true; }
            if (code == 'Z' && ! key.getModifiers().isAltDown()) { if (shift) session.redo(); else session.undo(); refresh(); return true; }
            if (code == 'L' && (shift || key.getModifiers().isAltDown())) return runMenuShortcut (key);
            if (code == 'L' && timeSelection.active() && ! showSession && ! showPiano) { selectionCommand (79); return true; }
            if (code == 'J' && ! shift && timeSelection.active() && ! showSession && ! showPiano) { selectionCommand (80); return true; }
            if (code == 'J' && shift && ! key.getModifiers().isAltDown() && ! showSession && ! showPiano) { runArrangementKey (arrangementCrop); return true; }
            if (code == 'L') { session.setLoop (! state.looping, state.loopStart, state.loopEnd); refresh(); return true; }
            // After a click on a header, Duplicate, Cut, Copy and Paste act on the selected tracks, as the reference's headers do.
            if (code == 'D' && ! shift && ! key.getModifiers().isAltDown() && headerFocus) { duplicateSelectedHeaders(); return true; }
            if ((code == 'C' || code == 'X' || code == 'V') && ! shift && ! key.getModifiers().isAltDown() && headerFocus) { trackClipboardCommand ((char) code); return true; }
            if (! shift && ! showSession && ! showPiano && timeSelection.active() && (code == 'E' || code == 'D' || code == 'C' || code == 'X'))
            { selectionCommand (code == 'E' ? 76 : code == 'D' ? 77 : code == 'C' ? 81 : 82); return true; }
            // A copied time selection pastes at the insert marker from the selected track.
            if (! shift && ! showSession && ! showPiano && code == 'V' && session.hasRangeClipboard()) { selectionCommand (83); return true; }
            // Cut, Paste and Duplicate Time, as in the reference.
            if (shift && ! showSession && ! showPiano && (code == 'X' || code == 'V' || code == 'D')) { menuItemSelected (code == 'X' ? 89 : code == 'V' ? 101 : 102, 1); return true; }
            // Capture and Insert Scene, as in the reference.
            if (code == 'I' && shift) { menuItemSelected (68, 4); return true; }
            if (code == 'I' && ! showSession && ! key.getModifiers().isAltDown()) { menuItemSelected (74, 1); return true; }
            // In the Arrangement, Option+Cmd+I and Option+Cmd+R show and hide its In/Out and returns, as the reference's keys do.
            if ((code == 'I' || code == 'R') && ! shift && key.getModifiers().isAltDown() && ! showSession)
            { menuItemSelected (code == 'I' ? menuArrangementInOut : menuArrangementReturns, 4); return true; }
            if ((code == juce::KeyPress::deleteKey || code == juce::KeyPress::backspaceKey) && shift && ! showSession) { menuItemSelected (75, 1); return true; }
            // Cmd+Delete clears the envelope last clicked, as the reference's key does.
            if ((code == juce::KeyPress::deleteKey || code == juce::KeyPress::backspaceKey) && ! shift && ! key.getModifiers().isAltDown() && automationMode && ! showSession && ! showPiano
                && selectedEnvelopeKey.isNotEmpty())
            { clearEnvelope (selectedEnvelopeTrack, selectedEnvelopeKey); return true; }
            // Cmd+Option+Delete deletes the selected clips' fades and crossfades, as the reference's key does.
            if ((code == juce::KeyPress::deleteKey || code == juce::KeyPress::backspaceKey) && key.getModifiers().isAltDown() && ! showSession && ! showPiano)
            { if (canResetFades()) resetSelectionFades(); return true; }
            if (code == 'G' && ! key.getModifiers().isAltDown()) { if (shift) ungroupSelectedTrack(); else groupSelectedTracks(); return true; }
            if ((code == 'E' || code == 'e') && shift && key.getModifiers().isAltDown()) { menuItemSelected (13, 1); return true; }
            if (code == 'C' && shift) { captureFromUI(); return true; }
            if ((code == 'U' || code == 'u') && key.getModifiers().isAltDown() && ! showSession) { toggleTakeLanes(); return true; }
            if ((code == juce::KeyPress::upKey || code == juce::KeyPress::downKey) && ! showSession && ! showPiano && timeSelection.active())
            {
                juce::StringArray cycled; // A cycle on a linked track comps its linked tracks too.
                for (const auto& id : timeSelection.trackIds)
                    if (const auto t = trackIndex (id); ! cycled.contains (id) && t >= 0)
                    {
                        report (session.cycleTake (id, timeSelection.start, timeSelection.end, code == juce::KeyPress::downKey));
                        cycled.add (id); addLinkedTracks (cycled);
                    }
                refresh(); return true;
            }
            if (! shift && ! showSession && ! showPiano && selectedClipIds.size() > 1 && (code == 'D' || code == 'C' || code == 'X')) { clipGroupCommand ((char) code); return true; }
            if (! shift && ! key.getModifiers().isAltDown() && ! showSession && ! showPiano && (code == 'E' || code == 'D' || code == 'C' || code == 'X' || code == 'V'))
            {
                for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused != nullptr; focused = focused->getParentComponent())
                    if (dynamic_cast<juce::TextEditor*> (focused)) return false;
                if (code == 'V')
                {
                    if (const auto* track = currentTrack(); track && ! track->isReturn)
                    { if(track->isMidi)midiClipCommand(7,{});else audioClipCommand(7,{}); return true; }
                    return false;
                }
                if (const auto* track = currentTrack(); track && juce::isPositiveAndBelow(selectedClip,(int)track->clips.size())
                    && track->clips[(size_t)selectedClip].isMidi && code=='E')
                { juce::String right; report (session.splitMidiClip (track->clips[(size_t) selectedClip].id, state.insertMarker, right)); refresh(); return true; }
                if (const auto* track = currentTrack(); track && juce::isPositiveAndBelow(selectedClip,(int)track->clips.size())
                    && track->clips[(size_t)selectedClip].isMidi && code!='E')
                {midiClipCommand(code=='D'?4:code=='C'?5:6,track->clips[(size_t)selectedClip].id);return true;}
                if (const auto* track = currentTrack(); track && juce::isPositiveAndBelow (selectedClip, (int) track->clips.size())
                    && track->clips[(size_t) selectedClip].isAudio)
                {
                    const auto id = track->clips[(size_t) selectedClip].id;
                    audioClipCommand (code == 'E' ? 3 : code == 'D' ? 4 : code == 'C' ? 5 : 6, id); return true;
                }
            }
            if (code == ',') { showPreferences(); return true; }
        }
        if (key.getTextCharacter() == '?' && ! cmd)
        {
            showInfo = ! showInfo; resized(); return true;
        }
        if ((key.getTextCharacter() == 'm' || key.getTextCharacter() == 'M') && ! cmd && ! shift && ! key.getModifiers().isAltDown())
        {
            for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
                if (dynamic_cast<juce::TextEditor*> (focused)) return false;
            setComputerKeyboard (! session.isComputerKeyboardEnabled()); return true;
        }
        if ((code == 'T' || code == 't') && ! cmd && shift && key.getModifiers().isAltDown() && ! showSession) { insertTakeLaneFromUI(); return true; }
        if ((code == 'T' || code == 't') && ! cmd && ! key.getModifiers().isAltDown() && ! showSession && takeSelection.laneId.isNotEmpty())
        {
            for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
                if (dynamic_cast<juce::TextEditor*> (focused)) return false;
            toggleAudition (takeSelection.laneId); return true;
        }
        if (code == juce::KeyPress::returnKey && ! cmd && ! showSession && ! showPiano && takeSelection.active()) { compSelectedTake(); return true; }
        if ((code == 'A' || code == 'a') && ! cmd && ! shift && ! key.getModifiers().isAltDown() && ! showSession)
        {
            for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
                if (dynamic_cast<juce::TextEditor*> (focused)) return false;
            setAutomationMode (! automationMode); return true;
        }
        if ((code == 'X' || (code == 'Z' && ! shift)) && ! cmd && ! key.getModifiers().isAltDown() && ! showSession && ! showPiano)
        {
            for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
                if (dynamic_cast<juce::TextEditor*> (focused)) return false;
            return code == 'Z' ? zoomToSelection() : zoomBackFromSelection();
        }
        if (code == juce::KeyPress::tabKey && shift) { if (showPiano) closeClipView(); else openPianoRoll(); return true; }
        if (code == juce::KeyPress::tabKey) { if (showSession) showArrangementView(); else showSessionView(); return true; }
        if (code == juce::KeyPress::spaceKey && shift && ! cmd) { if (state.playing) session.stop(); else report (session.continuePlayback()); refresh(); return true; }
        if (code == juce::KeyPress::spaceKey && ! cmd && ! key.getModifiers().isAltDown()) { togglePlay(); return true; }
        if (code == juce::KeyPress::homeKey) { session.returnToStart(); refresh(); return true; }
        // Escape jumps to the selected track's title bar, as the reference's does: the headers then take Edit's commands.
        if (code == juce::KeyPress::escapeKey) { if (currentTrack() != nullptr || groupInfo (selectedChain) != nullptr) { headerFocus = true; clickedArea = Area::headers; refresh(); } return true; }
        if (code == juce::KeyPress::F9Key && ! cmd) { report (session.recordButton (shift)); refresh(); return true; }
        // F1 to F8 switch tracks 1 to 8 on and off by their numbers, groups counted, as the reference's keys do.
        if (! cmd && ! shift && ! key.getModifiers().isAltDown() && code >= juce::KeyPress::F1Key && code <= juce::KeyPress::F8Key) { toggleNumberedTrack (code - juce::KeyPress::F1Key + 1); return true; }
        if ((code == juce::KeyPress::deleteKey || code == juce::KeyPress::backspaceKey) && ! cmd)
        {
            if (headerFocus) { deleteSelectedHeaders(); return true; }
            if (! showPiano && ! showSession && selectedFadeClip.isNotEmpty()) { deleteSelectedFade(); return true; }
            if (showPiano) pianoRoll.deleteSelectedNote(); else if (showSession) clearSelectedSlot();
            else if (timeSelection.active()) selectionCommand (78); else deleteSelectedClip();
            return true;
        }
        if (! cmd && ! shift && ! key.getModifiers().isAltDown() && ! showSession && ! showPiano
            && (code == juce::KeyPress::leftKey || code == juce::KeyPress::rightKey || code == juce::KeyPress::upKey || code == juce::KeyPress::downKey))
        {
            for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
                if (dynamic_cast<juce::TextEditor*> (focused)) return false;
            if (arrangementArrow (code)) return true;
        }
        if (key.getModifiers().isAltDown() && ! cmd && ! showSession && (code == '=' || code == '+' || code == '-'))
        { scaleTrackHeight (selectedTrack, code == '-' ? 1 / 1.25 : 1.25); return true; }
        // H, W, U, T, R and X also take Shift, as the reference's alternates do.
        if (! cmd && ! key.getModifiers().isAltDown() && ! showSession && ! showPiano && (code == 'H' || code == 'h')) { optimizeHeight(); return true; }
        if (! cmd && ! key.getModifiers().isAltDown() && ! showSession && ! showPiano && (code == 'R' || code == 'r') && clickedArea == Area::arrangement)
        {
            for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
                if (dynamic_cast<juce::TextEditor*> (focused)) return false;
            runArrangementKey (arrangementReverse); return true;
        }
        if (! cmd && ! showPiano && (code == 'U' || code == 'u')) { toggleFold (key.getModifiers().isAltDown()); return true; }
        if (! cmd && ! key.getModifiers().isAltDown() && ! showSession && ! showPiano && (code == 'W' || code == 'w')) { optimizeWidth(); return true; }
        if ((key.getTextCharacter() == '+' || key.getTextCharacter() == '=') && ! cmd) { if (showSession && ! showPiano) return false; if (showPiano) pianoRoll.zoom (1.3); else zoom (1.3); return true; }
        if (key.getTextCharacter() == '-' && ! cmd) { if (showSession && ! showPiano) return false; if (showPiano) pianoRoll.zoom (1.0 / 1.3); else zoom (1.0 / 1.3); return true; }
        for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused != nullptr; focused = focused->getParentComponent())
            if (dynamic_cast<juce::TextEditor*> (focused) != nullptr && ! cmd) return false;
        return runMenuShortcut (key);
    }

    // Crash recovery: every 30 s, unsaved work is copied to the recovery file; once saved it is removed.
    juce::File recoveryFile;
    int recoveryTicks = 0;
    bool recoveryPending = false; // The recovery prompt is open; its copy must survive until answered.
    static constexpr int recoveryIntervalTicks = 24 * 30;
    void enableRecovery (const juce::File& file)
    {
        recoveryFile = file; recoveryTicks = 0;
        // Started with the app's own settings: say if its preferences could not be read.
        if (const auto problem = session.preferencesProblem(); problem.isNotEmpty()) report (juce::Result::fail (problem));
        if (recoveryFile.existsAsFile()) offerRecovery();
    }
    void clearRecovery() { if (recoveryFile != juce::File()) recoveryFile.deleteFile(); }
    void setUserLibrary (const juce::File& folder);
    void startNewProjectFromLaunch() { startNewProject(); }
    void autosave()
    {
        if (recoveryFile == juce::File() || recoveryPending || session.isExporting() || state.recording) return;
        if (! state.dirty) { clearRecovery(); return; }
        if (const auto result = session.writeRecovery (recoveryFile); result.failed()) { status = result.getErrorMessage(); statusFrames = 24 * 5; }
    }
    void offerRecovery()
    {
        auto* dialog = new juce::AlertWindow ("Recover unsaved work?",
            "Halftrack closed before your last changes were saved. Recover them as an untitled project, or discard them.", juce::MessageBoxIconType::QuestionIcon);
        dialog->addButton ("Recover", 1, juce::KeyPress (juce::KeyPress::returnKey)); dialog->addButton ("Discard", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        recoveryPending = true;
        auto safe = juce::Component::SafePointer<Impl> (this);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe] (int result)
        {
            if (safe == nullptr) return;
            safe->recoveryPending = false;
            if (result != 1) { safe->clearRecovery(); return; }
            juce::File from;
            const auto recovered = safe->session.recoverProject (safe->recoveryFile, from);
            safe->report (recovered, from != juce::File() ? "Recovered unsaved work from " + from.getFileName() + ". Use Save As to keep it." : "Recovered unsaved work. Save it to keep it.");
            if (recovered.wasOk()) safe->resetView();
        }), true);
    }
    void ensureSaved (std::function<void()> action)
    {
        if (session.isExporting())
        {
            status = "Finish or cancel the export before closing or replacing this project.";
            statusFrames = 24 * 7; repaint(); return;
        }
        if (! session.snapshot().dirty) { action(); return; }
        auto safe = juce::Component::SafePointer<Impl> (this);
        juce::AlertWindow::showAsync (juce::MessageBoxOptions()
            .withIconType (juce::MessageBoxIconType::QuestionIcon)
            .withTitle ("Save this Halftrack project?")
            .withMessage ("Save your changes before continuing.")
            .withButton ("Save").withButton ("Discard").withButton ("Cancel"),
            [safe, action = std::move (action)] (int result)
            {
                if (safe == nullptr) return;
                if (result == 1) safe->saveProject (false, action);
                else if (result == 2) action();
            });
    }

   #if HALFTRACK_TESTS_ENABLED
    void runInteractionChecks (const juce::File& audioFixture);
    int runSeparationStress (const juce::File& root);
    void runExportInteractionChecks (const juce::File& audioFixture);
    bool captureTestErrors = false;
    std::function<void (const Session::AudioExportSettings&, uint64_t)> testExportDestination;
   #endif

private:
    // Arrangement lanes in visual order: group headers above their members; folded members have no height.
    static constexpr int groupHeight = 40;
    // A group header, a track, one of its take lanes (`take`) or automation lanes (`automation`, an
    // index into its keys).
    struct Lane { bool group = false; int index = -1, y = 0, height = 0, automation = -1, take = -1; };
    std::vector<Lane> lanes;
    int lanesHeight = 0;
    // Automation Mode: each track's lane shows one envelope over its clips, and lanes below it show more.
    bool automationMode = false;
    static constexpr int automationLaneHeight = 54;
    std::map<juce::String, juce::String> shownAutomation;       // Track id to the key on its lane; "none" hides it.
    std::map<juce::String, juce::StringArray> automationLanes;  // Track id to the keys shown in lanes below it.
    arrangementAutomation::Envelope envelope;
    juce::String envelopeTrack, envelopeKey;                    // The envelope a pointer gesture is editing.
    juce::String selectedEnvelopeTrack, selectedEnvelopeKey;    // The envelope last clicked, which Cmd+Delete clears.
    juce::String shownKey (const Session::TrackInfo& t) const
    { const auto found = shownAutomation.find (t.id); return found != shownAutomation.end() ? found->second : arrangementAutomation::volumeKey (t); }
    std::optional<arrangementAutomation::Target> automationTarget (const juce::String& trackId, const juce::String& key)
    {
        for (const auto& t : state.tracks) if (t.id == trackId) return arrangementAutomation::find (session, t, state.tracks, key);
        for (const auto& g : state.groups) if (g.id == trackId) return arrangementAutomation::find (session, automationView (g), state.tracks, key);
        return std::nullopt;
    }
    // A group as the automation choosers and envelopes see a track: its mixer, sends and devices, as
    // the reference's group lanes automate them.
    static Session::TrackInfo automationView (const Session::GroupInfo& g)
    {
        Session::TrackInfo t;
        t.id = g.id; t.name = g.name; t.colour = g.colour;
        t.gainDb = g.gainDb; t.pan = g.pan; t.splitPan = g.splitPan; t.leftSplitPan = g.leftSplitPan; t.rightSplitPan = g.rightSplitPan;
        t.volumeAutomation = g.volumeAutomation; t.panAutomation = g.panAutomation;
        t.leftSplitAutomation = g.leftSplitAutomation; t.rightSplitAutomation = g.rightSplitAutomation;
        t.sends = g.sends; t.plugins = g.plugins;
        return t;
    }
    void setAutomationMode (bool on) { automationMode = on; if (! on) { selectedEnvelopeTrack.clear(); selectedEnvelopeKey.clear(); } refresh(); resized(); canvas.repaint(); }
    // Clear Envelope, as the reference's (Cmd+Delete): every breakpoint of an envelope goes, one undo step.
    void clearEnvelope (const juce::String& trackId, const juce::String& key)
    {
        const auto target = automationTarget (trackId, key);
        if (! target || target->lane.points.empty()) return;
        auto lane = target->lane; lane.points.clear();
        session.beginEditGesture ("Clear " + target->control + " envelope");
        report (arrangementAutomation::write (session, *target, lane));
        session.endEditGesture(); refresh();
    }
    // An envelope's context menu: Simplify Envelope over the time selection, as the reference's.
    // The reference's automation shapes: the waveforms of its envelope menu's top row, one cycle over the
    // time selection (or a grid step without one) across the control's whole range.
    enum class EnvelopeShape { sine = 10, triangle, sawtooth, inverseSawtooth, square };
    void envelopeMenu (const arrangementAutomation::Target& target, double clickedBeat = 0)
    {
        const auto range = envelope.selectedBeats ? envelope.selectedBeats (target.trackId) : std::nullopt;
        juce::PopupMenu menu;
        menu.addItem (2, "Clear Envelope", ! target.lane.points.empty());
        menu.addItem (1, "Simplify Envelope", range.has_value() && target.lane.points.size() > 2);
        menu.addSectionHeader ("Shapes");
        for (const auto& [shape, name] : { std::pair { EnvelopeShape::sine, "Sine" }, { EnvelopeShape::triangle, "Triangle" }, { EnvelopeShape::sawtooth, "Sawtooth" },
                                          { EnvelopeShape::inverseSawtooth, "Inverse Sawtooth" }, { EnvelopeShape::square, "Square" } })
            menu.addItem ((int) shape, name);
        const auto span = range ? *range : std::pair { gridLine (clickedBeat, -1), gridLine (gridLine (clickedBeat, -1) + 1.0e-6, 1) };
        auto safe = juce::Component::SafePointer<Impl> (this);
        menu.showMenuAsync (juce::PopupMenu::Options(), [safe, trackId = target.trackId, key = target.key, range, span] (int choice)
        {
            if (safe == nullptr) return;
            if (choice == 2) safe->clearEnvelope (trackId, key);
            else if (choice == 1 && range) safe->simplifyEnvelope (trackId, key, *range);
            else if (choice >= (int) EnvelopeShape::sine && choice <= (int) EnvelopeShape::square) safe->insertEnvelopeShape (trackId, key, static_cast<EnvelopeShape> (choice), span);
        });
    }
    void insertEnvelopeShape (const juce::String& trackId, const juce::String& key, EnvelopeShape shape, std::pair<double, double> span)
    {
        const auto target = automationTarget (trackId, key);
        const auto [from, to] = span;
        if (! target || ! (to > from)) return;
        // The shape as the pointer would draw it freehand, so the lane keeps its shape around it.
        arrangementAutomation::Drawing drawing;
        drawing.begin (target->lane.points);
        const auto length = to - from, gap = arrangementAutomation::Drawing::stepGap;
        const auto add = [&] (double at, float proportion) { drawing.add (from + at, proportion, {}); };
        switch (shape)
        {
            case EnvelopeShape::sine:
                for (int i = 0; i <= 32; ++i) add (std::min (length - gap, length * i / 32.0), .5f + .5f * (float) std::sin (juce::MathConstants<double>::twoPi * i / 32.0));
                break;
            case EnvelopeShape::triangle: add (0, 0); add (length / 2, 1); add (length - gap, 0); break;
            case EnvelopeShape::sawtooth: add (0, 0); add (length - gap, 1); break;
            case EnvelopeShape::inverseSawtooth: add (0, 1); add (length - gap, 0); break;
            case EnvelopeShape::square: add (0, 1); add (length / 2 - gap, 1); add (length / 2, 0); add (length - gap, 0); break;
        }
        auto lane = target->lane;
        lane.points = drawing.points ([&target] (float p) { return arrangementAutomation::fromProportion (*target, p); },
                                      [&target] (float v) { return arrangementAutomation::toProportion (*target, v); }, target->manual);
        session.beginEditGesture ("Insert envelope shape");
        report (arrangementAutomation::write (session, *target, lane));
        session.endEditGesture(); refresh();
    }
    void simplifyEnvelope (const juce::String& trackId, const juce::String& key, std::pair<double, double> range)
    {
        const auto target = automationTarget (trackId, key);
        if (! target) return;
        session.beginEditGesture ("Simplify envelope");
        report (arrangementAutomation::write (session, *target, arrangementAutomation::Envelope::simplified (*target, range.first, range.second)));
        session.endEditGesture(); refresh();
    }
    void showAutomationKey (const juce::String& trackId, const juce::String& key) { shownAutomation[trackId] = key; refresh(); canvas.repaint(); }
    // The lane button moves the envelope into its own lane below the track.
    void addAutomationLane (const juce::String& trackId, const juce::String& key)
    { if (key.isEmpty() || key == "none") return; automationLanes[trackId].addIfNotAlreadyThere (key); shownAutomation[trackId] = "none"; refresh(); resized(); }
    void removeAutomationLane (const juce::String& trackId, int index)
    { if (auto found = automationLanes.find (trackId); found != automationLanes.end()) found->second.remove (index); refresh(); resized(); }
    const Lane* laneAt (int y) const { for (const auto& lane : lanes) if (lane.height > 0 && y >= lane.y && y < lane.y + lane.height) return &lane; return nullptr; }
    // Take lanes, as in the reference's comping: shown below their tracks; a time range selected in one
    // is comped into the main lane with Enter.
    static constexpr int takeLaneHeight = 46;
    std::set<juce::String> takeLanesShown;
    struct TakeSelection { juce::String laneId; double start = 0, end = 0; bool active() const { return laneId.isNotEmpty() && end > start; } } takeSelection;
    void toggleTakeLanes()
    {
        if (const auto* track = currentTrack(); track != nullptr && ! track->isReturn)
        { if (! takeLanesShown.erase (track->id)) takeLanesShown.insert (track->id); refresh(); resized(); }
    }
    void insertTakeLaneFromUI()
    {
        if (const auto* track = currentTrack(); track != nullptr && ! track->isReturn)
        { juce::String id; report (session.insertTakeLane (track->id, id)); takeLanesShown.insert (track->id); refresh(); resized(); }
    }
    void toggleAudition (const juce::String& laneId)
    {
        bool auditioned = false;
        for (const auto& t : state.tracks) auditioned = auditioned || t.auditionLane == laneId;
        if (auditioned) session.stopAuditioning(); else report (session.auditionTakeLane (laneId));
        refresh();
    }
    void compSelectedTake()
    {
        if (! takeSelection.active()) return;
        report (session.compTake (takeSelection.laneId, takeSelection.start, takeSelection.end)); refresh();
    }
    std::set<juce::String> multiSelectedTracks;
    // Solo and arm are exclusive by default, as in the reference: a plain click releases every other
    // track (and, for solo, group); Cmd/Ctrl-click adds to them. With exclusivity off in the
    // preferences, the two swap. As in the reference, neither is an undo step.
    void soloFromUI (int trackIndex, const juce::String& groupId, bool on, bool additive)
    {
        const auto current = session.snapshot();
        // Exclusive, as the reference's: the others go, so a plain click on an engaged switch clears every one.
        if (additive != session.preferences().exclusiveSolo)
        {
            for (int t = 0; t < (int) current.tracks.size(); ++t) if (t != trackIndex && current.tracks[(size_t) t].solo) session.setTrackSolo (t, false);
            for (const auto& g : current.groups) if (g.id != groupId && g.solo) session.setGroupSolo (g.id, false);
        }
        const auto result = groupId.isNotEmpty() ? session.setGroupSolo (groupId, on) : session.setTrackSolo (trackIndex, on);
        report (result); refresh();
    }
    void armFromUI (int trackIndex, bool on, bool additive)
    {
        const auto current = session.snapshot();
        juce::Result result = juce::Result::ok();
        if (on && additive != session.preferences().exclusiveArm)
            for (int t = 0; t < (int) current.tracks.size() && result.wasOk(); ++t)
                if (t != trackIndex && current.tracks[(size_t) t].armed) result = session.setTrackArmed (t, false);
        if (result.wasOk()) result = session.setTrackArmed (trackIndex, on);
        report (result); refresh();
    }
    // The Arrangement time selection: a range over a run of tracks; empty when end <= start.
    struct TimeSelection
    {
        double start = 0, end = 0;
        juce::StringArray trackIds;
        bool active() const { return end - start > .001 && ! trackIds.isEmpty(); }
    };
    TimeSelection timeSelection;
    // A grid's place: the Arrangement's, or a clip's in its editor, with the editor's zoom and width.
    struct GridPlace { juce::String clipId; double pixelsPerBeat = 0, visibleBeats = 0; int viewWidth = 0; };
    int trackIndex (const juce::String& id) const
    { for (int t = 0; t < (int) state.tracks.size(); ++t) if (state.tracks[(size_t) t].id == id) return t; return -1; }
    double snapTime (double seconds, juce::ModifierKeys mods) const { return juce::jmax (0.0, snaps (mods) ? toGrid (seconds) : seconds); }
    // As in the reference, Cmd (Mac) or Alt (elsewhere) held during an edit bypasses snapping, or
    // snaps when the grid's snapping is off.
    static bool bypassesGrid (juce::ModifierKeys mods)
    {
       #if JUCE_MAC
        return mods.isCommandDown();
       #else
        return mods.isAltDown();
       #endif
    }
    bool snaps (juce::ModifierKeys mods) const { return editGrid.snap != bypassesGrid (mods); }
    // Option (Mac) or Ctrl (elsewhere) held at the press drags copies, as the reference's does.
    static bool copiesOnDrag (juce::ModifierKeys mods)
    {
       #if JUCE_MAC
        return mods.isAltDown();
       #else
        return mods.isCtrlDown();
       #endif
    }
   #if JUCE_MAC
    static constexpr int bypassModifier = juce::ModifierKeys::commandModifier;
   #else
    static constexpr int bypassModifier = juce::ModifierKeys::altModifier;
   #endif
    // Paste Time lands from the selected track, or from the first when the clipboard holds every track.
    juce::String pasteTimeTrack() const
    {
        int tracks = 0; juce::String first;
        for (const auto& t : state.tracks) if (! t.isReturn) { if (first.isEmpty()) first = t.id; ++tracks; }
        const auto* track = currentTrack();
        return track == nullptr || track->isReturn || session.rangeClipboardTracks() >= tracks ? first : track->id;
    }
    // Time edits use the selection, or the loop range when nothing is selected.
    std::pair<double, double> editRange() const
    { return timeSelection.active() ? std::pair { timeSelection.start, timeSelection.end } : std::pair { state.loopStart, state.loopEnd }; }
    void selectionCommand (int item)
    {
        if (item == 83)
        {
            // As in the reference, the pasted time is selected on the tracks it landed on.
            const auto* track = currentTrack();
            if (track == nullptr) return;
            const auto at = state.insertMarker;
            const auto result = session.pasteRange (track->id, at);
            report (result); refresh();
            if (result.wasOk())
            {
                timeSelection = { at, at + session.rangeClipboardLength(), {} };
                for (int t = selectedTrack; t < (int) state.tracks.size() && timeSelection.trackIds.size() < session.rangeClipboardTracks(); ++t)
                    if (! state.tracks[(size_t) t].isReturn) timeSelection.trackIds.add (state.tracks[(size_t) t].id);
                canvas.repaint();
            }
            return;
        }
        if (! timeSelection.active()) return;
        const auto [start, end] = editRange();
        if (item == 76) report (session.splitRange (timeSelection.trackIds, start, end));
        else if (item == 77)
        {
            const auto result = session.duplicateRange (timeSelection.trackIds, start, end);
            report (result);
            // As in the reference, the selection moves onto the copy so repeating it continues the pattern.
            if (result.wasOk()) { timeSelection.start = end; timeSelection.end = end + (end - start); }
        }
        else if (item == 78) report (session.deleteRange (timeSelection.trackIds, start, end));
        else if (item == 79) session.setLoop (true, start, end);
        else if (item == 80) { juce::StringArray created; report (session.consolidateRange (timeSelection.trackIds, start, end, created)); }
        else if (item == 81 || item == 82) report (session.copyRange (timeSelection.trackIds, start, end, item == 82));
        refresh();
    }
    const Session::GroupInfo* groupInfo (const juce::String& id) const
    { for (const auto& g : state.groups) if (g.id == id) return &g; return nullptr; }
    // The groups a group is inside, and the group itself, outermost first, by index in state.groups.
    std::vector<int> groupPath (const juce::String& id) const
    {
        std::vector<int> path;
        for (auto current = id; current.isNotEmpty() && path.size() <= state.groups.size();)
        {
            int found = -1;
            for (int g = 0; g < (int) state.groups.size(); ++g) if (state.groups[(size_t) g].id == current) found = g;
            if (found < 0) break;
            path.insert (path.begin(), found); current = state.groups[(size_t) found].parentId;
        }
        return path;
    }
    // Whether a group, or one around it, is folded.
    bool anyFolded (const juce::String& groupId) const
    {
        for (const auto g : groupPath (groupId)) if (state.groups[(size_t) g].folded) return true;
        return false;
    }
    // The tracks and groups in the order the views show them: each group's header before what is in
    // it, empty groups too.
    struct Item { bool group = false; int index = -1; };
    static std::vector<Item> visualOrder (const Session::Snapshot& shown)
    {
        std::vector<Item> items;
        size_t g = 0;
        for (int t = 0; t <= (int) shown.tracks.size(); ++t)
        {
            for (; g < shown.groups.size() && shown.groups[g].position <= t; ++g) items.push_back ({ true, (int) g });
            if (t < (int) shown.tracks.size()) items.push_back ({ false, t });
        }
        return items;
    }
    std::vector<Item> visualOrder() const { return visualOrder (state); }
    // Whether a group is inside another, at any depth.
    bool groupInside (const juce::String& id, const juce::String& outer) const
    {
        for (const auto* g = groupInfo (id); g != nullptr; g = groupInfo (g->parentId)) if (g->parentId == outer) return true;
        return false;
    }
    // Dragging Arrangement headers, as in the reference: the tracks or group moving, and where they
    // would go: into a group (empty for the top level), before a track or group there.
    struct TrackDrop { juce::String groupId, beforeId; int lineY = -1; };
    juce::StringArray draggedTracks;
    std::optional<TrackDrop> trackDrop;
    // The groups a track or group is inside, outermost first.
    juce::StringArray groupsAround (const juce::String& id) const
    {
        juce::String parent;
        if (const auto* group = groupInfo (id)) parent = group->parentId;
        else if (const auto t = trackIndex (id); t >= 0) parent = state.tracks[(size_t) t].groupId;
        juce::StringArray around;
        for (const auto g : groupPath (parent)) around.add (state.groups[(size_t) g].id);
        return around;
    }
    // Where headers dropped beside a track or group go, as the reference's drop target places them.
    // Before it: in its group, before it. After a folded group's header: into the group, first. After
    // anything else: at the next place, in one of the groups that place can be in, from the deepest
    // one the items either side of it share to the innermost one the item before it is in (an
    // unfolded group's header is in itself, so what follows it goes in, first). Without a nesting
    // level picked that is the innermost; a picked group gives the one a level outward of it, or the
    // outermost if it is not among them. Beside nothing is after the last track. Returns go among
    // the returns only, and other tracks never there.
    std::optional<TrackDrop> dropBeside (const juce::String& itemId, bool after, const juce::String& levelRef, bool returns) const
    {
        std::vector<Item> order;
        for (const auto& item : visualOrder()) if ((! item.group && state.tracks[(size_t) item.index].isReturn) == returns) order.push_back (item);
        const auto idOf = [this] (const Item& item) { return item.group ? state.groups[(size_t) item.index].id : state.tracks[(size_t) item.index].id; };
        if (itemId.isEmpty()) return TrackDrop {};
        int at = -1;
        for (int i = 0; i < (int) order.size(); ++i) if (idOf (order[(size_t) i]) == itemId) at = i;
        if (at < 0) return std::nullopt;
        const auto& item = order[(size_t) at];
        const auto parent = item.group ? state.groups[(size_t) item.index].parentId : state.tracks[(size_t) item.index].groupId;
        if (! after) return TrackDrop { parent, itemId };
        const auto* group = item.group ? &state.groups[(size_t) item.index] : nullptr;
        // An item's id, then the groups around it, innermost first, then the top level.
        const auto path = [&] (int i)
        {
            juce::StringArray chain;
            if (i < (int) order.size())
            {
                chain = groupsAround (idOf (order[(size_t) i]));
                std::reverse (chain.begin(), chain.end());
                chain.insert (0, idOf (order[(size_t) i]));
            }
            chain.add ({}); // Past the last item the only place is the top level's end.
            return chain;
        };
        const auto next = path (at + 1);
        if (group != nullptr && group->folded) return TrackDrop { itemId, next.indexOf (itemId) > 0 ? next[0] : juce::String() };
        // The groups the next place can be in, outermost first.
        juce::StringArray candidates;
        auto before = path (at);
        if (group == nullptr) before.remove (0);
        for (const auto& g : before) { candidates.insert (0, g); if (next.contains (g)) break; }
        const auto picked = levelRef.isEmpty() ? candidates.size() - 1 : candidates.indexOf (levelRef);
        const auto into = candidates[levelRef.isEmpty() ? picked : juce::jmax (0, picked - 1)];
        // Before what follows there, or at the group's end.
        const auto inNext = next.indexOf (into);
        return TrackDrop { into, inNext > 0 ? next[inNext - 1] : juce::String() };
    }
    // Arrangement headers start after a strip for each group around them, outermost first, as the
    // reference's do. The strips pick a drop's nesting level.
    static constexpr int nestingStrip = 5;
    juce::String laneItemId (const Lane& lane) const { return lane.group ? state.groups[(size_t) lane.index].id : state.tracks[(size_t) lane.index].id; }
    // Where dragged headers would land in the Arrangement, as the reference places them: over the
    // upper half of a track or group before it, over the lower half after it (see dropBeside). The
    // pointer over a strip picks that group's level (0x103834258): one group around the item for
    // every 5 pixels from the headers' left edge. Below every lane they go after the last track. A
    // track's automation and take lanes count as the track.
    std::optional<TrackDrop> trackDropAt (juce::Point<int> at, bool returns = false) const
    {
        const int y = at.y, x = at.x - canvas.timelineWidth();
        const auto item = [] (const Lane& lane) { return lane.automation < 0 && lane.take < 0; };
        int returnsY = lanesHeight;
        for (const auto& lane : lanes) if (item (lane) && ! lane.group && state.tracks[(size_t) lane.index].isReturn) { returnsY = lane.y; break; }
        for (size_t i = 0; i < lanes.size(); ++i)
        {
            const auto& lane = lanes[i];
            if (! item (lane) || lane.height <= 0) continue;
            auto next = i + 1;
            while (next < lanes.size() && ! item (lanes[next])) ++next;
            const int bottom = next < lanes.size() ? lanes[next].y : lanesHeight;
            if (y >= bottom) continue;
            if (y < lane.y) return std::nullopt;
            const bool after = y >= (lane.y + bottom) / 2;
            const auto id = laneItemId (lane);
            juce::String level;
            if (const auto around = groupsAround (id); ! returns && x > -nestingStrip && x / nestingStrip < around.size()) level = around[x / nestingStrip];
            auto drop = dropBeside (id, after, level, returns);
            if (drop) drop->lineY = after ? bottom : lane.y;
            return drop;
        }
        return TrackDrop { {}, {}, returns ? lanesHeight : returnsY };
    }
    // Starts or continues dragging headers: the item, or the selected tracks when it is one of them.
    // Whether they are returns, or nothing for a mix of returns and other tracks, which land nowhere.
    std::optional<bool> draggedReturns (const juce::String& id)
    {
        if (draggedTracks.isEmpty())
        {
            const auto selected = selectedTrackIds();
            draggedTracks = selected.contains (id) ? selected : juce::StringArray { id };
        }
        int returns = 0;
        for (const auto& t : state.tracks) if (t.isReturn && draggedTracks.contains (t.id)) ++returns;
        if (returns > 0 && returns < draggedTracks.size()) return std::nullopt;
        return returns > 0;
    }
    // Option on the Mac, Ctrl elsewhere, copies what a drag carries, as the reference's drags do.
    static bool copyModifier (juce::ModifierKeys mods)
    {
       #if JUCE_MAC
        return mods.isAltDown();
       #else
        return mods.isCtrlDown();
       #endif
    }
    // Whether the headers being dragged would be copied, from the copy key at the last drag.
    bool copyingTracks = false;
    // Aims the dragged headers, though a move goes nowhere inside a group being dragged; copies may,
    // as the reference's copying drop allows (0x103274744).
    void aimTrackDrop (std::optional<TrackDrop> drop)
    {
        for (const auto& dragged : draggedTracks)
            if (drop && ! copyingTracks && (drop->groupId == dragged || groupInside (drop->groupId, dragged))) drop.reset();
        trackDrop = drop;
    }
    void dragTracks (const juce::String& id, juce::Point<int> at, bool copy = false)
    {
        canvas.scrollForDrag (at, false);
        copyingTracks = copy;
        const auto returns = draggedReturns (id);
        aimTrackDrop (returns ? trackDropAt (at, *returns) : std::nullopt); canvas.repaint();
    }
    // Pressing a track's header: with Shift the track joins or leaves the selected tracks. Where a
    // drag can start, pressing a track selected with others keeps them all for the drag, and the
    // result says a click without one then selects the track alone. Otherwise it is selected alone.
    bool pressTrackHeader (int index, bool shift, bool draggable)
    {
        const auto& id = state.tracks[(size_t) index].id;
        const bool keep = draggable && ! multiSelectedTracks.empty() && (selectedTrack == index || multiSelectedTracks.contains (id));
        if (shift || keep)
        {
            if (const auto* current = currentTrack(); current != nullptr && current->id != id) multiSelectedTracks.insert (current->id);
            if (shift && ! multiSelectedTracks.erase (id)) multiSelectedTracks.insert (id);
        }
        else multiSelectedTracks.clear();
        selectTrack (index);
        return keep && ! shift;
    }
    void dropTracks()
    {
        if (trackDrop && ! draggedTracks.isEmpty() && copyingTracks)
        {
            juce::StringArray copies;
            const auto result = session.copyTracksTo (draggedTracks, trackDrop->groupId, trackDrop->beforeId, copies);
            report (result); refresh();
            if (result.wasOk()) selectCopies (copies);
        }
        else if (trackDrop && ! draggedTracks.isEmpty())
        {
            const auto result = session.moveTracks (draggedTracks, trackDrop->groupId, trackDrop->beforeId);
            report (result);
            // The reference's move selects the selected track again (0x10242a5fc), which opens the
            // folded group it is in, though not one folded around that.
            if (result.wasOk())
            {
                refresh();
                const auto* group = groupInfo (selectedChain);
                const auto parent = group != nullptr ? group->parentId : currentTrack() != nullptr ? currentTrack()->groupId : juce::String();
                if (const auto* around = groupInfo (parent); around != nullptr && around->folded) session.setGroupFolded (parent, false);
            }
        }
        draggedTracks.clear(); trackDrop.reset(); copyingTracks = false; refresh(); canvas.repaint();
    }
    void buildLanes()
    {
        lanes.clear(); int y = 0;
        for (const auto& item : visualOrder())
        {
            // A header lane for each group, above what is in it; a folded group hides everything
            // inside it, nested groups' headers too.
            if (item.group)
            {
                const auto& group = state.groups[(size_t) item.index];
                const bool hidden = anyFolded (group.parentId);
                lanes.push_back ({ true, item.index, y, hidden ? 0 : groupHeight }); y += hidden ? 0 : groupHeight;
                // A group's automation lanes, below its header, as a track's below it.
                if (automationMode && ! hidden)
                    if (const auto found = automationLanes.find (group.id); found != automationLanes.end())
                        for (int k = 0; k < found->second.size(); ++k) { lanes.push_back ({ true, item.index, y, automationLaneHeight, k }); y += automationLaneHeight; }
                continue;
            }
            const int t = item.index;
            const auto& track = state.tracks[(size_t) t];
            const int height = anyFolded (track.groupId) || (track.isReturn && ! state.arrangementControls.returns) ? 0
                             : track.folded ? foldedTrackHeight : track.height > 0 ? track.height : trackHeight;
            lanes.push_back ({ false, t, y, height }); y += height;
            if (height > 0 && ! track.folded && takeLanesShown.count (track.id))
                for (int k = 0; k < (int) track.takeLanes.size(); ++k) { lanes.push_back ({ false, t, y, takeLaneHeight, -1, k }); y += takeLaneHeight; }
            if (automationMode && height > 0 && ! track.folded)
                if (const auto found = automationLanes.find (track.id); found != automationLanes.end())
                    for (int k = 0; k < found->second.size(); ++k) { lanes.push_back ({ false, t, y, automationLaneHeight, k }); y += automationLaneHeight; }
        }
        lanesHeight = y;
    }
    int laneY (int track) const
    { for (const auto& lane : lanes) if (! lane.group && lane.automation < 0 && lane.take < 0 && lane.index == track) return lane.y; return track * trackHeight; }
    int laneHeight (int track) const
    { for (const auto& lane : lanes) if (! lane.group && lane.automation < 0 && lane.take < 0 && lane.index == track) return lane.height; return trackHeight; }
    // Track heights, as in the reference: the split line under a header drags a track's height, with
    // Option (Alt elsewhere) every track's; Option +/- and Option-scrolling in a lane change it.
    void setTrackHeights (const juce::StringArray& ids, int pixels)
    {
        pixels = juce::jlimit (Session::minimumTrackHeight, Session::maximumTrackHeight, pixels);
        for (const auto& id : ids) report (session.setTrackHeight (id, pixels == trackHeight ? 0 : pixels));
        refresh(); resized(); canvas.repaint();
    }
    juce::StringArray allArrangementTracks() const { juce::StringArray ids; for (const auto& t : state.tracks) ids.add (t.id); return ids; }
    // Folding, as in the reference: a track's triangle folds it to its header strip, with Option/Alt
    // every track.
    static constexpr int foldedTrackHeight = 24;
    void foldTracks (const juce::StringArray& ids, bool folded)
    {
        for (const auto& id : ids) report (session.setTrackFolded (id, folded));
        refresh(); resized(); canvas.repaint();
    }
    // U folds or unfolds the selected tracks, or the selected group's tracks, and Alt+U all of them,
    // as the reference's Fold Selected Track and Expand All Tracks commands do; in the Session view
    // they fold groups' columns.
    void toggleFold (bool every)
    {
        const auto* group = groupInfo (selectedChain);
        const auto* current = showSession ? nullptr : currentTrack();
        if (group == nullptr && current == nullptr && ! (every && ! state.groups.empty())) return;
        const bool fold = group != nullptr ? ! group->folded : current != nullptr ? ! current->folded
                        : std::any_of (state.groups.begin(), state.groups.end(), [] (const auto& g) { return ! g.folded; });
        for (const auto& g : state.groups) if (every || g.id == selectedChain) report (session.setGroupFolded (g.id, fold));
        juce::StringArray ids;
        if (! showSession && every) ids = allArrangementTracks();
        else if (group == nullptr && current != nullptr) { ids.add (current->id); for (const auto& id : multiSelectedTracks) ids.addIfNotAlreadyThere (id); }
        foldTracks (ids, fold);
    }
    void scaleTrackHeight (int track, double factor)
    {
        if (! juce::isPositiveAndBelow (track, (int) state.tracks.size())) return;
        setTrackHeights ({ state.tracks[(size_t) track].id }, (int) std::round (laneHeight (track) * factor));
    }
    // Optimize Height (H) fits every track into the view, and again restores their heights; Optimize
    // Width (W) fits the Arrangement's length into the view, and again restores the zoom.
    std::optional<std::map<juce::String, int>> optimizedHeights;
    std::optional<std::pair<double, double>> optimizedWidth;
    void optimizeHeight()
    {
        if (optimizedHeights)
        {
            for (const auto& [id, height] : *optimizedHeights) report (session.setTrackHeight (id, height));
            optimizedHeights.reset();
        }
        else
        {
            std::map<juce::String, int> saved;
            int fixed = 0, count = 0;
            for (const auto& lane : lanes)
                if (lane.group || lane.automation >= 0 || lane.take >= 0) fixed += lane.height;
                else if (lane.height > 0) ++count;
            for (const auto& t : state.tracks) saved[t.id] = t.height;
            if (count == 0) return;
            const int each = juce::jlimit (Session::minimumTrackHeight, Session::maximumTrackHeight, (viewport.getHeight() - fixed) / count);
            for (const auto& t : state.tracks) report (session.setTrackHeight (t.id, each));
            optimizedHeights = std::move (saved);
        }
        refresh(); resized(); canvas.repaint();
    }
    void optimizeWidth()
    {
        if (optimizedWidth) { viewStart = optimizedWidth->first; pixelsPerSecond = optimizedWidth->second; optimizedWidth.reset(); updateScroll(); canvas.repaint(); ruler.repaint(); return; }
        optimizedWidth = std::pair { viewStart, pixelsPerSecond };
        fitTimeline();
    }
    // The track a time selection takes at a canvas y: the track, or the track an automation lane belongs to.
    int selectionTrackAtY (int y) const
    {
        for (const auto& lane : lanes) if (y >= lane.y && y < lane.y + lane.height && ! lane.group && lane.take < 0) return lane.index;
        return trackAtY (y);
    }
    // Track under a canvas y, -1 for none (including group header lanes).
    int trackAtY (int y) const
    {
        if (y < 0) return -1;
        for (const auto& lane : lanes) if (y >= lane.y && y < lane.y + lane.height) return lane.group || lane.automation >= 0 || lane.take >= 0 ? -1 : lane.index;
        return lanes.empty() && y / trackHeight < (int) state.tracks.size() ? y / trackHeight : -1;
    }
    // What Group Tracks groups: a selected group, with the tracks selected besides it, or the selected tracks.
    juce::StringArray groupingSelection() const
    {
        juce::StringArray ids;
        if (groupInfo (selectedChain) != nullptr) ids.add (selectedChain);
        for (const auto& track : state.tracks)
            if (multiSelectedTracks.contains (track.id) || (ids.isEmpty() && currentTrack() != nullptr && track.id == currentTrack()->id)) ids.add (track.id);
        return ids;
    }
    void groupSelectedTracks()
    {
        juce::String group; report (session.groupTracks (groupingSelection(), group)); multiSelectedTracks.clear(); refresh();
        if (group.isNotEmpty()) selectChain (group);
    }
    // Linked-track editing. The selected tracks, then Link Tracks: with Cmd/Ctrl held, the selection
    // joins the clicked track's link. Selecting time or a clip on a linked track selects the same on
    // the tracks linked to it.
    // The device chain the device view shows: a group's or the Main's (Session::mainChain) once
    // one is clicked, else the selected track's.
    juce::String selectedChain;
    juce::String deviceChainId() const
    {
        if (selectedChain.isNotEmpty()) return selectedChain;
        const auto* track = currentTrack(); return track != nullptr ? track->id : juce::String();
    }
    const std::vector<Session::PluginInfo>* chainDevices() const
    {
        if (selectedChain == Session::mainChain) return &state.mainPlugins;
        if (selectedChain.isNotEmpty()) { const auto* g = groupInfo (selectedChain); return g != nullptr ? &g->plugins : nullptr; }
        const auto* track = currentTrack(); return track != nullptr ? &track->plugins : nullptr;
    }
    juce::String chainTitle() const
    {
        if (selectedChain == Session::mainChain) return "Main";
        if (selectedChain.isNotEmpty()) { const auto* g = groupInfo (selectedChain); return g != nullptr ? g->name : juce::String(); }
        const auto* track = currentTrack(); return track != nullptr ? track->name : juce::String();
    }
    // Shows a group's or the Main's chain in the device view, as clicking its header or strip does.
    void selectChain (const juce::String& id)
    {
        if (id != Session::mainChain && groupInfo (id) == nullptr) return;
        selectedChain = id; selectedDevices.clear();
        deviceChain.sync(); deviceChain.repaint(); canvas.repaint();
    }
    // The reference's headers take the selection focus: after a click on an Arrangement header's name
    // or background, or a Session column's title, Delete deletes the selected tracks, or the selected
    // group with everything in it, and the track now where the first was is selected.
    static constexpr const char* arrangementHeader = "arrangementHeader";
    // A header's track name and own info text, for the Info view.
    static constexpr const char* infoTitleProperty = "infoTitle";
    static constexpr const char* infoTextProperty = "infoText";
    bool headerFocus = false;
    // The area last clicked, which the menu bar's Edit commands act on (see editArea).
    enum class Area { arrangement, session, headers, scenes, notes, devices };
    Area clickedArea = Area::arrangement;
    struct HeaderFocusWatcher final : juce::MouseListener
    {
        explicit HeaderFocusWatcher (Impl& o) : owner (o) { owner.addMouseListener (this, true); }
        ~HeaderFocusWatcher() override { owner.removeMouseListener (this); }
        void mouseDown (const juce::MouseEvent& e) override
        {
            auto* c = e.originalComponent;
            if (c == &owner.launcher)
            {
                owner.headerFocus = owner.launcher.titlePressed();
                owner.clickedArea = owner.headerFocus ? Area::headers : owner.launcher.onScene (e.getEventRelativeTo (&owner.launcher).getPosition()) ? Area::scenes : Area::session;
                return;
            }
            if (c != nullptr && (c->getName() == "Track name" || c->getName() == "Group name")) c = c->getParentComponent();
            owner.headerFocus = c != nullptr && static_cast<bool> (c->getProperties()[arrangementHeader]);
            if (owner.headerFocus) owner.clickedArea = Area::headers;
            else if (within (c, owner.pianoRoll)) owner.clickedArea = Area::notes;
            else if (within (c, owner.deviceChain)) owner.clickedArea = Area::devices;
            else if (within (c, owner.canvas) || within (c, owner.ruler)) owner.clickedArea = Area::arrangement;
            else if (within (c, owner.launcher)) owner.clickedArea = Area::session;
        }
        static bool within (const juce::Component* c, const juce::Component& area) { return c != nullptr && (c == &area || area.isParentOf (c)); }
        Impl& owner;
    } headerFocusWatcher { *this };
    // What the headers' Delete and Duplicate act on: the selected group, or the selected tracks.
    juce::StringArray headerSelection() const
    {
        if (const auto* group = groupInfo (selectedChain)) return { group->id };
        return selectedTrackIds();
    }
    void deleteSelectedHeaders()
    {
        const auto ids = headerSelection();
        int first = selectedTrack;
        if (const auto* group = groupInfo (selectedChain)) first = group->position;
        else for (int t = 0; t < (int) state.tracks.size(); ++t) if (ids.contains (state.tracks[(size_t) t].id)) { first = t; break; }
        // As the reference's Delete is disabled, nothing happens when it would empty a group or the project.
        if (ids.isEmpty() || ! session.canRemoveTracks (ids)) return;
        session.closePluginEditors();
        const auto result = session.removeTracks (ids);
        report (result);
        if (result.failed()) return;
        multiSelectedTracks.clear(); selectedChain.clear(); selectedClip = -1; headerFocus = false;
        refresh();
        if (state.tracks.empty()) selectedTrack = -1;
        else selectTrack (juce::jlimit (0, (int) state.tracks.size() - 1, first));
        refresh();
    }
    juce::StringArray selectedTrackIds() const
    {
        juce::StringArray ids;
        for (const auto& track : state.tracks) if (multiSelectedTracks.contains (track.id) || (currentTrack() != nullptr && track.id == currentTrack()->id)) ids.add (track.id);
        return ids;
    }
    // The pan controls' context menu, as the reference's: one item, switching the pan mode of every
    // selected track when the clicked one is among them.
    static juce::PopupMenu panModeItems (bool split)
    {
        juce::PopupMenu menu;
        menu.addItem (1, split ? "Split Stereo Pan Mode" : "Stereo Pan Mode");
        return menu;
    }
    void panModeMenu (const juce::String& trackId, bool split)
    { panModeItems (split).showMenuAsync (juce::PopupMenu::Options(), [this, trackId, split] (int chosen) { if (chosen == 1) choosePanMode (trackId, split); }); }
    void groupPanModeMenu (const juce::String& groupId, bool split)
    {
        panModeItems (split).showMenuAsync (juce::PopupMenu::Options(), [this, groupId, split] (int chosen)
        { if (chosen == 1) { report (session.setPanMode ({ groupId }, split)); refresh(); } });
    }
    void choosePanMode (const juce::String& trackId, bool split)
    {
        auto ids = selectedTrackIds();
        if (! ids.contains (trackId)) ids = { trackId };
        report (session.setPanMode (ids, split)); refresh();
    }
    void linkSelectedTracks (bool joinClickedLink)
    {
        auto ids = selectedTrackIds();
        if (joinClickedLink && currentTrack() != nullptr && currentTrack()->linkId.isNotEmpty())
            for (const auto& track : state.tracks) if (track.linkId == currentTrack()->linkId) ids.addIfNotAlreadyThere (track.id);
        juce::String link; report (session.linkTracks (ids, link)); multiSelectedTracks.clear(); refresh();
    }
    void unlinkSelectedTracks() { report (session.unlinkTracks (selectedTrackIds())); multiSelectedTracks.clear(); refresh(); }
    void addLinkedTracks (juce::StringArray& ids) const
    {
        for (int i = 0; i < ids.size(); ++i)
            if (const auto t = trackIndex (ids[i]); t >= 0 && state.tracks[(size_t) t].linkId.isNotEmpty())
                for (const auto& other : state.tracks) if (other.linkId == state.tracks[(size_t) t].linkId) ids.addIfNotAlreadyThere (other.id);
    }
    void selectLinkedTracks (const juce::String& link)
    {
        multiSelectedTracks.clear();
        for (const auto& track : state.tracks) if (track.linkId == link) multiSelectedTracks.insert (track.id);
        canvas.repaint(); for (int i = 0; i < canvas.getNumChildComponents(); ++i) canvas.getChildComponent (i)->repaint();
    }
    bool linkedToSelectedClip (int t, const Session::ClipInfo& clip) const
    {
        const auto* selected = currentTrack();
        if (selected == nullptr || selected->linkId.isEmpty() || t == selectedTrack || ! juce::isPositiveAndBelow (selectedClip, (int) selected->clips.size())
            || state.tracks[(size_t) t].linkId != selected->linkId) return false;
        const auto& chosen = selected->clips[(size_t) selectedClip];
        return std::abs (clip.start - chosen.start) < .001 && std::abs (clip.start + clip.length - chosen.start - chosen.length) < .001;
    }
    juce::String hoveredLink; // The link whose indicator is under the pointer; its tracks are outlined.
    // Ungroup Tracks acts on a selected group, as the reference's is enabled only with one selected.
    void ungroupSelectedTrack()
    {
        if (groupInfo (selectedChain) == nullptr) return;
        report (session.ungroupTracks (selectedChain)); selectedChain.clear();
        refresh();
    }
    static constexpr int minimumClipViewHeight = 340, dividerHeight = 5;
    double clipViewFraction = .58;
    juce::Rectangle<int> dividerBounds;
    static constexpr float automationMagnet = 6; // How near a grid line, in pixels, a breakpoint snaps to it.
    static constexpr int categoryWidth = 98, trackWidth = 252, trackHeight = 72, rulerHeight = 60,
                         deviceHeight = 268, statusHeight = 24;
    struct BrowserItem { juce::File file; bool directory = false, found = false; }; // found: a search result from the index.
    struct FolderScan
    {
        struct Entry { std::string name; bool directory = false; };
        std::atomic<bool> cancelled { false }, finished { false };
        std::mutex mutex;
        std::vector<Entry> entries;
        std::string error;
    };

    enum class BrowserCategory { instruments, audioEffects, midiEffects, plugins, samples, grooves, templates, packs, collection, place };
    // Left column of the browser, as the reference's sidebar: the collections, the Library's
    // categories, then Places: Packs, the User Library, the Current Project, the folders added, and
    // Add Folder. It scrolls inside the browser when taller.
    class BrowserCategories final : public juce::Component
    {
    public:
        explicit BrowserCategories (Impl& o) : owner (o) { setName ("Browser categories"); }
        int contentHeight() const { return placeBounds (placeRows()).getBottom() + 6; }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff272727));
            g.setColour (muted); g.setFont (font (9.5f, true));
            g.drawText ("COLLECTIONS", 6, 0, getWidth() - 8, headerHeight, juce::Justification::centredLeft);
            g.drawText ("LIBRARY", 6, categoriesTop() - headerHeight, getWidth() - 8, headerHeight, juce::Justification::centredLeft);
            g.drawText ("PLACES", 6, placesTop() - headerHeight, getWidth() - 8, headerHeight, juce::Justification::centredLeft);
            // A place being scanned spins beside the label, as the reference's does.
            if (owner.placeIndexing())
            {
                const auto x = 6.0f + juce::GlyphArrangement::getStringWidth (g.getCurrentFont(), "PLACES") + 9.0f, y = (float) (placesTop() - headerHeight / 2);
                const auto turn = (float) std::fmod (juce::Time::getMillisecondCounterHiRes() / 1000.0, 1.0) * juce::MathConstants<float>::twoPi;
                juce::Path arc; arc.addCentredArc (x, y, 3.5f, 3.5f, turn, 0.0f, juce::MathConstants<float>::pi * 1.5f, true);
                g.strokePath (arc, juce::PathStrokeType (1.4f));
            }
            for (int i = 0; i < Collections::count; ++i)
            {
                const auto row = collectionBounds (i);
                const bool selected = owner.browserCategory == BrowserCategory::collection && owner.browserCollection == i;
                if (selected) { g.setColour (raised); g.fillRect (row); }
                g.setColour (Collections::colour (i)); g.fillEllipse ((float) row.getX() + 8, (float) row.getCentreY() - 3, 6, 6);
                g.setColour (selected ? orange : ink.withAlpha (0.85f)); g.setFont (font (11.0f, selected));
                g.drawText (Collections::name (i), row.withTrimmedLeft (20), juce::Justification::centredLeft, true);
            }
            const auto drawRow = [&] (juce::Rectangle<int> row, const juce::String& text, bool selected, bool available)
            {
                if (selected) { g.setColour (raised); g.fillRect (row); }
                g.setColour (selected ? orange : available ? ink.withAlpha (0.85f) : muted.withAlpha (0.7f)); g.setFont (font (11.0f, selected));
                g.drawText (text, row.withTrimmedLeft (8), juce::Justification::centredLeft, true);
            };
            for (int i = 0; i < (int) entries.size(); ++i)
                drawRow (rowBounds (i), entries[(size_t) i].second, owner.browserCategory == entries[(size_t) i].first, true);
            drawRow (placeBounds (0), "Packs", owner.browserCategory == BrowserCategory::packs, true);
            for (int place = 0; place < owner.placeCount(); ++place)
                drawRow (placeBounds (place + 1), owner.placeName (place), owner.browserCategory == BrowserCategory::place && owner.browserPlace == place, owner.placeAvailable (place));
            drawRow (placeBounds (placeRows()), "Add Folder...", false, true);
            g.setColour (line); g.drawVerticalLine (getWidth() - 1, 0.0f, (float) getHeight());
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            const auto at = e.getPosition();
            for (int i = 0; i < Collections::count; ++i) if (collectionBounds (i).contains (at)) { owner.leavePlace(); owner.showBrowserCollection (i); return; }
            for (int i = 0; i < (int) entries.size(); ++i) if (rowBounds (i).contains (at)) { owner.leavePlace(); owner.setBrowserCategory (entries[(size_t) i].first); return; }
            if (placeBounds (0).contains (at)) { owner.leavePlace(); owner.setBrowserCategory (BrowserCategory::packs); return; }
            for (int place = 0; place < owner.placeCount(); ++place)
                if (placeBounds (place + 1).contains (at)) { if (e.mods.isPopupMenu()) owner.placeMenu (place); else owner.showPlace (place); return; }
            if (placeBounds (placeRows()).contains (at)) owner.addFolderToBrowser();
        }
        juce::Point<int> collectionPoint (int collection) const { return collectionBounds (collection).getCentre(); }
        juce::Point<int> categoryPoint (BrowserCategory category) const
        {
            if (category == BrowserCategory::packs) return placeBounds (0).getCentre();
            for (int i = 0; i < (int) entries.size(); ++i) if (entries[(size_t) i].first == category) return rowBounds (i).getCentre();
            return {};
        }
        juce::Point<int> placePoint (int place) const { return placeBounds (place + 1).getCentre(); }
        juce::Point<int> addFolderPoint() const { return placeBounds (placeRows()).getCentre(); }
    private:
        static constexpr int headerHeight = 20, rowHeight = 22;
        int categoriesTop() const { return headerHeight + Collections::count * rowHeight + 6 + headerHeight; }
        int placesTop() const { return categoriesTop() + (int) entries.size() * rowHeight + 6 + headerHeight; }
        // Packs, then a row per place; Add Folder follows them.
        int placeRows() const { return 1 + owner.placeCount(); }
        juce::Rectangle<int> collectionBounds (int i) const { return { 0, headerHeight + i * rowHeight, getWidth() - 1, rowHeight }; }
        juce::Rectangle<int> rowBounds (int i) const { return { 0, categoriesTop() + i * rowHeight, getWidth() - 1, rowHeight }; }
        juce::Rectangle<int> placeBounds (int i) const { return { 0, placesTop() + i * rowHeight, getWidth() - 1, rowHeight }; }
        Impl& owner;
        const std::array<std::pair<BrowserCategory, const char*>, 7> entries {{ { BrowserCategory::instruments, "Instruments" },
            { BrowserCategory::audioEffects, "Audio Effects" }, { BrowserCategory::midiEffects, "MIDI Effects" },
            { BrowserCategory::plugins, "Plug-Ins" }, { BrowserCategory::samples, "Samples" }, { BrowserCategory::grooves, "Grooves" },
            { BrowserCategory::templates, "Templates" } }};
    };

    // A linked track's header indicator: hovering outlines the tracks in its link; clicking selects them.
    class LinkIndicator final : public juce::Component, public juce::SettableTooltipClient
    {
    public:
        std::function<void()> onClick;
        std::function<void (bool)> onHover;
        void paint (juce::Graphics& g) override
        {
            // Two chain links side by side.
            const auto r = getLocalBounds().toFloat().reduced (2.0f, 5.0f);
            const auto w = r.getWidth() * .62f, h = r.getHeight();
            g.setColour (isMouseOver() ? themes::colour (0xffffffff) : themes::colour (0xff141414));
            g.drawRoundedRectangle ({ r.getX(), r.getY(), w, h }, h / 2, 1.6f);
            g.drawRoundedRectangle ({ r.getRight() - w, r.getY(), w, h }, h / 2, 1.6f);
        }
        void mouseEnter (const juce::MouseEvent&) override { if (onHover) onHover (true); repaint(); }
        void mouseExit (const juce::MouseEvent&) override { if (onHover) onHover (false); repaint(); }
        void mouseUp (const juce::MouseEvent& e) override { if (onClick != nullptr && getLocalBounds().contains (e.getPosition())) onClick(); }
    };
    // Input monitoring, as the reference's mixer shows it: three switches, In, Auto and Off, one lit.
    class MonitorSwitch final : public juce::Component
    {
    public:
        MonitorSwitch()
        {
            setName ("Track monitoring");
            const std::array<std::pair<juce::TextButton*, Session::MonitorMode>, 3> choices { { { &in, Session::MonitorMode::on }, { &automatic, Session::MonitorMode::automatic }, { &off, Session::MonitorMode::off } } };
            for (const auto& [button, choice] : choices)
            {
                addAndMakeVisible (button); button->setWantsKeyboardFocus (false); button->setMouseClickGrabsKeyboardFocus (false);
                button->setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); button->setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
                button->onClick = [this, choice = choice] { if (choice != mode && onChange) onChange (choice); };
            }
            in.setName ("Monitor In"); automatic.setName ("Monitor Auto"); off.setName ("Monitor Off");
            in.setTooltip ("Monitor In: always hear the track's input");
            automatic.setTooltip ("Monitor Auto: hear the input while the track is armed and no clip plays");
            off.setTooltip ("Monitor Off: never hear the input; record it only");
        }
        std::function<void (Session::MonitorMode)> onChange;
        void setMode (Session::MonitorMode m)
        {
            mode = m;
            in.setToggleState (m == Session::MonitorMode::on, juce::dontSendNotification);
            automatic.setToggleState (m == Session::MonitorMode::automatic, juce::dontSendNotification);
            off.setToggleState (m == Session::MonitorMode::off, juce::dontSendNotification);
        }
        Session::MonitorMode getMode() const noexcept { return mode; }
        void setEnabledSwitches (bool enabled) { for (auto* b : { &in, &automatic, &off }) b->setEnabled (enabled); }
        void resized() override
        {
            auto area = getLocalBounds();
            const int width = area.getWidth() / 3;
            in.setBounds (area.removeFromLeft (width)); automatic.setBounds (area.removeFromLeft (width)); off.setBounds (area);
        }
    private:
        juce::TextButton in { "In" }, automatic { "Auto" }, off { "Off" };
        Session::MonitorMode mode = Session::MonitorMode::off;
    };
    // Automation Mode's device and control choosers, in a track's header or a group's: the mixer or
    // device whose envelope the lane shows, and its control. A dot marks the automated ones.
    struct AutomationChoosers
    {
        AutomationChoosers (Impl& o, juce::Component& parent) : owner (o)
        {
            parent.addChildComponent (device); parent.addChildComponent (control);
            device.setName ("Automation device"); control.setName ("Automation control");
            device.setTooltip ("The mixer or device whose automation this track shows");
            control.setTooltip ("The control whose envelope this track shows; a dot marks automated controls");
            control.onChange = [this]
            {
                const auto item = control.getSelectedId() - 1;
                if (juce::isPositiveAndBelow (item, (int) controlKeys.size())) owner.showAutomationKey (id, controlKeys[(size_t) item]);
            };
        }
        void setVisible (bool visible) { device.setVisible (visible); control.setVisible (visible); }
        // Fills the choosers for a track, or a group seen as one; whether an envelope is shown.
        bool sync (const Session::TrackInfo& view)
        {
            id = view.id;
            targets = arrangementAutomation::targets (owner.session, view, owner.state.tracks);
            shownKey = owner.shownKey (view);
            const arrangementAutomation::Target* shown = nullptr;
            for (const auto& t : targets) if (t.key == shownKey) shown = &t;
            juce::StringArray devices; std::set<juce::String> automatedDevices;
            for (const auto& t : targets) { devices.addIfNotAlreadyThere (t.device); if (! t.lane.points.empty()) automatedDevices.insert (t.device); }
            const auto shownDevice = shown != nullptr ? shown->device : juce::String ("None");
            juce::String signature; for (const auto& d : devices) signature << d << (automatedDevices.count (d) ? "*" : "") << ";";
            if (signature != deviceSignature)
            {
                deviceSignature = signature; device.clear (juce::dontSendNotification);
                for (int i = 0; i < devices.size(); ++i) device.addItem ((automatedDevices.count (devices[i]) ? juce::String (juce::CharPointer_UTF8 ("\xe2\x80\xa2 ")) : juce::String()) + devices[i], i + 1);
                device.addItem ("None", devices.size() + 1);
            }
            const auto deviceIndex = devices.indexOf (shownDevice);
            device.setSelectedId (deviceIndex >= 0 ? deviceIndex + 1 : devices.size() + 1, juce::dontSendNotification);
            // The chooser's text carries the automated dot, so match the plain name when it changes.
            device.onChange = [this, devices]
            {
                const auto item = device.getSelectedId() - 1;
                if (! juce::isPositiveAndBelow (item, devices.size())) { owner.showAutomationKey (id, "none"); return; }
                for (const auto& t : targets) if (t.device == devices[item]) { owner.showAutomationKey (id, t.key); return; }
            };
            std::vector<juce::String> keys; juce::StringArray labels;
            for (const auto& t : targets)
                if (t.device == shownDevice) { keys.push_back (t.key); labels.add ((t.lane.points.empty() ? juce::String() : juce::String (juce::CharPointer_UTF8 ("\xe2\x80\xa2 "))) + t.control); }
            if (keys != controlKeys || labels != controlLabels)
            {
                controlKeys = keys; controlLabels = labels; control.clear (juce::dontSendNotification);
                for (int i = 0; i < labels.size(); ++i) control.addItem (labels[i], i + 1);
            }
            const auto at = std::find (controlKeys.begin(), controlKeys.end(), shownKey);
            control.setSelectedId (at != controlKeys.end() ? (int) std::distance (controlKeys.begin(), at) + 1 : 0, juce::dontSendNotification);
            control.setEnabled (shown != nullptr);
            return shown != nullptr;
        }
        Impl& owner;
        juce::ComboBox device, control;
        std::vector<arrangementAutomation::Target> targets;
        std::vector<juce::String> controlKeys;
        juce::StringArray controlLabels;
        juce::String shownKey, deviceSignature, id;
    };
    // A choice in an Audio To chooser: an output, or Configure... (see outputChoices).
    static constexpr int configureOutputItem = 9000;
    struct OutputChoice { juce::String label; std::optional<Session::TrackOutput> output; bool separatorBefore = false; };
    class TrackRow final : public juce::Component
    {
    public:
        TrackRow (Impl& o, int i, bool verticalLayout = false) : owner (o), index (i), trackId (o.state.tracks[(size_t)i].id), columnLayout (verticalLayout)
        {
            for (auto* c : std::initializer_list<juce::Component*> { &name, &mute, &solo, &arm, &gain, &pan, &input, &monitor, &sendMode }) addAndMakeVisible (c);
            addChildComponent (inputDetail); inputDetail.setName ("Track input channel");
            getProperties().set (arrangementHeader, ! columnLayout);
            name.setName ("Track name");
            name.setFont (font (11.5f, true));
            if (! columnLayout) name.setColour (juce::Label::textColourId, themes::colour (0xff141414));
            name.setEditable (false, true, false);
            name.onTextChange = [this] { owner.report (owner.session.renameTrack (index, name.getText())); };
            name.setTooltip ("Double-click to rename this track");
            addChildComponent (link); link.setName ("Linked track");
            link.setTooltip ("Linked track: edits apply to the tracks linked to it. Point at it to see them; click to select them.");
            link.onClick = [this] { owner.selectLinkedTracks (linkId); };
            link.onHover = [this] (bool over)
            {
                owner.hoveredLink = over ? linkId : juce::String();
                if (auto* parent = getParentComponent()) parent->repaint();
            };
            for (auto* button : { &mute, &solo, &arm })
            {
                button->setClickingTogglesState (true);
                button->setWantsKeyboardFocus (false);
                button->setMouseClickGrabsKeyboardFocus (false);
            }
            // The numbered track activator is lit while the track is audible.
            mute.onClick = [this] { owner.selectTrack (index); owner.report (owner.session.setTrackMute (index, ! mute.getToggleState())); };
            solo.onClick = [this] { owner.selectTrack (index); owner.soloFromUI (index, {}, solo.getToggleState(), juce::ModifierKeys::getCurrentModifiers().isCommandDown()); };
            arm.onClick = [this] { owner.selectTrack (index); owner.armFromUI (index, arm.getToggleState(), juce::ModifierKeys::getCurrentModifiers().isCommandDown()); };
            mute.setTooltip ("Track activator: click to mute or unmute"); solo.setTooltip ("Solo track"); arm.setTooltip ("Arm track for audio recording");
            mute.setName ("Track activator"); solo.setName ("Track solo");
            mute.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); mute.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            solo.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xff57a7ff)); solo.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            arm.setName ("Record arm"); input.setName ("Track audio input");
            sendMode.setName ("Return send position");
            sendMode.addItem ("Pre-fader", 1); sendMode.addItem ("Post-fader", 2);
            sendMode.setTooltip ("All sends into this return are taken before or after their source track volume fader.");
            sendMode.onChange = [this]
            {
                if (! returnTrack || index >= (int) owner.state.tracks.size()) return;
                owner.report (owner.session.setReturnSendMode (owner.state.tracks[(size_t) index].id,
                    sendMode.getSelectedId() == 1 ? Session::SendMode::pre : Session::SendMode::post));
                owner.refresh();
            };
            arm.setColour (juce::TextButton::buttonOnColourId, red);
            gain.setSliderStyle (juce::Slider::LinearHorizontal);
            gain.setName ("Track volume"); gain.setNormalisableRange (Session::levelRange (false));
            gain.setTextBoxStyle (juce::Slider::TextBoxRight, false, 50, 18);
            gain.textFromValueFunction = [] (double value) { return value <= -100 ? juce::String ("-inf") : juce::String (value, 1) + " dB"; };
            gain.valueFromTextFunction = [this] (juce::String text)
            {
                text = text.trim(); if (text.endsWithIgnoreCase ("dB")) text = text.dropLastCharacters (2).trim();
                if (text.equalsIgnoreCase ("-inf")) return -100.0;
                const auto input = text.toStdString(); char* end = nullptr; const auto value = std::strtod (input.c_str(), &end);
                return !input.empty() && end == input.c_str() + input.size() && std::isfinite (value) ? value : gain.getValue();
            };
            gain.setTooltip ("Track volume. Double-click to reset to 0 dB.");
            gain.onDragStart = [this] { owner.session.beginEditGesture ("Track volume"); };
            gain.onDragEnd = [this] { owner.session.endEditGesture(); };
            gain.onValueChange = [this] { owner.report (owner.session.setTrackGain (index, (float) gain.getValue())); };
            pan.setSliderStyle (juce::Slider::LinearHorizontal);
            pan.setName ("Track pan"); pan.setRange (-1.0, 1.0, 0.01);
            pan.setTextBoxStyle (juce::Slider::TextBoxRight, false, 32, 18);
            pan.textFromValueFunction = [] (double v) { return Session::panText ((float) v); };
            pan.valueFromTextFunction = [] (const juce::String& value) { return (double) Session::panFromText (value); };
            pan.setTooltip ("Track pan. Double-click to center.");
            pan.onDragStart = [this] { owner.session.beginEditGesture ("Track pan"); };
            pan.onDragEnd = [this] { owner.session.endEditGesture(); };
            pan.onValueChange = [this] { owner.report (owner.session.setTrackPan (index, (float) pan.getValue())); };
            // In Split Stereo pan mode two sliders pan the left and right channels in place of the pan.
            for (auto* split : { &leftSplit, &rightSplit })
            {
                addChildComponent (*split);
                const bool right = split == &rightSplit;
                split->setName (right ? "Right split pan" : "Left split pan");
                split->setSliderStyle (juce::Slider::LinearBar); split->setRange (-1.0, 1.0, 0.01);
                split->setColour (juce::Slider::trackColourId, themes::colour (0xff4a4a4a));
                split->textFromValueFunction = [] (double v) { return Session::panText ((float) v); };
                split->valueFromTextFunction = [] (const juce::String& value) { return (double) Session::panFromText (value); };
                split->updateText();
                split->onDragStart = [this, right] { owner.session.beginEditGesture (right ? "Right split pan" : "Left split pan"); };
                split->onDragEnd = [this] { owner.session.endEditGesture(); };
                split->onValueChange = [this, split, right] { owner.report (owner.session.setTrackSplitPan (index, right, (float) split->getValue())); };
            }
            for (auto* label : { &leftLabel, &rightLabel })
            { addChildComponent (*label); label->setFont (font (9.5f)); label->setJustificationType (juce::Justification::centred); label->setColour (juce::Label::textColourId, muted); }
            // Track Delay, in milliseconds; negative values play the track early. In the Arrangement it shows
            // with View > Arrangement Track Controls > Track Options.
            if (columnLayout) addAndMakeVisible (delay); else addChildComponent (delay);
            delay.setName ("Track delay");
            delay.setSliderStyle (juce::Slider::LinearBar); delay.setRange (-Session::maximumTrackDelayMs, Session::maximumTrackDelayMs, .1);
            delay.setDoubleClickReturnValue (true, 0); delay.setWantsKeyboardFocus (false);
            delay.setColour (juce::Slider::trackColourId, themes::colour (0xff4a4a4a)); delay.setColour (juce::Slider::textBoxTextColourId, ink);
            delay.textFromValueFunction = [] (double v) { return juce::String (v, 1) + " ms"; };
            delay.valueFromTextFunction = [] (const juce::String& text) { return text.retainCharacters ("-.0123456789").getDoubleValue(); };
            delay.setTooltip ("Track delay: positive values play this track later, negative values earlier. Double-click for 0 ms.");
            delay.onDragStart = [this] { owner.session.beginEditGesture ("Track delay"); };
            delay.onDragEnd = [this] { owner.session.endEditGesture(); };
            delay.onValueChange = [this] { owner.report (owner.session.setTrackDelay (trackId, delay.getValue())); };
            delay.updateText();
            if (columnLayout)
            {
                // Audio To: Master, Sends Only (only the sends are heard) or another audio track.
                addAndMakeVisible (output); output.setName ("Track output");
                output.setTooltip ("Audio To: where this track plays. With Sends Only, only its sends are heard.");
                output.onChange = [this]
                {
                    const int item = output.getSelectedId();
                    Session::TrackOutput chosen;
                    if (item >= firstPortItem)
                    {
                        // MIDI To: a port and channel.
                        const int port = (item - firstPortItem) / 16;
                        if (! juce::isPositiveAndBelow (port, outputPorts.size())) return;
                        chosen = { Session::OutputKind::midiPort, {}, outputPorts[port], (item - firstPortItem) % 16 + 1 };
                    }
                    else if (midiTo) chosen.kind = Session::OutputKind::master; // No Output.
                    else { owner.chooseOutput (trackId, output, outputChoiceList); return; }
                    owner.report (owner.session.setTrackOutput (trackId, chosen)); owner.refresh();
                };
                gain.setSliderStyle (juce::Slider::LinearVertical); gain.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 54, 16);
                pan.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag); pan.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 42, 15);
                pan.setRotaryParameters (juce::MathConstants<float>::pi * 1.25f, juce::MathConstants<float>::pi * 2.75f, true);
                name.setVisible (false); // The column title bar names the track.
            }
            gain.updateText(); pan.updateText(); // Text boxes predate their formatters.
            monitor.onChange = [this] (Session::MonitorMode mode) { owner.report (owner.session.setTrackMonitor (index, mode)); owner.refresh(); };
            // As the reference's In/Out section: Audio From or MIDI From chooses the source (No Input,
            // the audio interface's inputs as Ext. In, a MIDI input, or another track), and the chooser
            // under it its channel, a source track's tap, or the MIDI channel.
            input.onChange = [this]
            {
                const int item = input.getSelectedId();
                if (item >= firstSourceItem && item - firstSourceItem < inputSourceIds.size())
                    owner.report (owner.session.setTrackInputTrack (trackId, inputSourceIds[item - firstSourceItem], Session::InputTap::postMixer));
                else if (item <= 1) owner.report (owner.session.setTrackInput (index, {}));
                else if (! midi) owner.report (owner.session.setTrackInput (index, inputNames.contains (lastExternalInput) ? lastExternalInput : inputNames[0])); // Ext. In
                else owner.report (owner.session.setTrackInput (index, inputNames[item - 2]));
                owner.refresh();
            };
            inputDetail.onChange = [this]
            {
                const int item = inputDetail.getSelectedId();
                if (item <= 0) return;
                if (midi) owner.report (owner.session.setTrackInputChannel (index, item - 1));
                else if (sourceTrack.isNotEmpty()) owner.report (owner.session.setTrackInputTrack (trackId, sourceTrack, static_cast<Session::InputTap> (item - 1)));
                else owner.report (owner.session.setTrackInput (index, inputNames[item - 2]));
                owner.refresh();
            };
            input.setTooltip ("Choose an input before arming. Each input is assigned to one track; choosing it here moves its previous assignment.");
            inputDetail.setTooltip ("The input's channels, the source track's tap, or the MIDI channel to take");
            if (! columnLayout)
            {
                // Automation Mode's choosers, and the button that moves the envelope into a lane.
                addChildComponent (automationLane); automationLane.setName ("Show automation in lane");
                automationLane.setTooltip ("Move this envelope into its own lane below the track");
                automationLane.setWantsKeyboardFocus (false);
                automationLane.onClick = [this] { owner.addAutomationLane (trackId, choosers.shownKey); };
            }
        }
        const juce::String& getTrackId() const { return trackId; }
        void beginRename() { name.showEditor(); }
        void sync (const Session::TrackInfo& track, int position)
        {
            jassert (trackId == track.id);
            index = position;
            getProperties().set (infoTitleProperty, track.name); getProperties().set (infoTextProperty, track.infoText); // For the Info view.
            if (folded != track.folded) { folded = track.folded; repaint(); }
            colour = track.colour;
            midi = track.isMidi; returnTrack = track.isReturn;
            if (linkId != track.linkId) { linkId = track.linkId; resized(); }
            link.setVisible (! columnLayout && linkId.isNotEmpty());
            input.setVisible (! returnTrack); monitor.setVisible (! returnTrack); arm.setVisible (! returnTrack);
            inputDetail.setVisible (! returnTrack && inputDetailShown);
            input.setName (midi ? "Track MIDI input" : "Track audio input");
            sendMode.setVisible (returnTrack);
            sendMode.setSelectedId (track.sendMode == Session::SendMode::pre ? 1 : 2, juce::dontSendNotification);
            peakL = track.peakL; peakR = track.peakR;
            if (! name.isBeingEdited()) name.setText (track.name, juce::dontSendNotification);
            if (! gain.isMouseButtonDown()) gain.setValue (track.gainDb, juce::dontSendNotification);
            if (! pan.isMouseButtonDown()) pan.setValue (track.pan, juce::dontSendNotification);
            if (! leftSplit.isMouseButtonDown()) leftSplit.setValue (track.leftSplitPan, juce::dontSendNotification);
            if (! rightSplit.isMouseButtonDown()) rightSplit.setValue (track.rightSplitPan, juce::dontSendNotification);
            if (splitPan != track.splitPan) { splitPan = track.splitPan; showPans (pan.isVisible() || leftSplit.isVisible()); resized(); }
            gain.setEnabled (! owner.session.isExporting()); pan.setEnabled (! owner.session.isExporting());
            leftSplit.setEnabled (! owner.session.isExporting()); rightSplit.setEnabled (! owner.session.isExporting());
            leftSplit.getProperties().set ("midiMapTarget", "mixer:" + track.id + ":leftsplit"); rightSplit.getProperties().set ("midiMapTarget", "mixer:" + track.id + ":rightsplit");
            showAutomationState (leftSplit, track.leftSplitAutomation, "Left Split Stereo: pans the left channel. Double-click for hard left.", "Left Split Stereo");
            showAutomationState (rightSplit, track.rightSplitAutomation, "Right Split Stereo: pans the right channel. Double-click for hard right.", "Right Split Stereo");
            leftSplit.setTitle (track.name + " left split stereo pan"); rightSplit.setTitle (track.name + " right split stereo pan");
            showAutomationState (gain, track.volumeAutomation, "Track volume. Double-click to reset to 0 dB.", "Volume");
            gain.getProperties().set ("midiMapTarget", "mixer:" + track.id + ":volume"); pan.getProperties().set ("midiMapTarget", "mixer:" + track.id + ":pan");
            showAutomationState (pan, track.panAutomation, "Track pan. Double-click to center.", "Pan");
            mute.setToggleState (! track.mute, juce::dontSendNotification);
            mute.setButtonText (track.numberLabel); // Its number, or a return's letter, as the reference's activator shows.
            solo.setToggleState (track.solo, juce::dontSendNotification);
            // In Cue mode the switch cues the track, as the reference's does.
            solo.setButtonText (owner.state.cueMode ? "C" : "S");
            solo.setTooltip (owner.state.cueMode ? "Cue track: hear it on Cue Out from before its fader" : "Solo track");
            arm.setToggleState (track.armed, juce::dontSendNotification);
            // An auto-armed track shows a lighter arm, as it follows the selection.
            arm.setColour (juce::TextButton::buttonOnColourId, track.autoArmed ? red.withAlpha (.55f) : red);
            arm.setTooltip (track.autoArmed ? juce::String ("Armed because it is selected (Auto-Arm). Click to arm or disarm it by hand.")
                                            : juce::String (midi ? "Arm track for MIDI recording" : "Arm track for audio recording"));
            for (auto [button, name] : { std::pair { &mute, "mute" }, std::pair { &solo, "solo" }, std::pair { &arm, "arm" } })
                button->getProperties().set ("midiMapTarget", returnTrack ? juce::String() : "track:" + track.id + ":" + name);
            // Screen readers speak each control with its track's name.
            mute.setTitle (track.name + " track activator"); solo.setTitle (track.name + " solo"); arm.setTitle (track.name + " arm");
            gain.setTitle (track.name + " volume"); pan.setTitle (track.name + " pan"); delay.setTitle (track.name + " track delay");
            input.setTitle (track.name + " input"); monitor.setTitle (track.name + " monitoring"); output.setTitle (track.name + " output");
            sendMode.setTitle (track.name + " send position");
            if (sideA != nullptr) { sideA->setTitle (track.name + " crossfader A"); sideB->setTitle (track.name + " crossfader B"); }
            auto names = owner.session.inputNames (midi);
            // Audio From another track: the tracks this one may take audio from, by name.
            juce::StringArray sources, sourceLabels;
            if (! midi && ! returnTrack)
                for (const auto& id : owner.session.inputSources (track.id))
                    for (const auto& other : owner.state.tracks) if (other.id == id) { sources.add (id); sourceLabels.add (other.name); }
            if (names != inputNames || sourceLabels != inputSourceLabels || midi != inputIsMidi)
            {
                inputNames = names; inputSourceLabels = sourceLabels; inputIsMidi = midi;
                input.clear (juce::dontSendNotification);
                input.addItem ("No Input", 1);
                // The engine's All MIDI Ins is the reference's All Ins.
                if (midi) for (int n = 0; n < inputNames.size(); ++n) input.addItem (inputNames[n] == "All MIDI Ins" ? juce::String ("All Ins") : inputNames[n], n + 2);
                else if (! inputNames.isEmpty()) input.addItem ("Ext. In", 2);
                for (int n = 0; n < sourceLabels.size(); ++n) input.addItem (sourceLabels[n], firstSourceItem + n);
            }
            inputSourceIds = sources;
            sourceTrack = track.inputTrackId.isNotEmpty() && sources.contains (track.inputTrackId) ? track.inputTrackId : juce::String();
            int selected = 1;
            if (sourceTrack.isNotEmpty()) selected = firstSourceItem + sources.indexOf (sourceTrack);
            else if (track.inputName.isNotEmpty() && inputNames.contains (track.inputName)) selected = midi ? inputNames.indexOf (track.inputName) + 2 : 2;
            if (! midi && selected == 2) lastExternalInput = track.inputName;
            input.setSelectedId (selected, juce::dontSendNotification);
            // The chooser under it, rebuilt only when what it offers changes.
            const juce::StringArray detailItems = midi ? juce::StringArray { "All Channels", "Ch. 1", "Ch. 2", "Ch. 3", "Ch. 4", "Ch. 5", "Ch. 6", "Ch. 7", "Ch. 8",
                                                                             "Ch. 9", "Ch. 10", "Ch. 11", "Ch. 12", "Ch. 13", "Ch. 14", "Ch. 15", "Ch. 16" }
                                                 : sourceTrack.isNotEmpty() ? juce::StringArray { "Pre FX", "Post FX", "Post Mixer" } : inputNames;
            const int detailFirst = ! midi && sourceTrack.isEmpty() ? 2 : 1;
            if (detailItems != inputDetailItems)
            {
                inputDetailItems = detailItems;
                inputDetail.clear (juce::dontSendNotification);
                for (int n = 0; n < detailItems.size(); ++n) inputDetail.addItem (detailItems[n], n + detailFirst);
            }
            if (midi) inputDetail.setSelectedId (track.inputChannel + 1, juce::dontSendNotification);
            else if (sourceTrack.isNotEmpty()) inputDetail.setSelectedId (static_cast<int> (track.inputTap) + 1, juce::dontSendNotification);
            else inputDetail.setSelectedId (inputNames.indexOf (track.inputName) + 2, juce::dontSendNotification);
            const bool detailWanted = selected != 1;
            if (detailWanted != inputDetailShown)
            {
                inputDetailShown = detailWanted;
                inputDetail.setVisible (inputDetailShown && ! returnTrack && (! columnLayout || owner.state.mixerSections.inOut) && ! owner.automationMode);
                resized();
            }
            monitor.setMode (track.monitor);
            if (columnLayout) { syncSends (track); syncOutput (track); }
            if (! columnLayout) syncAutomation (track);
            if (! delay.isMouseButtonDown()) delay.setValue (track.delayMs, juce::dontSendNotification);
            delay.setEnabled (! track.frozen && ! owner.session.isExporting());
            if (columnLayout)
            {
                // Crossfader sides: A and B are exclusive toggles; neither leaves the track unassigned.
                if (sideA == nullptr)
                {
                    for (auto* side : { &sideA, &sideB })
                    {
                        *side = std::make_unique<juce::TextButton> (side == &sideA ? "A" : "B");
                        (*side)->setName (side == &sideA ? "Crossfade A" : "Crossfade B");
                        (*side)->setClickingTogglesState (true); (*side)->setWantsKeyboardFocus (false);
                        (*side)->setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); (*side)->setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
                        addAndMakeVisible (**side);
                    }
                    sideA->setTooltip ("Assign this track to the crossfader's A side"); sideB->setTooltip ("Assign this track to the crossfader's B side");
                    sideA->onClick = [this] { owner.report (owner.session.setTrackCrossfade (trackId, sideA->getToggleState() ? Session::CrossfadeAssign::a : Session::CrossfadeAssign::none)); owner.refresh(); };
                    sideB->onClick = [this] { owner.report (owner.session.setTrackCrossfade (trackId, sideB->getToggleState() ? Session::CrossfadeAssign::b : Session::CrossfadeAssign::none)); owner.refresh(); };
                    resized();
                }
                sideA->setToggleState (track.crossfade == Session::CrossfadeAssign::a, juce::dontSendNotification);
                sideB->setToggleState (track.crossfade == Session::CrossfadeAssign::b, juce::dontSendNotification);
                // The mixer's sections, as its View menu shows them.
                const auto& shown = owner.state.mixerSections;
                input.setVisible (shown.inOut && ! returnTrack); monitor.setVisible (shown.inOut && ! returnTrack);
                inputDetail.setVisible (shown.inOut && ! returnTrack && inputDetailShown);
                sendMode.setVisible (shown.inOut && returnTrack); output.setVisible (shown.inOut);
                for (auto& send : sends) send->setVisible (shown.sends);
                for (auto* c : std::initializer_list<juce::Component*> { &gain, &mute, &solo }) c->setVisible (shown.mixer);
                showPans (shown.mixer);
                arm.setVisible (shown.mixer && ! returnTrack);
                delay.setVisible (shown.trackDelay); sideA->setVisible (shown.crossfader); sideB->setVisible (shown.crossfader);
                if (shown != laidOut) { laidOut = shown; resized(); }
            }
            repaint();
        }
        // In Automation Mode the choosers replace the routing and mixer lines.
        void syncAutomation (const Session::TrackInfo& track)
        {
            const bool automating = owner.automationMode;
            choosers.setVisible (automating); automationLane.setVisible (automating);
            const auto& controls = owner.state.arrangementControls;
            if (automating) { for (auto* c : std::initializer_list<juce::Component*> { &input, &inputDetail, &monitor, &gain, &sendMode, &delay }) c->setVisible (false); showPans (false); }
            else
            {
                // View > Arrangement Track Controls: the routing, the volume and pan, and Track Delay.
                input.setVisible (controls.inOut && ! returnTrack); monitor.setVisible (controls.inOut && ! returnTrack);
                inputDetail.setVisible (controls.inOut && ! returnTrack && inputDetailShown); sendMode.setVisible (controls.inOut && returnTrack);
                gain.setVisible (controls.volume); showPans (controls.volume);
                delay.setVisible (controls.trackOptions);
            }
            if (! automating) return;
            automationLane.setEnabled (choosers.sync (track));
        }
        // Audio To, as the reference's: see Impl::outputChoices.
        void syncOutput (const Session::TrackInfo& track)
        {
            // A MIDI track without an instrument chooses MIDI To instead: No Output, or a channel
            // of each port whose Track switch is on (and of its current port, if that is off).
            midiTo = track.isMidi && ! track.hasInstrument;
            if (midiTo)
            {
                juce::StringArray ports;
                for (const auto& port : owner.session.midiOutputPorts()) if (port.track) ports.add (port.name);
                if (track.output.kind == Session::OutputKind::midiPort && ! ports.contains (track.output.port)) ports.add (track.output.port);
                if (ports != outputPorts || outputLabels != juce::StringArray { "MIDI To" })
                {
                    outputPorts = ports; outputLabels = { "MIDI To" }; outputSignature.clear(); output.clear (juce::dontSendNotification);
                    output.addItem ("No Output", 1);
                    for (int i = 0; i < ports.size(); ++i)
                    {
                        juce::PopupMenu channels;
                        for (int channel = 1; channel <= 16; ++channel) channels.addItem (firstPortItem + i * 16 + channel - 1, ports[i] + " | Ch. " + juce::String (channel));
                        output.getRootMenu()->addSubMenu (ports[i], channels);
                    }
                }
                const int port = outputPorts.indexOf (track.output.port);
                output.setSelectedId (track.output.kind == Session::OutputKind::midiPort && port >= 0 ? firstPortItem + port * 16 + track.output.midiChannel - 1 : 1, juce::dontSendNotification);
                output.setTooltip ("MIDI To: the MIDI port and channel this track's MIDI plays to.");
                output.setEnabled (! owner.session.isExporting());
                return;
            }
            outputPorts.clear(); outputLabels.clear();
            output.setTooltip (track.groupId.isNotEmpty() ? "Audio To: where this track plays, into its group or past it. With Sends Only, only its sends are heard."
                                                         : "Audio To: where this track plays. With Sends Only, only its sends are heard.");
            outputChoiceList = owner.outputChoices (track.id, track.groupId);
            owner.syncOutputChooser (output, outputChoiceList, track.output, outputSignature);
            output.setEnabled (! owner.session.isExporting());
        }
        // Session mixer sends: one knob per return, labelled A, B, C as the returns are.
        void syncSends (const Session::TrackInfo& track)
        {
            juce::StringArray ids;
            if (! track.isReturn) for (const auto& send : track.sends) ids.add (send.returnTrackId);
            if (ids != sendReturnIds)
            {
                sendReturnIds = ids; sends.clear();
                for (int i = 0; i < ids.size(); ++i)
                {
                    auto knob = std::make_unique<juce::Slider> (juce::Slider::RotaryHorizontalVerticalDrag, juce::Slider::NoTextBox);
                    knob->setName ("Send " + juce::String::charToString ((juce::juce_wchar) ('A' + i)));
                    knob->setNormalisableRange (Session::levelRange (true));
                    knob->setRotaryParameters (juce::MathConstants<float>::pi * 1.25f, juce::MathConstants<float>::pi * 2.75f, true);
                    knob->textFromValueFunction = [] (double v) { return v <= -99.95 ? juce::String ("-inf dB") : juce::String (v, 1) + " dB"; };
                    knob->onDragStart = [this] { owner.session.beginEditGesture ("Send level"); };
                    knob->onDragEnd = [this] { owner.session.endEditGesture(); };
                    knob->onValueChange = [this, i]
                    { owner.report (owner.session.setTrackSendGain (index, sendReturnIds[i], (float) sends[(size_t) i]->getValue())); };
                    addAndMakeVisible (*knob); sends.push_back (std::move (knob));
                }
                resized();
            }
            for (size_t i = 0; i < sends.size(); ++i)
            {
                sends[i]->getProperties().set ("midiMapTarget", "send:" + track.id + ":" + sendReturnIds[(int) i]);
                if (! sends[i]->isMouseButtonDown()) sends[i]->setValue (track.sends[i].gainDb, juce::dontSendNotification);
                for (const auto& other : owner.state.tracks) if (other.id == sendReturnIds[(int) i]) sends[i]->setTooltip ("Send to " + other.name + ": " + sends[i]->getTextFromValue (sends[i]->getValue()));
                sends[i]->setEnabled (! owner.session.isExporting());
            }
        }
        // Rows of send knobs, three to a row, above the pan control.
        int sendOffset() const noexcept { return sends.empty() ? 0 : (int) ((sends.size() + 2) / 3) * 40; }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (owner.selectedTrack == index ? themes::colour (0xff454545) : themes::colour (0xff383838));
            g.setColour (colour); g.fillRect (0, 0, 4, getHeight() - 1);
            g.setColour (line); g.drawRect (getLocalBounds());
            g.setColour (muted); g.setFont (font (9.5f, true));
            if (columnLayout)
            {
                // Two-channel meter beside the fader, 0 dB to -60 dB, with the Mixer section.
                const auto meter = meterBounds();
                for (int channel = 0; channel < 2 && gain.isVisible(); ++channel)
                {
                    const auto bar = meter.withWidth (4).translated (channel * 6, 0);
                    const auto level = channel == 0 ? peakL : peakR;
                    const auto fraction = juce::jlimit (0.0f, 1.0f, (juce::Decibels::gainToDecibels (level, -60.0f) + 60.0f) / 60.0f);
                    g.setColour (themes::colour (0xff181818)); g.fillRect (bar);
                    const auto lit = bar.withTop (bar.getBottom() - juce::roundToInt (bar.getHeight() * fraction));
                    g.setColour (level >= 1.0f ? red : green); g.fillRect (lit);
                }
                if (returnTrack && sendMode.isVisible()) { g.setColour (muted); g.setFont (font (9.0f)); g.drawText ("SEND INPUT", 6, 27, getWidth() - 12, 16, juce::Justification::centred); }
                g.setColour (muted); g.setFont (font (9.0f, true));
                for (size_t i = 0; i < sends.size() && sends[i]->isVisible(); ++i)
                    g.drawText (juce::String::charToString ((juce::juce_wchar) ('A' + (int) i)), sends[i]->getBounds().withY (sends[i]->getBottom()).withHeight (11), juce::Justification::centred);
                return;
            }
            // Header strip in the track colour, then routing and mixer lines.
            const bool selected = owner.selectedTrack == index || owner.multiSelectedTracks.contains (trackId);
            g.setColour (selected ? colour.brighter (0.2f) : colour); g.fillRect (0, 0, getWidth() - 8, 24);
            // The fold triangle: pointing right while folded, down while unfolded.
            {
                juce::Path triangle;
                if (folded) triangle.addTriangle (7.0f, 7.0f, 7.0f, 17.0f, 14.0f, 12.0f);
                else triangle.addTriangle (6.0f, 9.0f, 15.0f, 9.0f, 10.5f, 16.0f);
                g.setColour (themes::colour (0xff141414)); g.fillPath (triangle);
            }
            if (owner.multiSelectedTracks.contains (trackId)) { g.setColour (orange); g.drawRect (0, 0, getWidth() - 8, getHeight(), 2); }
            else if (linkId.isNotEmpty() && linkId == owner.hoveredLink) { g.setColour (ink); g.drawRect (0, 0, getWidth() - 8, getHeight(), 1); }
            g.setColour (muted); g.setFont (font (9.0f, true));
            if (owner.automationMode) { g.drawText ("DEVICE", 10, 26, 44, 19, juce::Justification::centredLeft); g.drawText ("CONTROL", 10, 49, 44, 20, juce::Justification::centredLeft); }
            else if (returnTrack) g.drawText ("SEND INPUT", 10, 26, 64, 19, juce::Justification::centredLeft);
            else g.drawText (midi ? "MIDI" : "IN", 10, 26, 24, 19, juce::Justification::centredLeft);
            if (! owner.automationMode) g.drawText ("VOL", 10, 49, 24, 20, juce::Justification::centredLeft);
            for (int channel = 0; channel < 2; ++channel)
            {
                const auto level = channel == 0 ? peakL : peakR;
                const auto fraction = juce::jlimit (0.0f, 1.0f, (juce::Decibels::gainToDecibels (level, -60.0f) + 60.0f) / 60.0f);
                const auto bar = juce::Rectangle<int> (getWidth() - 7 + channel * 3, 1, 2, getHeight() - 2);
                g.setColour (themes::colour (0xff181818)); g.fillRect (bar);
                g.setColour (level >= 1.0f ? red : green); g.fillRect (bar.withTop (bar.getBottom() - juce::roundToInt (bar.getHeight() * fraction)));
            }
        }
        void resized() override
        {
            if (columnLayout)
            {
                // Top to bottom, each as its section is shown: input and output routing (In/Out),
                // the sends, then the Mixer's pan and volume with meter, Track Delay and the
                // crossfader assignment above the Mixer's activator / solo / arm.
                const auto& shown = owner.state.mixerSections;
                name.setBounds (6, 2, getWidth() - 12, 18);
                input.setBounds (5, 4, getWidth() - 10, 19); inputDetail.setBounds (5, 25, getWidth() - 10, 19);
                monitor.setBounds (5, 46, getWidth() - 10, 19); output.setBounds (5, 67, getWidth() - 10, 19);
                sendMode.setBounds (5, 4, getWidth() - 10, 19);
                int top = shown.inOut ? inOutHeight : 4;
                for (size_t i = 0; i < sends.size(); ++i)
                    sends[i]->setBounds (8 + (int) (i % 3) * 36, top + (int) (i / 3) * 40, 34, 28);
                if (shown.sends) top += sendOffset();
                int bottom = getHeight();
                const int buttons = getHeight() - 28, w = (getWidth() - 14) / 3;
                mute.setBounds (5, buttons, w, 22); solo.setBounds (7 + w, buttons, w, 22); arm.setBounds (9 + 2 * w, buttons, w, 22);
                if (shown.mixer) bottom -= 28;
                if (sideA != nullptr)
                {
                    const int half = (getWidth() - 12) / 2;
                    sideA->setBounds (5, bottom - 24, half, 20); sideB->setBounds (7 + half, bottom - 24, half, 20);
                }
                if (shown.crossfader) bottom -= 24;
                delay.setBounds (5, bottom - 22, getWidth() - 10, 19);
                if (shown.trackDelay) bottom -= 22;
                pan.setBounds ((getWidth() - 46) / 2, top + 2, 46, 50);
                // The split pans stack Left over Right, labelled when the strip is wide enough.
                const int labels = getWidth() >= 93 ? 14 : 0;
                leftLabel.setBounds (5, top + 8, labels, 16); rightLabel.setBounds (5, top + 27, labels, 16);
                leftSplit.setBounds (5 + labels, top + 8, getWidth() - 10 - labels, 16); rightSplit.setBounds (5 + labels, top + 27, getWidth() - 10 - labels, 16);
                gain.setBounds (6, top + 58, 54, juce::jmax (20, bottom - 4 - (top + 58)));
                return;
            }
            const int w = getWidth() - 8, half = (w - 40) / 2;
            name.setBounds (18, 2, w - (linkId.isNotEmpty() ? 124 : 104), 20);
            link.setBounds (w - 106, 3, 20, 18);
            mute.setBounds (w - 84, 3, 26, 18); solo.setBounds (w - 56, 3, 26, 18); arm.setBounds (w - 28, 3, 26, 18);
            // The source takes the whole width unless the chooser under it is shown beside it.
            input.setBounds (36, 27, inputDetailShown ? half / 2 - 1 : half, 18); inputDetail.setBounds (37 + half / 2, 27, half - half / 2 - 1, 18);
            monitor.setBounds (40 + half, 27, w - 44 - half, 18);
            sendMode.setBounds (76, 27, w - 80, 18);
            gain.setBounds (32, 49, half + 4, 20); pan.setBounds (40 + half, 49, w - 44 - half, 20);
            delay.setBounds (32, 71, half + 4, 18); // Track Options' Track Delay, on a tall enough header.
            // The split pans share the pan's place, Left beside Right.
            const int pans = w - 44 - half;
            leftSplit.setBounds (40 + half, 49, pans / 2 - 1, 20); rightSplit.setBounds (41 + half + pans / 2, 49, pans - pans / 2 - 1, 20);
            choosers.device.setBounds (58, 27, w - 62, 18);
            choosers.control.setBounds (58, 49, w - 90, 18); automationLane.setBounds (w - 28, 49, 24, 18);
        }
        // The split line under an Arrangement header drags the track's height.
        bool onSplitLine (juce::Point<int> at) const { return ! columnLayout && at.y >= getHeight() - 4; }
        void mouseMove (const juce::MouseEvent& e) override { setMouseCursor (onSplitLine (e.getPosition()) ? juce::MouseCursor::UpDownResizeCursor : juce::MouseCursor::NormalCursor); }
        void mouseDrag (const juce::MouseEvent& e) override
        {
            if (heightAtDown <= 0)
            {
                // Dragging the header by its name or background moves the track, or the selected tracks.
                if (dragArmed && e.getDistanceFromDragStart() > 6) { headerDrag = true; owner.dragTracks (trackId, e.getEventRelativeTo (&owner.canvas).getPosition(), copyModifier (e.mods)); }
                return;
            }
            const auto pixels = heightAtDown + e.getDistanceFromDragStartY();
            owner.setTrackHeights (e.mods.isAltDown() ? owner.allArrangementTracks() : juce::StringArray { trackId }, pixels);
        }
        void mouseUp (const juce::MouseEvent&) override
        {
            heightAtDown = 0; dragArmed = false;
            const bool collapse = std::exchange (collapseOnUp, false);
            if (std::exchange (headerDrag, false)) owner.dropTracks();
            else if (collapse) { owner.multiSelectedTracks.clear(); owner.selectTrack (index); }
        }
        // Double-clicking a mixer control resets it, and the controls linked to it (see Session::resetTrackControl).
        void mouseDoubleClick (const juce::MouseEvent& e) override
        {
            juce::String control;
            if (e.originalComponent == &gain) control = "volume";
            else if (e.originalComponent == &pan) control = "pan";
            else if (e.originalComponent == &leftSplit) control = "leftsplit";
            else if (e.originalComponent == &rightSplit) control = "rightsplit";
            else for (size_t i = 0; i < sends.size(); ++i) if (e.originalComponent == sends[i].get()) control = "send:" + sendReturnIds[(int) i];
            if (control.isNotEmpty()) { owner.report (owner.session.resetTrackControl (index, control)); owner.refresh(); }
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            heightAtDown = onSplitLine (e.getPosition()) && ! folded && ! e.mods.isPopupMenu() ? getHeight() : 0;
            if (heightAtDown > 0) return;
            dragArmed = ! columnLayout && ! e.mods.isPopupMenu() && (e.originalComponent == this || e.originalComponent == &name);
            if (dragArmed) owner.canvas.beginDragScroll();
            if (! columnLayout && ! e.mods.isPopupMenu() && e.originalComponent == this && e.x < 18 && e.y < 22)
            { owner.selectTrack (index); owner.foldTracks (e.mods.isAltDown() ? owner.allArrangementTracks() : juce::StringArray { trackId }, ! folded); return; }
            const auto within = [&e] (juce::Component& c) { return e.originalComponent == &c || c.isParentOf (e.originalComponent); };
            // A control of a selected track keeps the selection, so the other selected tracks move with
            // it, as the reference links them.
            bool onControl = within (gain) || within (pan) || within (leftSplit) || within (rightSplit) || within (mute);
            for (const auto& knob : sends) onControl = onControl || within (*knob);
            if (onControl && ! e.mods.isPopupMenu() && (owner.selectedTrack == index || owner.multiSelectedTracks.contains (trackId)))
            {
                if (const auto* current = owner.currentTrack(); current != nullptr && current->id != trackId) owner.multiSelectedTracks.insert (current->id);
                owner.selectTrack (index); return;
            }
            const bool headerMenu = e.mods.isPopupMenu() && (e.originalComponent == this || e.originalComponent == &name);
            if (! e.mods.isPopupMenu()) collapseOnUp = owner.pressTrackHeader (index, ! columnLayout && e.mods.isShiftDown(), dragArmed);
            else if (! headerMenu) owner.selectTrack (index);
            // The pan controls' menu switches the pan mode, as the reference's does.
            if (e.mods.isPopupMenu() && (within (pan) || within (leftSplit) || within (rightSplit))) { owner.panModeMenu (trackId, ! splitPan); return; }
            if (headerMenu) owner.showHeaderMenu (trackId, ! columnLayout);
        }
    private:
        Impl& owner;
        int index;
        int heightAtDown = 0;
        bool folded = false, dragArmed = false, headerDrag = false, collapseOnUp = false;
        juce::String trackId;
        juce::Colour colour;
        float peakL = 0, peakR = 0;
        bool midi = false, columnLayout = false, returnTrack = false;
        juce::String linkId;
        juce::Label name;
        LinkIndicator link;
        juce::TextButton mute { "M" }, solo { "S" }, arm { "R" };
        juce::Slider gain, pan, delay, leftSplit, rightSplit;
        juce::Label leftLabel { {}, "L" }, rightLabel { {}, "R" };
        bool splitPan = false;
        // The pan, or in Split Stereo mode the split pans, as the section showing them is shown.
        void showPans (bool visible)
        {
            pan.setVisible (visible && ! splitPan);
            leftSplit.setVisible (visible && splitPan); rightSplit.setVisible (visible && splitPan);
            leftLabel.setVisible (visible && splitPan && columnLayout && getWidth() >= 93); rightLabel.setVisible (leftLabel.isVisible());
        }
        juce::ComboBox input, sendMode, output;
        MonitorSwitch monitor;
        juce::TextButton automationLane { "+" };
        AutomationChoosers choosers { owner, *this };
        juce::StringArray inputNames, sendReturnIds, outputLabels, inputSourceIds, inputSourceLabels, inputDetailItems;
        juce::ComboBox inputDetail;
        juce::String sourceTrack, lastExternalInput;
        bool inputIsMidi = false, inputDetailShown = false;
        juce::StringArray outputPorts; // MIDI To: the ports offered, by item.
        bool midiTo = false;
        static constexpr int firstPortItem = 1000;
        std::vector<Impl::OutputChoice> outputChoiceList; // The Audio To choices, in the chooser's order.
        juce::String outputSignature;
        static constexpr int firstSourceItem = 1000;
        std::vector<std::unique_ptr<juce::Slider>> sends;
        std::unique_ptr<juce::TextButton> sideA, sideB;
        Session::MixerSections laidOut;
        juce::Rectangle<int> meterBounds() const { return { 66, gain.getY() + 4, 10, juce::jmax (10, gain.getBottom() - 20 - gain.getY()) }; }
        ChildMouseEvents childMouse { *this };
    public:
        // The Session mixer's Audio To row, which every strip leaves room for so their faders line up.
        static constexpr int outputRow = 21;
        // The In/Out section's height: Audio or MIDI From and its channel, monitoring and Audio To.
        static constexpr int inOutHeight = 48 + outputRow + 21;
    };

    bool syncTrackRows (juce::Component& parent, std::vector<std::unique_ptr<TrackRow>>& rows, bool vertical)
    {
        bool reordered = rows.size() != state.tracks.size();
        if (reordered) rows.clear();
        for (size_t i = 0; i < state.tracks.size(); ++i)
        {
            const auto& track = state.tracks[i];
            if (i >= rows.size())
            {
                auto row = std::make_unique<TrackRow> (*this, (int)i, vertical);
                parent.addAndMakeVisible (*row); rows.push_back (std::move (row));
            }
            if (rows[i]->getTrackId() != track.id)
            {
                auto found = std::find_if (rows.begin()+static_cast<std::ptrdiff_t>(i+1), rows.end(),
                    [&] (const auto& row) { return row->getTrackId() == track.id; });
                if (found != rows.end()) std::iter_swap (rows.begin()+static_cast<std::ptrdiff_t>(i), found);
                else { rows[i] = std::make_unique<TrackRow> (*this, (int)i, vertical); parent.addAndMakeVisible (*rows[i]); }
                reordered = true;
            }
            rows[i]->sync (track, (int)i);
        }
        if (reordered) for (auto& row : rows) row->toFront (false);
        return reordered;
    }

    // Disclosure triangle: points right when folded, down when open.
    class FoldButton final : public juce::Button
    {
    public:
        FoldButton() : juce::Button ("Fold") {}
        bool folded = false;
        void paintButton (juce::Graphics& g, bool over, bool) override
        {
            juce::Path triangle; const auto b = getLocalBounds().toFloat().withSizeKeepingCentre (9.0f, 9.0f);
            if (folded) triangle.addTriangle (b.getX() + 1, b.getY(), b.getX() + 1, b.getBottom(), b.getRight(), b.getCentreY());
            else triangle.addTriangle (b.getX(), b.getY() + 1, b.getRight(), b.getY() + 1, b.getCentreX(), b.getBottom());
            g.setColour (juce::Colour (over ? 0xff000000 : 0xff141414)); g.fillPath (triangle);
        }
    };
    // Arrangement header for a group: fold switch, name, activator, solo and the group mixer.
    class GroupHeader final : public juce::Component
    {
    public:
        GroupHeader (Impl& o, juce::String id, bool column = false) : owner (o), groupId (std::move (id)), columnLayout (column)
        {
            for (auto* c : std::initializer_list<juce::Component*> { &fold, &name, &activator, &solo, &gain, &pan }) addAndMakeVisible (c);
            fold.setName ("Group fold"); fold.setTooltip ("Fold or unfold the group's tracks");
            fold.onClick = [this] { if (const auto* g = info()) owner.report (owner.session.setGroupFolded (groupId, ! g->folded)); owner.refresh(); };
            getProperties().set (arrangementHeader, ! columnLayout);
            name.setName ("Group name"); name.setFont (font (11.5f, true)); name.setEditable (false, true, false);
            name.setColour (juce::Label::textColourId, themes::colour (0xff141414));
            name.onTextChange = [this] { owner.report (owner.session.renameGroup (groupId, name.getText())); owner.refresh(); };
            for (auto* b : { &activator, &solo }) { b->setClickingTogglesState (true); b->setWantsKeyboardFocus (false); b->setMouseClickGrabsKeyboardFocus (false); }
            activator.setName ("Group activator"); activator.setTooltip ("Group activator: click to mute or unmute the whole group");
            activator.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); activator.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            solo.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xff57a7ff)); solo.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            activator.onClick = [this] { owner.report (owner.session.setGroupMute (groupId, ! activator.getToggleState())); owner.refresh(); };
            solo.onClick = [this] { owner.soloFromUI (-1, groupId, solo.getToggleState(), juce::ModifierKeys::getCurrentModifiers().isCommandDown()); };
            gain.setName ("Group volume"); gain.setSliderStyle (juce::Slider::LinearHorizontal); gain.setNormalisableRange (Session::levelRange (false));
            gain.setTextBoxStyle (juce::Slider::TextBoxRight, false, 50, 16); gain.setDoubleClickReturnValue (true, 0);
            gain.textFromValueFunction = [] (double v) { return v <= -100 ? juce::String ("-inf") : juce::String (v, 1) + " dB"; };
            gain.onDragStart = [this] { owner.session.beginEditGesture ("Group volume"); };
            gain.onDragEnd = [this] { owner.session.endEditGesture(); };
            gain.onValueChange = [this] { owner.report (owner.session.setGroupGain (groupId, (float) gain.getValue())); };
            pan.setName ("Group pan"); pan.setSliderStyle (juce::Slider::LinearHorizontal); pan.setRange (-1, 1, .01);
            pan.setTextBoxStyle (juce::Slider::TextBoxRight, false, 32, 16); pan.setDoubleClickReturnValue (true, 0);
            pan.textFromValueFunction = [] (double v) { return Session::panText ((float) v); };
            pan.valueFromTextFunction = [] (const juce::String& value) { return (double) Session::panFromText (value); };
            pan.onDragStart = [this] { owner.session.beginEditGesture ("Group pan"); };
            pan.onDragEnd = [this] { owner.session.endEditGesture(); };
            pan.onValueChange = [this] { owner.report (owner.session.setGroupPan (groupId, (float) pan.getValue())); };
            // Split Stereo pan mode, as on tracks.
            for (auto* split : { &leftSplit, &rightSplit })
            {
                addChildComponent (*split);
                const bool right = split == &rightSplit;
                split->setName (right ? "Group right split pan" : "Group left split pan");
                split->setSliderStyle (juce::Slider::LinearBar); split->setRange (-1.0, 1.0, 0.01);
                split->setDoubleClickReturnValue (true, right ? 1 : -1);
                split->setColour (juce::Slider::trackColourId, themes::colour (0xff4a4a4a));
                split->textFromValueFunction = [] (double v) { return Session::panText ((float) v); };
                split->valueFromTextFunction = [] (const juce::String& value) { return (double) Session::panFromText (value); };
                split->updateText();
                split->onDragStart = [this, right] { owner.session.beginEditGesture (right ? "Group right split pan" : "Group left split pan"); };
                split->onDragEnd = [this] { owner.session.endEditGesture(); };
                split->onValueChange = [this, split, right] { owner.report (owner.session.setGroupSplitPan (groupId, right, (float) split->getValue())); };
            }
            if (! columnLayout)
            {
                // Automation Mode's button that moves the envelope into a lane below the group.
                addChildComponent (automationLane); automationLane.setName ("Show automation in lane");
                automationLane.setTooltip ("Move this envelope into its own lane below the group");
                automationLane.setWantsKeyboardFocus (false);
                automationLane.onClick = [this] { owner.addAutomationLane (groupId, choosers.shownKey); };
            }
            if (columnLayout)
            {
                // Its Audio To, in the In/Out section in line with the tracks', as the reference's group
                // strip shows only its output.
                addChildComponent (output); output.setName ("Group output");
                output.setTooltip ("Audio To: where this group plays. With Sends Only, only its sends are heard.");
                output.onChange = [this] { owner.chooseOutput (groupId, output, outputChoiceList); };
                // Session mixer strip: the grid column header names and folds the group.
                gain.setSliderStyle (juce::Slider::LinearVertical); gain.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 54, 16);
                pan.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag); pan.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 42, 15);
                pan.setRotaryParameters (juce::MathConstants<float>::pi * 1.25f, juce::MathConstants<float>::pi * 2.75f, true);
                fold.setVisible (false); name.setVisible (false);
            }
            gain.updateText(); pan.updateText();
        }
        const juce::String& getId() const noexcept { return groupId; }
        void beginRename() { name.showEditor(); }
        void sync()
        {
            const auto* g = info(); if (g == nullptr) return;
            colour = g->colour; folded = g->folded; peakL = g->peakL; peakR = g->peakR; fold.folded = folded; fold.repaint();
            getProperties().set (infoTitleProperty, g->name); getProperties().set (infoTextProperty, g->infoText); // For the Info view.
            if (! name.isBeingEdited()) name.setText (g->name, juce::dontSendNotification);
            activator.setToggleState (! g->mute, juce::dontSendNotification); solo.setToggleState (g->solo, juce::dontSendNotification);
            solo.setEnabled (! owner.state.cueMode); // Groups cannot be cued.
            activator.setButtonText (g->numberLabel); // A group's number, as the reference's shows.
            if (! gain.isMouseButtonDown()) gain.setValue (g->gainDb, juce::dontSendNotification);
            if (! pan.isMouseButtonDown()) pan.setValue (g->pan, juce::dontSendNotification);
            if (! leftSplit.isMouseButtonDown()) leftSplit.setValue (g->leftSplitPan, juce::dontSendNotification);
            if (! rightSplit.isMouseButtonDown()) rightSplit.setValue (g->rightSplitPan, juce::dontSendNotification);
            splitPan = g->splitPan;
            // MIDI and key mapping targets, as on tracks.
            gain.getProperties().set ("midiMapTarget", "mixer:" + groupId + ":volume"); pan.getProperties().set ("midiMapTarget", "mixer:" + groupId + ":pan");
            leftSplit.getProperties().set ("midiMapTarget", "mixer:" + groupId + ":leftsplit"); rightSplit.getProperties().set ("midiMapTarget", "mixer:" + groupId + ":rightsplit");
            bool mixerShown = true;
            if (columnLayout)
            {
                syncSends (*g);
                outputChoiceList = owner.outputChoices (groupId, g->parentId);
                owner.syncOutputChooser (output, outputChoiceList, g->output, outputSignature);
                output.setVisible (owner.state.mixerSections.inOut); output.setEnabled (! owner.session.isExporting());
                // The Mixer section, lined up with the tracks' as the In/Out section moves it.
                const auto& shown = owner.state.mixerSections;
                for (auto* c : std::initializer_list<juce::Component*> { &gain, &activator, &solo }) c->setVisible (shown.mixer);
                for (auto& send : sends) send->setVisible (shown.sends);
                mixerShown = shown.mixer;
                if (shown != laidOut) { laidOut = shown; resized(); }
            }
            else
            {
                // In Automation Mode the choosers take the mixer's line, as on tracks.
                const bool automating = owner.automationMode;
                choosers.setVisible (automating); automationLane.setVisible (automating); gain.setVisible (! automating);
                mixerShown = ! automating;
                if (automating) automationLane.setEnabled (choosers.sync (Impl::automationView (*g)));
            }
            pan.setVisible (mixerShown && ! splitPan); leftSplit.setVisible (mixerShown && splitPan); rightSplit.setVisible (mixerShown && splitPan);
            repaint();
        }
        // The Session mixer's sends: one knob per return, A, B, C, as on the tracks' strips.
        void syncSends (const Session::GroupInfo& group)
        {
            juce::StringArray ids;
            for (const auto& send : group.sends) ids.add (send.returnTrackId);
            if (ids != sendReturnIds)
            {
                sendReturnIds = ids; sends.clear();
                for (int i = 0; i < ids.size(); ++i)
                {
                    auto knob = std::make_unique<juce::Slider> (juce::Slider::RotaryHorizontalVerticalDrag, juce::Slider::NoTextBox);
                    knob->setName ("Group send " + juce::String::charToString ((juce::juce_wchar) ('A' + i)));
                    knob->setNormalisableRange (Session::levelRange (true));
                    knob->setRotaryParameters (juce::MathConstants<float>::pi * 1.25f, juce::MathConstants<float>::pi * 2.75f, true);
                    knob->setDoubleClickReturnValue (true, -100);
                    knob->textFromValueFunction = [] (double v) { return v <= -99.95 ? juce::String ("-inf dB") : juce::String (v, 1) + " dB"; };
                    knob->onDragStart = [this] { owner.session.beginEditGesture ("Send level"); };
                    knob->onDragEnd = [this] { owner.session.endEditGesture(); };
                    knob->onValueChange = [this, i]
                    { owner.report (owner.session.setGroupSendGain (groupId, sendReturnIds[i], (float) sends[(size_t) i]->getValue())); };
                    addAndMakeVisible (*knob); sends.push_back (std::move (knob));
                }
                resized();
            }
            for (size_t i = 0; i < sends.size(); ++i)
            {
                sends[i]->getProperties().set ("midiMapTarget", "send:" + groupId + ":" + sendReturnIds[(int) i]);
                if (! sends[i]->isMouseButtonDown()) sends[i]->setValue (group.sends[i].gainDb, juce::dontSendNotification);
                for (const auto& other : owner.state.tracks) if (other.id == sendReturnIds[(int) i]) sends[i]->setTooltip ("Send to " + other.name + ": " + sends[i]->getTextFromValue (sends[i]->getValue()));
                sends[i]->setEnabled (! owner.session.isExporting());
            }
        }
        void resized() override
        {
            if (columnLayout)
            {
                const auto& shown = owner.state.mixerSections;
                int top = shown.inOut ? TrackRow::inOutHeight : 4;
                output.setBounds (5, 67, getWidth() - 10, 19);
                for (size_t i = 0; i < sends.size(); ++i)
                    sends[i]->setBounds (8 + (int) (i % 3) * 36, top + (int) (i / 3) * 40, 34, 28);
                if (shown.sends && ! sends.empty()) top += (int) ((sends.size() + 2) / 3) * 40;
                pan.setBounds ((getWidth() - 46) / 2, top + 2, 46, 50);
                leftSplit.setBounds (5, top + 8, getWidth() - 10, 16); rightSplit.setBounds (5, top + 27, getWidth() - 10, 16);
                gain.setBounds (6, top + 58, 54, juce::jmax (20, getHeight() - 34 - (top + 58)));
                const int buttons = getHeight() - 28, half = (getWidth() - 12) / 2;
                activator.setBounds (5, buttons, half, 22); solo.setBounds (7 + half, buttons, half, 22);
                return;
            }
            const int w = getWidth() - 8;
            fold.setBounds (2, 2, 18, 18); name.setBounds (20, 1, w - 80, 20);
            activator.setBounds (w - 56, 2, 26, 18); solo.setBounds (w - 28, 2, 26, 18);
            gain.setBounds (24, 21, (w - 30) / 2 + 10, 17); pan.setBounds (24 + (w - 30) / 2 + 14, 21, w - 38 - (w - 30) / 2 - 10, 17);
            choosers.device.setBounds (gain.getBounds()); choosers.control.setBounds (pan.getBounds().withTrimmedRight (26));
            automationLane.setBounds (pan.getRight() - 24, pan.getY(), 24, pan.getHeight());
            const int pans = w - 38 - (w - 30) / 2 - 10, x = 24 + (w - 30) / 2 + 14;
            leftSplit.setBounds (x, 21, pans / 2 - 1, 17); rightSplit.setBounds (x + pans / 2 + 1, 21, pans - pans / 2 - 1, 17);
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            // The pan controls' menu switches the group's pan mode, as on tracks.
            const auto within = [&e] (juce::Component& c) { return e.originalComponent == &c || c.isParentOf (e.originalComponent); };
            if (e.mods.isPopupMenu() && (within (pan) || within (leftSplit) || within (rightSplit))) { owner.groupPanModeMenu (groupId, ! splitPan); return; }
            if (e.mods.isPopupMenu() && (e.originalComponent == this || e.originalComponent == &name)) { owner.showHeaderMenu (groupId, ! columnLayout); return; }
            dragArmed = ! columnLayout && ! e.mods.isPopupMenu() && (e.originalComponent == this || e.originalComponent == &name);
            if (dragArmed) owner.canvas.beginDragScroll();
            // Clicking the group shows its device chain.
            if (! e.mods.isPopupMenu()) owner.selectChain (groupId);
        }
        // Dragging the header by its name or background moves the group, with everything in it.
        void mouseDrag (const juce::MouseEvent& e) override
        {
            if (dragArmed && e.getDistanceFromDragStart() > 6) { headerDrag = true; owner.dragTracks (groupId, e.getEventRelativeTo (&owner.canvas).getPosition(), copyModifier (e.mods)); }
        }
        void mouseUp (const juce::MouseEvent&) override
        {
            dragArmed = false;
            if (std::exchange (headerDrag, false)) owner.dropTracks();
        }
        void paint (juce::Graphics& g) override
        {
            if (columnLayout)
            {
                g.fillAll (themes::colour (0xff383838));
                g.setColour (colour); g.fillRect (0, 0, 4, getHeight() - 1);
                g.setColour (muted); g.setFont (font (9.0f, true)); g.drawText ("GROUP", 6, 8, getWidth() - 12, 16, juce::Justification::centred);
                for (size_t i = 0; i < sends.size() && sends[i]->isVisible(); ++i)
                    g.drawText (juce::String::charToString ((juce::juce_wchar) ('A' + (int) i)), sends[i]->getBounds().withY (sends[i]->getBottom()).withHeight (11), juce::Justification::centred);
                const juce::Rectangle<int> meter { 66, gain.getY() + 4, 10, juce::jmax (10, gain.getBottom() - 20 - gain.getY()) };
                for (int channel = 0; channel < 2 && gain.isVisible(); ++channel)
                {
                    const auto bar = meter.withWidth (4).translated (channel * 6, 0);
                    const auto level = channel == 0 ? peakL : peakR;
                    const auto fraction = juce::jlimit (0.0f, 1.0f, (juce::Decibels::gainToDecibels (level, -60.0f) + 60.0f) / 60.0f);
                    g.setColour (themes::colour (0xff181818)); g.fillRect (bar);
                    g.setColour (level >= 1.0f ? red : green); g.fillRect (bar.withTop (bar.getBottom() - juce::roundToInt (bar.getHeight() * fraction)));
                }
                g.setColour (line); g.drawRect (getLocalBounds()); return;
            }
            g.fillAll (themes::colour (0xff2a2a2a));
            g.setColour (colour); g.fillRect (0, 0, getWidth() - 8, 21);
            for (int channel = 0; channel < 2; ++channel)
            {
                const auto level = channel == 0 ? peakL : peakR;
                const auto fraction = juce::jlimit (0.0f, 1.0f, (juce::Decibels::gainToDecibels (level, -60.0f) + 60.0f) / 60.0f);
                const auto bar = juce::Rectangle<int> (getWidth() - 7 + channel * 3, 1, 2, getHeight() - 2);
                g.setColour (themes::colour (0xff181818)); g.fillRect (bar);
                g.setColour (level >= 1.0f ? red : green); g.fillRect (bar.withTop (bar.getBottom() - juce::roundToInt (bar.getHeight() * fraction)));
            }
            g.setColour (line); g.drawRect (getLocalBounds());
        }
    private:
        const Session::GroupInfo* info() const { return owner.groupInfo (groupId); }
        Impl& owner;
        juce::String groupId;
        juce::Colour colour;
        bool folded = false, columnLayout = false;
        float peakL = 0, peakR = 0;
        FoldButton fold;
        juce::TextButton activator { "G" }, solo { "S" };
        juce::ComboBox output;
        std::vector<OutputChoice> outputChoiceList;
        juce::String outputSignature;
        Session::MixerSections laidOut;
        juce::Label name;
        juce::Slider gain, pan, leftSplit, rightSplit;
        bool splitPan = false, dragArmed = false, headerDrag = false;
        std::vector<std::unique_ptr<juce::Slider>> sends;
        juce::StringArray sendReturnIds;
        juce::TextButton automationLane { "+" };
        AutomationChoosers choosers { owner, *this };
        ChildMouseEvents childMouse { *this };
    };

    // The header of an automation lane: what it shows, and a button that hides it.
    class AutomationLaneHeader final : public juce::Component
    {
    public:
        explicit AutomationLaneHeader (Impl& o) : owner (o)
        {
            addAndMakeVisible (hide); hide.setName ("Hide automation lane"); hide.setWantsKeyboardFocus (false);
            hide.setTooltip ("Hide this lane. Its automation keeps playing.");
            hide.onClick = [this] { owner.removeAutomationLane (trackId, index); };
        }
        void set (const juce::String& track, int lane, const juce::String& text, juce::Colour c)
        { if (track != trackId || lane != index || text != label || c != colour) { trackId = track; index = lane; label = text; colour = c; setTitle (text); repaint(); } }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff323232)); g.setColour (colour); g.fillRect (0, 0, 4, getHeight());
            g.setColour (ink); g.setFont (font (10.5f));
            g.drawFittedText (label, 10, 4, getWidth() - 46, getHeight() - 8, juce::Justification::centredLeft, 2);
            g.setColour (line); g.drawRect (getLocalBounds());
        }
        void resized() override { hide.setBounds (getWidth() - 34, 4, 24, 18); }
        juce::String trackId, label;
        int index = 0;
    private:
        Impl& owner;
        juce::Colour colour;
        juce::TextButton hide { "x" };
    };
    // A small speaker, lit while its take lane is auditioned.
    class SpeakerButton final : public juce::Button
    {
    public:
        SpeakerButton() : juce::Button ("Audition take lane") { setClickingTogglesState (false); }
        void paintButton (juce::Graphics& g, bool over, bool) override
        {
            const auto b = getLocalBounds().toFloat().reduced (3);
            g.setColour (getToggleState() ? orange : over ? ink : muted);
            juce::Path speaker;
            speaker.startNewSubPath (b.getX(), b.getCentreY() - b.getHeight() * .18f); speaker.lineTo (b.getX() + b.getWidth() * .3f, b.getCentreY() - b.getHeight() * .18f);
            speaker.lineTo (b.getX() + b.getWidth() * .6f, b.getY()); speaker.lineTo (b.getX() + b.getWidth() * .6f, b.getBottom());
            speaker.lineTo (b.getX() + b.getWidth() * .3f, b.getCentreY() + b.getHeight() * .18f); speaker.lineTo (b.getX(), b.getCentreY() + b.getHeight() * .18f); speaker.closeSubPath();
            g.fillPath (speaker);
            if (getToggleState()) g.drawLine (b.getRight() - 2, b.getY() + 2, b.getRight() - 2, b.getBottom() - 2, 1.5f);
        }
    };
    // A take lane's header: its name, which double-clicking renames, its audition switch and a button
    // that deletes it.
    class TakeLaneHeader final : public juce::Component
    {
    public:
        explicit TakeLaneHeader (Impl& o) : owner (o)
        {
            for (auto* c : std::initializer_list<juce::Component*> { &name, &remove, &audition }) addAndMakeVisible (c);
            audition.setTooltip ("Audition this take lane in place of the main lane  |  T"); audition.setWantsKeyboardFocus (false);
            audition.onClick = [this] { owner.toggleAudition (laneId); };
            name.setName ("Take lane name"); name.setEditable (false, true, false); name.setFont (font (10.5f));
            name.setColour (juce::Label::textColourId, ink); name.setTooltip ("Double-click to rename this take lane");
            name.onTextChange = [this] { owner.report (owner.session.renameTakeLane (laneId, name.getText())); owner.refresh(); };
            remove.setName ("Delete take lane"); remove.setWantsKeyboardFocus (false); remove.setTooltip ("Delete this take lane and its takes");
            remove.onClick = [this] { owner.report (owner.session.removeTakeLane (laneId)); owner.refresh(); };
        }
        void set (const juce::String& id, const juce::String& text, juce::Colour c, bool auditioned)
        {
            laneId = id; colour = c; setTitle (text);
            audition.setToggleState (auditioned, juce::dontSendNotification);
            if (! name.isBeingEdited() && name.getText() != text) name.setText (text, juce::dontSendNotification);
            repaint();
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff2e2e2e)); g.setColour (colour.withAlpha (.6f)); g.fillRect (0, 0, 4, getHeight());
            g.setColour (line); g.drawRect (getLocalBounds());
        }
        void resized() override { name.setBounds (10, 4, getWidth() - 78, 18); audition.setBounds (getWidth() - 62, 4, 22, 18); remove.setBounds (getWidth() - 34, 4, 24, 18); }
        juce::String laneId;
    private:
        Impl& owner;
        juce::Colour colour;
        juce::Label name;
        juce::TextButton remove { "x" };
        SpeakerButton audition;
    };
    class Canvas final : public juce::Component, private juce::ChangeListener
    {
    public:
        explicit Canvas (Impl& o) : owner (o) { setWantsKeyboardFocus (true); }
        ~Canvas() override
        {
            if (clipGesture) owner.session.endEditGesture();
            for (auto& item : thumbnails) item.second->removeChangeListener (this);
        }
        void syncRows()
        {
            bool layout = owner.syncTrackRows (*this, rows, false);
            bool same = groupHeaders.size() == owner.state.groups.size();
            for (size_t i = 0; same && i < groupHeaders.size(); ++i) same = groupHeaders[i]->getId() == owner.state.groups[i].id;
            if (! same)
            {
                groupHeaders.clear();
                for (const auto& group : owner.state.groups) { groupHeaders.push_back (std::make_unique<GroupHeader> (owner, group.id)); addAndMakeVisible (*groupHeaders.back()); }
                layout = true;
            }
            for (auto& header : groupHeaders) header->sync();
            // One header per automation lane.
            size_t count = 0;
            for (const auto& lane : owner.lanes)
                if (lane.automation >= 0)
                {
                    if (count >= laneHeaders.size()) { laneHeaders.push_back (std::make_unique<AutomationLaneHeader> (owner)); addAndMakeVisible (*laneHeaders.back()); layout = true; }
                    // A track's lane, or a group's.
                    const auto& id = lane.group ? owner.state.groups[(size_t) lane.index].id : owner.state.tracks[(size_t) lane.index].id;
                    const auto colour = lane.group ? owner.state.groups[(size_t) lane.index].colour : owner.state.tracks[(size_t) lane.index].colour;
                    const auto key = owner.automationLanes[id][lane.automation];
                    const auto target = owner.automationTarget (id, key);
                    laneHeaders[count]->set (id, lane.automation, target ? target->device + ": " + target->control : juce::String ("Unavailable"), colour);
                    ++count;
                }
            if (laneHeaders.size() != count) { laneHeaders.resize (count); layout = true; }
            size_t takes = 0;
            for (const auto& lane : owner.lanes)
                if (lane.take >= 0)
                {
                    if (takes >= takeHeaders.size()) { takeHeaders.push_back (std::make_unique<TakeLaneHeader> (owner)); addAndMakeVisible (*takeHeaders.back()); layout = true; }
                    const auto& track = owner.state.tracks[(size_t) lane.index];
                    const auto& take = track.takeLanes[(size_t) lane.take];
                    takeHeaders[takes]->set (take.id, take.name, track.colour, track.auditionLane == take.id);
                    ++takes;
                }
            if (takeHeaders.size() != takes) { takeHeaders.resize (takes); layout = true; }
            if (layout || owner.lanesHeight != lastLanesHeight) { lastLanesHeight = owner.lanesHeight; resized(); }
            repaint();
        }
        std::vector<std::unique_ptr<AutomationLaneHeader>> laneHeaders;
        std::vector<std::unique_ptr<TakeLaneHeader>> takeHeaders;
        bool selectingTake = false;
        double takeAnchor = 0;
        juce::Rectangle<float> envelopeArea;
        // Automation Mode: the envelope a canvas y shows, as its track, key and drawing area.
        bool envelopeAt (int y, juce::String& trackId, juce::String& key, juce::Rectangle<float>& area) const
        {
            const auto* lane = owner.laneAt (y);
            // A group's lane shows its own envelope, and the lanes below it more.
            if (lane != nullptr && lane->group && juce::isPositiveAndBelow (lane->index, (int) owner.state.groups.size()))
            {
                const auto& group = owner.state.groups[(size_t) lane->index];
                if (lane->automation >= 0)
                {
                    const auto found = owner.automationLanes.find (group.id);
                    if (found == owner.automationLanes.end() || lane->automation >= found->second.size()) return false;
                    key = found->second[lane->automation];
                }
                else key = owner.shownKey (Impl::automationView (group));
                if (key == "none") return false;
                trackId = group.id;
                area = { 0.0f, (float) lane->y + 5, (float) timelineWidth(), (float) juce::jmax (4, lane->height - 10) };
                return true;
            }
            if (lane == nullptr || lane->group || lane->take >= 0 || ! juce::isPositiveAndBelow (lane->index, (int) owner.state.tracks.size())) return false;
            const auto& track = owner.state.tracks[(size_t) lane->index];
            if (lane->automation >= 0)
            {
                const auto found = owner.automationLanes.find (track.id);
                if (found == owner.automationLanes.end() || lane->automation >= found->second.size()) return false;
                key = found->second[lane->automation];
            }
            else key = owner.shownKey (track);
            if (key == "none") return false;
            trackId = track.id;
            area = { 0.0f, (float) lane->y + 5, (float) timelineWidth(), (float) juce::jmax (4, lane->height - 10) };
            return true;
        }
        std::vector<std::unique_ptr<GroupHeader>> groupHeaders;
        int lastLanesHeight = -1;
        int timelineWidth() const { return getWidth() - trackWidth; }
        void resized() override
        {
            // Each header after its strips.
            const auto indent = [this] (const juce::String& id) { return (int) owner.groupsAround (id).size() * Impl::nestingStrip; };
            for (size_t i = 0; i < rows.size() && i < owner.state.tracks.size(); ++i)
            {
                const int height = owner.laneHeight ((int) i), x = indent (owner.state.tracks[i].id);
                rows[i]->setVisible (height > 0); rows[i]->setBounds (timelineWidth() + x, owner.laneY ((int) i), trackWidth - x, juce::jmax (1, height));
            }
            for (const auto& lane : owner.lanes)
                if (lane.group && lane.automation < 0 && juce::isPositiveAndBelow (lane.index, (int) groupHeaders.size()))
                {
                    const int x = indent (owner.laneItemId (lane));
                    groupHeaders[(size_t) lane.index]->setBounds (timelineWidth() + x, lane.y, trackWidth - x, lane.height);
                }
            size_t header = 0, takeHeader = 0;
            for (const auto& lane : owner.lanes)
            {
                const int x = lane.automation >= 0 || lane.take >= 0 ? indent (owner.laneItemId (lane)) : 0;
                if (lane.automation >= 0 && header < laneHeaders.size()) laneHeaders[header++]->setBounds (timelineWidth() + x, lane.y, trackWidth - x, lane.height);
                if (lane.take >= 0 && takeHeader < takeHeaders.size()) takeHeaders[takeHeader++]->setBounds (timelineWidth() + x, lane.y, trackWidth - x, lane.height);
            }
        }
        juce::Rectangle<float> clipBounds (const Session::ClipInfo& clip, int track) const
        {
            return { (float) ((clip.start - owner.viewStart) * owner.pixelsPerSecond), (float) (owner.laneY (track) + 6),
                     (float) juce::jmax (3.0, clip.length * owner.pixelsPerSecond), (float) juce::jmax (0, owner.laneHeight (track) - 12) };
        }
        juce::Point<float> fadeHandle (const Session::ClipInfo& clip, int track, bool out) const
        {
            const auto b = clipBounds (clip, track);
            const auto time = out ? clip.length - clip.audio.fadeOutSeconds : clip.audio.fadeInSeconds;
            return { juce::jlimit (b.getX()+4, b.getRight()-4, b.getX()+(float) (time*owner.pixelsPerSecond)),
                     b.getY()+(out ? 39.0f : 27.0f) };
        }
        int hitFade (const Session::ClipInfo& clip, int track, juce::Point<float> point) const
        {
            if (! clip.isAudio || ! clip.canEditAudioFades || clipBounds (clip, track).getWidth() < 20) return 0;
            if (fadeHandle (clip, track, false).getDistanceFrom (point) <= 6) return 1;
            if (fadeHandle (clip, track, true).getDistanceFrom (point) <= 6) return 2;
            return 0;
        }
        int hitTrim (const Session::ClipInfo& clip, int track, juce::Point<float> point) const
        {
            const auto bounds = clipBounds (clip, track);
            if (! (clip.canEditAudioRange || clip.canLoop) || bounds.getWidth() < 20 || ! bounds.contains (point)) return 0;
            if (point.x-bounds.getX() <= 6) return 1;
            if (bounds.getRight()-point.x <= 6) return 2;
            return 0;
        }
        // Where dragged headers would land, as a line across the headers from the strips of the groups
        // the place is in.
        void paintOverChildren (juce::Graphics& g) override
        {
            if (! owner.trackDrop) return;
            const int x = (int) owner.groupPath (owner.trackDrop->groupId).size() * Impl::nestingStrip;
            g.setColour (orange); g.fillRect (timelineWidth() + x, juce::jlimit (0, juce::jmax (0, getHeight() - 2), owner.trackDrop->lineY - 1), trackWidth - x, 2);
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (panel);
            const auto tw = timelineWidth();
            // Each header's strips, one in the colour of each group around it, outermost first.
            for (const auto& lane : owner.lanes)
            {
                if (lane.height <= 0) continue;
                const auto around = owner.groupsAround (owner.laneItemId (lane));
                for (int k = 0; k < around.size(); ++k)
                    if (const auto* group = owner.groupInfo (around[k]))
                    { g.setColour (group->colour); g.fillRect (tw + k * Impl::nestingStrip, lane.y, Impl::nestingStrip - 1, lane.height - 1); }
            }
            g.saveState();
            g.reduceClipRegion (0, 0, tw, getHeight());
            for (const auto& lane : owner.lanes)
            {
                if (lane.height == 0) continue;
                if (lane.group)
                {
                    const auto& group = owner.state.groups[(size_t) lane.index];
                    g.setColour (themes::colour (0xff262626)); g.fillRect (0, lane.y, tw, lane.height);
                    // Member clips summarized as thin bars, as on a folded group lane.
                    for (int t = 0; t < (int) owner.state.tracks.size(); ++t)
                        if (owner.state.tracks[(size_t) t].groupId == group.id || owner.groupInside (owner.state.tracks[(size_t) t].groupId, group.id))
                            for (const auto& clip : owner.state.tracks[(size_t) t].clips)
                            {
                                const auto x = (float) ((clip.start - owner.viewStart) * owner.pixelsPerSecond);
                                g.setColour (clip.colour.withAlpha (clip.active ? 0.8f : 0.3f));
                                g.fillRect (x, (float) lane.y + 12.0f, (float) juce::jmax (2.0, clip.length * owner.pixelsPerSecond), (float) lane.height - 24.0f);
                            }
                }
                else
                {
                    const int i = lane.index;
                    g.setColour (i == owner.selectedTrack ? themes::colour (0xff353535) : (i % 2 == 0 ? themes::colour (0xff2c2c2c) : themes::colour (0xff303030)));
                    g.fillRect (0, lane.y, tw, lane.height);
                }
                g.setColour (line); g.drawHorizontalLine (lane.y + lane.height - 1, 0.0f, (float) tw);
            }
            // The grid's lines run from each bar's start, through the time signature markers; a fine fixed
            // grid draws every other line until they are 4 pixels apart.
            auto grid = owner.gridBeats();
            while (grid * owner.gridPixelsPerBeat() < 4) grid *= 2;
            const auto end = owner.viewStart + tw / owner.pixelsPerSecond;
            const auto& markers = owner.state.timeSignatures;
            const auto gridLine = [&] (double b, bool bar)
            {
                g.setColour (bar ? themes::colour (0xff4a4a4a) : themes::colour (0xff3a3a3a));
                g.drawVerticalLine ((int) std::round ((owner.secondsAt (b) - owner.viewStart) * owner.pixelsPerSecond), 0.0f, (float) getHeight());
            };
            for (auto bar = Session::barAt (markers, owner.beatsAt (owner.viewStart)); owner.secondsAt (bar.start) <= end; bar = Session::barAt (markers, bar.start + bar.length))
            {
                if (grid >= bar.meter.beatsPerBar() - 1.0e-9)
                {
                    if (bar.number % juce::jmax (1, (int) std::round (grid / bar.meter.beatsPerBar())) == 0) gridLine (bar.start, true);
                    continue;
                }
                for (double b = bar.start; b < bar.start + bar.length - 1.0e-9; b += grid) gridLine (b, b == bar.start);
            }
            if (owner.state.looping)
            {
                g.setColour (orange.withAlpha (0.035f));
                g.fillRect ((float) ((owner.state.loopStart - owner.viewStart) * owner.pixelsPerSecond), 0.0f,
                            (float) ((owner.state.loopEnd - owner.state.loopStart) * owner.pixelsPerSecond), (float) getHeight());
            }
            for (int t = 0; t < (int) owner.state.tracks.size(); ++t)
            {
                const auto& track = owner.state.tracks[(size_t) t];
                if (track.isReturn)
                {
                    g.setColour (background); g.fillRect (0, owner.laneY (t) + 1, tw, owner.laneHeight (t) - 2);
                    g.setColour (muted); g.setFont (font (11.0f));
                    g.drawText ("RETURN  /  Audio from track sends", 16, owner.laneY (t) + owner.laneHeight (t) / 2 - 13, tw - 32, 26, juce::Justification::centredLeft);
                    continue;
                }
                for (int c = 0; c < (int) track.clips.size(); ++c)
                {
                    const auto& clip = track.clips[(size_t) c];
                    auto bounds = clipBounds (clip, t);
                    if (bounds.getRight() < 0 || bounds.getX() > tw) continue;
                    const bool selected = (t == owner.selectedTrack && c == owner.selectedClip) || owner.isExtraMidiClip (clip.id) || owner.linkedToSelectedClip (t, clip) || owner.isClipSelected (clip.id);
                    auto colour = clip.colour; // Its own, or its track's.
                    if (colour.isTransparent()) colour = themes::colour (0xff76b5bf);
                    if (!clip.active) colour=muted;
                    g.setColour (colour.withAlpha (track.mute || !clip.active ? 0.24f : 0.72f)); g.fillRect (bounds);
                    g.setColour (selected ? orange : colour.brighter (0.1f));
                    g.fillRect (bounds.withHeight (20));
                    g.setColour (themes::colour (0xff182025)); g.setFont (font (11.0f, true));
                    g.drawText ((clip.active?juce::String():juce::String("OFF  /  "))+clip.name, bounds.withHeight (20).reduced (6, 0), juce::Justification::centredLeft, true);
                    auto wave = bounds.withTrimmedTop (24).reduced (2, 4);
                    g.setColour (themes::colour (0xff14252b).withAlpha (track.mute ? 0.4f : 0.9f));
                    // Each stretch of content the clip plays, a loop's pass at a time.
                    const auto spans = clip.canLoop ? contentSpans (clip) : std::vector<ContentSpan> {};
                    const auto spanX = [&] (double beatsIn) { return wave.getX() + (float) (beatsIn / std::max (1e-9, clip.lengthBeats)) * wave.getWidth(); };
                    if (clip.isMidi && clip.lengthBeats > 0)
                    {
                        int low = 60, high = 71;
                        for (const auto& note : clip.notes) { low = juce::jmin (low, note.pitch); high = juce::jmax (high, note.pitch); }
                        const auto noteHeight = wave.getHeight() / (float) (high - low + 1);
                        for (const auto& span : spans)
                            for (const auto& note : clip.notes)
                            {
                                const auto from = std::max (note.startBeat, span.content), to = std::min (note.startBeat + note.lengthBeats, span.content + span.length);
                                if (to <= from) continue;
                                g.setColour (themes::colour (0xff14252b).withAlpha (note.active ? (track.mute ? 0.4f : 0.9f) : 0.25f));
                                const auto x = spanX (span.at + from - span.content);
                                g.fillRect (x, wave.getY() + (high - note.pitch) * noteHeight, juce::jmax (2.0f, spanX (span.at + to - span.content) - x), juce::jmax (2.0f, noteHeight * 0.65f));
                            }
                    }
                    // Loop notches where each pass begins again.
                    if (spans.size() > 1)
                    {
                        g.setColour (themes::colour (0xff182025));
                        for (size_t i = 1; i < spans.size(); ++i)
                        {
                            const auto x = spanX (spans[i].at);
                            juce::Path notch; notch.addTriangle (x - 4, bounds.getY() + 20, x + 4, bounds.getY() + 20, x, bounds.getY() + 26);
                            g.fillPath (notch); g.drawVerticalLine ((int) x, bounds.getY() + 20, bounds.getBottom());
                        }
                    }
                   #if JUCE_MAC
                    // A video clip's pictures along its top half, each from the time playing under it.
                    if (clip.videoFile != juce::File() && wave.getHeight() >= 16)
                    {
                        if (owner.videoThumbnails == nullptr)
                            owner.videoThumbnails = std::make_unique<VideoThumbnails> ([safe = juce::Component::SafePointer<Canvas> (this)] { if (safe != nullptr) safe->repaint(); });
                        const auto strip = wave.withHeight (std::floor (wave.getHeight() / 2));
                        const int height = (int) strip.getHeight();
                        const auto shape = owner.videoThumbnails->get (clip.videoFile, std::round (clip.sourceOffset * 4) / 4, height);
                        const float width = shape.isValid() ? (float) shape.getWidth() : height * 16.0f / 9;
                        g.saveState(); g.reduceClipRegion (strip.toNearestInt());
                        const auto firstFrame = std::floor (std::max (0.0f, -strip.getX()) / width);
                        for (auto x = strip.getX() + firstFrame * width; x < std::min (strip.getRight(), (float) tw); x += width)
                        {
                            const auto seconds = std::round ((clip.sourceOffset + (x - strip.getX()) / owner.pixelsPerSecond) * 4) / 4;
                            if (const auto picture = owner.videoThumbnails->get (clip.videoFile, seconds, height); picture.isValid())
                                g.drawImageAt (picture, (int) x, (int) strip.getY());
                        }
                        g.restoreState();
                        wave = wave.withTrimmedTop (strip.getHeight());
                    }
                   #endif
                    auto* thumbnail = clip.isMidi ? nullptr : thumbnailFor (clip.file);
                    if (thumbnail != nullptr && thumbnail->getTotalLength() > 0 && clip.isAudio && clip.canLoop && ! clip.reversed)
                    {
                        // A warped clip's waveform, each pass from its own source time.
                        for (const auto& span : spans)
                        {
                            const auto x0 = std::max (0.0f, spanX (span.at)), x1 = std::min ((float) tw, spanX (span.at + span.length));
                            if (x1 - x0 < .5f) continue;
                            const auto toContent = [&] (float x) { return span.content + (x - spanX (span.at)) / std::max (1e-9f, spanX (span.at + span.length) - spanX (span.at)) * span.length; };
                            const auto area = juce::Rectangle<float> (x0, wave.getY(), x1 - x0, wave.getHeight());
                            thumbnail->drawChannels (g, area.toNearestInt(), sourceSecondsAt (clip, toContent (x0)), sourceSecondsAt (clip, toContent (x1)), 0.9f);
                        }
                    }
                    else if (thumbnail != nullptr && thumbnail->getTotalLength() > 0)
                    {
                        const auto visible = wave.getIntersection (juce::Rectangle<float> (0, wave.getY(), (float) tw, wave.getHeight()));
                        const auto startSeconds = juce::jmax (0.0, (visible.getX() - wave.getX()) / owner.pixelsPerSecond);
                        const auto endSeconds = juce::jmin (clip.length, startSeconds + visible.getWidth() / owner.pixelsPerSecond);
                        if (clip.reversed)
                        {
                            // Read the same immutable source interval and mirror its display.
                            g.saveState();
                            g.addTransform (juce::AffineTransform (-1,0,visible.getX()+visible.getRight(),0,1,0));
                            thumbnail->drawChannels (g, visible.toNearestInt(), clip.sourceLength-clip.sourceOffset-endSeconds,
                                clip.sourceLength-clip.sourceOffset-startSeconds,0.9f);
                            g.restoreState();
                        }
                        else thumbnail->drawChannels (g, visible.toNearestInt(), clip.sourceOffset + startSeconds, clip.sourceOffset + endSeconds, 0.9f);
                    }
                    if (clip.mediaMissing)
                    {
                        // A clip whose file is missing plays silence until it is located.
                        g.setColour (themes::colour (0xff000000).withAlpha (.35f)); g.fillRect (bounds);
                        g.setColour (red); g.setFont (font (10.5f, true));
                        g.drawText ("Missing: " + clip.file.getFileName(), bounds.reduced (6, 2).withTrimmedTop (16), juce::Justification::topLeft, true);
                    }
                    if (track.frozen)
                    {
                        // Frozen clips play their render: an icy hatch marks them as locked.
                        juce::Graphics::ScopedSaveState frost (g); g.reduceClipRegion (bounds.toNearestInt());
                        g.setColour (themes::colour (0x6094c8ff));
                        for (auto x = bounds.getX() - bounds.getHeight(); x < bounds.getRight(); x += 9.0f)
                            g.drawLine (x, bounds.getBottom(), x + bounds.getHeight(), bounds.getY(), 1.4f);
                    }
                    if (selected && clip.isAudio && clip.canEditAudioFades && bounds.getWidth() >= 20)
                    {
                        const auto curve = [] (double x, Session::FadeCurve type)
                        {
                            const auto a = x*juce::MathConstants<double>::halfPi;
                            if (type == Session::FadeCurve::convex) return std::sin (a);
                            if (type == Session::FadeCurve::concave) return 1-std::cos (a);
                            if (type == Session::FadeCurve::sCurve) return (1-x)*(1-std::cos (a))+x*std::sin (a);
                            if (type == Session::FadeCurve::smoothstep) return x*x*(3-2*x);
                            return x;
                        };
                        juce::Path envelope;
                        for (int n=0; n<=128; ++n)
                        {
                            const auto time = clip.length*n/128; double level = 1;
                            if (clip.audio.fadeInSeconds > 0 && time < clip.audio.fadeInSeconds)
                                level *= curve (time/clip.audio.fadeInSeconds, clip.audio.fadeInCurve);
                            if (clip.audio.fadeOutSeconds > 0 && time > clip.length-clip.audio.fadeOutSeconds)
                                level *= curve ((clip.length-time)/clip.audio.fadeOutSeconds, clip.audio.fadeOutCurve);
                            const auto x = bounds.getX()+bounds.getWidth()*n/128;
                            const auto y = wave.getBottom()-(float) level*wave.getHeight();
                            if (n == 0) envelope.startNewSubPath (x,y); else envelope.lineTo (x,y);
                        }
                        g.setColour (orange); g.strokePath (envelope, juce::PathStrokeType (1.5f));
                        for (bool out : { false, true })
                        {
                            const auto handle = fadeHandle (clip,t,out);
                            const bool chosen = owner.selectedFadeClip == clip.id && owner.selectedFadeEdge == (out ? 2 : 1);
                            g.setColour (chosen ? orange : background); g.fillRect (handle.x-4,handle.y-4,8.0f,8.0f);
                            g.setColour (orange); g.drawRect (handle.x-4,handle.y-4,8.0f,8.0f,1.5f);
                        }
                    }
                    if (selected && (clip.canEditAudioRange || clip.canLoop) && bounds.getWidth() >= 20)
                    {
                        g.setColour (ink);
                        for (auto x : { bounds.getX()+3, bounds.getRight()-3 })
                            g.drawLine (x, bounds.getBottom()-16, x, bounds.getBottom()-5, 2.0f);
                    }
                    g.setColour (selected ? orange : colour.darker (0.45f)); g.drawRect (bounds, selected ? 2.0f : 1.0f);
                }
                if (owner.state.recording && track.armed)
                {
                    const auto from = owner.recordingStart;
                    g.setColour (red.withAlpha (0.22f));
                    g.fillRect ((float) ((from - owner.viewStart) * owner.pixelsPerSecond), (float) owner.laneY (t) + 6,
                                (float) juce::jmax (2.0, (owner.state.position - from) * owner.pixelsPerSecond), (float) owner.laneHeight (t) - 12);
                    g.setColour (red); g.setFont (font (11.0f, true));
                    g.drawText ("RECORDING", (int) ((from - owner.viewStart) * owner.pixelsPerSecond) + 8, owner.laneY (t) + 12, 96, 18, juce::Justification::centredLeft);
                }
            }
            if (owner.state.tracks.empty())
            {
                auto message = juce::Rectangle<int> (0, 0, tw, juce::jmin (getHeight(), 340)).reduced (35);
                g.setColour (ink); g.setFont (font (18.0f));
                g.drawText ("Drop audio to start your session", message.withHeight (30).withY (message.getCentreY() - 28), juce::Justification::centred);
                g.setColour (muted); g.setFont (font (12.0f));
                g.drawText ("Or insert an audio track, choose an input and arm it to record.", message.withHeight (24).withY (message.getCentreY() + 8), juce::Justification::centred);
            }
            // Take lanes: their clips, dimmed, and a selection to comp.
            for (const auto& lane : owner.lanes)
            {
                if (lane.take < 0 || lane.height == 0 || ! juce::isPositiveAndBelow (lane.index, (int) owner.state.tracks.size())) continue;
                const auto& track = owner.state.tracks[(size_t) lane.index];
                if (! juce::isPositiveAndBelow (lane.take, (int) track.takeLanes.size())) continue;
                const auto& take = track.takeLanes[(size_t) lane.take];
                g.setColour (themes::colour (0xff272727)); g.fillRect (0, lane.y, tw, lane.height);
                g.setColour (line); g.drawHorizontalLine (lane.y, 0.0f, (float) tw);
                for (const auto& clip : take.clips)
                {
                    const juce::Rectangle<float> b ((float) ((clip.start - owner.viewStart) * owner.pixelsPerSecond), (float) lane.y + 4,
                                                    (float) juce::jmax (3.0, clip.length * owner.pixelsPerSecond), (float) lane.height - 8);
                    if (b.getRight() < 0 || b.getX() > tw) continue;
                    g.setColour (clip.colour.withAlpha (.35f)); g.fillRect (b);
                    if (clip.isAudio)
                        if (auto* thumbnail = thumbnailFor (clip.file); thumbnail != nullptr && thumbnail->getTotalLength() > 0)
                        { g.setColour (clip.colour.withAlpha (.8f)); thumbnail->drawChannels (g, b.reduced (0, 2).toNearestInt(), clip.sourceOffset, clip.sourceOffset + clip.length, .9f); }
                    if (clip.isMidi)
                        for (const auto& note : clip.notes)
                        {
                            const auto x = (float) ((owner.secondsAt (clip.startBeat + note.startBeat) - clip.sourceOffset - owner.viewStart) * owner.pixelsPerSecond);
                            const auto w = (float) juce::jmax (1.0, (owner.secondsAt (clip.startBeat + note.startBeat + note.lengthBeats) - owner.secondsAt (clip.startBeat + note.startBeat)) * owner.pixelsPerSecond);
                            const auto y = b.getBottom() - (float) (note.pitch % 48) / 48.0f * b.getHeight();
                            g.setColour (clip.colour.brighter (.3f)); g.fillRect (x, y - 1, w, 2.0f);
                        }
                    g.setColour (clip.colour.darker (.4f)); g.drawRect (b, 1.0f);
                }
                if (owner.takeSelection.laneId == take.id && owner.takeSelection.end > owner.takeSelection.start)
                {
                    const auto x0 = (float) ((owner.takeSelection.start - owner.viewStart) * owner.pixelsPerSecond), x1 = (float) ((owner.takeSelection.end - owner.viewStart) * owner.pixelsPerSecond);
                    g.setColour (themes::colour (0xffb9d3ff).withAlpha (.3f)); g.fillRect (x0, (float) lane.y, x1 - x0, (float) lane.height);
                }
            }
            // Automation Mode: an envelope over each track's clips, and one in each of its lanes.
            if (owner.automationMode)
                for (const auto& lane : owner.lanes)
                {
                    if (lane.height == 0) continue;
                    if (lane.automation >= 0)
                    {
                        g.setColour (themes::colour (0xff262626)); g.fillRect (0, lane.y, tw, lane.height);
                        g.setColour (line); g.drawHorizontalLine (lane.y, 0.0f, (float) tw);
                    }
                    else { g.setColour (themes::colour (0xff000000).withAlpha (.22f)); g.fillRect (0, lane.y, tw, lane.height); }
                    juce::String trackId, key; juce::Rectangle<float> area;
                    if (envelopeAt (lane.y + 1, trackId, key, area))
                        if (const auto target = owner.automationTarget (trackId, key)) owner.envelope.paint (g, area, *target);
                }
            // The time selection lights its lanes between its edges.
            if (owner.timeSelection.active())
            {
                const auto x0 = (float) ((owner.timeSelection.start - owner.viewStart) * owner.pixelsPerSecond);
                const auto x1 = (float) ((owner.timeSelection.end - owner.viewStart) * owner.pixelsPerSecond);
                for (int t = 0; t < (int) owner.state.tracks.size(); ++t)
                    if (owner.timeSelection.trackIds.contains (owner.state.tracks[(size_t) t].id) && owner.laneHeight (t) > 0)
                    {
                        const juce::Rectangle<float> area (x0, (float) owner.laneY (t), x1 - x0, (float) owner.laneHeight (t));
                        g.setColour (themes::colour (0xffb9d3ff).withAlpha (.3f)); g.fillRect (area);
                        g.setColour (themes::colour (0xffb9d3ff).withAlpha (.7f)); g.drawVerticalLine ((int) x0, area.getY(), area.getBottom()); g.drawVerticalLine ((int) x1, area.getY(), area.getBottom());
                    }
            }
            // The insert marker, where Play starts, flashes; the play position shows while playing
            // or where playback stopped away from the marker.
            const bool atMarker = std::abs (owner.state.position - owner.state.insertMarker) < 1e-6;
            if (owner.insertMarkerLit())
            {
                const auto ix = (float) ((owner.state.insertMarker - owner.viewStart) * owner.pixelsPerSecond);
                g.setColour (insertBlue); g.drawLine (ix, 0, ix, (float) getHeight(), 1.0f);
            }
            if (owner.state.playing || owner.state.recording || ! atMarker)
            {
                auto x = (float) ((owner.state.position - owner.viewStart) * owner.pixelsPerSecond);
                g.setColour (owner.state.recording ? red : themes::colour (0xffeeeeee));
                g.drawLine (x, 0, x, (float) getHeight(), 1.3f);
            }
            if (dragHover)
            {
                g.setColour (orange.withAlpha (0.1f)); g.fillRect (0, 0, tw, getHeight());
                g.setColour (orange); g.drawRect (0, 0, tw, getHeight(), 2);
            }
            g.restoreState();
            g.setColour (line); g.drawVerticalLine (tw, 0.0f, (float) getHeight());
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            if (e.x >= timelineWidth()) return;
            // A held press without a move then gets no drag events from the auto-repeat.
            lastDrag = std::make_tuple (e.x, e.y, owner.viewStart, owner.viewport.getViewPositionY(), e.mods.getRawFlags());
            if (! e.mods.isPopupMenu()) beginDragScroll();
            // A take lane selects a time range to comp.
            if (const auto* lane = owner.laneAt (e.y); lane != nullptr && lane->take >= 0)
            {
                grabKeyboardFocus();
                const auto& track = owner.state.tracks[(size_t) lane->index];
                owner.selectTrack (lane->index);
                takeAnchor = owner.snapTime (owner.viewStart + e.x / owner.pixelsPerSecond, e.mods);
                const auto laneId = track.takeLanes[(size_t) lane->take].id;
                if (e.mods.isPopupMenu())
                {
                    // A right-click inside the lane's selection keeps it for Copy to Main Lane.
                    const auto at = owner.viewStart + e.x / owner.pixelsPerSecond;
                    if (! (owner.takeSelection.laneId == laneId && at >= owner.takeSelection.start && at <= owner.takeSelection.end)) owner.takeSelection = { laneId, takeAnchor, takeAnchor };
                    owner.timeSelection = {}; repaint();
                    owner.showArrangementMenu ({ lane->index, {}, at, true });
                    return;
                }
                owner.takeSelection = { laneId, takeAnchor, takeAnchor };
                owner.timeSelection = {}; selectingTake = true; repaint(); return;
            }
            owner.takeSelection = {};
            if (owner.automationMode)
            {
                grabKeyboardFocus();
                juce::String trackId, key; juce::Rectangle<float> area;
                if (envelopeAt (e.y, trackId, key, area))
                {
                    if (e.mods.isPopupMenu()) if (const auto target = owner.automationTarget (trackId, key)) { owner.envelopeMenu (*target, owner.envelope.beatOfX (e.position.x)); return; }
                    if (const auto target = owner.automationTarget (trackId, key); target && owner.envelope.mouseDown (owner.session, *target, area, e))
                    {
                        owner.envelopeTrack = owner.selectedEnvelopeTrack = trackId; owner.envelopeKey = owner.selectedEnvelopeKey = key;
                        envelopeArea = area; owner.refresh(); return;
                    }
                    owner.selectedEnvelopeTrack.clear(); owner.selectedEnvelopeKey.clear();
                }
                // An automation lane's background selects time, as the reference's does; it holds no clips.
            }
            grabKeyboardFocus(); fadeDrag = 0; rangeDrag = 0; dragClipId.clear(); owner.selectedFadeClip.clear();
            const auto previousTrack = owner.selectedTrack, previousClip = owner.selectedClip;
            const auto* previousMidi = owner.currentMidiClip();
            const auto previousMidiId = previousMidi != nullptr && owner.selectedLauncherClipId.isEmpty() ? previousMidi->id : juce::String();
            auto track = owner.trackAtY (e.y);
            // An automation lane's background selects time on its track, as the reference's does.
            if (track < 0 && owner.automationMode) track = owner.selectionTrackAtY (e.y);
            if (track < 0) return;
            owner.selectedClip = -1;
            owner.selectedLauncherClipId.clear();
            if (track < (int) owner.state.tracks.size())
            {
                owner.selectTrack (track);
                if (owner.state.tracks[(size_t) track].isReturn) { draggedClip = -1; return; }
                const auto& clips = owner.state.tracks[(size_t) track].clips;
                for (int c = (int) clips.size() - 1; c >= 0; --c)
                    if (clipBounds (clips[(size_t) c], track).contains (e.position))
                    {
                        // Shift-clicking a MIDI clip shows it in the editor with the clips already shown.
                        if (e.mods.isShiftDown() && ! e.mods.isAltDown() && clips[(size_t) c].isMidi && previousMidiId.isNotEmpty() && previousMidiId != clips[(size_t) c].id)
                        {
                            if (! owner.isExtraMidiClip (previousMidiId)) owner.extraMidiClipIds.push_back (previousMidiId);
                            std::erase (owner.extraMidiClipIds, clips[(size_t) c].id);
                        }
                        else if (! e.mods.isPopupMenu()) owner.extraMidiClipIds.clear();
                        if (e.mods.isPopupMenu())
                        {
                            const auto at = owner.viewStart + e.x / owner.pixelsPerSecond;
                            const Impl::ArrangementPlace place { track, clips[(size_t) c].id, at, false };
                            owner.prepareArrangementMenu (place, owner.snapTime (at, e.mods));
                            draggedClip = -1; owner.refresh(); repaint();
                            owner.showArrangementMenu (place);
                            return;
                        }
                        chooseClips (track, c, e.mods, previousTrack, previousClip);
                        owner.selectedClip = c;
                        owner.timeSelection = {};
                        draggedClip = c;
                        originalStart = clips[(size_t) c].start;
                        dragStartX = e.x; dragTrack = track;
                        moving.clear();
                        for (const auto& id : owner.selectedClipIds)
                            if (const auto [mt, mc] = owner.arrangementClipIndex (id); mt >= 0)
                                moving.push_back ({ id, mt, owner.state.tracks[(size_t) mt].clips[(size_t) mc].start, owner.state.tracks[(size_t) mt].clips[(size_t) mc].isMidi });
                        if (! e.mods.isPopupMenu())
                        {
                            fadeDrag = track == previousTrack && c == previousClip ? hitFade (clips[(size_t) c],track,e.position) : 0;
                            if (fadeDrag != 0) { owner.selectedFadeClip = clips[(size_t) c].id; owner.selectedFadeEdge = fadeDrag; }
                            dragClipId = clips[(size_t) c].id;
                            originalRange = clips[(size_t) c];
                            originalFade = fadeDrag == 2 ? originalRange.audio.fadeOutSeconds : originalRange.audio.fadeInSeconds;
                            if (e.mods.isShiftDown() && e.mods.isAltDown() && originalRange.canEditAudioRange)
                            { rangeDrag = 3; fadeDrag = 0; }
                            else if (fadeDrag == 0 && track == previousTrack && c == previousClip)
                                rangeDrag = hitTrim (originalRange, track, e.position);
                        }
                        repaint();
                        return;
                    }
            }
            draggedClip = -1;
            owner.extraMidiClipIds.clear();
            if (e.mods.isPopupMenu())
            {
                const auto at = juce::jmax (0.0, owner.viewStart + e.x / owner.pixelsPerSecond);
                if (track < (int) owner.state.tracks.size())
                {
                    const Impl::ArrangementPlace place { track, {}, at, false };
                    owner.prepareArrangementMenu (place, owner.snapTime (at, e.mods));
                    owner.refresh(); repaint();
                    owner.showArrangementMenu (place);
                }
                return;
            }
            owner.selectedClipIds.clear();
            // Dragging over empty lane space selects time; Shift-click extends the selection.
            {
                const auto at = owner.snapTime (owner.viewStart + e.x / owner.pixelsPerSecond, e.mods);
                if (e.mods.isShiftDown() && owner.timeSelection.active())
                {
                    selectionAnchorTime = std::abs (at - owner.timeSelection.start) > std::abs (at - owner.timeSelection.end) ? owner.timeSelection.start : owner.timeSelection.end;
                    selectionAnchorTrack = owner.trackIndex (owner.timeSelection.trackIds[0]);
                    extendSelection (at, track);
                }
                else { owner.timeSelection = {}; selectionAnchorTime = at; selectionAnchorTrack = track; }
                selecting = true;
            }
            owner.session.setInsertMarker (owner.snapTime (owner.viewStart + e.x / owner.pixelsPerSecond, e.mods));
            owner.refresh();
        }
        void mouseDoubleClick (const juce::MouseEvent& e) override
        {
            if (e.x >= timelineWidth()) return;
            // A fade handle opens the clip's gain, fades and range, Halftrack's own dialog for their curves and lengths.
            if (const auto track = owner.trackAtY (e.y); juce::isPositiveAndBelow (track, (int) owner.state.tracks.size()))
                for (const auto& clip : owner.state.tracks[(size_t) track].clips)
                    if (clip.isAudio && clip.canEditAudioFades && clipBounds (clip, track).contains (e.position) && hitFade (clip, track, e.position) != 0)
                    { owner.audioClipCommand (2, clip.id); return; }
            if (owner.automationMode)
            {
                juce::String trackId, key; juce::Rectangle<float> area;
                if (envelopeAt (e.y, trackId, key, area))
                    if (const auto target = owner.automationTarget (trackId, key); target && owner.envelope.doubleClick (owner.session, *target, area, e)) { owner.refresh(); return; }
                if (const auto* lane = owner.laneAt (e.y); lane != nullptr && lane->automation >= 0) return;
            }
            if (const auto* track = owner.currentTrack(); track != nullptr && track->isMidi)
            {
                if (owner.selectedClip >= 0) owner.openPianoRoll();
                else owner.createMidiClip (juce::jmax (0.0, owner.viewStart + e.x / owner.pixelsPerSecond));
            }
            else if (const auto* track = owner.currentTrack(); track && juce::isPositiveAndBelow (owner.selectedClip, (int)track->clips.size()))
                if (track->clips[(size_t)owner.selectedClip].isAudio) owner.openPianoRoll();
        }
        void mouseDrag (const juce::MouseEvent& e) override
        {
            if (owner.envelopeKey.isEmpty() && (selectingTake || selecting || draggedClip >= 0) && ! e.mods.isPopupMenu() && e.mouseWasDraggedSinceMouseDown())
                scrollForDrag (e.getPosition(), true);
            // While the pointer rests, the auto-repeat sends the same event again; only a move or a scroll changes anything.
            const auto drag = std::make_tuple (e.x, e.y, owner.viewStart, owner.viewport.getViewPositionY(), e.mods.getRawFlags());
            if (lastDrag == drag) return;
            lastDrag = drag;
            if (selectingTake)
            {
                const auto at = owner.snapTime (owner.viewStart + e.x / owner.pixelsPerSecond, e.mods);
                owner.takeSelection.start = juce::jmin (takeAnchor, at); owner.takeSelection.end = juce::jmax (takeAnchor, at);
                repaint(); return;
            }
            if (owner.envelopeKey.isNotEmpty())
            {
                owner.refresh();
                if (const auto target = owner.automationTarget (owner.envelopeTrack, owner.envelopeKey)) owner.envelope.mouseDrag (owner.session, *target, envelopeArea, e);
                owner.refresh(); return;
            }
            if (selecting && e.mouseWasDraggedSinceMouseDown())
            {
                extendSelection (owner.snapTime (juce::jmax (0.0, owner.viewStart + e.x / owner.pixelsPerSecond), e.mods), owner.selectionTrackAtY (juce::jmax (0, e.y)));
                return;
            }
            if (draggedClip < 0 || e.mods.isPopupMenu() || ! e.mouseWasDraggedSinceMouseDown()) return;
            const auto current = owner.session.snapshot();
            if (fadeDrag != 0)
            {
                for (const auto& track : current.tracks) for (const auto& clip : track.clips)
                    if (clip.id == dragClipId && clip.canEditAudioFades)
                    {
                        auto settings = clip.audio;
                        const auto other = fadeDrag == 1 ? settings.fadeOutSeconds : settings.fadeInSeconds;
                        const auto value = juce::jlimit (0.0, juce::jmax (0.0,clip.length-other),
                            originalFade+(e.x-dragStartX)/owner.pixelsPerSecond*(fadeDrag == 1 ? 1 : -1));
                        if (! clipGesture) { owner.session.beginEditGesture ("Adjust clip fade"); clipGesture = true; }
                        if (fadeDrag == 1) settings.fadeInSeconds = value; else settings.fadeOutSeconds = value;
                        owner.report (owner.session.setAudioClipSettings (dragClipId,settings)); owner.refresh(); return;
                    }
                return;
            }
            if (rangeDrag != 0)
            {
                for (const auto& track : current.tracks) for (const auto& clip : track.clips)
                    if (clip.id == dragClipId && clip.canEditAudioRange)
                    {
                        auto start = originalRange.start, length = originalRange.length, offset = originalRange.sourceOffset;
                        const auto minimum = juce::jmax (.001, clip.audio.fadeInSeconds+clip.audio.fadeOutSeconds);
                        const auto delta = (e.x-dragStartX)/owner.pixelsPerSecond;
                        const auto snap = [&] (double value)
                        { return owner.snaps (e.mods) ? owner.toGrid (value) : value; };
                        if (rangeDrag == 1)
                        {
                            const auto shift = juce::jlimit (-juce::jmin (start,offset), juce::jmax (0.0,length-minimum), snap (start+delta)-start);
                            start += shift; offset += shift; length -= shift;
                        }
                        else if (rangeDrag == 2)
                            length = juce::jlimit (minimum, juce::jmax (minimum,clip.sourceLength-offset), snap (start+length+delta)-start);
                        else
                            offset = juce::jlimit (0.0, juce::jmax (0.0,clip.sourceLength-length), offset-delta);
                        if (! clipGesture) { owner.session.beginEditGesture (rangeDrag == 3 ? "Slip audio source" : "Trim audio edge"); clipGesture = true; }
                        const auto result = owner.session.setAudioClipRange (dragClipId,start,length,offset);
                        owner.report (result); owner.refresh();
                        if (result.wasOk()) owner.selectArrangementClip (dragClipId);
                        return;
                    }
                    else if (clip.id == dragClipId && clip.canLoop && rangeDrag != 3)
                    {
                        // MIDI and warped clips trim in beats. A looped clip's start wraps round its
                        // loop; an unlooped one cannot start before its content or, for audio, run
                        // past its source.
                        const auto& from = originalRange;
                        const auto edge = owner.secondsAt (rangeDrag == 1 ? from.startBeat : from.startBeat + from.lengthBeats) + (e.x - dragStartX) / owner.pixelsPerSecond;
                        const auto beat = owner.beatsAt (owner.snaps (e.mods) ? owner.toGrid (std::max (0.0, edge)) : edge);
                        constexpr double shortest = 1.0 / 64;
                        auto startBeat = from.startBeat, length = from.lengthBeats, content = from.contentStartBeat;
                        if (rangeDrag == 1)
                        {
                            auto shift = juce::jlimit (-from.startBeat, from.lengthBeats - shortest, beat - from.startBeat);
                            if (! from.loop.on) shift = std::max (shift, -from.contentStartBeat);
                            startBeat += shift; length -= shift;
                            content = from.loop.on ? from.loop.start + std::fmod (std::fmod (from.contentStartBeat - from.loop.start + shift, from.loop.length) + from.loop.length, from.loop.length)
                                                   : from.contentStartBeat + shift;
                        }
                        else
                        {
                            length = std::max (shortest, beat - from.startBeat);
                            if (! from.loop.on) length = std::min (length, sourceBeats (from) - from.contentStartBeat);
                        }
                        if (! clipGesture) { owner.session.beginEditGesture ("Trim clip edge"); clipGesture = true; }
                        const auto result = owner.session.setClipBeats (dragClipId, startBeat, length, content);
                        owner.report (result); owner.refresh();
                        if (result.wasOk()) owner.selectArrangementClip (dragClipId);
                        return;
                    }
                return;
            }
            if (owner.selectedClipIds.size() > 1 && owner.selectedClipIds.contains (dragClipId)) { dragGroup (e, current); return; }
            // Resolve the stable identity on every event; sorting, deletion or a
            // project switch must never redirect a body drag to the old index.
            for (int t=0; t<(int)current.tracks.size(); ++t)
                for (int c=0; c<(int)current.tracks[(size_t)t].clips.size(); ++c)
                    if (current.tracks[(size_t)t].clips[(size_t)c].id == dragClipId)
                    {
                        auto start = juce::jmax (0.0, originalStart + (e.x - dragStartX) / owner.pixelsPerSecond);
                        if (owner.snaps (e.mods)) start = owner.toGrid (start);
                        const auto& clip = current.tracks[(size_t)t].clips[(size_t)c];
                        const int destination = owner.trackAtY (e.y);
                        if (! juce::isPositiveAndBelow (destination,(int)current.tracks.size())
                            || current.tracks[(size_t)destination].isMidi != clip.isMidi || current.tracks[(size_t)destination].isReturn) return;
                        if (! clipGesture)
                        {
                            // A copying drag leaves a copy where the clip was, as the reference's does.
                            owner.session.beginEditGesture (copyDrag (e.mods) ? "Copy clip" : "Move clip"); clipGesture = true;
                            juce::String copy;
                            if (copyDrag (e.mods) && juce::isPositiveAndBelow (dragTrack, (int) current.tracks.size()))
                                owner.report (owner.session.copyClipTo (dragClipId, current.tracks[(size_t) dragTrack].id, originalStart, copy));
                            movedClips = { { dragClipId, dragTrack, originalStart } }; movedByCopy = copyDrag (e.mods);
                        }
                        const auto result = clip.isAudio ? owner.session.moveAudioClip (dragClipId,current.tracks[(size_t)destination].id,start, false)
                            : owner.session.moveMidiClip (dragClipId,current.tracks[(size_t)destination].id,start, false);
                        owner.report (result); owner.refresh();
                        if (result.wasOk()) owner.selectArrangementClip (dragClipId);
                        return;
                    }
        }
        void mouseUp (const juce::MouseEvent& e) override
        {
            // A click without a drag on a clip of a group selects it alone, or with Cmd/Ctrl leaves it out.
            if (! e.mouseWasDraggedSinceMouseDown() && dragClipId.isNotEmpty())
            {
                if (toggleOffOnUp)
                {
                    owner.selectedClipIds.removeString (dragClipId);
                    const auto rest = owner.selectedClipIds;
                    if (rest.size() < 2) owner.selectedClipIds.clear();
                    if (! rest.isEmpty()) owner.selectArrangementClip (rest[0]);
                }
                else if (collapseOnUp) owner.selectedClipIds.clear();
                repaint();
            }
            toggleOffOnUp = collapseOnUp = false;
            if (selectingTake) { selectingTake = false; return; }
            if (owner.envelopeKey.isNotEmpty())
            {
                owner.refresh();
                const auto target = owner.automationTarget (owner.envelopeTrack, owner.envelopeKey);
                owner.envelope.mouseUp (owner.session, target ? *target : arrangementAutomation::Target {});
                owner.envelopeKey.clear(); owner.refresh(); return;
            }
            if (clipGesture && ! movedClips.empty())
            {
                // The automation follows the clips that stayed on their tracks, in one go, as the reference's does.
                const auto now = owner.session.snapshot();
                juce::StringArray ids; double offset = 0;
                for (const auto& moved : movedClips)
                    if (juce::isPositiveAndBelow (moved.track, (int) now.tracks.size()))
                        for (const auto& clip : now.tracks[(size_t) moved.track].clips)
                            if (clip.id == moved.id && std::abs (clip.start - moved.start) > 1.0e-9) { ids.add (moved.id); offset = clip.start - moved.start; }
                if (! ids.isEmpty()) owner.report (owner.session.moveAutomationWithClips (ids, offset, movedByCopy));
            }
            movedClips.clear();
            if (clipGesture) { owner.session.endEditGesture(); clipGesture = false; }
            draggedClip = -1; fadeDrag = 0; rangeDrag = 0; dragClipId.clear(); selecting = false;
        }
        // A click on a clip: Cmd (Mac) or Ctrl adds it to the selection, or on mouse up without a drag
        // leaves it out; Shift takes in every clip in the span from the selection to it, across the
        // tracks between; a plain click on a clip of a group keeps the group for a drag; otherwise
        // the clip is selected alone.
        void chooseClips (int track, int c, juce::ModifierKeys mods, int previousTrack, int previousClip)
        {
            const auto& clip = owner.state.tracks[(size_t) track].clips[(size_t) c];
            auto group = owner.selectedClipIds;
            if (group.isEmpty() && juce::isPositiveAndBelow (previousTrack, (int) owner.state.tracks.size())
                && juce::isPositiveAndBelow (previousClip, (int) owner.state.tracks[(size_t) previousTrack].clips.size()))
                group.add (owner.state.tracks[(size_t) previousTrack].clips[(size_t) previousClip].id);
            toggleOffOnUp = collapseOnUp = false;
           #if JUCE_MAC
            const bool adds = mods.isCommandDown();
           #else
            const bool adds = mods.isCtrlDown();
           #endif
            if (adds) { if (group.contains (clip.id)) toggleOffOnUp = true; else group.add (clip.id); }
            else if (mods.isShiftDown() && ! mods.isAltDown() && ! group.isEmpty())
            {
                group.add (clip.id);
                const auto span = owner.clipSpan (group);
                for (int t = span.first; t <= span.last; ++t)
                    for (const auto& other : owner.state.tracks[(size_t) t].clips)
                        if (other.start >= span.start - 1e-9 && other.start + other.length <= span.end + 1e-9) group.addIfNotAlreadyThere (other.id);
            }
            else if (group.contains (clip.id) && group.size() > 1) collapseOnUp = true;
            else group = { clip.id };
            owner.selectedClipIds = group.size() > 1 ? group : juce::StringArray();
        }
        // Option (Mac) or Ctrl held as a drag begins copies, as in the reference.
        static bool copyDrag (juce::ModifierKeys mods)
        {
           #if JUCE_MAC
            return mods.isAltDown();
           #else
            return mods.isCtrlDown();
           #endif
        }
        // A group moves together by the dragged clip's snapped move and its change of track, as long
        // as every clip lands on a track of its kind; a copying drag leaves copies behind.
        void dragGroup (const juce::MouseEvent& e, const Session::Snapshot& current)
        {
            auto start = juce::jmax (0.0, originalStart + (e.x - dragStartX) / owner.pixelsPerSecond);
            if (owner.snaps (e.mods)) start = owner.toGrid (start);
            auto shift = start - originalStart;
            for (const auto& m : moving) shift = juce::jmax (shift, -m.start);
            const auto destination = owner.trackAtY (e.y);
            if (destination < 0 || destination >= (int) current.tracks.size()) return;
            const int trackShift = destination - dragTrack;
            for (const auto& m : moving)
            {
                const int t = m.track + trackShift;
                if (! juce::isPositiveAndBelow (t, (int) current.tracks.size()) || current.tracks[(size_t) t].isReturn || current.tracks[(size_t) t].isMidi != m.midi) return;
            }
            if (! clipGesture)
            {
                owner.session.beginEditGesture (copyDrag (e.mods) ? "Copy clips" : "Move clips"); clipGesture = true;
                if (copyDrag (e.mods))
                    for (const auto& m : moving) { juce::String copy; owner.report (owner.session.copyClipTo (m.id, current.tracks[(size_t) m.track].id, m.start, copy)); }
                movedClips.clear(); movedByCopy = copyDrag (e.mods);
                for (const auto& m : moving) movedClips.push_back ({ m.id, m.track, m.start });
            }
            for (const auto& m : moving)
            {
                const auto& to = current.tracks[(size_t) (m.track + trackShift)].id;
                const auto result = m.midi ? owner.session.moveMidiClip (m.id, to, m.start + shift, false) : owner.session.moveAudioClip (m.id, to, m.start + shift, false);
                if (result.failed()) { owner.report (result); break; }
            }
            owner.refresh(); owner.selectArrangementClip (dragClipId);
        }
        struct Moving { juce::String id; int track = -1; double start = 0; bool midi = false; };
        std::vector<Moving> moving;
        // The clips a drag moves, where they started: their automation follows them when it ends.
        struct MovedClip { juce::String id; int track = -1; double start = 0; };
        std::vector<MovedClip> movedClips;
        bool movedByCopy = false;
        int dragTrack = -1;
        bool toggleOffOnUp = false, collapseOnUp = false;
        // The selection runs from the anchor to the pointer in time and across the tracks between them.
        void extendSelection (double at, int track)
        {
            const int count = (int) owner.state.tracks.size();
            if (count == 0 || selectionAnchorTrack < 0) return;
            const int first = juce::jlimit (0, count - 1, juce::jmin (selectionAnchorTrack, track < 0 ? count - 1 : track));
            const int last = juce::jlimit (0, count - 1, juce::jmax (selectionAnchorTrack, track < 0 ? count - 1 : track));
            Impl::TimeSelection next { juce::jmin (selectionAnchorTime, at), juce::jmax (selectionAnchorTime, at), {} };
            for (int t = first; t <= last; ++t) next.trackIds.add (owner.state.tracks[(size_t) t].id);
            owner.addLinkedTracks (next.trackIds);
            owner.timeSelection = next; owner.session.setInsertMarker (next.start); repaint(); owner.ruler.repaint();
        }
        void mouseMove (const juce::MouseEvent& e) override
        {
            // A clip's own info text shows in the Info view while pointing at it.
            juce::String infoTitle, infoText;
            const auto track = owner.trackAtY (e.y); bool handle = false;
            if (e.x < timelineWidth() && juce::isPositiveAndBelow (track, (int) owner.state.tracks.size()))
                for (const auto& clip : owner.state.tracks[(size_t) track].clips)
                    if (clipBounds (clip, track).contains (e.position)) { infoTitle = clip.name; infoText = clip.infoText; }
            getProperties().set (infoTitleProperty, infoTitle); getProperties().set (infoTextProperty, infoText);
            if (e.x < timelineWidth() && e.y >= 0 && juce::isPositiveAndBelow (track,(int) owner.state.tracks.size()))
            {
                const auto& clips = owner.state.tracks[(size_t) track].clips;
                for (int c=(int)clips.size()-1; c>=0; --c)
                    if (clipBounds (clips[(size_t)c],track).contains (e.position))
                    { handle = track == owner.selectedTrack && c == owner.selectedClip
                        && (hitFade (clips[(size_t)c],track,e.position) != 0 || hitTrim (clips[(size_t)c],track,e.position) != 0); break; }
            }
            // In Draw Mode the pointer is a pencil over the envelopes it draws.
            juce::String envelopeTrack, envelopeKey; juce::Rectangle<float> envelopeLane;
            if (owner.drawMode && owner.automationMode && e.x < timelineWidth() && envelopeAt (e.y, envelopeTrack, envelopeKey, envelopeLane)) { setMouseCursor (owner.drawCursor); return; }
            setMouseCursor (handle ? juce::MouseCursor::LeftRightResizeCursor : juce::MouseCursor::NormalCursor);
        }
        void mouseWheelMove (const juce::MouseEvent& event, const juce::MouseWheelDetails& wheel) override
        {
            if (event.mods.isCommandDown()) { owner.zoom (wheel.deltaY > 0 ? 1.12 : 1.0 / 1.12); return; }
            if (event.mods.isAltDown() && wheel.deltaY != 0) { owner.scaleTrackHeight (owner.trackAtY (event.y), wheel.deltaY > 0 ? 1.12 : 1 / 1.12); return; }
            if (event.mods.isShiftDown() || std::abs (wheel.deltaX) > std::abs (wheel.deltaY))
            {
                const auto delta = event.mods.isShiftDown() ? wheel.deltaY : wheel.deltaX;
                if (owner.state.playing) owner.setFollow (false);
                owner.viewStart = juce::jmax (0.0, owner.viewStart - delta * 300.0 / owner.pixelsPerSecond);
                owner.updateScroll(); owner.ruler.repaint(); repaint(); return;
            }
            juce::Component::mouseWheelMove (event, wheel);
        }
        bool keyPressed (const juce::KeyPress& key) override { return owner.handleKey (key); }
        bool dragHover = false;
        // A drag that may scroll the view starts: see scrollForDrag. While the pointer rests, drag events keep coming.
        void beginDragScroll() { dragClock = false; verticalCarry = 0; beginDragAutoRepeat (30); }
        // When the last drag event came, once the drag has moved; each scrolls by the time since the one before.
        double lastDragScroll = 0;
        // Dragging to the timeline's left or right edge scrolls it, when the drag moves along time, and to
        // the top or bottom of the lanes shown scrolls them, faster the further the pointer goes and on
        // while it rests there, so a drag reaches what is out of view. A drag along time keeps its anchor
        // at the same time, so what is dragged stays under the pointer. The speeds are Halftrack's own.
        void scrollForDrag (juce::Point<int> at, bool alongTime)
        {
            constexpr int border = 16;
            const auto now = juce::Time::getMillisecondCounterHiRes();
            const auto elapsed = std::exchange (dragClock, true) ? juce::jlimit (0.0, 0.1, (now - lastDragScroll) / 1000.0) : 0.0;
            lastDragScroll = now;
            // From 60 pixels a second at the border to 2400 at 100 pixels into or past it.
            const auto speed = [] (int depth) { return depth == 0 ? 0.0 : std::copysign (juce::jlimit (60.0, 2400.0, std::abs (depth) * 24.0), (double) depth); };
            const auto width = timelineWidth();
            if (const auto pixels = alongTime ? speed (at.x < border ? at.x - border : at.x > width - border ? at.x - (width - border) : 0) * elapsed : 0.0; pixels != 0)
            {
                const auto before = owner.viewStart;
                owner.viewStart = juce::jmax (0.0, owner.viewStart + pixels / owner.pixelsPerSecond);
                if (owner.viewStart != before)
                {
                    if (owner.state.playing) owner.setFollow (false);
                    dragStartX -= (owner.viewStart - before) * owner.pixelsPerSecond;
                    owner.updateScroll(); owner.ruler.repaint(); repaint();
                }
            }
            const auto y = owner.viewport.getLocalPoint (this, at).y, height = owner.viewport.getMaximumVisibleHeight();
            const auto depth = y < border ? y - border : y > height - border ? y - (height - border) : 0;
            verticalCarry = depth == 0 ? 0 : verticalCarry + speed (depth) * elapsed;
            if (const auto step = (int) verticalCarry; step != 0)
            {
                verticalCarry -= step;
                owner.viewport.setViewPosition (0, owner.viewport.getViewPositionY() + step);
            }
        }
    private:
        Impl& owner;
        std::vector<std::unique_ptr<TrackRow>> rows;
        bool dragClock = false;
        double verticalCarry = 0; // The part of a pixel the lanes have yet to scroll by.
        std::optional<std::tuple<int, int, double, int, int>> lastDrag;
        std::map<juce::String, std::unique_ptr<juce::AudioThumbnail>> thumbnails;
        int draggedClip = -1, selectionAnchorTrack = -1;
        double dragStartX = 0;
        double originalStart = 0, originalFade = 0, selectionAnchorTime = 0;
        bool selecting = false;
        int fadeDrag = 0, rangeDrag = 0;
        Session::ClipInfo originalRange;
        juce::String dragClipId;
        bool clipGesture = false;
        void changeListenerCallback (juce::ChangeBroadcaster*) override { repaint(); }
        juce::AudioThumbnail* thumbnailFor (const juce::File& file)
        {
            if (! file.existsAsFile()) return nullptr;
            const auto key = file.getFullPathName();
            auto found = thumbnails.find (key);
            if (found != thumbnails.end()) return found->second.get();
            auto thumb = std::make_unique<juce::AudioThumbnail> (256, owner.formats, owner.thumbnailCache);
            thumb->addChangeListener (this);
            thumb->setSource (new juce::FileInputSource (file));
            auto* result = thumb.get();
            thumbnails.emplace (key, std::move (thumb));
            return result;
        }
    };

    class Ruler final : public juce::Component
    {
    public:
        explicit Ruler (Impl& o) : owner (o)
        {
            setName ("Arrangement ruler and locators"); setWantsKeyboardFocus (true);
            for (auto* button : { &add, &previous, &next, &automationMode }) { addAndMakeVisible (button); button->setWantsKeyboardFocus (false); }
            add.setName ("Add locator at playhead"); previous.setName ("Previous locator"); next.setName ("Next locator");
            automationMode.setName ("Automation Mode"); automationMode.setClickingTogglesState (true);
            automationMode.setTooltip ("Automation Mode: show and edit envelopes in the tracks  |  A");
            automationMode.setColour (juce::TextButton::buttonOnColourId, orange); automationMode.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            automationMode.onClick = [this] { owner.setAutomationMode (automationMode.getToggleState()); };
            add.setTooltip ("Name a song section at the playhead. Double-click a locator to edit it.");
            previous.setTooltip ("Jump to previous locator"); next.setTooltip ("Jump to next locator");
            add.onClick = [this] { addAt (owner.session.snapshot().position); };
            previous.onClick = [this] { navigate (false); }; next.onClick = [this] { navigate (true); };
        }
        ~Ruler() override { if (definingLoop || locatorGesture) owner.session.endEditGesture(); }
        void resized() override
        {
            const auto left = owner.canvas.timelineWidth()+12;
            add.setBounds (left,32,132,22); previous.setBounds (left+142,32,44,22); next.setBounds (left+192,32,44,22);
            automationMode.setBounds (left+120,4,116,22);
        }
        void sync()
        {
            bool exists=false,hasPrevious=false,hasNext=false;
            for (const auto& marker : owner.state.locators)
            {
                exists = exists || marker.id == selected;
                hasPrevious = hasPrevious || marker.position < owner.state.position-.001;
                hasNext = hasNext || marker.position > owner.state.position+.001;
            }
            if (! exists) selected.clear();
            if (selectedMeter >= (int) owner.state.timeSignatures.size()) selectedMeter = -1;
            const bool enabled = ! owner.session.isExporting();
            add.setEnabled (enabled); previous.setEnabled (enabled && hasPrevious); next.setEnabled (enabled && hasNext);
            automationMode.setToggleState (owner.automationMode, juce::dontSendNotification); repaint();
        }
        void addAt (double seconds)
        {
            juce::String id; const auto result = owner.session.addLocator (seconds,{},id);
            owner.report (result); if (result.wasOk()) selected=id; owner.refresh();
        }
        void navigate (bool forward)
        {
            owner.report (owner.session.navigateLocator (forward)); owner.refresh();
            const auto width = owner.canvas.timelineWidth()/owner.pixelsPerSecond;
            if (owner.state.position < owner.viewStart || owner.state.position > owner.viewStart+width)
                owner.viewStart = juce::jmax (0.0,owner.state.position-width*.2);
            owner.updateScroll(); owner.canvas.repaint(); repaint();
        }
        juce::Rectangle<float> locatorBounds (const Session::LocatorInfo& marker) const
        {
            const auto x = (float)((marker.position-owner.viewStart)*owner.pixelsPerSecond);
            float width=130;
            const auto nextMarker=std::upper_bound (owner.state.locators.begin(),owner.state.locators.end(),marker.position,
                [] (double time,const Session::LocatorInfo& item) {return time<item.position;});
            if (nextMarker!=owner.state.locators.end())
                width=juce::jmin (width,(float)((nextMarker->position-marker.position)*owner.pixelsPerSecond)-3);
            return {x,(float) scrubTop()+1,juce::jmax (12.0f,width),20};
        }
        // Where the locators' scrub area starts: under the bar numbers, and the time signature lane while it shows.
        int scrubTop() const { return 35 + (owner.meterLaneShown() ? meterLaneHeight : 0); }
        // A time signature marker's place in its lane, as wide as its meter's text or the room before the next.
        juce::Rectangle<float> meterBounds (int index) const
        {
            const auto& markers = owner.state.timeSignatures;
            const auto x = (float) ((owner.secondsAt (markers[(size_t) index].beat) - owner.viewStart) * owner.pixelsPerSecond);
            float width = 40;
            if (index + 1 < (int) markers.size()) width = juce::jmin (width, (float) ((owner.secondsAt (markers[(size_t) index + 1].beat) - owner.viewStart) * owner.pixelsPerSecond) - x - 2);
            return { x, 35, juce::jmax (8.0f, width), (float) meterLaneHeight };
        }
        int hitMeter (juce::Point<float> point) const
        {
            if (! owner.meterLaneShown() || point.y < 35 || point.y >= 35 + meterLaneHeight || point.x < 0 || point.x >= owner.canvas.timelineWidth()) return -1;
            for (int i = (int) owner.state.timeSignatures.size(); --i >= 0;) if (meterBounds (i).contains (point)) return i;
            return -1;
        }
        int selectedMeter = -1;
        void selectMeter (int index) { selectedMeter = index; selected.clear(); braceSelected = false; repaint(); }
        // The marker after a fragmentary bar: the bar a time is in, or the one before a marker; 0 if none.
        int fragmentMarker (double seconds,int meter) const
        {
            const auto& markers=owner.state.timeSignatures;
            if (meter>0 && meter<(int)markers.size() && Session::barAt (markers,markers[(size_t)meter].beat-1.0e-6).fragmentary) return meter;
            const auto bar=Session::barAt (markers,owner.beatsAt (seconds));
            if (! bar.fragmentary) return 0;
            for (int i=1;i<(int)markers.size();++i) if (std::abs (markers[(size_t)i].beat-(bar.start+bar.length))<1.0e-9) return i;
            return 0;
        }
        // The song's start, which the ruler marks with a small play triangle: a locator, or the loop's start.
        std::optional<double> songStartTime() const
        {
            for (const auto& marker:owner.state.locators) if (marker.songStart) return marker.position;
            if (owner.state.loopIsSongStart) return owner.state.loopStart;
            return std::nullopt;
        }
        // The loop brace's handles and bar, which the reference drags: the start or end handle moves
        // that end, the bar moves the whole loop.
        enum class BracePart { none, start, end, bar };
        BracePart bracePart (juce::Point<float> point) const
        {
            if (point.y >= 14 || point.x < 0 || point.x >= owner.canvas.timelineWidth()) return BracePart::none;
            const auto x1 = (float) ((owner.state.loopStart - owner.viewStart) * owner.pixelsPerSecond);
            const auto x2 = (float) ((owner.state.loopEnd - owner.viewStart) * owner.pixelsPerSecond);
            if (std::abs (point.x - x1) <= 4) return BracePart::start;
            if (std::abs (point.x - x2) <= 4) return BracePart::end;
            return point.x > x1 && point.x < x2 ? BracePart::bar : BracePart::none;
        }
        // The brace once clicked: the arrow keys move and resize it, as the reference's.
        bool braceSelected = false;
        void moveBrace (double startBeat, double endBeat)
        {
            if (startBeat < 0) { endBeat -= startBeat; startBeat = 0; }
            owner.session.setLoop (owner.state.looping, owner.secondsAt (startBeat), owner.secondsAt (endBeat)); owner.refresh();
        }
        juce::String hitLocator (juce::Point<float> point) const
        {
            if (point.x < 0 || point.x >= owner.canvas.timelineWidth()) return {};
            for (auto it=owner.state.locators.rbegin();it!=owner.state.locators.rend();++it)
                if (locatorBounds (*it).contains (point)) return it->id;
            return {};
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff393939));
            const auto width=owner.canvas.timelineWidth();
            g.saveState();g.reduceClipRegion (0,0,width,getHeight());
            const auto x1=(float)((owner.state.loopStart-owner.viewStart)*owner.pixelsPerSecond);
            const auto x2=(float)((owner.state.loopEnd-owner.viewStart)*owner.pixelsPerSecond);
            g.setColour (owner.state.looping?orange:muted.withAlpha (.55f));
            g.fillRect (x1,3.0f,juce::jmax (1.0f,x2-x1),3.0f);g.fillRect (x1,3.0f,2.0f,9.0f);g.fillRect (x2-2,3.0f,2.0f,9.0f);
            if (braceSelected) { g.setColour (ink);g.drawRect (juce::Rectangle<float> (x1-1,2.0f,juce::jmax (3.0f,x2-x1+2),11.0f),1.0f); }
            // Bar numbers at the bars' starts through the time signature markers and the tempo map, spaced
            // at least 48 pixels apart at the playhead's tempo.
            const auto& markers=owner.state.timeSignatures;
            const auto firstBar=Session::barAt (markers,owner.beatsAt (owner.viewStart));
            const auto barWidth=firstBar.meter.beatsPerBar()*60.0/owner.state.tempo*owner.pixelsPerSecond;
            const auto stepBars=juce::jmax (1,(int)std::pow (2.0,std::ceil (std::log2 (48.0/juce::jmax (1.0e-6,barWidth)))));
            const auto end=owner.viewStart+width/owner.pixelsPerSecond;
            const auto xAt=[this] (double beat) { return (int)std::round ((owner.secondsAt (beat)-owner.viewStart)*owner.pixelsPerSecond); };
            g.setFont (font (10.5f));
            for (int bar=(int)std::floor ((double)firstBar.number/stepBars)*stepBars;;bar+=stepBars)
            {
                const auto start=Session::barStart (markers,bar);
                if (owner.secondsAt (start)>end) break;
                const int x=xAt (start);
                g.setColour (muted);g.drawText (juce::String (bar+1),x+5,15,55,19,juce::Justification::centredLeft);
                g.setColour (themes::colour (0xff5d5d5d));g.drawVerticalLine (x,14.0f,34.0f);
            }
            // A bar a marker cuts short is crosshatched, as the reference's fragmentary bars are.
            for (size_t i=1;i<markers.size();++i)
                if (const auto cut=Session::barAt (markers,markers[i].beat-1.0e-6); cut.fragmentary)
                {
                    const int x1=xAt (cut.start),x2=xAt (markers[i].beat);
                    if (x2<0 || x1>width) continue;
                    g.saveState();g.reduceClipRegion (juce::Rectangle<int> (x1,14,juce::jmax (1,x2-x1),21));
                    g.setColour (themes::colour (0xff5d5d5d));
                    for (int k=x1-20;k<x2;k+=5) g.drawLine ((float)k,35.0f,(float)k+20,14.0f);
                    g.restoreState();
                }
            g.setColour (background);g.fillRect (0,35,width,getHeight()-35);
            // The time signature markers' lane, while the meter changes.
            if (owner.meterLaneShown())
            {
                g.setColour (themes::colour (0xff2f2f2f));g.fillRect (0,35,width,meterLaneHeight);
                for (int i=0;i<(int)markers.size();++i)
                {
                    const auto bounds=meterBounds (i);
                    if (bounds.getRight()<0 || bounds.getX()>=width) continue;
                    g.setColour (i==selectedMeter?orange:themes::colour (0xffb2b2b2));
                    g.drawVerticalLine ((int)bounds.getX(),35.0f,35.0f+meterLaneHeight);
                    g.setFont (font (10.0f,i==selectedMeter));
                    g.drawText (Impl::meterText (markers[(size_t)i].meter),bounds.withTrimmedLeft (3),juce::Justification::centredLeft,false);
                }
            }
            for (const auto& marker : owner.state.locators)
            {
                const auto bounds=locatorBounds (marker);
                if (bounds.getRight()<0 || bounds.getX()>=width) continue;
                g.setColour (marker.id==selected?orange:themes::colour (0xffb2b2b2));
                juce::Path flag;flag.addTriangle (bounds.getX(),bounds.getY()+1,bounds.getX()+8,bounds.getY()+1,bounds.getX(),bounds.getY()+9);g.fillPath (flag);
                g.drawVerticalLine ((int)bounds.getX(),bounds.getY()+1,bounds.getBottom());
                g.setFont (font (10.0f,marker.id==selected));
                g.drawText (marker.name,bounds.withTrimmedLeft (11),juce::Justification::centredLeft,true);
            }
            if (const auto start=songStartTime())
            {
                const auto sx=(float)((*start-owner.viewStart)*owner.pixelsPerSecond);
                const auto top=(float)scrubTop();
                juce::Path play;play.addTriangle (sx+2,top+12,sx+2,top+20,sx+8,top+16);
                g.setColour (ink);g.fillPath (play);
            }
            const auto px=(float)((owner.state.position-owner.viewStart)*owner.pixelsPerSecond);
            juce::Path needle;needle.addTriangle (px-5,15,px+5,15,px,23);
            g.setColour (owner.state.recording?red:ink);g.fillPath (needle);g.restoreState();
            g.setColour (raised);g.fillRect (width,0,getWidth()-width,getHeight());
            g.setColour (muted);g.setFont (font (10.0f,true));
            g.drawText ("TRACK / MIXER",width+12,0,trackWidth-24,29,juce::Justification::centredLeft);
            g.setColour (line);g.drawHorizontalLine (getHeight()-1,0.0f,(float)getWidth());
        }
        void mouseDown (const juce::MouseEvent& event) override
        {
            if (event.x>=owner.canvas.timelineWidth() || owner.session.isExporting()) return;
            grabKeyboardFocus(); dragId.clear();
            anchor=juce::jmax (0.0,owner.viewStart+event.x/owner.pixelsPerSecond);
            const auto hit=hitLocator (event.position);
            const auto meter=hitMeter (event.position);
            if (event.mods.isPopupMenu()) { if (meter>=0) selectMeter (meter); showMenu (hit,anchor,meter);return; }
            // A time signature marker: clicking selects it, and dragging moves it, but not the first.
            if (owner.meterLaneShown() && event.y>=35 && event.y<35+meterLaneHeight)
            {
                selectMeter (meter);meterDrag=meter>0?meter:-1;downX=event.x;
                if (meter>0) originalMeter=owner.state.timeSignatures[(size_t)meter].beat;
                return;
            }
            selectedMeter=-1;
            definingLoop=event.mods.isShiftDown();
            braceDrag=definingLoop?BracePart::none:bracePart (event.position);
            braceSelected=braceDrag!=BracePart::none;
            if (definingLoop) return;
            if (braceDrag!=BracePart::none)
            {
                downX=event.x;braceStart=owner.beatsAt (owner.state.loopStart);braceEnd=owner.beatsAt (owner.state.loopEnd);
                selected.clear();owner.refresh();return;
            }
            if (hit.isNotEmpty())
            {
                selected=hit;dragId=hit;downX=event.x;
                for (const auto& marker : owner.state.locators) if (marker.id==hit) original=marker.position;
                owner.report (owner.session.seekLocator (hit));
            }
            else {selected.clear();owner.session.seek (anchor);}
            owner.refresh();
        }
        void mouseDoubleClick (const juce::MouseEvent& event) override
        {
            if (event.x>=owner.canvas.timelineWidth() || event.mods.isPopupMenu() || event.mods.isShiftDown()) return;
            if (const auto meter=hitMeter (event.position); meter>=0) { owner.editMeterDialog (meter);return; }
            const auto hit=hitLocator (event.position);
            if (hit.isNotEmpty()) owner.editLocatorDialog (hit);
            else if (event.y>=scrubTop()) addAt (juce::jmax (0.0,owner.viewStart+event.x/owner.pixelsPerSecond));
        }
        void mouseDrag (const juce::MouseEvent& event) override
        {
            if (owner.session.isExporting()) return;
            if (meterDrag>0)
            {
                if (! event.mouseWasDraggedSinceMouseDown()) return;
                auto beat=originalMeter+owner.beatsAt (juce::jmax (0.0,owner.viewStart+event.x/owner.pixelsPerSecond))-owner.beatsAt (juce::jmax (0.0,owner.viewStart+downX/owner.pixelsPerSecond));
                if (owner.snaps (event.mods)) beat=owner.gridLine (beat);
                if (beat<=0) return;
                const auto& markers=owner.state.timeSignatures;
                for (int i=0;i<(int)markers.size();++i) if (i!=meterDrag && std::abs (markers[(size_t)i].beat-beat)<1.0/960) return; // Not onto another.
                if (! meterGesture) { owner.session.beginEditGesture ("Move time signature change");meterGesture=true; }
                owner.report (owner.session.moveTimeSignatureChange (meterDrag,beat));owner.refresh();
                for (int i=0;i<(int)owner.state.timeSignatures.size();++i) if (std::abs (owner.state.timeSignatures[(size_t)i].beat-beat)<1.0e-9) selectedMeter=meterDrag=i;
                return;
            }
            if (braceDrag!=BracePart::none)
            {
                if (! event.mouseWasDraggedSinceMouseDown()) return;
                const auto at=[this] (int x) { return owner.beatsAt (juce::jmax (0.0,owner.viewStart+x/owner.pixelsPerSecond)); };
                const auto grid=owner.gridBeats();const bool snap=owner.snaps (event.mods);
                const auto snapped=[&] (double beat) { return snap ? owner.gridLine (beat) : beat; };
                const auto least=snap ? grid : 1.0/64;
                auto start=braceStart,end=braceEnd;
                if (braceDrag==BracePart::bar) { start=juce::jmax (0.0,snapped (braceStart+at (event.x)-at (downX)));end=start+(braceEnd-braceStart); }
                else if (braceDrag==BracePart::start) start=juce::jlimit (0.0,end-least,snapped (at (event.x)));
                else end=juce::jmax (start+least,snapped (at (event.x)));
                moveBrace (start,end);return;
            }
            if (definingLoop)
            {
                const auto cursor=juce::jmax (0.0,owner.viewStart+event.x/owner.pixelsPerSecond);
                const auto first=owner.gridLine (owner.beatsAt (juce::jmin (anchor,cursor)),-1);
                auto last=owner.gridLine (owner.beatsAt (juce::jmax (anchor,cursor)),1);
                if (last<=first+1.0e-9) last=owner.gridLine (first+1.0e-6,1);
                owner.session.setLoop (true,owner.secondsAt (first),owner.secondsAt (last));owner.refresh();return;
            }
            if (dragId.isEmpty() || ! event.mouseWasDraggedSinceMouseDown()) return;
            for (const auto& marker : owner.session.snapshot().locators) if (marker.id==dragId)
            {
                auto time=original+(event.x-downX)/owner.pixelsPerSecond;
                if (owner.snaps (event.mods)) time = owner.toGrid (time);
                time=juce::jlimit (0.0,172800.0-.001,time);
                if (!locatorGesture){owner.session.beginEditGesture ("Move locator");locatorGesture=true;}
                owner.report (owner.session.updateLocator (dragId,marker.name,time));owner.refresh();return;
            }
        }
        void mouseUp (const juce::MouseEvent& event) override
        {
            // Clicking the brace selects the loop's time across the tracks, as the reference's Select Loop.
            if (braceDrag!=BracePart::none && ! event.mouseWasDraggedSinceMouseDown())
            {
                juce::StringArray ids;for (const auto& t:owner.state.tracks) ids.add (t.id);
                owner.timeSelection={ owner.state.loopStart,owner.state.loopEnd,ids };owner.refresh();
            }
            if (locatorGesture)owner.session.endEditGesture();
            if (meterGesture)owner.session.endEditGesture();
            definingLoop=false;locatorGesture=false;meterGesture=false;meterDrag=-1;dragId.clear();braceDrag=BracePart::none;
        }
        void focusLost (FocusChangeType) override { if (braceSelected) { braceSelected=false;repaint(); } }
        bool keyPressed (const juce::KeyPress& key) override
        {
            if (owner.session.isExporting())return true;
            // A selected time signature marker: Delete deletes it, the arrows move it by the grid, and
            // Cmd/Ctrl+R types its meter, as the reference's Edit Time Signature.
            if (juce::isPositiveAndBelow (selectedMeter,(int)owner.state.timeSignatures.size()))
            {
                const auto code=key.getKeyCode();
                if (code=='R' && key.getModifiers().isCommandDown()) { owner.editMeterDialog (selectedMeter);return true; }
                if (selectedMeter>0 && (code==juce::KeyPress::deleteKey || code==juce::KeyPress::backspaceKey))
                { owner.report (owner.session.removeTimeSignatureChange (selectedMeter));selectedMeter=-1;owner.refresh();return true; }
                if (selectedMeter>0 && (code==juce::KeyPress::leftKey || code==juce::KeyPress::rightKey))
                {
                    const auto beat=owner.state.timeSignatures[(size_t)selectedMeter].beat;
                    const auto to=code==juce::KeyPress::rightKey ? owner.gridLine (beat+1.0e-6,1) : owner.gridLine (beat-1.0e-6,-1);
                    if (to>0) owner.report (owner.session.moveTimeSignatureChange (selectedMeter,to));
                    owner.refresh();
                    for (int i=0;i<(int)owner.state.timeSignatures.size();++i) if (std::abs (owner.state.timeSignatures[(size_t)i].beat-to)<1.0e-9) selectedMeter=i;
                    repaint();return true;
                }
            }
            if ((key.getKeyCode()==juce::KeyPress::deleteKey || key.getKeyCode()==juce::KeyPress::backspaceKey)&&selected.isNotEmpty())
            {owner.report (owner.session.removeLocator (selected));owner.refresh();return true;}
            // A selected brace, as the reference's: Left and Right move it by the grid, Up and Down by its
            // length; with Cmd/Ctrl, Left and Right shorten and lengthen it by the grid, and Up and Down
            // double and halve it.
            if (braceSelected)
            {
                const auto code=key.getKeyCode();
                const bool horizontal=code==juce::KeyPress::leftKey || code==juce::KeyPress::rightKey, vertical=code==juce::KeyPress::upKey || code==juce::KeyPress::downKey;
                if (horizontal || vertical)
                {
                    const auto start=owner.beatsAt (owner.state.loopStart),end=owner.beatsAt (owner.state.loopEnd),length=end-start,grid=owner.gridBeats();
                    const bool later=code==juce::KeyPress::rightKey || code==juce::KeyPress::downKey;
                    if (key.getModifiers().isCommandDown())
                    {
                        if (horizontal) moveBrace (start,juce::jmax (start+grid,end+(later?grid:-grid)));
                        else moveBrace (start,code==juce::KeyPress::upKey ? start+length*2 : start+juce::jmax (length/2,1.0/64));
                    }
                    else
                    {
                        const auto step=horizontal?grid:length;
                        moveBrace (start+(later?step:-step),end+(later?step:-step));
                    }
                    return true;
                }
            }
            return owner.handleKey (key);
        }
    private:
        Impl& owner;
        juce::TextButton add {"Add locator"},previous {"<"},next {">"},automationMode {"Automation Mode"};
        juce::String selected,dragId;
        double anchor=0,original=0,braceStart=0,braceEnd=0,originalMeter=0;int downX=0,meterDrag=-1;
        bool definingLoop=false,locatorGesture=false,meterGesture=false;
        BracePart braceDrag=BracePart::none;
    public:
        // The ruler's menu, and acting on a choice from it; the UI suite uses both.
        juce::PopupMenu menuFor (const juce::String& id,double position,int meter=-1) const
        {
            juce::PopupMenu menu;menu.addItem (1,"Add locator here");
            // Time signature changes, as the reference's scrub area offers them.
            menu.addItem (10,"Insert Time Signature Change");
            if (meter>=0) { menu.addItem (11,"Edit Time Signature");menu.addItem (12,"Delete Time Signature Change",meter>0); }
            // A fragmentary bar, clicked or before the marker clicked, and the reference's two fixes.
            if (fragmentMarker (position,meter)>0) { menu.addItem (13,"Delete Fragmentary Bar Time");menu.addItem (14,"Complete Fragmentary Bar"); }
            if (id.isNotEmpty())
            {
                menu.addItem (2,"Edit locator...");menu.addItem (3,"Delete locator");
                // On a locator, as the reference's: Play then starts at the locator.
                bool songStart=false;for (const auto& marker:owner.state.locators) songStart=songStart||(marker.id==id&&marker.songStart);
                menu.addSeparator();menu.addItem (5,"Set Song Start Time Here",true,songStart);
            }
            // On the loop brace, as the reference's: Play then starts at the loop's start.
            else if (position>=owner.state.loopStart && position<owner.state.loopEnd) {menu.addSeparator();menu.addItem (4,"Set Song Start Time Here",true,owner.state.loopIsSongStart);}
            juce::PopupMenu jumps;int index=0;
            for (const auto& marker:owner.state.locators) jumps.addItem(100+index++,marker.name+"  /  "+juce::String(marker.position,3)+" s");
            if (index>0)menu.addSubMenu ("Jump to locator",jumps);
            return menu;
        }
        void choose (int choice,const juce::String& id,double position,const juce::StringArray& ids,int meter=-1)
        {
            if(choice==1)addAt(position);
            if(choice==10)owner.insertMeterChange(owner.snaps({})?owner.gridLine(owner.beatsAt(position)):owner.beatsAt(position));
            if(choice==11)owner.editMeterDialog(meter);
            if(choice==12&&meter>0){owner.report(owner.session.removeTimeSignatureChange(meter));selectedMeter=-1;owner.refresh();}
            if(choice==13||choice==14)
                if(const auto marker=fragmentMarker(position,meter);marker>0)
                {owner.report(choice==13?owner.session.deleteFragmentaryBarTime(marker):owner.session.completeFragmentaryBar(marker));owner.refresh();}
            if(choice==2)owner.editLocatorDialog(id);
            if(choice==3){owner.report(owner.session.removeLocator(id));owner.refresh();}
            if(choice==4){owner.report(owner.session.setLoopIsSongStart(!owner.state.loopIsSongStart));owner.refresh();}
            if(choice==5)
                for (const auto& marker:owner.state.locators)
                    if (marker.id==id){owner.report(owner.session.setLocatorSongStart(id,!marker.songStart));owner.refresh();break;}
            if(choice>=100&&choice-100<ids.size()){owner.report(owner.session.seekLocator(ids[choice-100]));owner.refresh();}
        }
    private:
        void showMenu (const juce::String& id,double position,int meter)
        {
            juce::StringArray ids;for (const auto& marker:owner.state.locators)ids.add(marker.id);
            auto safe=juce::Component::SafePointer<Ruler> (this);
            menuFor (id,position,meter).showMenuAsync (juce::PopupMenu::Options(),[safe,id,position,ids,meter](int choice) { if(safe!=nullptr)safe->choose(choice,id,position,ids,meter); });
        }
    };

    // The Arrangement's overview, after the reference's: the whole song in miniature, each track's clips
    // in its colour, with an outline round the time the Arrangement shows. A press outside the outline
    // centres the view there; a drag across moves the view, and down or up zooms it in or out about the
    // press.
    class Overview final : public juce::Component
    {
    public:
        explicit Overview (Impl& o) : owner (o) { setName ("Arrangement overview"); }
        static constexpr int height = 20;
        // What it spans: the clips, the loop and what the Arrangement shows.
        double span() const
        {
            auto end = juce::jmax (owner.state.loopEnd, owner.viewStart + visible());
            for (const auto& track : owner.state.tracks) for (const auto& clip : track.clips) end = juce::jmax (end, clip.start + clip.length);
            return juce::jmax (end, 1.0);
        }
        double visible() const { return owner.canvas.timelineWidth() / owner.pixelsPerSecond; }
        int stripWidth() const { return juce::jmax (1, juce::jmin (getWidth(), owner.canvas.timelineWidth())); }
        float xOf (double seconds, double total) const { return (float) (seconds / total * stripWidth()); }
        // Repaints once what it shows has changed.
        void sync()
        {
            auto hash = (juce::int64) std::llround (owner.viewStart * 1000) * 31 + (juce::int64) std::llround (owner.pixelsPerSecond * 1000) * 17 + stripWidth();
            for (const auto& track : owner.state.tracks)
                for (const auto& clip : track.clips)
                    hash = hash * 31 + (juce::int64) std::llround (clip.start * 1000) * 7 + (juce::int64) std::llround (clip.length * 1000) + (juce::int64) clip.colour.getARGB() + (clip.active ? 1 : 0);
            if (std::exchange (painted, hash) != hash) repaint();
        }
        void paint (juce::Graphics& g) override
        {
            const auto total = span();
            const auto strip = getLocalBounds().withWidth (stripWidth());
            g.setColour (themes::colour (0xff181818)); g.fillRect (strip);
            int rows = 0; for (const auto& track : owner.state.tracks) rows += track.isReturn ? 0 : 1;
            const auto rowHeight = (float) (strip.getHeight() - 2) / (float) juce::jmax (1, rows);
            int row = 0;
            for (const auto& track : owner.state.tracks)
            {
                if (track.isReturn) continue;
                const auto y = 1.0f + (float) row++ * rowHeight;
                for (const auto& clip : track.clips)
                {
                    const auto x = xOf (clip.start, total);
                    g.setColour (clip.active ? clip.colour : clip.colour.withSaturation (0.0f).withMultipliedAlpha (0.6f));
                    g.fillRect (juce::Rectangle<float> (x, y, juce::jmax (1.0f, xOf (clip.start + clip.length, total) - x), juce::jmax (1.0f, rowHeight - (rowHeight > 3.0f ? 1.0f : 0.0f))));
                }
            }
            // The time the Arrangement shows.
            const auto from = xOf (owner.viewStart, total);
            g.setColour (ink); g.drawRect (juce::Rectangle<float> (from, 0.5f, juce::jmax (3.0f, xOf (owner.viewStart + visible(), total) - from), (float) getHeight() - 1.0f), 1.0f);
            g.setColour (line); g.drawHorizontalLine (getHeight() - 1, (float) strip.getRight(), (float) getWidth());
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            pressSpan = span(); pressZoom = owner.pixelsPerSecond;
            pressSeconds = e.position.x / (double) stripWidth() * pressSpan;
            pressView = owner.viewStart;
            if (owner.state.playing) owner.setFollow (false); // As a hand scroll does.
            if (pressSeconds < owner.viewStart || pressSeconds > owner.viewStart + visible())
            { pressView = juce::jmax (0.0, pressSeconds - visible() / 2); owner.setView (pressView, pressZoom); }
        }
        void mouseDrag (const juce::MouseEvent& e) override
        {
            const auto zoom = juce::jlimit (3.0, 650.0, pressZoom * std::pow (1.01, (double) e.getDistanceFromDragStartY()));
            // The pressed time keeps its place in the Arrangement while zooming.
            const auto at = (pressSeconds - pressView) * pressZoom;
            owner.setView (pressSeconds - at / zoom + e.getDistanceFromDragStartX() / (double) stripWidth() * pressSpan, zoom);
        }
    private:
        Impl& owner;
        juce::int64 painted = 0;
        double pressSpan = 1, pressSeconds = 0, pressView = 0, pressZoom = 1;
    };
    Overview overview { *this };
    // Sets the Arrangement's view: its start and zoom.
    void setView (double start, double zoomLevel)
    {
        pixelsPerSecond = juce::jlimit (3.0, 650.0, zoomLevel);
        viewStart = juce::jmax (0.0, start);
        updateScroll(); canvas.repaint(); ruler.repaint(); timeRuler.repaint(); overview.sync();
    }

    // The Arrangement's time ruler, after the reference's: below the tracks, the time in minutes and
    // seconds or in SMPTE frames (Options > Time Ruler Format), labelled at steps at least 64 pixels apart.
    class TimeRuler final : public juce::Component
    {
    public:
        explicit TimeRuler (Impl& o) : owner (o) { setName ("Time ruler"); }
        static constexpr int height = 16;
        // Frames a second, and whether drop-frame numbering applies.
        static double frameRate (Session::TimeFormat format)
        {
            switch (format)
            {
                case Session::TimeFormat::smpte24: return 24.0;
                case Session::TimeFormat::smpte25: return 25.0;
                case Session::TimeFormat::smpte30: return 30.0;
                case Session::TimeFormat::smpte30Drop: case Session::TimeFormat::smpte2997: return 30000.0 / 1001.0;
                default: return 0.0;
            }
        }
        // A label: minutes and seconds (with milliseconds below a second's step), or SMPTE hours,
        // minutes, seconds and frames, the frames after a semicolon in drop-frame.
        static juce::String label (double seconds, Session::TimeFormat format, double step)
        {
            seconds = juce::jmax (0.0, seconds);
            if (format == Session::TimeFormat::minutesSeconds)
            {
                const auto milliseconds = (juce::int64) std::llround (seconds * 1000.0);
                auto text = juce::String (milliseconds / 60000) + ":" + juce::String ((milliseconds / 1000) % 60).paddedLeft ('0', 2);
                return step < 0.999 ? text + ":" + juce::String (milliseconds % 1000).paddedLeft ('0', 3) : text;
            }
            const int nominal = format == Session::TimeFormat::smpte24 ? 24 : format == Session::TimeFormat::smpte25 ? 25 : 30;
            auto frame = (juce::int64) std::floor (seconds * frameRate (format) + 1e-6);
            if (format == Session::TimeFormat::smpte30Drop)
            {
                // Frames 0 and 1 of every minute but each tenth are skipped.
                const auto tens = frame / 17982, rest = frame % 17982;
                frame += 18 * tens + (rest > 2 ? 2 * ((rest - 2) / 1798) : 0);
            }
            const auto two = [] (juce::int64 v) { return juce::String (v).paddedLeft ('0', 2); };
            const auto totalSeconds = frame / nominal;
            return two (totalSeconds / 3600) + ":" + two ((totalSeconds / 60) % 60) + ":" + two (totalSeconds % 60)
                 + (format == Session::TimeFormat::smpte30Drop ? ";" : ":") + two (frame % nominal);
        }
        // The labels' step in seconds: the first of the format's steps at least `minimum` long.
        static double step (double minimum, Session::TimeFormat format)
        {
            static constexpr double clock[] { .001, .002, .005, .01, .02, .05, .1, .2, .5, 1, 2, 5, 10, 15, 30, 60, 120, 300, 600, 1200, 1800, 3600 };
            if (const auto rate = frameRate (format); rate > 0)
            {
                for (const auto frames : { 1, 2, 5, 10 }) if (frames / rate >= minimum) return frames / rate;
                for (const auto s : clock) if (s >= 1 && s >= minimum) return s;
            }
            else for (const auto s : clock) if (s >= minimum) return s;
            return 3600;
        }
        void paint (juce::Graphics& g) override
        {
            const auto width = juce::jmin (getWidth(), owner.canvas.timelineWidth());
            g.setColour (themes::colour (0xff1e1e1e)); g.fillRect (getLocalBounds());
            g.setColour (line); g.drawHorizontalLine (0, 0.0f, (float) getWidth());
            const auto format = owner.state.timeRulerFormat;
            const auto every = step (64.0 / owner.pixelsPerSecond, format);
            g.setFont (font (9.5f));
            for (auto t = std::floor (owner.viewStart / every) * every; ; t += every)
            {
                const auto x = (float) ((t - owner.viewStart) * owner.pixelsPerSecond);
                if (x > (float) width) break;
                if (x < 0) continue;
                g.setColour (muted); g.drawVerticalLine ((int) x, 1.0f, 5.0f);
                g.setColour (ink.withAlpha (0.75f)); g.drawText (label (t, format, every), juce::Rectangle<float> (x + 3, 2, 90, (float) getHeight() - 2), juce::Justification::centredLeft, false);
            }
        }
    private:
        Impl& owner;
    };
    TimeRuler timeRuler { *this };

    // A scene's tempo and time signature fields' texts: its own, or the song's, which its field shows dimmed.
    juce::String sceneTempoText (const Session::SceneInfo& scene) const { return juce::String (scene.tempo.value_or (state.tempo), 2); }
    juce::String sceneSignatureText (const Session::SceneInfo& scene) const
    {
        const auto meter = scene.timeSignature.value_or (state.timeSignatures.empty() ? Session::TimeSignature {} : state.timeSignatures.front().meter);
        return juce::String (meter.numerator) + "/" + juce::String (meter.denominator);
    }
    class LauncherGrid final : public juce::Component, private juce::ScrollBar::Listener
    {
    public:
        explicit LauncherGrid (Impl& o) : owner (o)
        {
            setName ("Session clip grid"); setWantsKeyboardFocus (true);
            for (auto* child : std::initializer_list<juce::Component*> { &mixers, &horizontal, &vertical, &masterStrip }) addAndMakeVisible (child);
            mixers.setInterceptsMouseClicks (false, true);
            horizontal.addListener (this); vertical.addListener (this);
        }
        ~LauncherGrid() override { horizontal.removeListener (this); vertical.removeListener (this); }
        void sync()
        {
            buildColumns();
            owner.syncTrackRows (mixers, rows, true);
            bool same = groupStrips.size() == owner.state.groups.size();
            for (size_t i = 0; same && i < groupStrips.size(); ++i) same = groupStrips[i]->getId() == owner.state.groups[i].id;
            if (! same)
            {
                groupStrips.clear();
                for (const auto& group : owner.state.groups) { groupStrips.push_back (std::make_unique<GroupHeader> (owner, group.id, true)); mixers.addAndMakeVisible (*groupStrips.back()); }
            }
            for (auto& strip : groupStrips) strip->sync();
            masterStrip.sync();
            resized(); repaint();
        }
        // Display columns: a group's column precedes its members, and a folded group hides them.
        struct Column { int track = -1, group = -1; };
        void buildColumns()
        {
            columns.clear();
            for (const auto& item : owner.visualOrder())
            {
                // A column for each group, before what is in it, unless a group around it is folded.
                if (item.group)
                {
                    if (! owner.anyFolded (owner.state.groups[(size_t) item.index].parentId)) columns.push_back ({ -1, item.index });
                    continue;
                }
                const auto& track = owner.state.tracks[(size_t) item.index];
                if (track.isReturn && ! owner.state.mixerSections.returns) continue; // The Returns section hidden.
                if (! owner.anyFolded (track.groupId)) columns.push_back ({ item.index, -1 });
            }
        }
        int columnCount() const { return (int) columns.size(); }
        int columnOf (int track) const { for (size_t c = 0; c < columns.size(); ++c) if (columns[c].track == track) return (int) c; return -1; }
        int groupColumnOf (int group) const { for (size_t c = 0; c < columns.size(); ++c) if (columns[c].group == group) return (int) c; return -1; }
        int columnX (int column) const { return column * columnWidth - (int) offsetX; }
        int columnAt (int x) const
        {
            const int c = (int) std::floor ((x + offsetX) / columnWidth);
            return x >= 0 && x < tracksWidth() && c >= 0 && c < (int) columns.size() ? c : -1;
        }
        void resized() override
        {
            const auto grid = gridArea();
            mixers.setBounds (0, grid.getBottom() + stopHeight, tracksWidth(), mixerHeight());
            for (int i = 0; i < (int) rows.size(); ++i)
            {
                const int c = columnOf (i);
                rows[(size_t) i]->setVisible (c >= 0); rows[(size_t) i]->setBounds (columnX (juce::jmax (0, c)), 0, columnWidth, mixerHeight());
            }
            for (int g = 0; g < (int) groupStrips.size(); ++g)
            {
                const int c = groupColumnOf (g);
                groupStrips[(size_t) g]->setVisible (c >= 0); groupStrips[(size_t) g]->setBounds (columnX (juce::jmax (0, c)), 0, columnWidth, mixerHeight());
            }
            horizontal.setBounds (0, getHeight() - scrollSize, tracksWidth(), scrollSize);
            vertical.setBounds (getWidth() - scrollSize, gridTop, scrollSize, grid.getHeight());
            masterStrip.setBounds (masterX(), grid.getBottom() + stopHeight, sceneWidth, mixerHeight());
            mixers.setVisible (owner.state.mixerSections.shown); masterStrip.setVisible (owner.state.mixerSections.shown);
            const auto totalWidth = juce::jmax ((double) tracksWidth(), (double) columns.size() * columnWidth);
            offsetX = juce::jlimit (0.0, juce::jmax (0.0, totalWidth - tracksWidth()), offsetX);
            horizontal.setRangeLimits (0, totalWidth, juce::dontSendNotification); horizontal.setCurrentRange (offsetX, tracksWidth(), juce::dontSendNotification); horizontal.setSingleStepSize (columnWidth);
            const auto visibleRows = (double) grid.getHeight() / rowHeight;
            const auto totalRows = juce::jmax (visibleRows, (double) owner.state.scenes.size());
            offsetScene = juce::jlimit (0.0, juce::jmax (0.0, totalRows - visibleRows), offsetScene);
            vertical.setRangeLimits (0, totalRows, juce::dontSendNotification); vertical.setCurrentRange (offsetScene, visibleRows, juce::dontSendNotification); vertical.setSingleStepSize (1);
        }
        std::pair<int, int> cellAt (juce::Point<int> point) const
        {
            if (point.y < gridTop || point.y >= gridArea().getBottom() || point.x < 0 || point.x >= tracksWidth()) return { -1, -1 };
            const int column = columnAt (point.x);
            const int track = column >= 0 ? columns[(size_t) column].track : -1;
            const int scene = (int) ((point.y - gridTop) / (double) rowHeight + offsetScene);
            return track >= 0 && track < (int) owner.state.tracks.size() && ! owner.state.tracks[(size_t) track].isReturn && scene < (int) owner.state.scenes.size() ? std::pair<int, int> { track, scene } : std::pair<int, int> { -1, -1 };
        }
        void paint (juce::Graphics& g) override
        {
            // Cells sit on a dark ground with one-pixel gutters, like a console grid.
            g.fillAll (gutter);
            const auto grid = gridArea();
            const auto dark = themes::colour (0xff141414);
            g.saveState(); g.reduceClipRegion (0, 0, tracksWidth(), getHeight());
            for (int c = 0; c < (int) columns.size(); ++c)
            {
                const int x = columnX (c);
                if (x + columnWidth <= 0 || x >= tracksWidth()) continue;
                if (columns[(size_t) c].group >= 0) { paintGroupColumn (g, columns[(size_t) c].group, x); continue; }
                const int t = columns[(size_t) c].track;
                const auto& track = owner.state.tracks[(size_t) t];
                const bool selectedTrack = t == owner.selectedTrack;
                const auto header = juce::Rectangle<int> (x, 0, columnWidth, headerHeight).reduced (1, 0).withTrimmedBottom (1);
                g.setColour (selectedTrack ? track.colour.brighter (0.25f) : track.colour); g.fillRect (header);
                g.setColour (dark); g.setFont (font (11.0f, selectedTrack));
                g.drawText (track.name, header.reduced (6, 0), juce::Justification::centredLeft, true);
                if (track.isReturn)
                {
                    g.setColour (slotColour); g.fillRect (x + 1, gridTop, columnWidth - 2, grid.getHeight() + stopHeight);
                    continue;
                }
                g.saveState(); g.reduceClipRegion (grid.withWidth (tracksWidth()));
                for (int scene = 0; scene < (int) owner.state.scenes.size(); ++scene)
                {
                    const auto bounds = slotBounds (t, scene);
                    if (! bounds.intersects (grid)) continue;
                    const auto* slot = slotAt (t, scene);
                    const bool filled = slot != nullptr && slot->hasClip;
                    const bool selected = (selectedTrack && owner.state.scenes[(size_t) scene].id == owner.selectedSceneId) || owner.isSlotSelected (t, scene);
                    const bool queued = slot != nullptr && (slot->queued || slot->stopQueued);
                    const bool blink = owner.ticks % 16 < 8;
                    const auto cell = bounds.reduced (1, 0).withTrimmedBottom (1);
                    if (filled)
                    {
                        const auto clipColour = slot->clip.active ? slot->clip.colour : themes::colour (0xff6a6a6a);
                        g.setColour (queued && blink ? clipColour.brighter (0.35f) : clipColour); g.fillRect (cell);
                        g.setColour (slot->playing ? green.brighter (0.2f) : queued ? themes::colour (0xffffffff) : dark);
                        if (slot->stopQueued) g.fillRect (cell.getX() + 6, cell.getCentreY() - 4, 8, 8);
                        else if (slot->overdubbing) { g.setColour (red); g.fillEllipse ((float) cell.getX() + 6, (float) cell.getCentreY() - 4, 8, 8); }
                        else drawTriangle (g, cell.getX() + 6, cell.getCentreY() - 5);
                        if (slot->playing) { g.setColour (dark.withAlpha (0.35f)); g.fillRect (cell.withTrimmedLeft (cell.getWidth() - 3)); }
                        const bool follows = slot->clip.follow.action != Session::FollowAction::off;
                        g.setColour (dark); g.setFont (font (10.5f));
                        g.drawText ((slot->clip.active ? juce::String() : juce::String ("OFF / ")) + slot->clip.name,
                                    cell.withTrimmedLeft (20).withTrimmedRight (follows ? 34 : 4), juce::Justification::centredLeft, true);
                        if (follows)
                        {
                            g.setFont (font (9.0f));
                            g.drawText (juce::String (slot->clip.follow.afterBeats, 2).trimCharactersAtEnd ("0").trimCharactersAtEnd (".") + "b >",
                                        cell.withLeft (cell.getRight() - 33).reduced (2, 0), juce::Justification::centredRight, true);
                        }
                    }
                    else if (slot != nullptr && slot->recording)
                    {
                        // A recording slot blinks red until its take ends on the grid.
                        g.setColour (red.withAlpha (0.35f)); g.fillRect (cell);
                        g.setColour (red.withAlpha (blink ? 1.0f : 0.55f)); g.fillEllipse ((float) cell.getX() + 6, (float) cell.getCentreY() - 4, 8, 8);
                        g.setColour (ink); g.setFont (font (10.5f)); g.drawText ("Recording", cell.withTrimmedLeft (20), juce::Justification::centredLeft, true);
                    }
                    else
                    {
                        g.setColour (slotColour); g.fillRect (cell);
                        if (track.armed && ! queued)
                        {
                            // On an armed track an empty slot's button records into it.
                            g.setColour (themes::colour (0xff9a4a46)); g.drawEllipse ((float) cell.getX() + 6, (float) cell.getCentreY() - 4, 8, 8, 1.5f);
                        }
                        else if (slot == nullptr || slot->stopButton)
                        {
                            g.setColour (queued ? orange.withAlpha (blink ? 1.0f : 0.45f) : themes::colour (0xff4d4d4d));
                            g.fillRect (cell.getX() + 7, cell.getCentreY() - 3, 6, 6);
                        }
                    }
                    if (selected) { g.setColour (orange); g.drawRect (cell.expanded (1, 0).withTrimmedTop (-1), 2); }
                }
                g.restoreState();
                const auto stop = juce::Rectangle<int> (x, grid.getBottom(), columnWidth, stopHeight).reduced (1, 0).withTrimmedBottom (1);
                g.setColour (slotColour.darker (0.15f)); g.fillRect (stop);
                g.setColour (track.launcherActive ? orange : muted); g.fillRect (stop.getCentreX() - 4, stop.getCentreY() - 4, 8, 8);
            }
            g.restoreState();
            // Master column: scene launchers, with Stop All Clips under them.
            const int sceneX = masterX();
            const auto master = juce::Rectangle<int> (sceneX, 0, sceneWidth, headerHeight).reduced (1, 0).withTrimmedBottom (1);
            g.setColour (themes::colour (0xff4a4a4a)); g.fillRect (master);
            g.setColour (ink); g.setFont (font (11.0f, true)); g.drawText ("Main", master.reduced (6, 0), juce::Justification::centredLeft);
            g.saveState(); g.reduceClipRegion (sceneX, gridTop, sceneWidth, grid.getHeight());
            for (int scene = 0; scene < (int) owner.state.scenes.size(); ++scene)
            {
                const auto cell = juce::Rectangle<int> (sceneX, sceneY (scene), sceneWidth, rowHeight).reduced (1, 0).withTrimmedBottom (1);
                const bool selected = owner.state.scenes[(size_t) scene].id == owner.selectedSceneId;
                const auto& info = owner.state.scenes[(size_t) scene];
                // A scene with a colour of its own fills its cell with it, lighter while selected.
                const bool coloured = ! info.colour.isTransparent();
                g.setColour (coloured ? (selected ? info.colour.brighter (0.25f) : info.colour) : selected ? themes::colour (0xff4a4a4a) : themes::colour (0xff383838)); g.fillRect (cell);
                // A scene that changes the tempo or meter lights its launch button.
                const bool settings = info.tempo.has_value() || info.timeSignature.has_value();
                g.setColour (selected ? orange : settings ? green : ink.withAlpha (0.8f)); drawTriangle (g, cell.getX() + 6, cell.getCentreY() - 5);
                auto nameArea = cell.withTrimmedLeft (20).withTrimmedRight (6);
                // Its tempo and time signature fields, while they show: its own, or the song's dimmed.
                if (owner.state.sceneSettingsShown)
                {
                    const auto [tempoField, signatureField] = sceneFields (scene);
                    nameArea.setRight (tempoField.getX() - 2);
                    g.setFont (font (9.5f));
                    for (const auto& [field, text, own] : { std::tuple { tempoField, owner.sceneTempoText (info), info.tempo.has_value() },
                                                           std::tuple { signatureField, owner.sceneSignatureText (info), info.timeSignature.has_value() } })
                    {
                        g.setColour (themes::colour (0xff1e1e1e).withAlpha (0.85f)); g.fillRect (field);
                        g.setColour (own ? ink : muted.withAlpha (0.7f)); g.drawText (text, field, juce::Justification::centred, false);
                    }
                }
                g.setColour (coloured ? themes::colour (0xff141414) : ink); g.setFont (font (10.5f)); g.drawText (info.name, nameArea, juce::Justification::centredLeft, true);
            }
            g.restoreState();
            const auto stopAll = stopAllBounds();
            g.setColour (themes::colour (0xff383838)); g.fillRect (stopAll);
            g.setColour (ink.withAlpha (0.85f)); g.fillRect (stopAll.getX() + 7, stopAll.getCentreY() - 4, 8, 8);
            g.setFont (font (10.0f)); g.drawText ("Stop All Clips", stopAll.withTrimmedLeft (22), juce::Justification::centredLeft, true);
            if (owner.state.scenes.empty()) { g.setColour (muted); g.setFont (font (13.0f)); g.drawText ("Insert a scene to begin launching clips.", grid.reduced (20), juce::Justification::centred); }
            // A dragged clip's destination.
            if (dragging && dropCell.first >= 0)
            {
                g.saveState(); g.reduceClipRegion (grid);
                g.setColour (ink); g.drawRect (slotBounds (dropCell.first, dropCell.second).reduced (1), 2);
                g.restoreState();
            }
            // Where dragged headers would land: a line down the columns' edge.
            if (headerDragging && owner.trackDrop && dropLineX >= 0)
            { g.setColour (orange); g.fillRect (juce::jlimit (0, juce::jmax (0, tracksWidth() - 2), dropLineX - 1), 0, 2, grid.getBottom() + stopHeight); }
            // Where a dragged scene would land: a line across the scene column.
            if (sceneDragging && sceneDrop >= 0)
            { g.setColour (orange); g.fillRect (masterX(), juce::jlimit (gridTop, juce::jmax (gridTop, grid.getBottom() - 2), sceneY (sceneDrop) - 1), sceneWidth, 2); }
        }
        // A group column: header with disclosure triangle, slots that launch the members' row, and a stop button.
        void paintGroupColumn (juce::Graphics& g, int index, int x)
        {
            const auto& group = owner.state.groups[(size_t) index];
            const auto grid = gridArea();
            const auto dark = themes::colour (0xff141414);
            const auto header = juce::Rectangle<int> (x, 0, columnWidth, headerHeight).reduced (1, 0).withTrimmedBottom (1);
            g.setColour (group.colour); g.fillRect (header);
            juce::Path fold; const auto fx = (float) header.getX() + 7, fy = (float) header.getCentreY();
            if (group.folded) fold.addTriangle (fx, fy - 4, fx, fy + 4, fx + 6, fy);
            else fold.addTriangle (fx - 1, fy - 3, fx + 7, fy - 3, fx + 3, fy + 3);
            g.setColour (dark); g.fillPath (fold);
            g.setFont (font (11.0f, true)); g.drawText (group.name, header.withTrimmedLeft (18).reduced (4, 0), juce::Justification::centredLeft, true);
            const bool blink = owner.ticks % 16 < 8;
            bool active = false;
            g.saveState(); g.reduceClipRegion (grid.withWidth (tracksWidth()));
            for (int scene = 0; scene < (int) owner.state.scenes.size(); ++scene)
            {
                const auto cell = juce::Rectangle<int> (x, sceneY (scene), columnWidth, rowHeight).reduced (1, 0).withTrimmedBottom (1);
                if (! cell.intersects (grid)) continue;
                bool clips = false, playing = false, queued = false;
                for (int t = 0; t < (int) owner.state.tracks.size(); ++t)
                    if (owner.state.tracks[(size_t) t].groupId == group.id || owner.groupInside (owner.state.tracks[(size_t) t].groupId, group.id))
                        if (const auto* slot = slotAt (t, scene))
                        { clips = clips || slot->hasClip; playing = playing || slot->playing; queued = queued || slot->queued || slot->stopQueued; }
                if (clips)
                {
                    const auto fill = group.colour.withMultipliedSaturation (0.6f).darker (0.2f);
                    g.setColour (queued && blink ? fill.brighter (0.35f) : fill); g.fillRect (cell);
                    g.setColour (playing ? green.brighter (0.2f) : queued ? themes::colour (0xffffffff) : dark); drawTriangle (g, cell.getX() + 6, cell.getCentreY() - 5);
                }
                else
                {
                    g.setColour (slotColour.darker (0.1f)); g.fillRect (cell);
                    g.setColour (themes::colour (0xff4d4d4d)); g.fillRect (cell.getX() + 7, cell.getCentreY() - 3, 6, 6);
                }
                if (owner.state.scenes[(size_t) scene].id == owner.selectedSceneId) { g.setColour (orange.withAlpha (0.5f)); g.drawRect (cell, 1); }
            }
            g.restoreState();
            for (const auto& track : owner.state.tracks)
                active = active || ((track.groupId == group.id || owner.groupInside (track.groupId, group.id)) && track.launcherActive);
            const auto stop = juce::Rectangle<int> (x, grid.getBottom(), columnWidth, stopHeight).reduced (1, 0).withTrimmedBottom (1);
            g.setColour (slotColour.darker (0.15f)); g.fillRect (stop);
            g.setColour (active ? orange : muted); g.fillRect (stop.getCentreX() - 4, stop.getCentreY() - 4, 8, 8);
        }
        // Geometry used by pointer handlers and their tests.
        juce::Point<float> groupFoldPoint (int group) const { return { (float) columnX (groupColumnOf (group)) + 8.0f, headerHeight / 2.0f }; }
        juce::Point<float> groupLaunchPoint (int group, int scene) const { return { (float) columnX (groupColumnOf (group)) + 10.0f, (float) sceneY (scene) + rowHeight / 2.0f }; }
        juce::Point<float> groupStopPoint (int group) const { return { (float) columnX (groupColumnOf (group)) + columnWidth / 2.0f, (float) (gridArea().getBottom() + stopHeight / 2) }; }
        juce::Point<float> slotCentre (int track, int scene) const { return slotBounds (track, scene).getCentre().toFloat(); }
        // Map Mode's targets here: each track's clip slots and clip stop, each scene, and Stop All Clips.
        std::vector<std::pair<juce::Rectangle<int>, juce::String>> mapAreas() const
        {
            std::vector<std::pair<juce::Rectangle<int>, juce::String>> areas;
            const auto grid = gridArea();
            for (int t = 0; t < (int) owner.state.tracks.size(); ++t)
            {
                const auto& track = owner.state.tracks[(size_t) t];
                if (track.isReturn || columnOf (t) < 0) continue;
                for (int scene = 0; scene < (int) owner.state.scenes.size(); ++scene)
                    if (const auto b = slotBounds (t, scene); b.getBottom() > grid.getY() && b.getY() < grid.getBottom())
                        areas.push_back ({ b.reduced (1).getIntersection (grid), "slot:" + track.id + ":" + owner.state.scenes[(size_t) scene].id });
                areas.push_back ({ juce::Rectangle<int> (columnX (columnOf (t)), grid.getBottom(), columnWidth, stopHeight).reduced (1, 0), "track:" + track.id + ":stop" });
            }
            for (int scene = 0; scene < (int) owner.state.scenes.size(); ++scene)
                if (const auto y = sceneY (scene); y + rowHeight > grid.getY() && y < grid.getBottom())
                    areas.push_back ({ juce::Rectangle<int> (masterX(), y, sceneWidth, rowHeight).reduced (1).getIntersection (grid.withX (masterX()).withWidth (sceneWidth)), "scene:" + owner.state.scenes[(size_t) scene].id });
            areas.push_back ({ stopAllBounds(), "transport:stopClips" });
            return areas;
        }
        juce::Point<float> launchPoint (int track, int scene) const { const auto b = slotBounds (track, scene); return { (float) b.getX() + 10.0f, (float) b.getCentreY() }; }
        juce::Point<float> trackStopPoint (int track) const { return { (float) (columnX (columnOf (track)) + columnWidth / 2), (float) (gridArea().getBottom() + stopHeight / 2) }; }
        juce::Point<float> stopAllPoint() const { return stopAllBounds().getCentre().toFloat(); }
        void mouseDown (const juce::MouseEvent& event) override
        {
            if (owner.session.isExporting()) return;
            grabKeyboardFocus();
            headerPressed.clear(); collapseHeadersOnUp = false;
            if (const int column = columnAt (event.x); column >= 0 && columns[(size_t) column].group >= 0)
            {
                const auto& group = owner.state.groups[(size_t) columns[(size_t) column].group];
                const auto local = event.x - columnX (column);
                if (event.y < headerHeight)
                {
                    if (event.mods.isPopupMenu()) { owner.showHeaderMenu (group.id, false); repaint(); return; }
                    if (local < 20) owner.report (owner.session.setGroupFolded (group.id, ! group.folded));
                    else { headerPressed = group.id; owner.selectChain (group.id); } // Its title selects the group, and drags it.
                }
                else if (event.y < gridArea().getBottom())
                {
                    const int scene = (int) ((event.y - gridTop) / (double) rowHeight + offsetScene);
                    if (scene >= 0 && scene < (int) owner.state.scenes.size())
                    {
                        owner.selectedSceneId = owner.state.scenes[(size_t) scene].id;
                        if (local < 25) owner.report (owner.session.launchGroupSlot (group.id, scene));
                    }
                }
                else if (event.y < gridArea().getBottom() + stopHeight) owner.report (owner.session.stopGroup (group.id));
                owner.refresh(); repaint(); return;
            }
            const auto cell = cellAt (event.getPosition());
            if (cell.first >= 0)
            {
                const Session::SlotRef anchor { owner.selectedTrack, owner.selectedSceneIndex() };
                toggleOnUp = collapseOnUp = false; rubberFrom = { -1, -1 };
                const bool onButton = event.x - slotBounds (cell.first, cell.second).getX() < 25;
                if (! event.mods.isPopupMenu() && ! onButton) chooseSlots ({ cell.first, cell.second }, anchor, event.mods);
                else if (! owner.isSlotSelected (cell.first, cell.second)) owner.selectedSlots.clear();
                owner.selectLauncherSlot (cell.first, cell.second);
                if (event.mods.isPopupMenu()) { owner.showSlotMenu(); repaint(); return; }
                if (onButton)
                {
                    // Gate and Repeat clips follow the button, so the release is sent on mouse up.
                    pressedCell = cell; owner.report (owner.session.pressSlot (cell.first, cell.second)); owner.refresh();
                }
                else if (const auto* slot = slotAt (cell.first, cell.second); slot != nullptr && slot->hasClip) dragFrom = cell;
                else if (! event.mods.isAnyModifierKeyDown()) rubberFrom = cell; // A drag from an empty slot selects a rectangle.
                repaint(); return;
            }
            if (stopAllBounds().contains (event.getPosition())) { owner.report (owner.session.stopAllLauncherClips()); owner.refresh(); return; }
            const auto scene = sceneAt (event.getPosition());
            if (scene >= 0)
            {
                owner.selectedSceneId = owner.state.scenes[(size_t) scene].id;
                if (const auto [tempoField, signatureField] = sceneFields (scene); owner.state.sceneSettingsShown && ! event.mods.isPopupMenu()
                    && (tempoField.contains (event.getPosition()) || signatureField.contains (event.getPosition())))
                { repaint(); owner.sceneSettingsDialog (scene, tempoField.contains (event.getPosition())); return; }
                if (! event.mods.isPopupMenu() && event.x - masterX() >= 22) scenePressed = owner.state.scenes[(size_t) scene].id;
                if (event.mods.isPopupMenu())
                {
                    repaint();
                    const auto id = owner.state.scenes[(size_t) scene].id;
                    auto colour = std::make_shared<int> (-1);
                    owner.sceneContextMenu (id, colour).showMenuAsync (juce::PopupMenu::Options(), [safe = juce::Component::SafePointer<Impl> (&owner), id, colour] (int result)
                    { if (safe != nullptr && result != 0) safe->chooseSceneItem (result, id, *colour); });
                    return;
                }
                else if (event.x - masterX() < 22) { owner.report (owner.session.launchScene (scene)); owner.refresh(); }
                repaint(); return;
            }
            if (event.x >= masterX() && event.x < masterX() + sceneWidth && event.y >= gridTop && event.mods.isPopupMenu())
            { owner.selectedSlots.clear(); owner.showSessionSpaceMenu(); return; }
            const int column = columnAt (event.x);
            const auto track = column >= 0 ? columns[(size_t) column].track : -1;
            if (event.x < tracksWidth() && track >= 0 && track < (int) owner.state.tracks.size())
            {
                // A track's title selects it, as an Arrangement header does, and drags it; its menu is the header's.
                if (event.y < headerHeight && event.mods.isPopupMenu()) { owner.showHeaderMenu (owner.state.tracks[(size_t) track].id, false); repaint(); return; }
                // Below the slots, the track there and the last scene are selected, and the grid's own menu shows.
                if (event.y >= gridTop && event.y < gridArea().getBottom() && event.mods.isPopupMenu() && ! owner.state.scenes.empty())
                {
                    owner.selectedSlots.clear();
                    owner.selectLauncherSlot (track, (int) owner.state.scenes.size() - 1);
                    repaint(); owner.showSessionSpaceMenu(); return;
                }
                if (event.y < headerHeight)
                {
                    headerPressed = owner.state.tracks[(size_t) track].id;
                    collapseHeadersOnUp = owner.pressTrackHeader (track, event.mods.isShiftDown(), true);
                }
                else owner.selectTrack (track);
                if (! owner.state.tracks[(size_t) track].isReturn && event.y >= gridArea().getBottom() && event.y < gridArea().getBottom() + stopHeight) { owner.report (owner.session.stopLauncherTrack (track)); owner.refresh(); }
                repaint();
            }
        }
        // Where dragged headers would land over the column titles, as the reference's Session places
        // them: over a column's left half before its track or group, over its right half after it (see
        // Impl::dropBeside), the height in the title picking the nesting level: a group around the
        // track for every 6 pixels from its top, outermost first. Returns land among the returns, or
        // over the Main column's left half after the last of them. Past the Main column is after the
        // last track. The line showing where goes at the column edge, as lineX.
        std::optional<Impl::TrackDrop> columnDropAt (juce::Point<int> at, bool returns, int& lineX) const
        {
            lineX = -1;
            if (at.y < 0 || at.y >= headerHeight) return std::nullopt;
            const int column = columnAt (at.x);
            if (column < 0)
            {
                const bool onMain = at.x >= masterX() && at.x < masterX() + sceneWidth;
                if (at.x < masterX() || (onMain && (! returns || at.x >= masterX() + sceneWidth / 2))) return std::nullopt;
                // After the last of the tracks or returns dragged.
                int last = -1;
                for (int c = 0; c < (int) columns.size(); ++c)
                    if (columns[(size_t) c].group >= 0 ? ! returns : owner.state.tracks[(size_t) columns[(size_t) c].track].isReturn == returns) last = c;
                lineX = last >= 0 ? columnX (last) + columnWidth : 0;
                return Impl::TrackDrop {};
            }
            const auto& shown = columns[(size_t) column];
            const auto id = shown.group >= 0 ? owner.state.groups[(size_t) shown.group].id : owner.state.tracks[(size_t) shown.track].id;
            const int left = columnX (column);
            const bool after = at.x >= left + columnWidth / 2;
            juce::String level;
            if (const auto around = owner.groupsAround (id); ! returns && at.y / 6 < around.size()) level = around[at.y / 6];
            auto drop = owner.dropBeside (id, after, level, returns);
            if (drop) lineX = after ? left + columnWidth : left;
            return drop;
        }
        // Whether the press now under way is on a column's title.
        bool titlePressed() const { return headerPressed.isNotEmpty(); }
        bool onScene (juce::Point<int> point) const { return sceneAt (point) >= 0; }
        // A scene's tempo and time signature fields, at the right of its cell while they show.
        std::pair<juce::Rectangle<int>, juce::Rectangle<int>> sceneFields (int scene) const
        {
            auto cell = juce::Rectangle<int> (masterX(), sceneY (scene), sceneWidth, rowHeight).reduced (1, 0).withTrimmedBottom (1).withTrimmedRight (3);
            const auto signature = cell.removeFromRight (28).reduced (0, 4);
            cell.removeFromRight (2);
            return { cell.removeFromRight (40).reduced (0, 4), signature };
        }
        // Pointing at a title whose track or group has its own info text gives it to the Info view.
        void mouseMove (const juce::MouseEvent& event) override
        {
            juce::String title, text;
            if (const int column = columnAt (event.x); column >= 0 && event.y < headerHeight)
            {
                if (const auto g = columns[(size_t) column].group; g >= 0) { title = owner.state.groups[(size_t) g].name; text = owner.state.groups[(size_t) g].infoText; }
                else { const auto& track = owner.state.tracks[(size_t) columns[(size_t) column].track]; title = track.name; text = track.infoText; }
            }
            else if (const auto cell = cellAt (event.getPosition()); cell.first >= 0)
            { if (const auto* slot = slotAt (cell.first, cell.second); slot != nullptr && slot->hasClip) { title = slot->clip.name; text = slot->clip.infoText; } }
            else if (const auto scene = sceneAt (event.getPosition()); scene >= 0)
            { title = owner.state.scenes[(size_t) scene].name; text = owner.state.scenes[(size_t) scene].infoText; }
            getProperties().set (infoTitleProperty, title); getProperties().set (infoTextProperty, text);
        }
        void mouseExit (const juce::MouseEvent&) override { getProperties().set (infoTextProperty, juce::String()); }
        void mouseDrag (const juce::MouseEvent& event) override
        {
            // A scene dragged in the scene column moves to where its line shows, as the reference's scenes do.
            if (scenePressed.isNotEmpty())
            {
                if (! sceneDragging && event.getDistanceFromDragStart() <= 4) return;
                sceneDragging = true;
                sceneDrop = juce::jlimit (0, (int) owner.state.scenes.size(), (int) std::round ((event.y - gridTop) / (double) rowHeight + offsetScene));
                repaint(); return;
            }
            if (headerPressed.isNotEmpty())
            {
                if (! headerDragging && event.getDistanceFromDragStart() <= 6) return;
                headerDragging = true;
                int line = -1;
                owner.copyingTracks = copyModifier (event.mods);
                const auto returns = owner.draggedReturns (headerPressed);
                owner.aimTrackDrop (returns ? columnDropAt (event.getPosition(), *returns, line) : std::nullopt);
                dropLineX = owner.trackDrop ? line : -1;
                repaint(); return;
            }
            if (rubberFrom.first >= 0)
            {
                if (const auto cell = cellAt (event.getPosition()); cell.first >= 0)
                {
                    const auto cells = owner.slotRectangle ({ rubberFrom.first, rubberFrom.second }, { cell.first, cell.second });
                    owner.selectedSlots = cells.size() > 1 ? cells : std::vector<Session::SlotRef>();
                    repaint();
                }
                return;
            }
            if (dragFrom.first < 0 || (! dragging && event.getDistanceFromDragStart() < 4)) return;
            dragging = true;
            dropCell = cellAt (event.getPosition());
            setMouseCursor (copyDrag (event.mods) ? juce::MouseCursor::CopyingCursor : juce::MouseCursor::DraggingHandCursor);
            repaint();
        }
        void mouseUp (const juce::MouseEvent& event) override
        {
            if (const auto scene = std::exchange (scenePressed, {}); scene.isNotEmpty())
            {
                const auto drop = std::exchange (sceneDrop, -1);
                if (std::exchange (sceneDragging, false) && drop >= 0)
                {
                    const auto from = owner.launcherIndices ({}, scene).second;
                    if (from >= 0 && drop != from && drop != from + 1) { owner.report (owner.session.moveScene (scene, drop > from ? drop - 1 : drop)); owner.refresh(); }
                }
                repaint(); return;
            }
            if (headerPressed.isNotEmpty())
            {
                headerPressed.clear(); dropLineX = -1;
                const bool collapse = std::exchange (collapseHeadersOnUp, false);
                if (std::exchange (headerDragging, false)) owner.dropTracks();
                else if (collapse) { owner.multiSelectedTracks.clear(); owner.selectTrack (owner.selectedTrack); }
                repaint(); return;
            }
            releasePressed (pressedCell);
            rubberFrom = { -1, -1 };
            // A click without a drag on a slot of a group selects it alone, or with Cmd/Ctrl leaves it out.
            if (! event.mouseWasDraggedSinceMouseDown())
            {
                const Session::SlotRef here { owner.selectedTrack, owner.selectedSceneIndex() };
                if (toggleOnUp) std::erase (owner.selectedSlots, here);
                else if (collapseOnUp) owner.selectedSlots.clear();
                if (owner.selectedSlots.size() < 2) owner.selectedSlots.clear();
                repaint();
            }
            toggleOnUp = collapseOnUp = false;
            const auto from = std::exchange (dragFrom, { -1, -1 });
            if (! std::exchange (dragging, false)) return;
            setMouseCursor (juce::MouseCursor::NormalCursor);
            const auto to = std::exchange (dropCell, { -1, -1 });
            if (to.first >= 0 && to != from) dropClip (from, to, copyDrag (event.mods));
            repaint();
        }
        // Dropping a dragged clip on a slot moves it there, or copies it with Option (Mac) or Ctrl held.
        static bool copyDrag (juce::ModifierKeys mods)
        {
           #if JUCE_MAC
            return mods.isAltDown();
           #else
            return mods.isCtrlDown();
           #endif
        }
        void dropClip (std::pair<int, int> from, std::pair<int, int> to, bool copy)
        {
            // A clip of a group carries the whole group's clips by the same tracks and scenes.
            if (owner.selectedSlots.size() > 1 && owner.isSlotSelected (from.first, from.second))
            {
                const int tracks = to.first - from.first, scenes = to.second - from.second;
                const auto result = owner.session.moveSlotClips (owner.selectedSlotClips(), tracks, scenes, copy);
                owner.report (result); owner.refresh();
                if (result.wasOk())
                {
                    for (auto& ref : owner.selectedSlots) { ref.track += tracks; ref.scene += scenes; }
                    owner.selectLauncherSlot (to.first, to.second);
                }
                return;
            }
            const auto result = owner.session.moveSlotClip (from.first, from.second, to.first, to.second, copy);
            owner.report (result);
            owner.refresh();
            if (result.wasOk()) owner.selectLauncherSlot (to.first, to.second);
        }
        // A click on a slot: Cmd (Mac) or Ctrl adds it to the group, or on release leaves it out; Shift
        // takes in the rectangle from the selected slot; a plain click on a slot of the group keeps the
        // group for a drag; otherwise the slot is selected alone.
        void chooseSlots (Session::SlotRef cell, Session::SlotRef anchor, juce::ModifierKeys mods)
        {
            auto group = owner.selectedSlots;
            const bool anchored = anchor.track >= 0 && anchor.scene >= 0 && juce::isPositiveAndBelow (anchor.track, (int) owner.state.tracks.size()) && ! owner.state.tracks[(size_t) anchor.track].isReturn;
            if (group.empty() && anchored) group.push_back (anchor);
           #if JUCE_MAC
            const bool adds = mods.isCommandDown();
           #else
            const bool adds = mods.isCtrlDown();
           #endif
            if (adds) { if (std::find (group.begin(), group.end(), cell) != group.end()) toggleOnUp = true; else group.push_back (cell); }
            else if (mods.isShiftDown() && anchored) group = owner.slotRectangle (anchor, cell);
            else if (group.size() > 1 && std::find (group.begin(), group.end(), cell) != group.end()) collapseOnUp = true;
            else group.clear();
            owner.selectedSlots = group.size() > 1 ? group : std::vector<Session::SlotRef>();
        }
        std::pair<int, int> rubberFrom { -1, -1 };
        bool toggleOnUp = false, collapseOnUp = false;
        void mouseDoubleClick (const juce::MouseEvent& event) override
        {
            const auto cell = cellAt (event.getPosition());
            if (cell.first >= 0)
            {
                owner.selectLauncherSlot (cell.first, cell.second);
                const auto* slot = slotAt (cell.first, cell.second);
                if (owner.state.tracks[(size_t) cell.first].isMidi)
                {
                    if (slot != nullptr && ! slot->hasClip) owner.createLauncherMidiClip();
                    else if (slot != nullptr && slot->hasClip && slot->clip.isMidi) owner.openPianoRoll();
                }
                else if (slot != nullptr && ! slot->hasClip) owner.importSlotDialog (cell.first, cell.second);
                return;
            }
            const int scene = sceneAt (event.getPosition()); if (scene >= 0) { owner.renameSceneDialog (scene); return; }
            // Double-clicking below the last scene inserts another, as in the master column.
            if (event.x >= masterX() && event.x < masterX() + sceneWidth && event.y >= gridTop && event.y < gridArea().getBottom()) owner.addSceneFromUI();
        }
        bool keyPressed (const juce::KeyPress& key) override
        {
            if (owner.session.isExporting()) return true;
            const auto code = key.getKeyCode();
            const auto mods = key.getModifiers();
            // The reference's Session keys: Cmd+Return stops the selected slot's track; Return launches the
            // scene when its column was clicked; Page Up and Down move eight scenes; Home and End go to the
            // first and last track; Cmd with Left and Right moves the selected track, with Up and Down the
            // selected scene.
            if (code == juce::KeyPress::returnKey && mods.isCommandDown())
            {
                if (const auto* track = owner.currentTrack(); track != nullptr && ! track->isReturn) owner.report (owner.session.stopLauncherTrack (owner.selectedTrack));
                owner.refresh(); return true;
            }
            if (! owner.state.tracks.empty() && ! owner.state.scenes.empty() && ! mods.isAnyModifierKeyDown()
                && (code == juce::KeyPress::pageUpKey || code == juce::KeyPress::pageDownKey || code == juce::KeyPress::homeKey || code == juce::KeyPress::endKey))
            {
                int track = juce::jmax (0, owner.selectedTrack), scene = juce::jmax (0, owner.selectedSceneIndex());
                if (code == juce::KeyPress::pageUpKey || code == juce::KeyPress::pageDownKey) scene += code == juce::KeyPress::pageUpKey ? -8 : 8;
                else if (code == juce::KeyPress::homeKey) track = 0;
                else for (int t = 0; t < (int) owner.state.tracks.size(); ++t) if (! owner.state.tracks[(size_t) t].isReturn) track = t;
                owner.selectLauncherSlot (juce::jlimit (0, (int) owner.state.tracks.size() - 1, track), juce::jlimit (0, (int) owner.state.scenes.size() - 1, scene));
                scrollSelectionIntoView(); owner.refresh(); return true;
            }
            if (mods.isCommandDown() && ! mods.isShiftDown() && ! mods.isAltDown() && (code == juce::KeyPress::leftKey || code == juce::KeyPress::rightKey))
            {
                if (const auto* track = owner.currentTrack(); track != nullptr && ! track->isReturn)
                {
                    const auto to = owner.selectedTrack + (code == juce::KeyPress::leftKey ? -1 : 1);
                    if (juce::isPositiveAndBelow (to, (int) owner.state.tracks.size()) && ! owner.state.tracks[(size_t) to].isReturn)
                    {
                        const auto id = track->id;
                        owner.report (owner.session.moveTrack (id, to)); owner.refresh();
                        for (int t = 0; t < (int) owner.state.tracks.size(); ++t) if (owner.state.tracks[(size_t) t].id == id) owner.selectTrack (t);
                        owner.refresh();
                    }
                }
                return true;
            }
            if (mods.isCommandDown() && ! mods.isShiftDown() && ! mods.isAltDown() && (code == juce::KeyPress::upKey || code == juce::KeyPress::downKey))
            {
                const auto scene = owner.selectedSceneIndex(), to = scene + (code == juce::KeyPress::upKey ? -1 : 1);
                if (scene >= 0 && juce::isPositiveAndBelow (to, (int) owner.state.scenes.size()))
                { owner.report (owner.session.moveScene (owner.selectedSceneId, to)); owner.refresh(); scrollSelectionIntoView(); }
                return true;
            }
            if (code == juce::KeyPress::returnKey)
            {
                if (keyCell.first >= 0) return true; // Key repeat while Enter is held.
                const auto scene = owner.selectedSceneIndex();
                if (scene >= 0 && (key.getModifiers().isShiftDown() || owner.clickedArea == Area::scenes)) owner.report (owner.session.launchScene (scene));
                else if (scene >= 0 && owner.currentTrack() != nullptr && ! owner.currentTrack()->isReturn)
                {
                    keyCell = { owner.selectedTrack, scene }; owner.report (owner.session.pressSlot (owner.selectedTrack, scene));
                }
                owner.refresh(); return true;
            }
            if (const auto mods = key.getModifiers(); mods.isCommandDown() && ! mods.isShiftDown() && ! mods.isAltDown() && (code == 'C' || code == 'X' || code == 'V' || code == 'D'))
            {
                if (code == 'D' && owner.headerFocus) { owner.duplicateSelectedHeaders(); return true; } // After a click on a title.
                if (owner.headerFocus) { owner.trackClipboardCommand ((char) code); return true; }
                return owner.slotCommand (code == 'X' ? 84 : code == 'C' ? 85 : code == 'V' ? 86 : 87);
            }
            if (code == juce::KeyPress::leftKey || code == juce::KeyPress::rightKey || code == juce::KeyPress::upKey || code == juce::KeyPress::downKey)
            {
                int track = owner.selectedTrack, scene = owner.selectedSceneIndex();
                if (code == juce::KeyPress::leftKey) --track; if (code == juce::KeyPress::rightKey) ++track;
                if (code == juce::KeyPress::upKey) --scene; if (code == juce::KeyPress::downKey) ++scene;
                if (! owner.state.tracks.empty() && ! owner.state.scenes.empty()) owner.selectLauncherSlot (juce::jlimit (0, (int) owner.state.tracks.size() - 1, track), juce::jlimit (0, (int) owner.state.scenes.size() - 1, scene));
                scrollSelectionIntoView(); return true;
            }
            return owner.handleKey (key);
        }
        bool keyStateChanged (bool) override
        {
            if (keyCell.first >= 0 && ! juce::KeyPress::isKeyCurrentlyDown (juce::KeyPress::returnKey)) releasePressed (keyCell);
            return false;
        }
        void focusLost (FocusChangeType) override { releasePressed (keyCell); }
        void mouseWheelMove (const juce::MouseEvent& event, const juce::MouseWheelDetails& wheel) override
        {
            if (event.mods.isShiftDown() || std::abs (wheel.deltaX) > std::abs (wheel.deltaY)) offsetX = juce::jmax (0.0, offsetX - (wheel.deltaX + wheel.deltaY) * 300.0);
            else offsetScene = juce::jmax (0.0, offsetScene - wheel.deltaY * 5.0);
            resized(); repaint();
        }
        void scrollSelectionIntoView()
        {
            const auto scene = owner.selectedSceneIndex();
            if (scene >= 0) { if (scene < offsetScene) offsetScene = scene; if (scene + 1 > offsetScene + gridArea().getHeight() / (double) rowHeight) offsetScene = scene + 1 - gridArea().getHeight() / (double) rowHeight; }
            if (const int column = columnOf (owner.selectedTrack); column >= 0)
            { const auto x = column * columnWidth; if (x < offsetX) offsetX = x; if (x + columnWidth > offsetX + tracksWidth()) offsetX = x + columnWidth - tracksWidth(); }
            resized(); repaint();
        }
    private:
        Impl& owner;
        // Launch buttons held by the mouse and by Enter, released into Gate and Repeat clips.
        std::pair<int, int> pressedCell { -1, -1 }, keyCell { -1, -1 };
        // A clip dragged from its slot, and the slot it would drop on.
        std::pair<int, int> dragFrom { -1, -1 }, dropCell { -1, -1 };
        bool dragging = false;
        // A column's title pressed, which a drag moves with the tracks selected with it, and the line
        // showing where they would land.
        juce::String headerPressed;
        bool headerDragging = false, collapseHeadersOnUp = false;
        int dropLineX = -1;
        // A scene pressed in the scene column, which a drag moves, and the line it would land on.
        juce::String scenePressed;
        bool sceneDragging = false;
        int sceneDrop = -1;
        void releasePressed (std::pair<int, int>& cell)
        {
            if (cell.first < 0) return;
            const auto held = std::exchange (cell, { -1, -1 });
            if (owner.session.isExporting()) return;
            owner.report (owner.session.releaseSlot (held.first, held.second)); owner.refresh();
        }
    public:
        static constexpr int headerHeight = 22, gridTop = headerHeight, columnWidth = 120, rowHeight = 24,
                             sceneWidth = 132, baseMixerHeight = 252 + TrackRow::inOutHeight - 48, stopHeight = 22, scrollSize = 10;
        // The mixer grows by a row of send knobs for every three returns.
        // The strips' height, from the mixer's sections shown: all of them make the base height.
        int mixerHeight() const
        {
            const auto& shown = owner.state.mixerSections;
            if (! shown.shown) return 0; // View > Mixer hides it, the grid taking its place.
            int returns = 0; for (const auto& track : owner.state.tracks) returns += track.isReturn;
            return (shown.inOut ? TrackRow::inOutHeight : 4) + (shown.sends ? (returns + 2) / 3 * 40 : 0)
                 + (shown.mixer ? 158 : 4) + (shown.trackDelay ? 22 : 0) + (shown.crossfader ? 24 : 0);
        }
        // The Master column follows the last track column, or the right edge once tracks scroll.
        int masterX() const { return juce::jlimit (0, tracksWidth(), (int) columns.size() * columnWidth - (int) offsetX); }
    private:
        static inline const juce::Colour gutter { 0xff1a1a1a }, slotColour { 0xff2c2c2c };
        juce::Component mixers;
        std::vector<std::unique_ptr<TrackRow>> rows;
        std::vector<std::unique_ptr<GroupHeader>> groupStrips;
        std::vector<Column> columns;
        // The Master channel at the foot of the Master column: volume fader and output meter.
        class MasterStrip final : public juce::Component
        {
        public:
            explicit MasterStrip (Impl& o) : owner (o)
            {
                setName ("Session master strip");
                gain.setName ("Session master volume"); gain.setSliderStyle (juce::Slider::LinearVertical);
                gain.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 54, 16); gain.setNormalisableRange (Session::levelRange (false));
                gain.setDoubleClickReturnValue (true, 0);
                gain.textFromValueFunction = [] (double v) { return v <= -100 ? juce::String ("-inf dB") : juce::String (v, 1) + " dB"; };
                gain.onDragStart = [this] { owner.session.beginEditGesture ("Main volume"); };
                gain.onDragEnd = [this] { owner.session.endEditGesture(); };
                gain.onValueChange = [this] { owner.report (owner.session.setMasterGain ((float) gain.getValue())); };
                gain.updateText(); addAndMakeVisible (gain);
                crossfader.setName ("Crossfader"); crossfader.setSliderStyle (juce::Slider::LinearHorizontal);
                crossfader.setTextBoxStyle (juce::Slider::NoTextBox, false, 0, 0); crossfader.setRange (-1, 1, .001); crossfader.setDoubleClickReturnValue (true, 0);
                crossfader.setTooltip ("Crossfader: left plays side A, right plays side B. Double-click to centre.");
                crossfader.onDragStart = [this] { owner.session.beginEditGesture ("Crossfader"); };
                crossfader.onDragEnd = [this] { owner.session.endEditGesture(); };
                crossfader.onValueChange = [this] { owner.report (owner.session.setCrossfader ((float) crossfader.getValue())); };
                addAndMakeVisible (crossfader);
                // Main Out, as the reference's Main track chooses the output it plays to.
                output.setName ("Main Out"); output.setTooltip ("Main Out: the audio output the Main track plays to.");
                output.onChange = [this]
                {
                    const auto names = owner.session.outputNames();
                    if (juce::isPositiveAndBelow (output.getSelectedId() - 1, names.size())) owner.report (owner.session.setMasterOutput (names[output.getSelectedId() - 1]));
                    owner.refresh();
                };
                addAndMakeVisible (output);
                // The cue, as the reference's master track has it: Cue Out, the Solo/Cue switch and
                // the cue volume, at which the click, previews and cued tracks play on Cue Out.
                cueOutput.setName ("Cue Out"); cueOutput.setTooltip ("Cue Out: the audio output the click, previews and cued tracks play to.");
                cueOutput.onChange = [this]
                {
                    const auto names = owner.session.outputNames();
                    if (juce::isPositiveAndBelow (cueOutput.getSelectedId() - 1, names.size())) owner.report (owner.session.setCueOutput (names[cueOutput.getSelectedId() - 1]));
                    owner.refresh();
                };
                addAndMakeVisible (cueOutput);
                soloCue.setName ("Solo/Cue"); soloCue.setClickingTogglesState (false);
                soloCue.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xff57a7ff)); soloCue.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
                soloCue.onClick = [this] { owner.report (owner.session.setCueMode (! owner.state.cueMode)); owner.refresh(); };
                addAndMakeVisible (soloCue);
                cueVolume.setName ("Cue volume"); cueVolume.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag);
                cueVolume.setTextBoxStyle (juce::Slider::NoTextBox, false, 0, 0); cueVolume.setNormalisableRange (Session::levelRange (false, -70));
                cueVolume.setDoubleClickReturnValue (true, -6);
                cueVolume.textFromValueFunction = [] (double v) { return v <= -70 ? juce::String ("-inf dB") : juce::String (v, 1) + " dB"; };
                cueVolume.onDragStart = [this] { owner.session.beginEditGesture ("Cue volume"); };
                cueVolume.onDragEnd = [this] { owner.session.endEditGesture(); };
                cueVolume.onValueChange = [this] { owner.report (owner.session.setCueVolume ((float) cueVolume.getValue())); };
                cueVolume.setPopupDisplayEnabled (true, true, nullptr);
                addAndMakeVisible (cueVolume);
            }
            void sync()
            {
                const auto& shown = owner.state.mixerSections;
                cueOutput.setVisible (shown.inOut); output.setVisible (shown.inOut);
                for (auto* c : std::initializer_list<juce::Component*> { &soloCue, &cueVolume, &gain }) c->setVisible (shown.mixer);
                crossfader.setVisible (shown.crossfader);
                if (shown != laidOut) { laidOut = shown; resized(); }
                const auto names = owner.session.outputNames();
                if (names != cueOutputNames) { cueOutputNames = names; cueOutput.clear (juce::dontSendNotification); for (int i = 0; i < names.size(); ++i) cueOutput.addItem (names[i], i + 1); }
                const auto cue = owner.state.cueOutput.isNotEmpty() ? owner.state.cueOutput : owner.session.masterOutput();
                cueOutput.setSelectedId (names.indexOf (cue) + 1, juce::dontSendNotification);
                cueOutput.setEnabled (names.size() > 1 && ! owner.session.isExporting());
                soloCue.setButtonText (owner.state.cueMode ? "Cue" : "Solo");
                soloCue.setToggleState (owner.state.cueMode, juce::dontSendNotification);
                soloCue.setEnabled (owner.state.cueAvailable && ! owner.session.isExporting());
                soloCue.setTooltip (owner.state.cueAvailable ? "Solo/Cue: the tracks' switches solo them, or cue them on Cue Out"
                                                             : "Solo/Cue: choose a Cue Out apart from the Main Out to cue tracks");
                if (! cueVolume.isMouseButtonDown()) cueVolume.setValue (owner.state.cueVolumeDb, juce::dontSendNotification);
                cueVolume.setTooltip ("Cue volume: " + cueVolume.getTextFromValue (cueVolume.getValue()) + ". The click, previews and cued tracks play at it. Double-click for -6 dB.");
                cueVolume.setEnabled (! owner.session.isExporting());
                if (! crossfader.isMouseButtonDown()) crossfader.setValue (owner.state.crossfader, juce::dontSendNotification);
                crossfader.setEnabled (! owner.session.isExporting());
                if (! gain.isMouseButtonDown()) gain.setValue (owner.state.masterGainDb, juce::dontSendNotification);
                gain.setEnabled (! owner.session.isExporting());
                showAutomationState (gain, owner.state.masterVolumeAutomation, "Main output level. Double-click for 0 dB.", "Main volume");
                gain.getProperties().set ("midiMapTarget", "master");
                if (names != outputNames) { outputNames = names; output.clear (juce::dontSendNotification); for (int i = 0; i < names.size(); ++i) output.addItem (names[i], i + 1); }
                output.setSelectedId (names.indexOf (owner.session.masterOutput()) + 1, juce::dontSendNotification);
                output.setEnabled (names.size() > 1 && ! owner.session.isExporting());
                peakL = owner.state.masterPeakL; peakR = owner.state.masterPeakR; repaint();
            }
            void resized() override
            {
                // In line with the tracks' monitor and Audio To rows, and their pan knobs, as the
                // mixer's sections are shown.
                const auto& shown = owner.state.mixerSections;
                const int top = shown.inOut ? TrackRow::inOutHeight : 4;
                cueOutput.setBounds (5, 46, getWidth() - 10, 19);
                output.setBounds (5, 67, getWidth() - 10, 19);
                soloCue.setBounds (5, top + 9, 44, 18); cueVolume.setBounds (getWidth() - 39, top + 3, 32, 32);
                const int bottom = getHeight() - (shown.crossfader ? 56 : 34);
                gain.setBounds (6, top + 58, 54, juce::jmax (20, bottom - (top + 58))); crossfader.setBounds (16, getHeight() - 34, getWidth() - 32, 22);
            }
            void mouseDown (const juce::MouseEvent& e) override { if (! e.mods.isPopupMenu()) owner.selectChain (Session::mainChain); }
            void paint (juce::Graphics& g) override
            {
                g.fillAll (themes::colour (0xff383838));
                g.setColour (muted); g.setFont (font (9.0f, true)); g.drawText ("MAIN", 6, 4, getWidth() - 12, 16, juce::Justification::centred);
                if (cueVolume.isVisible()) g.drawText ("CUE", cueVolume.getX(), cueVolume.getBottom(), 32, 10, juce::Justification::centred);
                if (crossfader.isVisible()) { g.drawText ("A", 4, getHeight() - 34, 12, 22, juce::Justification::centred); g.drawText ("B", getWidth() - 16, getHeight() - 34, 12, 22, juce::Justification::centred); }
                const juce::Rectangle<int> meter { 66, gain.getY() + 4, 10, juce::jmax (10, gain.getBottom() - 20 - gain.getY()) };
                for (int channel = 0; channel < 2 && gain.isVisible(); ++channel)
                {
                    const auto bar = meter.withWidth (4).translated (channel * 6, 0);
                    const auto level = channel == 0 ? peakL : peakR;
                    const auto fraction = juce::jlimit (0.0f, 1.0f, (juce::Decibels::gainToDecibels (level, -60.0f) + 60.0f) / 60.0f);
                    g.setColour (themes::colour (0xff181818)); g.fillRect (bar);
                    g.setColour (level >= 1.0f ? red : green); g.fillRect (bar.withTop (bar.getBottom() - juce::roundToInt (bar.getHeight() * fraction)));
                }
                g.setColour (line); g.drawRect (getLocalBounds());
            }
        private:
            Impl& owner;
            juce::Slider gain, crossfader;
            juce::ComboBox output, cueOutput; juce::StringArray outputNames, cueOutputNames;
            juce::TextButton soloCue { "Solo" };
            juce::Slider cueVolume;
            Session::MixerSections laidOut;
            float peakL = 0, peakR = 0;
            ChildMouseEvents childMouse { *this }; // A click anywhere on the strip shows the Main's chain.
        } masterStrip { owner };
        juce::ScrollBar horizontal { false }, vertical { true };
        double offsetX = 0, offsetScene = 0;
        int tracksWidth() const { return juce::jmax (1, getWidth() - sceneWidth - scrollSize); }
        juce::Rectangle<int> gridArea() const { return { 0, gridTop, tracksWidth(), juce::jmax (rowHeight, getHeight() - gridTop - mixerHeight() - stopHeight - scrollSize) }; }
        int sceneY (int scene) const { return gridTop + (int) std::round ((scene - offsetScene) * rowHeight); }
        juce::Rectangle<int> stopAllBounds() const { return juce::Rectangle<int> (masterX(), gridArea().getBottom(), sceneWidth, stopHeight).reduced (1, 0).withTrimmedBottom (1); }
        juce::Rectangle<int> slotBounds (int track, int scene) const
        { const int column = columnOf (track); return column < 0 ? juce::Rectangle<int>() : juce::Rectangle<int> { columnX (column), sceneY (scene), columnWidth, rowHeight }; }
        const Session::SlotInfo* slotAt (int track, int scene) const
        {
            if (track < 0 || track >= (int) owner.state.tracks.size()) return nullptr;
            const auto& slots = owner.state.tracks[(size_t) track].slots;
            return scene >= 0 && scene < (int) slots.size() ? &slots[(size_t) scene] : nullptr;
        }
        int sceneAt (juce::Point<int> point) const
        {
            if (point.x < masterX() || point.x >= masterX() + sceneWidth || point.y < gridTop || point.y >= gridArea().getBottom()) return -1;
            const int scene = (int) ((point.y - gridTop) / (double) rowHeight + offsetScene);
            return scene < (int) owner.state.scenes.size() ? scene : -1;
        }
        static void drawTriangle (juce::Graphics& g, int x, int y) { juce::Path path; path.addTriangle ((float) x, (float) y, (float) x, (float) y + 10, (float) x + 9, (float) y + 5); g.fillPath (path); }
        void scrollBarMoved (juce::ScrollBar* bar, double start) override { if (bar == &horizontal) offsetX = start; else offsetScene = start; resized(); repaint(); }
    };

    // Audio clip detail: Clip and Sample boxes (warp, tempo, gain, reverse) beside the waveform.
    // The clip view's Launch box for a Session clip: launch mode, legato and launch grid.
    class LaunchBox final : public juce::Component
    {
    public:
        static constexpr int width = 150;
        explicit LaunchBox (Impl& o) : owner (o)
        {
            setName ("Launch box");
            for (auto* c : std::initializer_list<juce::Component*> { &mode, &legato, &grid, &velocity, &follow }) addAndMakeVisible (c);
            follow.setName ("Follow action"); follow.setTooltip ("Follow Action: what plays after this clip, and when");
            follow.setWantsKeyboardFocus (false); follow.onClick = [this] { owner.clipFollowDialog (clip.id); };
            mode.setName ("Launch mode");
            for (auto* text : { "Trigger", "Gate", "Toggle", "Repeat" }) mode.addItem (text, mode.getNumItems() + 1);
            mode.setTooltip ("Launch mode: Trigger starts on press, Gate plays while held, Toggle starts and stops on press, Repeat retriggers on the grid while held");
            grid.setName ("Launch quantization");
            for (const auto& [text, value] : Session::clipQuantisations()) grid.addItem (text, (int) value + 1); // In the reference's order.
            grid.setTooltip ("Launch quantization for this clip; Global follows the control bar");
            legato.setName ("Launch legato"); legato.setClickingTogglesState (true);
            legato.setWantsKeyboardFocus (false); legato.setMouseClickGrabsKeyboardFocus (false);
            legato.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); legato.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            legato.setTooltip ("Legato: start in phase with the clip already playing on this track");
            // Velocity, as the reference's Launch box shows its amount: 0 to 100 %.
            velocity.setName ("Launch velocity"); velocity.setSliderStyle (juce::Slider::LinearBar);
            velocity.setRange (0, 100, 0.1); velocity.setTextValueSuffix (" %"); velocity.setNumDecimalPlacesToDisplay (1);
            velocity.setColour (juce::Slider::trackColourId, themes::colour (0xffffab3d).withAlpha (0.55f)); velocity.setColour (juce::Slider::textBoxTextColourId, ink);
            velocity.setTooltip ("Velocity: how much a launching MIDI note's velocity sets the clip's volume");
            velocity.onDragEnd = [this] { apply(); };
            velocity.onValueChange = [this] { if (! velocity.isMouseButtonDown()) apply(); };
            mode.onChange = [this] { apply(); }; grid.onChange = [this] { apply(); }; legato.onClick = [this] { apply(); };
        }
        void setClip (const Session::ClipInfo& shown)
        {
            clip = shown;
            mode.setSelectedId ((int) clip.launch.mode + 1, juce::dontSendNotification);
            grid.setSelectedId ((int) clip.launch.quantisation + 1, juce::dontSendNotification);
            legato.setToggleState (clip.launch.legato, juce::dontSendNotification);
            if (! velocity.isMouseButtonDown()) velocity.setValue (clip.launch.velocityAmount * 100.0, juce::dontSendNotification);
            for (auto* c : std::initializer_list<juce::Component*> { &mode, &legato, &grid, &velocity, &follow }) c->setEnabled (! owner.session.isExporting() && ! owner.state.recording);
        }
        void resized() override
        {
            auto area = getLocalBounds().reduced (6, 0).withTrimmedTop (28);
            area.removeFromTop (14); mode.setBounds (area.removeFromTop (22));
            area.removeFromTop (8); legato.setBounds (area.removeFromTop (22));
            area.removeFromTop (20); grid.setBounds (area.removeFromTop (22));
            area.removeFromTop (20); velocity.setBounds (area.removeFromTop (20));
            area.removeFromTop (8); follow.setBounds (area.removeFromTop (22));
        }
        void paint (juce::Graphics& g) override
        {
            g.setColour (themes::colour (0xff303030)); g.fillRect (getLocalBounds());
            g.setColour (themes::colour (0xff4a4a4a)); g.fillRect (getLocalBounds().withHeight (22));
            g.setColour (line); g.drawRect (getLocalBounds());
            g.setColour (ink); g.setFont (font (11.0f, true));
            g.drawText ("Launch", getLocalBounds().withHeight (22).reduced (6, 0), juce::Justification::centredLeft);
            g.setColour (muted); g.setFont (font (10.0f));
            g.drawText ("Mode", 6, mode.getY() - 14, getWidth() - 12, 13, juce::Justification::bottomLeft);
            g.drawText ("Quantization", 6, grid.getY() - 14, getWidth() - 12, 13, juce::Justification::bottomLeft);
            g.drawText ("Velocity", 6, velocity.getY() - 14, getWidth() - 12, 13, juce::Justification::bottomLeft);
        }
    private:
        Impl& owner;
        Session::ClipInfo clip;
        juce::ComboBox mode, grid;
        juce::TextButton legato { "Legato" }, follow { "Follow Action..." };
        juce::Slider velocity;
        void apply()
        {
            const Session::LaunchSettings settings { static_cast<Session::LaunchMode> (mode.getSelectedId() - 1),
                                                     static_cast<Session::ClipQuantisation> (grid.getSelectedId() - 1), legato.getToggleState(),
                                                     (float) (velocity.getValue() / 100.0) };
            if (settings == clip.launch) return;
            owner.report (owner.session.setClipLaunchSettings (clip.id, settings)); owner.refresh();
        }
    };

    // A MIDI or warped audio clip's Start, End and Loop, after the reference's clip view: the content
    // beat it starts on, where an unlooped clip ends, and the loop's Position and Length, in
    // bars.beats.sixteenths. Turning Loop on loops what the clip plays.
    class LoopBox final : public juce::Component
    {
    public:
        static constexpr int width = 150;
        explicit LoopBox (Impl& o) : owner (o)
        {
            setName ("Loop box");
            for (auto [field, name] : { std::pair<juce::Label*, const char*> { &start, "Clip start" }, { &end, "Clip end" }, { &position, "Loop position" }, { &length, "Loop length" } })
            {
                addAndMakeVisible (field); field->setName (name); field->setEditable (true);
                field->setJustificationType (juce::Justification::centred);
                field->setColour (juce::Label::backgroundColourId, themes::colour (0xff1c1c1c));
                field->setColour (juce::Label::outlineColourId, line);
                field->setColour (juce::Label::textColourId, ink);
            }
            addAndMakeVisible (loop); loop.setName ("Clip loop"); loop.setClickingTogglesState (true);
            loop.setWantsKeyboardFocus (false); loop.setMouseClickGrabsKeyboardFocus (false);
            loop.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); loop.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            loop.setTooltip ("Loop: repeat the loop's Position and Length for as long as the clip lasts");
            start.setTooltip ("Start: the beat of the clip's content it starts playing on");
            end.setTooltip ("End: where an unlooped clip stops playing its content");
            start.onTextChange = [this] { edit (start); };
            end.onTextChange = [this] { edit (end); };
            position.onTextChange = [this] { edit (position); };
            length.onTextChange = [this] { edit (length); };
            loop.onClick = [this] { toggle(); };
            // The Set buttons, as the reference's: while the clip plays, each puts its marker at the play
            // position, rounded to the global launch quantization.
            const char* names[] { "Set start", "Set end", "Set loop position", "Set loop length" };
            for (int i = 0; i < 4; ++i)
            {
                auto& button = set[(size_t) i];
                addAndMakeVisible (button); button.setName (names[i]); button.setWantsKeyboardFocus (false); button.setMouseClickGrabsKeyboardFocus (false);
                button.setTooltip (juce::String (names[i]).replace ("Set ", "Set the ") + " at the play position while the clip plays");
                button.onClick = [this, i]
                {
                    if (const auto beat = owner.clipPlayBeat (clip)) owner.setClipMarker (clip, static_cast<ClipMarker> (i), owner.globallyQuantised (*beat));
                };
            }
        }
        void setClip (const Session::ClipInfo& shown)
        {
            clip = shown;
            const auto& meter = owner.state.timeSignature;
            start.setText (barsBeats (clip.contentStartBeat, meter, true), juce::dontSendNotification);
            end.setText (barsBeats (clip.contentStartBeat + clip.lengthBeats, meter, true), juce::dontSendNotification);
            position.setText (barsBeats (clip.loop.start, meter, true), juce::dontSendNotification);
            length.setText (barsBeats (clip.loop.length, meter, false), juce::dontSendNotification);
            loop.setToggleState (clip.loop.on, juce::dontSendNotification);
            const bool enabled = ! owner.session.isExporting();
            start.setEnabled (enabled); loop.setEnabled (enabled);
            end.setEnabled (enabled && ! clip.loop.on);
            position.setEnabled (enabled && clip.loop.on); length.setEnabled (enabled && clip.loop.on);
            const bool playing = enabled && owner.clipPlayBeat (clip).has_value();
            for (int i = 0; i < 4; ++i) set[(size_t) i].setEnabled (playing && (i != (int) ClipMarker::end || ! clip.loop.on));
            repaint();
        }
        void resized() override
        {
            auto area = getLocalBounds().reduced (6, 0).withTrimmedTop (28);
            const auto row = [&] (juce::Component& c, juce::Component& button)
            { auto r = area.removeFromTop (22); r.removeFromLeft (54); button.setBounds (r.removeFromRight (26)); r.removeFromRight (3); c.setBounds (r); area.removeFromTop (6); };
            row (start, set[0]); row (end, set[1]);
            loop.setBounds (area.removeFromTop (22)); area.removeFromTop (6);
            row (position, set[2]); row (length, set[3]);
        }
        void paint (juce::Graphics& g) override
        {
            g.setColour (themes::colour (0xff303030)); g.fillRect (getLocalBounds());
            g.setColour (themes::colour (0xff4a4a4a)); g.fillRect (getLocalBounds().withHeight (22));
            g.setColour (line); g.drawRect (getLocalBounds());
            g.setColour (ink); g.setFont (font (11.0f, true));
            g.drawText ("Loop", getLocalBounds().withHeight (22).reduced (6, 0), juce::Justification::centredLeft);
            g.setFont (font (10.0f));
            for (auto [field, name] : { std::pair<juce::Label*, const char*> { &start, "Start" }, { &end, "End" }, { &position, "Position" }, { &length, "Length" } })
            {
                g.setColour (field->isEnabled() ? muted : muted.withAlpha (0.45f));
                g.drawText (name, 6, field->getY(), 52, field->getHeight(), juce::Justification::centredLeft);
            }
        }
    private:
        Impl& owner;
        Session::ClipInfo clip;
        juce::Label start, end, position, length;
        juce::TextButton loop { "Loop" };
        std::array<juce::TextButton, 4> set { juce::TextButton ("Set"), juce::TextButton ("Set"), juce::TextButton ("Set"), juce::TextButton ("Set") };
        void edit (juce::Label& field)
        {
            const auto& meter = owner.state.timeSignature;
            const auto value = readBarsBeats (field.getText(), meter, &field != &length);
            if (! value) { owner.report (juce::Result::fail ("Enter beats as bar.beat.sixteenth.")); setClip (clip); return; }
            auto next = clip.loop;
            auto from = clip.contentStartBeat;
            if (&field == &start) from = *value;
            else if (&field == &end)
            {
                owner.report (owner.session.setClipBeats (clip.id, clip.startBeat, *value - clip.contentStartBeat, clip.contentStartBeat)); owner.refresh(); return;
            }
            else
            {
                if (&field == &position) next.start = *value; else next.length = *value;
                // The start stays in the loop.
                if (from < next.start || from >= next.start + next.length) from = next.start;
            }
            owner.report (owner.session.setClipLoop (clip.id, next, from)); owner.refresh();
        }
        void toggle()
        {
            auto next = clip.loop;
            next.on = loop.getToggleState();
            if (next.on)
            {
                // What the clip plays becomes its loop.
                next.start = clip.contentStartBeat;
                next.length = std::max (1.0 / 64, std::min (clip.lengthBeats, sourceBeats (clip) - clip.contentStartBeat));
            }
            owner.report (owner.session.setClipLoop (clip.id, next, clip.contentStartBeat)); owner.refresh();
        }
    };

    // A MIDI clip's Groove section, after the reference's clip view: the pool groove the clip
    // plays with, Commit, and the Groove Pool window.
    class GrooveBox final : public juce::Component
    {
    public:
        static constexpr int width = 150;
        explicit GrooveBox (Impl& o) : owner (o)
        {
            setName ("Groove box");
            for (auto* c : std::initializer_list<juce::Component*> { &groove, &commit, &pool }) addAndMakeVisible (c);
            groove.setName ("Clip groove"); groove.addItem ("None", 1);
            groove.setTooltip ("The groove this clip plays with. It moves and accents the notes on playback without changing them.");
            commit.setName ("Commit groove"); commit.setTooltip ("Commit: write the groove into the clip's notes and set its groove to None");
            pool.setName ("Open Groove Pool"); pool.setTooltip ("Groove Pool: the project's grooves and their Base, Quantize, Timing, Random and Velocity");
            for (auto* b : { &commit, &pool }) { b->setWantsKeyboardFocus (false); b->setMouseClickGrabsKeyboardFocus (false); }
            groove.onChange = [this]
            {
                const auto index = groove.getSelectedId() - 2;
                owner.report (owner.session.setClipGroove (clip.id, juce::isPositiveAndBelow (index, ids.size()) ? ids[index] : juce::String())); owner.refresh();
            };
            commit.onClick = [this] { owner.report (owner.session.commitClipGroove (clip.id), "Committed the groove into the clip's notes."); owner.refresh(); };
            pool.onClick = [this] { owner.openGroovePool(); };
        }
        void setClip (const Session::ClipInfo& shown)
        {
            clip = shown;
            juce::StringArray grooveIds, names;
            for (const auto& g : owner.state.grooves) { grooveIds.add (g.id); names.add (g.name); }
            if (grooveIds != ids || names != shownNames)
            {
                ids = grooveIds; shownNames = names;
                groove.clear (juce::dontSendNotification); groove.addItem ("None", 1);
                for (int i = 0; i < names.size(); ++i) groove.addItem (names[i], i + 2);
            }
            groove.setSelectedId (clip.grooveId.isEmpty() ? 1 : ids.indexOf (clip.grooveId) + 2, juce::dontSendNotification);
            const bool editable = ! owner.session.isExporting();
            groove.setEnabled (editable); commit.setEnabled (editable && clip.grooveId.isNotEmpty());
        }
        void resized() override
        {
            auto area = getLocalBounds().reduced (6, 0).withTrimmedTop (28);
            area.removeFromTop (14); groove.setBounds (area.removeFromTop (22));
            area.removeFromTop (8); commit.setBounds (area.removeFromTop (22));
            area.removeFromTop (8); pool.setBounds (area.removeFromTop (22));
        }
        void paint (juce::Graphics& g) override
        {
            g.setColour (themes::colour (0xff303030)); g.fillRect (getLocalBounds());
            g.setColour (themes::colour (0xff4a4a4a)); g.fillRect (getLocalBounds().withHeight (22));
            g.setColour (line); g.drawRect (getLocalBounds());
            g.setColour (ink); g.setFont (font (11.0f, true));
            g.drawText ("Groove", getLocalBounds().withHeight (22).reduced (6, 0), juce::Justification::centredLeft);
            g.setColour (muted); g.setFont (font (10.0f));
            g.drawText ("Groove", 6, groove.getY() - 14, getWidth() - 12, 13, juce::Justification::bottomLeft);
        }
    private:
        Impl& owner;
        Session::ClipInfo clip;
        juce::StringArray ids, shownNames;
        juce::ComboBox groove;
        juce::TextButton commit { "Commit" }, pool { "Groove Pool" };
    };

    // The Groove Pool: every groove in the project with its Base, Quantize, Timing, Random and
    // Velocity, and the Global Amount that scales Timing, Random and Velocity for all of them.
    // View > Undo History, after the reference's: the project's history from its start, oldest first.
    // The current step is selected, the steps Redo would do again are dimmed, and a click undoes or
    // redoes to the step clicked.
    class UndoHistoryPanel final : public juce::Component, private juce::ListBoxModel
    {
    public:
        explicit UndoHistoryPanel (Impl& o) : owner (o)
        {
            setName ("Undo History");
            addAndMakeVisible (list); list.setName ("Undo steps"); list.setModel (this); list.setRowHeight (22);
            list.setColour (juce::ListBox::backgroundColourId, background);
            sync();
        }
        void sync()
        {
            const auto undoNow = owner.session.undoSteps(), redoNow = owner.session.redoSteps();
            if (undoNow == undo && redoNow == redo && list.getNumSelectedRows() == 1) return;
            undo = undoNow; redo = redoNow;
            list.updateContent(); list.selectRow (currentRow(), false, true); list.repaint();
        }
        int rowCount() const { return 1 + undo.size() + redo.size(); }
        int currentRow() const { return undo.size(); }
        // The start, then each step by its name, as Edit's Undo and Redo name it.
        juce::String rowText (int row) const
        {
            const auto step = row == 0 ? juce::String ("Start") : row <= undo.size() ? undo[undo.size() - row] : redo[row - undo.size() - 1];
            return step.isEmpty() ? juce::String ("Edit") : step.substring (0, 1).toUpperCase() + step.substring (1);
        }
        void clickRow (int row) { owner.moveInHistory (row - currentRow()); }
        void resized() override { list.setBounds (getLocalBounds()); }
    private:
        Impl& owner;
        juce::ListBox list;
        juce::StringArray undo, redo;
        int getNumRows() override { return rowCount(); }
        void paintListBoxItem (int row, juce::Graphics& g, int width, int height, bool selected) override
        {
            if (selected) g.fillAll (orange.withAlpha (.25f));
            g.setColour (row > currentRow() ? muted : ink); g.setFont (font (12.0f));
            g.drawText (rowText (row), 10, 0, width - 20, height, juce::Justification::centredLeft, true);
        }
        void listBoxItemClicked (int row, const juce::MouseEvent&) override { clickRow (row); }
    };
    class GroovePoolPanel final : public juce::Component
    {
    public:
        explicit GroovePoolPanel (Impl& o) : owner (o)
        {
            setName ("Groove Pool");
            for (auto* c : std::initializer_list<juce::Component*> { &viewport, &amount, &add, &empty }) addAndMakeVisible (c);
            viewport.setViewedComponent (&list, false); viewport.setScrollBarsShown (true, false);
            amount.setName ("Global groove amount"); amount.setSliderStyle (juce::Slider::LinearBar);
            amount.setRange (0, Session::maximumGrooveAmount, 1); amount.setDoubleClickReturnValue (true, 100);
            styleBar (amount);
            amount.textFromValueFunction = [] (double v) { return "Global Amount " + juce::String (juce::roundToInt (v)) + "%"; };
            amount.setTooltip ("Global Amount: scales the Timing, Random and Velocity of every groove (0-130%). Double-click for 100%.");
            amount.valueFromTextFunction = [] (const juce::String& text) { return text.retainCharacters (".0123456789").getDoubleValue(); };
            amount.updateText();
            amount.onDragStart = [this] { owner.session.beginEditGesture ("Groove amount"); };
            amount.onDragEnd = [this] { owner.session.endEditGesture(); };
            amount.onValueChange = [this] { owner.report (owner.session.setGrooveAmount ((float) amount.getValue())); owner.refresh(); };
            add.setName ("Add groove"); add.setTooltip ("Add a groove from Halftrack's library, a groove file or the selected MIDI clip");
            add.onClick = [this] { owner.showAddGrooveMenu (add); };
            empty.setText ("No grooves yet. Add one from the library or a groove file, or extract one from a MIDI clip.", juce::dontSendNotification);
            empty.setColour (juce::Label::textColourId, muted); empty.setJustificationType (juce::Justification::centred);
            sync();
        }
        ~GroovePoolPanel() override { owner.session.endEditGesture(); }
        void sync()
        {
            const auto& pool = owner.state.grooves;
            juce::StringArray ids; for (const auto& g : pool) ids.add (g.id);
            if (ids != rowIds)
            {
                rowIds = ids; rows.clear();
                for (const auto& g : pool) { auto* row = rows.add (new Row (*this, g.id)); list.addAndMakeVisible (row); }
                layoutRows();
            }
            for (int i = 0; i < rows.size(); ++i) rows[i]->show (pool[(size_t) i]);
            if (! amount.isMouseButtonDown()) amount.setValue (owner.state.grooveAmount, juce::dontSendNotification);
            empty.setVisible (pool.empty());
        }
        void resized() override
        {
            auto area = getLocalBounds().reduced (10);
            auto footer = area.removeFromBottom (26); area.removeFromBottom (8);
            add.setBounds (footer.removeFromLeft (110)); footer.removeFromLeft (10); amount.setBounds (footer.removeFromLeft (220));
            header = area.removeFromTop (18);
            viewport.setBounds (area); empty.setBounds (area);
            layoutRows();
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (panel);
            g.setColour (muted); g.setFont (font (10.0f, true));
            int x = header.getX();
            for (const auto& [label, w] : columns()) { g.drawText (label, x + 2, header.getY(), w - 4, header.getHeight(), juce::Justification::centredLeft); x += w; }
        }
    private:
        static std::vector<std::pair<const char*, int>> columns()
        { return { { "GROOVE", 190 }, { "BASE", 70 }, { "QUANTIZE", 90 }, { "TIMING", 90 }, { "RANDOM", 90 }, { "VELOCITY", 90 }, { "", 30 } }; }
        static void styleBar (juce::Slider& s)
        {
            s.setWantsKeyboardFocus (false); s.setColour (juce::Slider::trackColourId, themes::colour (0xff4a4a4a));
            s.setColour (juce::Slider::textBoxTextColourId, ink);
        }
        class Row final : public juce::Component
        {
        public:
            Row (GroovePoolPanel& p, const juce::String& grooveId) : pool (p), id (grooveId)
            {
                for (auto* c : std::initializer_list<juce::Component*> { &name, &base, &quantize, &timing, &random, &velocity, &remove }) addAndMakeVisible (c);
                name.setEditable (false, true, false); name.setColour (juce::Label::textColourId, ink);
                name.setTooltip ("Double-click to rename");
                name.onTextChange = [this] { auto g = groove; g.name = name.getText(); apply (g); };
                for (int b = 0; b < Session::grooveBaseCount; ++b) base.addItem (Session::grooveBaseName ((Session::GrooveBase) b), b + 1);
                base.setName ("Base"); base.setTooltip ("Base: the grid the groove's timing is measured against");
                base.onChange = [this] { auto g = groove; g.base = (Session::GrooveBase) (base.getSelectedId() - 1); apply (g); };
                const auto bar = [this] (juce::Slider& s, const char* label, double low, double initial, float Session::GrooveInfo::* field, const char* tip)
                {
                    s.setName (juce::String (label)); s.setSliderStyle (juce::Slider::LinearBar); s.setRange (low, 100, 1);
                    s.setDoubleClickReturnValue (true, initial); styleBar (s); s.setTooltip (tip);
                    s.textFromValueFunction = [] (double v) { return juce::String (juce::roundToInt (v)) + "%"; };
                    s.valueFromTextFunction = [] (const juce::String& text) { return text.retainCharacters ("-.0123456789").getDoubleValue(); };
                    s.updateText();
                    s.onDragStart = [this] { pool.owner.session.beginEditGesture ("Groove"); };
                    s.onDragEnd = [this] { pool.owner.session.endEditGesture(); };
                    s.onValueChange = [this, &s, field] { auto g = groove; g.*field = (float) s.getValue(); apply (g); };
                };
                bar (quantize, "Quantize", 0, 0, &Session::GrooveInfo::quantize, "Quantize: how far notes move onto the Base grid before the groove applies");
                bar (timing, "Timing", 0, 100, &Session::GrooveInfo::timing, "Timing: how much the groove's timing moves the notes");
                bar (random, "Random", 0, 0, &Session::GrooveInfo::random, "Random: random timing of up to half a Base step, different for every note");
                bar (velocity, "Velocity", -100, 0, &Session::GrooveInfo::velocity, "Velocity: how much the groove's accents change note velocities; negative values invert them");
                remove.setName ("Remove groove"); remove.setTooltip ("Remove this groove; clips that use it play without a groove");
                remove.onClick = [this] { pool.owner.report (pool.owner.session.removeGroove (id)); pool.owner.refresh(); };
            }
            void show (const Session::GrooveInfo& g)
            {
                groove = g;
                if (! name.isBeingEdited()) name.setText (g.name, juce::dontSendNotification);
                name.setName ("Groove name " + g.name);
                base.setSelectedId ((int) g.base + 1, juce::dontSendNotification);
                const std::array<std::pair<juce::Slider*, float>, 4> values {{ { &quantize, g.quantize }, { &timing, g.timing }, { &random, g.random }, { &velocity, g.velocity } }};
                for (const auto& [slider, value] : values)
                    if (! slider->isMouseButtonDown()) slider->setValue (value, juce::dontSendNotification);
            }
            void resized() override
            {
                int x = 0;
                std::array<juce::Component*, 7> cells { &name, &base, &quantize, &timing, &random, &velocity, &remove };
                const auto widths = columns();
                for (size_t i = 0; i < cells.size(); ++i) { cells[i]->setBounds (x + 2, 3, widths[i].second - 4, getHeight() - 6); x += widths[i].second; }
            }
            void paint (juce::Graphics& g) override { g.setColour (line); g.drawHorizontalLine (getHeight() - 1, 0.0f, (float) getWidth()); }
            GroovePoolPanel& pool;
            const juce::String id;
        private:
            Session::GrooveInfo groove;
            juce::Label name;
            juce::ComboBox base;
            juce::Slider quantize, timing, random, velocity;
            juce::TextButton remove { "X" };
            void apply (const Session::GrooveInfo& g) { pool.owner.report (pool.owner.session.setGroove (id, g)); pool.owner.refresh(); }
        };
        void layoutRows()
        {
            int total = 0; for (const auto& [label, w] : columns()) total += w;
            list.setSize (std::max (total, viewport.getMaximumVisibleWidth()), rows.size() * rowHeight);
            for (int i = 0; i < rows.size(); ++i) rows[i]->setBounds (0, i * rowHeight, list.getWidth(), rowHeight);
        }
        static constexpr int rowHeight = 30;
        Impl& owner;
        juce::Viewport viewport;
        juce::Component list;
        juce::OwnedArray<Row> rows;
        juce::StringArray rowIds;
        juce::Rectangle<int> header;
        juce::Slider amount;
        juce::TextButton add { "Add Groove..." };
        juce::Label empty;
    };

    // MIDI Map Mode, after the reference: mappable controls show in blue with their controller, the
    // control being learned is outlined, and clicking a control learns it. Controls take part by
    // carrying a "midiMapTarget" property with their mapping target.
    class MapOverlay final : public juce::Component
    {
    public:
        explicit MapOverlay (Impl& o) : owner (o) { setName ("MIDI map overlay"); setAlwaysOnTop (true); }
        // A mappable control, or an area of one (a launcher slot, scene or stop button), and its target.
        struct Target { juce::Component* component; juce::Rectangle<int> area; juce::String key; };
        std::vector<Target> targets() const
        {
            std::vector<Target> found;
            const std::function<void (juce::Component&)> visit = [&] (juce::Component& c)
            {
                // Visibility down from the main component, so hidden panels and their controls are skipped.
                if (&c == this || ! c.isVisible()) return;
                if (const auto key = c.getProperties()["midiMapTarget"].toString(); key.isNotEmpty()) found.push_back ({ &c, c.getLocalBounds(), key });
                if (&c == &owner.launcher) for (const auto& [area, key] : owner.launcher.mapAreas()) found.push_back ({ &c, area, key });
                for (auto* child : c.getChildren()) visit (*child);
            };
            visit (owner);
            return found;
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff000000).withAlpha (0.12f));
            const bool keys = owner.keyMapMode;
            for (const auto& t : targets())
            {
                const auto r = getLocalArea (t.component, t.area).toFloat();
                if (! getLocalBounds().toFloat().intersects (r)) continue;
                g.setColour ((keys ? themes::colour (0xffff8f3d) : themes::colour (0xff3d8bff)).withAlpha (0.42f)); g.fillRect (r);
                g.setColour (themes::colour (0xffffffff)); g.setFont (font (9.0f, true));
                if (keys)
                {
                    for (const auto& m : owner.state.keyMappings)
                        if (m.target == t.key) g.drawFittedText (juce::String::charToString (juce::CharacterFunctions::toUpperCase (m.key)), r.toNearestInt(), juce::Justification::centred, 1);
                }
                else
                    for (const auto& m : owner.state.midiMappings)
                        if (m.target == t.key) g.drawFittedText (juce::String (m.channel) + "/" + (m.note ? midimonitor::noteName (m.controller) : juce::String (m.controller)), r.toNearestInt(), juce::Justification::centred, 1);
                if ((keys ? owner.state.keyLearnTarget : owner.state.midiLearnTarget) == t.key) { g.setColour (keys ? themes::colour (0xffffffff) : orange); g.drawRect (r.expanded (1), 2.0f); }
            }
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            juce::String key;
            for (const auto& t : targets())
                if (getLocalArea (t.component, t.area).contains (e.getPosition())) key = t.key;
            owner.report (owner.keyMapMode ? owner.session.setKeyLearnTarget (key) : owner.session.setMidiLearnTarget (key)); owner.refresh(); repaint();
        }
    private:
        Impl& owner;
    };

    // The Mapping Browser: every MIDI mapping with its control, controller, Min and Max.
    class MappingList final : public juce::Component
    {
    public:
        explicit MappingList (Impl& o) : owner (o) { setName ("MIDI mappings"); }
        void sync()
        {
            const bool keys = owner.keyMapMode;
            juce::StringArray targets;
            if (keys) for (const auto& m : owner.state.keyMappings) targets.add (m.target);
            else for (const auto& m : owner.state.midiMappings) targets.add (m.target);
            if (targets != shown || keys != showingKeys)
            {
                shown = targets; showingKeys = keys; rows.clear();
                for (const auto& target : targets) { auto* row = rows.add (new Row (*this, target, keys)); addAndMakeVisible (row); }
                resized();
            }
            for (int i = 0; i < rows.size(); ++i)
                if (keys) rows[i]->showKey (owner.state.keyMappings[(size_t) i]); else rows[i]->show (owner.state.midiMappings[(size_t) i]);
            repaint();
        }
        void resized() override
        {
            for (int i = 0; i < rows.size(); ++i) rows[i]->setBounds (0, 22 + i * 46, getWidth(), 44);
        }
        void paint (juce::Graphics& g) override
        {
            g.setColour (muted); g.setFont (font (10.0f, true));
            g.drawText (owner.keyMapMode ? "KEY MAPPINGS" : "MIDI MAPPINGS", 4, 0, getWidth() - 8, 20, juce::Justification::centredLeft);
            if (rows.isEmpty())
            {
                g.setFont (font (11.0f));
                g.drawFittedText ("Click a blue control, then move a knob or fader on your MIDI controller.", getLocalBounds().withTrimmedTop (24).reduced (8), juce::Justification::centredTop, 4);
            }
        }
        // A mapping's controller or note, for the list: "Ch 1  CC 7" or "Ch 1  Note C3".
        static juce::String controllerText (const Session::MidiMapping& m)
        { return "Ch " + juce::String (m.channel) + (m.note ? "  Note " + midimonitor::noteName (m.controller) : "  CC " + juce::String (m.controller)); }
        // The control a target names, for the list.
        juce::String describe (const juce::String& target) const
        {
            const auto parts = juce::StringArray::fromTokens (target, ":", "");
            if (target == "master") return "Main / Volume";
            if (parts[0] == "transport")
            {
                const juce::StringArray ids { "play", "stop", "record", "loop", "metronome", "stopClips" }, names { "Play", "Stop", "Record", "Loop", "Metronome", "Stop All Clips" };
                return "Transport / " + names[juce::jmax (0, ids.indexOf (parts[1]))];
            }
            for (size_t scene = 0; scene < owner.state.scenes.size(); ++scene)
                if ((parts[0] == "scene" && parts[1] == owner.state.scenes[scene].id) || (parts[0] == "slot" && parts[2] == owner.state.scenes[scene].id))
                {
                    const auto sceneName = owner.state.scenes[scene].name.isNotEmpty() ? owner.state.scenes[scene].name : "Scene " + juce::String ((int) scene + 1);
                    if (parts[0] == "scene") return sceneName + " / Launch";
                    for (const auto& t : owner.state.tracks) if (t.id == parts[1]) return t.name + " / " + sceneName + " clip slot";
                }
            for (const auto& t : owner.state.tracks)
            {
                if (parts[0] == "track" && t.id == parts[1])
                    return t.name + " / " + (parts[2] == "mute" ? "Track Activator" : parts[2] == "solo" ? "Solo" : parts[2] == "arm" ? "Arm" : "Clip Stop");
                if (parts[0] == "device" && parts[2] == "on")
                    for (const auto& p : t.plugins) if (p.id == parts[1]) return t.name + " / " + p.name + " / Device On";
                if (parts[0] == "mixer" && t.id == parts[1]) return t.name + " / " + (parts[2] == "pan" ? "Pan" : "Volume");
                if (parts[0] == "device")
                    for (const auto* list : { &t.plugins })
                        for (const auto& p : *list)
                            if (p.id == parts[1] && p.isNativeEffect)
                            {
                                const auto fields = effectParameters (p.effect.kind);
                                const int index = parts[2].getIntValue();
                                return t.name + " / " + p.name + " / " + (juce::isPositiveAndBelow (index, (int) fields.size()) ? juce::String (fields[(size_t) index].label) : juce::String());
                            }
                if (parts[0] == "device" && t.instrument.isNativeEffect && t.instrument.id == parts[1])
                {
                    const auto fields = effectParameters (t.instrument.effect.kind);
                    const int index = parts[2].getIntValue();
                    return t.name + " / " + t.instrument.name + " / " + (juce::isPositiveAndBelow (index, (int) fields.size()) ? juce::String (fields[(size_t) index].label) : juce::String());
                }
            }
            return target;
        }
    private:
        class Row final : public juce::Component
        {
        public:
            Row (MappingList& l, const juce::String& t, bool keyRow) : list (l), target (t), forKey (keyRow)
            {
                for (auto* c : std::initializer_list<juce::Component*> { &minimum, &maximum, &remove }) addAndMakeVisible (c);
                for (auto* s : { &minimum, &maximum })
                {
                    s->setSliderStyle (juce::Slider::LinearBar); s->setWantsKeyboardFocus (false);
                    s->setColour (juce::Slider::trackColourId, themes::colour (0xff3d8bff).withAlpha (0.5f)); s->setColour (juce::Slider::textBoxTextColourId, ink);
                    s->setNumDecimalPlacesToDisplay (2);
                    s->onValueChange = [this] { list.owner.report (list.owner.session.setMidiMappingRange (target, (float) minimum.getValue(), (float) maximum.getValue())); list.owner.refresh(); };
                }
                minimum.setName ("Mapping minimum"); maximum.setName ("Mapping maximum");
                minimum.setTooltip ("Min: the control's value at the controller's lowest position");
                maximum.setTooltip ("Max: the control's value at the controller's highest position. Set it below Min to invert.");
                remove.setName ("Remove mapping"); remove.setTooltip ("Remove this mapping");
                remove.onClick = [this] { list.owner.report (forKey ? list.owner.session.removeKeyMapping (target) : list.owner.session.removeMidiMapping (target)); list.owner.refresh(); };
                // Buttons, and keys, have no range to set.
                const bool ranged = ! forKey && ! Session::isButtonTarget (target);
                minimum.setVisible (ranged); maximum.setVisible (ranged);
            }
            void showKey (const Session::KeyMapping& m) { keyMapping = m; repaint(); }
            void show (const Session::MidiMapping& m)
            {
                mapping = m;
                if (const auto range = list.owner.session.midiTargetRange (target))
                    for (auto* s : { &minimum, &maximum }) s->setRange (range->first, range->second, 0);
                if (! minimum.isMouseButtonDown()) minimum.setValue (m.minimum, juce::dontSendNotification);
                if (! maximum.isMouseButtonDown()) maximum.setValue (m.maximum, juce::dontSendNotification);
                repaint();
            }
            void resized() override
            {
                auto area = getLocalBounds().reduced (4, 2); area.removeFromTop (18);
                remove.setBounds (area.removeFromRight (22));
                minimum.setBounds (area.removeFromLeft (area.getWidth() / 2).reduced (1, 0)); maximum.setBounds (area.reduced (1, 0));
            }
            void paint (juce::Graphics& g) override
            {
                g.setColour (ink); g.setFont (font (10.5f));
                g.drawText (list.describe (target), 4, 0, getWidth() - 94, 18, juce::Justification::centredLeft, true);
                g.setColour (muted); g.setFont (font (10.0f));
                g.drawText (forKey ? "Key " + juce::String::charToString (juce::CharacterFunctions::toUpperCase (keyMapping.key))
                                   : MappingList::controllerText (mapping), getWidth() - 90, 0, 86, 18, juce::Justification::centredRight);
                g.setColour (line); g.drawHorizontalLine (getHeight() - 1, 0.0f, (float) getWidth());
            }
        private:
            MappingList& list;
            const juce::String target;
            const bool forKey;
            Session::MidiMapping mapping;
            Session::KeyMapping keyMapping;
            juce::Slider minimum, maximum;
            juce::TextButton remove { "X" };
        };
        Impl& owner;
        juce::OwnedArray<Row> rows;
        juce::StringArray shown;
        bool showingKeys = false;
    };

    // Clip envelope editing, shared by the piano roll's lane and the audio clip view: the controls
    // a clip's envelopes can change, and the chosen envelope as a breakpoint line over the clip's
    // content beats. Clicking adds a point and drags it; double-click or right-click deletes one.
    struct EnvelopeChoice { Session::EnvelopeTarget target; Session::EnvelopeMode mode; juce::String device, control; };
    class EnvelopeEditor
    {
    public:
        explicit EnvelopeEditor (Impl& o) : owner (o) {}
        std::optional<EnvelopeChoice> choice;
        // Draw Mode's grid: the editor's step, and whether a drag with these keys snaps to it.
        std::function<double()> gridStep;
        std::function<bool (juce::ModifierKeys)> snaps;
        bool active() const { return choice.has_value(); }
        // The track's mixer and device controls; Session clips can also automate them.
        static std::vector<EnvelopeChoice> choices (const Impl& owner, const Session::TrackInfo& track, bool sessionClip)
        {
            std::vector<EnvelopeChoice> result;
            for (const auto mode : { Session::EnvelopeMode::modulation, Session::EnvelopeMode::automation })
            {
                if (mode == Session::EnvelopeMode::automation && ! sessionClip) continue;
                result.push_back ({ { {}, 0 }, mode, "Mixer", "Track Volume" });
                // The pans of the track's pan mode, as the reference's chooser offers them.
                if (! track.splitPan) result.push_back ({ { {}, 1 }, mode, "Mixer", "Track Panning" });
                else { result.push_back ({ { {}, 2 }, mode, "Mixer", "Left Split Stereo" }); result.push_back ({ { {}, 3 }, mode, "Mixer", "Right Split Stereo" }); }
                auto devices = track.plugins;
                if (track.instrument.isNativeEffect) devices.insert (devices.begin(), track.instrument);
                for (const auto& device : devices)
                {
                    if (device.isNativeEffect && ! device.isRack)
                    {
                        const auto fields = effectParameters (device.effect.kind);
                        for (size_t i = 0; i < fields.size(); ++i) result.push_back ({ { device.id, (int) i }, mode, device.name, fields[i].label });
                    }
                    else if (! device.isNativeEffect && ! device.isUtility && ! device.missing)
                    {
                        const auto parameters = owner.session.pluginParameters (device.id);
                        for (size_t i = 0; i < parameters.size(); ++i) result.push_back ({ { device.id, (int) i }, mode, device.name, parameters[i].name });
                    }
                }
            }
            return result;
        }
        juce::String label() const
        {
            if (! choice) return {};
            return choice->control + (choice->mode == Session::EnvelopeMode::automation ? " (Automation)" : " (Modulation)");
        }
        // Position 0-1 from the bottom of the editor for an envelope value, and back.
        float proportion (float value) const
        {
            if (! choice) return 0;
            using Mode = Session::EnvelopeMode;
            const bool mixer = choice->target.pluginId.isEmpty(), volume = mixer && choice->target.parameter == 0;
            if (choice->mode == Mode::modulation) return volume ? value : (value + 1) / 2;
            if (volume) return Session::automationValueToProportion (Session::AutomationTarget::volume, value);
            if (mixer) return (value + 1) / 2;
            if (const auto* d = device(); d != nullptr && d->isNativeEffect) return Session::deviceAutomationValueToProportion (d->effect.kind, choice->target.parameter, value);
            return value;
        }
        float value (float position) const
        {
            if (! choice) return 0;
            using Mode = Session::EnvelopeMode;
            position = juce::jlimit (0.0f, 1.0f, position);
            const bool mixer = choice->target.pluginId.isEmpty(), volume = mixer && choice->target.parameter == 0;
            if (choice->mode == Mode::modulation) return volume ? position : position * 2 - 1;
            if (volume) return juce::jlimit (-100.0f, 6.0f, Session::automationProportionToValue (Session::AutomationTarget::volume, position));
            if (mixer) return position * 2 - 1;
            if (const auto* d = device(); d != nullptr && d->isNativeEffect) return Session::deviceAutomationProportionToValue (d->effect.kind, choice->target.parameter, position);
            return position;
        }
        // The level a control keeps where there are no points: unchanged by modulation.
        float neutral() const
        {
            const bool volume = choice && choice->target.pluginId.isEmpty() && choice->target.parameter == 0;
            return choice && choice->mode == Session::EnvelopeMode::modulation ? (volume ? 1.0f : 0.0f) : value (.5f);
        }
        std::vector<Session::AutomationPoint> points (const Session::ClipInfo& clip) const
        {
            if (preview) return *preview;
            if (const auto* e = envelope (clip)) return e->points;
            return {};
        }
        void paint (juce::Graphics& g, juce::Rectangle<float> area, const Session::ClipInfo& clip, const std::function<float (double)>& x, double endBeat) const
        {
            if (! choice) return;
            const auto y = [&] (float v) { return area.getBottom() - proportion (v) * area.getHeight(); };
            const auto list = points (clip);
            g.setColour (themes::colour (0x40ffffff)); g.drawHorizontalLine ((int) y (neutral()), area.getX(), area.getRight());
            if (list.empty()) return;
            juce::Path path;
            path.startNewSubPath (x (0), y (list.front().value));
            for (const auto& point : list) path.lineTo (x (point.beat), y (point.value));
            path.lineTo (x (endBeat), y (list.back().value));
            g.setColour (themes::colour (0xffff5e5e)); g.strokePath (path, juce::PathStrokeType (1.5f));
            for (size_t i = 0; i < list.size(); ++i)
            {
                g.setColour ((int) i == dragged ? themes::colour (0xffffffff) : themes::colour (0xffff5e5e));
                g.fillEllipse (x (list[i].beat) - 3.5f, y (list[i].value) - 3.5f, 7, 7);
            }
        }
        void mouseDown (const juce::MouseEvent& e, juce::Rectangle<float> area, const Session::ClipInfo& clip,
                        const std::function<float (double)>& x, const std::function<double (float)>& beatAt, double endBeat)
        {
            dragged = -1; preview.reset(); drawing = false;
            if (! choice) return;
            clipId = clip.id;
            if (owner.drawMode && ! e.mods.isPopupMenu())
            {
                // Draw Mode draws over the points, as the Arrangement's envelopes do.
                sketch.begin (points (clip)); drawing = true;
                drawTo (e, area, beatAt, endBeat);
                return;
            }
            auto list = points (clip);
            const auto y = [&] (float v) { return area.getBottom() - proportion (v) * area.getHeight(); };
            int hit = -1;
            for (int i = (int) list.size(); --i >= 0;)
                if (std::abs (x (list[(size_t) i].beat) - e.position.x) <= 5 && std::abs (y (list[(size_t) i].value) - e.position.y) <= 6) { hit = i; break; }
            if (hit >= 0 && (e.mods.isPopupMenu() || e.getNumberOfClicks() > 1)) { list.erase (list.begin() + hit); commit (clip, list); return; }
            if (e.mods.isPopupMenu()) return;
            if (hit < 0)
            {
                const Session::AutomationPoint point { juce::jlimit (0.0, endBeat, snapped (beatAt (e.position.x), e.position.x, beatAt, e.mods)), value ((area.getBottom() - e.position.y) / area.getHeight()) };
                const auto at = std::lower_bound (list.begin(), list.end(), point.beat, [] (const auto& p, double b) { return p.beat < b; });
                if (at != list.end() && std::abs (at->beat - point.beat) < 1e-6) return;
                hit = (int) (at - list.begin()); list.insert (at, point);
            }
            preview = list; dragged = hit;
        }
        void mouseDrag (const juce::MouseEvent& e, juce::Rectangle<float> area, const std::function<double (float)>& beatAt, double endBeat)
        {
            if (drawing) { drawTo (e, area, beatAt, endBeat); return; }
            if (! preview || dragged < 0) return;
            auto& list = *preview;
            const double low = dragged > 0 ? list[(size_t) dragged - 1].beat + 1.0 / 960 : 0;
            const double high = (size_t) dragged + 1 < list.size() ? list[(size_t) dragged + 1].beat - 1.0 / 960 : endBeat;
            list[(size_t) dragged] = { juce::jlimit (low, juce::jmax (low, high), snapped (beatAt (e.position.x), e.position.x, beatAt, e.mods)), value ((area.getBottom() - e.position.y) / area.getHeight()) };
        }
        void mouseUp (const Session::ClipInfo& clip)
        {
            drawing = false;
            if (preview) { auto list = *preview; preview.reset(); dragged = -1; commit (clip, list); }
        }
    private:
        Impl& owner;
        juce::String clipId;
        arrangementAutomation::Drawing sketch;
        bool drawing = false;
        // A breakpoint near a grid line snaps to it, with Snap Automation to Grid on and the grid's snapping not bypassed.
        double snapped (double beat, float x, const std::function<double (float)>& beatAt, juce::ModifierKeys mods) const
        {
            const auto step = gridStep ? gridStep() : 0.0;
            if (step <= 0 || ! snaps || ! snaps (mods) || ! owner.session.snapAutomationToGrid()) return beat;
            const auto line = std::round (beat / step) * step;
            return line >= beatAt (x - automationMagnet) && line <= beatAt (x + automationMagnet) ? line : beat;
        }
        // Steps as wide as the editor's grid, or freehand with its snapping off or bypassed; the drawing shows until release.
        void drawTo (const juce::MouseEvent& e, juce::Rectangle<float> area, const std::function<double (float)>& beatAt, double endBeat)
        {
            arrangementAutomation::Drawing::Cell cell;
            if (const auto step = gridStep ? gridStep() : 0.0; step > 0 && snaps && snaps (e.mods))
                cell = [step, endBeat] (double beat) -> std::optional<std::pair<double, double>>
                {
                    const auto start = std::floor (beat / step + 1.0e-9) * step;
                    return std::pair { start, juce::jmin (endBeat, start + step) };
                };
            sketch.add (juce::jlimit (0.0, endBeat, beatAt (e.position.x)), (area.getBottom() - e.position.y) / juce::jmax (1.0f, area.getHeight()), cell);
            auto list = sketch.points ([this] (float p) { return value (p); }, [this] (float v) { return proportion (v); }, neutral());
            std::erase_if (list, [endBeat] (const auto& p) { return p.beat > endBeat + 1.0e-9; });
            preview = list;
        }
        std::optional<std::vector<Session::AutomationPoint>> preview;
        int dragged = -1;
        const Session::PluginInfo* device() const
        {
            const auto* track = owner.currentTrack();
            if (track == nullptr || ! choice) return nullptr;
            if (track->instrument.id == choice->target.pluginId) return &track->instrument;
            for (const auto& p : track->plugins) if (p.id == choice->target.pluginId) return &p;
            return nullptr;
        }
        const Session::ClipEnvelope* envelope (const Session::ClipInfo& clip) const
        {
            for (const auto& e : clip.envelopes) if (choice && e.target == choice->target && e.mode == choice->mode) return &e;
            return nullptr;
        }
        void commit (const Session::ClipInfo& clip, const std::vector<Session::AutomationPoint>& list)
        {
            Session::ClipEnvelope next { choice->target, choice->mode, list };
            if (const auto* e = envelope (clip)) { next.unlinked = e->unlinked; next.loopBeats = e->loopBeats; }
            owner.report (owner.session.setClipEnvelope (clipId, next)); owner.refresh();
        }
    };
    class AudioClipView final : public juce::Component, private juce::ChangeListener
    {
    public:
        explicit AudioClipView (Impl& o) : owner (o), thumbnail (512, o.formats, o.thumbnailCache)
        {
            setName ("Audio clip view");
            envelope.gridStep = [this] { return snapGrid(); };
            envelope.snaps = [this] (juce::ModifierKeys mods) { return snapsMarkers (mods); };
            for (auto* c : std::initializer_list<juce::Component*> { &warp, &mode, &bpm, &halve, &twice, &gain, &reverse, &transpose, &detune }) addAndMakeVisible (c);
            for (auto* c : std::initializer_list<juce::Component*> { &transientLoop, &transientEnvelope, &grainSize, &flux, &formants }) addChildComponent (c);
            addChildComponent (launch);
            addChildComponent (loopBox);
            for (auto* b : { &warp, &halve, &twice, &reverse }) { b->setWantsKeyboardFocus (false); b->setMouseClickGrabsKeyboardFocus (false); }
            warp.setName ("Clip warp"); warp.setClickingTogglesState (true); warp.setTooltip ("Warp: follow the project tempo (length fixed in beats)");
            warp.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); warp.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            warp.onClick = [this] { auto next = clip.warp; next.mode = warp.getToggleState() ? selectedMode() : Session::WarpMode::off; apply (next); };
            mode.setName ("Warp mode");
            mode.addItem ("Beats", 1); mode.addItem ("Tones", 2); mode.addItem ("Texture", 3); mode.addItem ("Re-Pitch", 4);
            mode.addItem ("Complex", 5); mode.addItem ("Complex Pro", 6); mode.addSeparator(); mode.addItem ("Complex (Efficient)", 7);
            mode.setTooltip ("Warp mode: Beats keeps transients, Tones and Texture stretch in grains, Re-Pitch changes the pitch with the tempo, Complex and Complex Pro suit full mixes");
            mode.onChange = [this] { if (clip.warp.mode != Session::WarpMode::off) { auto next = clip.warp; next.mode = selectedMode(); apply (next); } };
            // The chosen mode's own settings.
            transientLoop.setName ("Transient loop");
            transientLoop.addItem ("Loop Off", 1); transientLoop.addItem ("Loop Forward", 2); transientLoop.addItem ("Loop Back-and-Forth", 3);
            transientLoop.setTooltip ("What a segment plays once its audio runs out before the next transient");
            transientLoop.onChange = [this] { auto next = clip.warp; next.transientLoop = (Session::TransientLoop) (transientLoop.getSelectedId() - 1); apply (next); };
            const auto setting = [this] (juce::Slider& slider, const juce::String& name, double low, double high, const juce::String& tip, std::function<void (Session::WarpSettings&, float)> set)
            {
                slider.setName (name); slider.setSliderStyle (juce::Slider::LinearBar); slider.setRange (low, high, 1);
                slider.setTextValueSuffix (""); slider.setTooltip (tip);
                slider.textFromValueFunction = [name] (double v) { return name + " " + juce::String ((int) v); };
                slider.onDragStart = [this, name] { owner.session.beginEditGesture (name); gesture = true; };
                slider.onDragEnd = [this] { if (gesture) owner.session.endEditGesture(); gesture = false; };
                slider.onValueChange = [this, &slider, set]
                {
                    auto next = clip.warp; set (next, (float) slider.getValue());
                    if (next == clip.warp) return;
                    owner.report (owner.session.setAudioClipWarp (clip.id, next)); owner.refresh();
                };
            };
            setting (transientEnvelope, "Envelope", 0, 100, "Transient Envelope: below 100 each segment fades out", [] (auto& w, float v) { w.transientEnvelope = v; });
            setting (grainSize, "Grain", 1, 100, "Grain Size", [] (auto& w, float v) { w.grainSize = v; });
            setting (flux, "Flux", 0, 100, "Flux: how far the grains wander", [] (auto& w, float v) { w.flux = v; });
            setting (formants, "Formants", 0, 100, "Formants: how much of the formants stay when the clip is transposed", [] (auto& w, float v) { w.formants = v; });
            const auto knob = [this] (juce::Slider& slider, const juce::String& name, double low, double high, std::function<void (Session::AudioClipSettings&, double)> set)
            {
                slider.setName (name); slider.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag); slider.setRange (low, high, 1);
                slider.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 56, 14); slider.setDoubleClickReturnValue (true, 0);
                slider.setColour (juce::Slider::textBoxOutlineColourId, juce::Colours::transparentBlack);
                slider.onDragStart = [this, name] { owner.session.beginEditGesture (name); gesture = true; };
                slider.onDragEnd = [this] { if (gesture) owner.session.endEditGesture(); gesture = false; };
                slider.onValueChange = [this, &slider, set]
                {
                    auto next = clip.audio; set (next, slider.getValue());
                    if (next == clip.audio) return;
                    owner.report (owner.session.setAudioClipSettings (clip.id, next)); owner.refresh();
                };
            };
            knob (transpose, "Clip transpose", -48, 48, [] (auto& a, double v) { a.transposeSemitones = (int) v; });
            transpose.textFromValueFunction = [] (double v) { return (v > 0 ? "+" : "") + juce::String ((int) v) + " st"; };
            transpose.setTooltip ("Transpose: semitones, keeping the clip's speed (warped clips in a stretching mode)");
            knob (detune, "Clip detune", -50, 50, [] (auto& a, double v) { a.detuneCents = (float) v; });
            detune.textFromValueFunction = [] (double v) { return juce::String ((int) v) + " ct"; };
            detune.setTooltip ("Detune: cents, keeping the clip's speed (warped clips in a stretching mode)");
            bpm.setName ("Clip tempo"); bpm.setEditable (false, true, false); bpm.setJustificationType (juce::Justification::centred);
            bpm.setColour (juce::Label::backgroundColourId, background); bpm.setColour (juce::Label::outlineColourId, line);
            bpm.setTooltip ("The source's own tempo (Seg. BPM). Double-click to type it.");
            bpm.onTextChange = [this]
            {
                const auto text = bpm.getText().trim().toStdString(); char* end = nullptr; const auto value = std::strtod (text.c_str(), &end);
                if (! text.empty() && end == text.c_str() + text.size() && std::isfinite (value)) { auto next = clip.warp; next.bpm = value; apply (next); }
                else sync();
            };
            halve.setTooltip ("Halve the clip tempo (plays twice as long)"); twice.setTooltip ("Double the clip tempo (plays twice as fast)");
            halve.onClick = [this] { auto next = clip.warp; next.bpm /= 2; apply (next); };
            twice.onClick = [this] { auto next = clip.warp; next.bpm *= 2; apply (next); };
            gain.setName ("Clip gain"); gain.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag); gain.setRange (-100, 24, .1);
            gain.setSkewFactorFromMidPoint (-12); gain.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 56, 14);
            gain.setColour (juce::Slider::textBoxOutlineColourId, juce::Colours::transparentBlack); gain.setDoubleClickReturnValue (true, 0);
            gain.textFromValueFunction = [] (double v) { return v <= -100 ? juce::String ("-inf dB") : juce::String (v, 1) + " dB"; };
            gain.onDragStart = [this] { owner.session.beginEditGesture ("Clip gain"); gesture = true; };
            gain.onDragEnd = [this] { if (gesture) owner.session.endEditGesture(); gesture = false; };
            gain.onValueChange = [this]
            {
                auto settings = clip.audio; settings.gainDb = (float) gain.getValue();
                if (settings == clip.audio) return;
                owner.report (owner.session.setAudioClipSettings (clip.id, settings)); owner.refresh();
            };
            reverse.setName ("Clip reverse"); reverse.setClickingTogglesState (true);
            reverse.onClick = [this] { owner.report (owner.session.setAudioClipReversed (clip.id, reverse.getToggleState())); owner.refresh(); };
            addAndMakeVisible (envelopeChoice);
            envelopeChoice.setName ("Clip envelope");
            envelopeChoice.setTooltip ("Clip envelope: a mixer or device control this clip changes while it plays, drawn over the waveform. Click to add a point; double-click or right-click one to delete it.");
            envelopeChoice.onChange = [this]
            {
                const auto id = envelopeChoice.getSelectedId() - envelopeChoiceBase;
                envelope.choice.reset();
                if (juce::isPositiveAndBelow (id, (int) envelopeList.size())) envelope.choice = envelopeList[(size_t) id];
                repaint();
            };
            thumbnail.addChangeListener (this);
        }
        ~AudioClipView() override { thumbnail.removeChangeListener (this); if (gesture) owner.session.endEditGesture(); }
        bool sync()
        {
            const auto* selected = owner.selectedAudioClip();
            if (selected == nullptr) return false;
            clip = *selected;
            // Session clips show their Launch box between the Clip and Sample boxes.
            if (launch.isVisible() != owner.showSession) { launch.setVisible (owner.showSession); resized(); }
            // A warped clip shows its Loop box after the Launch box.
            if (loopBox.isVisible() != clip.canLoop) { loopBox.setVisible (clip.canLoop); resized(); }
            if (clip.canLoop) loopBox.setClip (clip);
            if (owner.showSession) launch.setClip (clip);
            if (clip.file != shownFile) { shownFile = clip.file; thumbnail.setSource (clip.file.existsAsFile() ? new juce::FileInputSource (clip.file) : nullptr); }
            const bool warped = clip.warp.mode != Session::WarpMode::off;
            // A warped clip shows its source's transients, read once a file.
            const auto transientsKey = warped ? clip.id + "|" + clip.file.getFullPathName() : juce::String();
            if (transientsKey != transientsFor) { transientsFor = transientsKey; transients = warped ? owner.session.audioClipTransients (clip.id) : std::vector<double> {}; }
            warp.setToggleState (warped, juce::dontSendNotification); warp.setEnabled (clip.canWarp && ! owner.session.isExporting());
            mode.setSelectedId (modeId (clip.warp.mode), juce::dontSendNotification); mode.setEnabled (warped);
            using Mode = Session::WarpMode;
            const auto shown = clip.warp.mode;
            transientLoop.setVisible (shown == Mode::beats); transientEnvelope.setVisible (shown == Mode::beats);
            grainSize.setVisible (shown == Mode::tones || shown == Mode::texture); flux.setVisible (shown == Mode::texture);
            formants.setVisible (shown == Mode::complexPro);
            transientLoop.setSelectedId ((int) clip.warp.transientLoop + 1, juce::dontSendNotification);
            const auto show = [] (juce::Slider& slider, double value) { if (! slider.isMouseButtonDown()) slider.setValue (value, juce::dontSendNotification); slider.updateText(); };
            show (transientEnvelope, clip.warp.transientEnvelope);
            show (grainSize, clip.warp.grainSize > 0 ? clip.warp.grainSize : (shown == Mode::texture ? 65.0 : 30.0));
            show (flux, clip.warp.flux); show (formants, clip.warp.formants);
            const bool pitchable = shown != Mode::off && shown != Mode::repitch;
            transpose.setEnabled (pitchable); detune.setEnabled (pitchable);
            show (transpose, clip.audio.transposeSemitones); show (detune, clip.audio.detuneCents);
            if (shown != laidOutMode) { laidOutMode = shown; resized(); }
            if (! bpm.isBeingEdited()) bpm.setText (juce::String (clip.warp.bpm, 2), juce::dontSendNotification);
            for (auto* c : std::initializer_list<juce::Component*> { &bpm, &halve, &twice }) c->setEnabled (clip.canWarp);
            if (! gain.isMouseButtonDown()) gain.setValue (clip.audio.gainDb, juce::dontSendNotification);
            gain.updateText();
            reverse.setToggleState (clip.reversed, juce::dontSendNotification); reverse.setEnabled (clip.canReverse || clip.reversed);
            refreshEnvelopeChoices();
            repaint(); return true;
        }
        // Rebuilt when the track's controls change; the shown envelope stays while its control remains.
        void refreshEnvelopeChoices()
        {
            const auto* track = owner.currentTrack();
            const auto list = track != nullptr ? EnvelopeEditor::choices (owner, *track, owner.showSession) : std::vector<EnvelopeChoice>();
            juce::StringArray signature;
            for (const auto& c : list) signature.add (c.target.pluginId + "|" + juce::String (c.target.parameter) + "|" + juce::String ((int) c.mode) + "|" + c.device + "|" + c.control);
            if (signature == envelopeSignature && envelopeChoice.getNumItems() > 0) return;
            envelopeSignature = signature; envelopeList = list;
            envelopeChoice.clear (juce::dontSendNotification);
            envelopeChoice.addItem ("No envelope", 1);
            for (const auto mode : { Session::EnvelopeMode::modulation, Session::EnvelopeMode::automation })
            {
                juce::PopupMenu modeMenu, deviceMenu;
                juce::String device;
                for (size_t i = 0; i < list.size(); ++i)
                {
                    if (list[i].mode != mode) continue;
                    if (list[i].device != device && deviceMenu.getNumItems() > 0) { modeMenu.addSubMenu (device, deviceMenu); deviceMenu = {}; }
                    device = list[i].device;
                    deviceMenu.addItem (envelopeChoiceBase + (int) i, list[i].control);
                }
                if (deviceMenu.getNumItems() > 0) modeMenu.addSubMenu (device, deviceMenu);
                if (modeMenu.getNumItems() > 0) envelopeChoice.getRootMenu()->addSubMenu (mode == Session::EnvelopeMode::modulation ? "Modulation" : "Automation", modeMenu);
            }
            int keep = 1;
            if (envelope.choice)
            {
                const auto shown = *envelope.choice;
                const auto at = std::find_if (list.begin(), list.end(), [&] (const auto& c) { return c.target == shown.target && c.mode == shown.mode; });
                if (at != list.end()) keep = envelopeChoiceBase + (int) (at - list.begin()); else envelope.choice.reset();
            }
            envelopeChoice.setSelectedId (keep, juce::dontSendNotification);
        }
        void resized() override
        {
            launch.setBounds (clipBox().getRight() + 6, 6, LaunchBox::width, getHeight() - 12);
            loopBox.setBounds (clipBox().getRight() + 6 + (launch.isVisible() ? LaunchBox::width + 6 : 0), 6, LoopBox::width, getHeight() - 12);
            auto sample = sampleBox();
            sample.removeFromTop (24);
            auto row = sample.removeFromTop (22).reduced (6, 0);
            warp.setBounds (row.removeFromLeft (52)); row.removeFromLeft (4); mode.setBounds (row);
            sample.removeFromTop (6);
            row = sample.removeFromTop (22).reduced (6, 0);
            twice.setBounds (row.removeFromRight (26)); halve.setBounds (row.removeFromRight (26)); row.removeFromRight (4);
            bpm.setBounds (row.withTrimmedLeft (54));
            sample.removeFromTop (6);
            // The mode's settings, then Transpose, Detune and Gain.
            row = sample.removeFromTop (22).reduced (6, 0);
            using Mode = Session::WarpMode;
            if (laidOutMode == Mode::beats) { transientLoop.setBounds (row.removeFromLeft (row.getWidth() * 3 / 5)); row.removeFromLeft (4); transientEnvelope.setBounds (row); }
            if (laidOutMode == Mode::tones) grainSize.setBounds (row);
            if (laidOutMode == Mode::texture) { grainSize.setBounds (row.removeFromLeft (row.getWidth() / 2 - 2)); row.removeFromLeft (4); flux.setBounds (row); }
            if (laidOutMode == Mode::complexPro) formants.setBounds (row);
            sample.removeFromTop (6);
            row = sample.removeFromTop (84).reduced (6, 0).withTrimmedTop (14);
            const auto third = row.getWidth() / 3;
            transpose.setBounds (row.removeFromLeft (third)); detune.setBounds (row.removeFromLeft (third)); gain.setBounds (row);
            sample.removeFromTop (6);
            reverse.setBounds (sample.removeFromTop (22).reduced (6, 0));
            envelopeChoice.setBounds (clipBox().reduced (8, 0).removeFromBottom (32).withTrimmedBottom (8));
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff262626));
            for (auto box : { clipBox(), sampleBox() })
            {
                g.setColour (themes::colour (0xff303030)); g.fillRect (box);
                g.setColour (themes::colour (0xff4a4a4a)); g.fillRect (box.withHeight (22));
                g.setColour (line); g.drawRect (box);
            }
            g.setColour (ink); g.setFont (font (11.0f, true));
            g.drawText ("Clip", clipBox().withHeight (22).reduced (6, 0), juce::Justification::centredLeft);
            g.drawText ("Sample", sampleBox().withHeight (22).reduced (6, 0), juce::Justification::centredLeft);
            auto details = clipBox().withTrimmedTop (28).reduced (8, 0);
            g.setFont (font (11.0f));
            g.setColour (owner.selectedTrackColour()); g.fillRect (details.removeFromTop (20));
            g.setColour (themes::colour (0xff141414)); g.drawText (clip.name, details.translated (0, -20).withHeight (20).reduced (5, 0), juce::Justification::centredLeft, true);
            g.setColour (muted);
            const auto line1 = "Start  " + juce::String (clip.start, 3) + " s", line2 = "Length  " + juce::String (clip.length, 3) + " s";
            g.drawText (line1, details.removeFromTop (20).withTrimmedTop (4), juce::Justification::centredLeft);
            g.drawText (line2, details.removeFromTop (18), juce::Justification::centredLeft);
            g.drawText (clip.file.getFileName(), details.removeFromTop (18), juce::Justification::centredLeft, true);
            g.drawText ("Seg. BPM", sampleBox().getX() + 6, bpm.getY(), 52, bpm.getHeight(), juce::Justification::centredLeft);
            for (auto [knob, name] : { std::pair<juce::Component*, const char*> { &transpose, "Transpose" }, { &detune, "Detune" }, { &gain, "Gain" } })
                g.drawText (name, knob->getBounds().withY (knob->getY() - 14).withHeight (14), juce::Justification::centred);
            // Waveform of the visible source span, with beat lines when warped. A warped clip is drawn
            // in its beats, each warp segment over its own beats.
            const auto wave = waveBounds();
            g.setColour (themes::colour (0xff1c1c1c)); g.fillRect (wave);
            const auto [firstBeat, beats] = visibleBeats();
            if (thumbnail.getTotalLength() > 0 && beats > 0)
            {
                g.setColour (owner.selectedTrackColour().withAlpha (0.85f));
                if (clip.warp.mode == Session::WarpMode::off)
                    thumbnail.drawChannels (g, wave.reduced (0, 6), clip.sourceOffset, clip.sourceOffset + clip.length, 0.95f);
                else
                {
                    const auto map = warpMap();
                    for (size_t i = 1; i < map.size(); ++i)
                    {
                        const auto from = std::max (map[i - 1].beat, firstBeat), to = std::min (map[i].beat, firstBeat + beats);
                        if (to <= from) continue;
                        const auto x0 = beatX (from), x1 = beatX (to);
                        if (x1 - x0 < .5f) continue;
                        const auto area = juce::Rectangle<float> (x0, (float) wave.getY() + 6, x1 - x0, (float) wave.getHeight() - 12);
                        thumbnail.drawChannels (g, area.toNearestInt(), sourceAt (from), sourceAt (to), 0.95f);
                    }
                }
            }
            if (clip.warp.mode != Session::WarpMode::off && beats > 0)
            {
                for (int beat = (int) std::ceil (firstBeat); beat <= (int) (firstBeat + beats); ++beat)
                {
                    const auto x = beatX (beat);
                    g.setColour (beat % 4 == 0 ? themes::colour (0x66ffffff) : themes::colour (0x22ffffff)); g.drawVerticalLine ((int) x, (float) wave.getY(), (float) wave.getBottom());
                }
                // The loop brace along the top and the start marker.
                if (clip.loop.on)
                {
                    const auto from = beatX (clip.loop.start), to = beatX (clip.loop.start + clip.loop.length);
                    g.setColour (themes::colour (0xffb4b4b4)); g.fillRect (from, (float) wave.getY(), to - from, 4.0f);
                }
                {
                    const auto x = beatX (clip.contentStartBeat);
                    juce::Path flag; flag.addTriangle (x, (float) wave.getBottom() - 10, x + 8, (float) wave.getBottom() - 5, x, (float) wave.getBottom());
                    g.setColour (themes::colour (0xffdadada)); g.fillPath (flag);
                }
                // Transients: short grey marks along the top, where a double-click pins a marker.
                g.setColour (themes::colour (0xffa0a0a0));
                for (const auto t : transients)
                {
                    const auto x = beatX (beatAtSource (t));
                    if (x >= wave.getX() && x <= wave.getRight()) g.drawVerticalLine ((int) x, (float) wave.getY() + 1, (float) wave.getY() + 7);
                }
                // Warp markers: yellow handles above lines through the waveform.
                for (size_t i = 0; i < clip.warpMarkers.size(); ++i)
                {
                    const auto& m = clip.warpMarkers[i];
                    if (i == 0 && m.beat == 0 && m.sourceSeconds == 0) continue; // The fixed start.
                    const auto x = beatX (m.beat);
                    if (x < wave.getX() - 4 || x > wave.getRight() + 4) continue;
                    g.setColour (juce::Colour ((int) i == draggedMarker ? 0xffffffff : 0xffffcf4a));
                    g.drawVerticalLine ((int) x, (float) wave.getY(), (float) wave.getBottom());
                    juce::Path handle; handle.addTriangle (x - 5, (float) wave.getY(), x + 5, (float) wave.getY(), x, (float) wave.getY() + 8);
                    g.fillPath (handle);
                }
            }
            if (envelope.active())
            {
                const auto [first, length] = envelopeBeats();
                envelope.paint (g, envelopeArea(), clip, [this] (double b) { return envelopeX (b); }, first + length);
            }
            g.setColour (line); g.drawRect (wave);
        }
    private:
        Impl& owner;
        juce::AudioThumbnail thumbnail;
        juce::File shownFile;
        Session::ClipInfo clip;
        std::vector<double> transients;
        juce::String transientsFor;
        juce::TextButton warp { "WARP" }, halve { ":2" }, twice { "*2" }, reverse { "Reverse" };
        juce::ComboBox mode, transientLoop;
        juce::Slider transientEnvelope, grainSize, flux, formants, transpose, detune;
        Session::WarpMode laidOutMode = Session::WarpMode::off;
        juce::Label bpm;
        juce::Slider gain;
        LaunchBox launch { owner };
        LoopBox loopBox { owner };
        bool gesture = false;
        // The Launch and Loop boxes' room between the Clip and Sample boxes.
        int launchSpace() const { return (launch.isVisible() ? LaunchBox::width + 6 : 0) + (loopBox.isVisible() ? LoopBox::width + 6 : 0); }
        juce::Rectangle<int> clipBox() const { return { 6, 6, 170, getHeight() - 12 }; }
        juce::Rectangle<int> sampleBox() const { return { 182 + launchSpace(), 6, 200, getHeight() - 12 }; }
        juce::Rectangle<int> waveBounds() const { return { 390 + launchSpace(), 6, juce::jmax (40, getWidth() - 396 - launchSpace()), getHeight() - 12 }; }
        // Chooser items in the reference's order, with Halftrack's cheaper Complex last.
        static constexpr Session::WarpMode chooserModes[] { Session::WarpMode::beats, Session::WarpMode::tones, Session::WarpMode::texture, Session::WarpMode::repitch,
                                                            Session::WarpMode::stretch, Session::WarpMode::complexPro, Session::WarpMode::efficient };
        static int modeId (Session::WarpMode m)
        {
            for (int i = 0; i < (int) std::size (chooserModes); ++i) if (chooserModes[i] == m) return i + 1;
            return 5; // An unwarped clip shows Complex, which the Warp switch chooses.
        }
        Session::WarpMode selectedMode() const
        { return juce::isPositiveAndBelow (mode.getSelectedId() - 1, (int) std::size (chooserModes)) ? chooserModes[mode.getSelectedId() - 1] : Session::WarpMode::stretch; }
        // Warp markers are edited in the stretching modes.
        bool markersEditable() const { return clip.warp.mode != Session::WarpMode::off && clip.warp.mode != Session::WarpMode::repitch; }
        void apply (const Session::WarpSettings& settings)
        {
            owner.report (owner.session.setAudioClipWarp (clip.id, settings)); owner.refresh(); sync();
        }
        void changeListenerCallback (juce::ChangeBroadcaster*) override { repaint(); }
    public:
        // The beats of the source the waveform shows: from the clip's start over its length, or the
        // loop with the start when it loops.
        std::pair<double, double> visibleBeats() const
        {
            if (clip.warp.mode == Session::WarpMode::off) return { 0.0, clip.length };
            const auto first = clip.loop.on ? std::min (clip.loop.start, clip.contentStartBeat) : clip.contentStartBeat;
            return { first, std::max (1e-6, contentEndBeat (clip) - first) };
        }
        float beatX (double beat) const
        {
            const auto wave = waveBounds(); const auto [first, beats] = visibleBeats();
            return wave.getX() + (float) ((beat - first) / std::max (1e-9, beats)) * wave.getWidth();
        }
        double xBeat (float x) const
        {
            const auto wave = waveBounds(); const auto [first, beats] = visibleBeats();
            return first + (x - wave.getX()) / std::max (1.0f, (float) wave.getWidth()) * beats;
        }
        // The warp map in source seconds and beats: the fixed start, the clip's markers and, after the
        // last, the clip's tempo to the source's end.
        std::vector<Session::WarpMarker> warpMap() const
        {
            auto map = clip.warpMarkers;
            if (map.empty() || map.front().sourceSeconds > 0 || map.front().beat > 0) map.insert (map.begin(), { 0, 0 });
            if (map.back().sourceSeconds < clip.sourceLength)
                map.push_back ({ clip.sourceLength, map.back().beat + (clip.sourceLength - map.back().sourceSeconds) * clip.warp.bpm / 60 });
            return map;
        }
        double sourceAt (double beat) const
        {
            const auto map = warpMap();
            if (beat <= 0) return beat * 60 / clip.warp.bpm;
            for (size_t i = 1; i < map.size(); ++i)
                if (beat <= map[i].beat || i + 1 == map.size())
                {
                    const auto span = map[i].beat - map[i - 1].beat;
                    return map[i - 1].sourceSeconds + (span > 0 ? (beat - map[i - 1].beat) / span : 0) * (map[i].sourceSeconds - map[i - 1].sourceSeconds);
                }
            return beat * 60 / clip.warp.bpm;
        }
        // The beat a point of the source plays on: the inverse of sourceAt.
        double beatAtSource (double seconds) const
        {
            const auto map = warpMap();
            for (size_t i = 1; i < map.size(); ++i)
                if (seconds <= map[i].sourceSeconds || i + 1 == map.size())
                {
                    const auto span = map[i].sourceSeconds - map[i - 1].sourceSeconds;
                    return map[i - 1].beat + (span > 0 ? (seconds - map[i - 1].sourceSeconds) / span : 0) * (map[i].beat - map[i - 1].beat);
                }
            return seconds * clip.warp.bpm / 60;
        }
        // The transient within a few pixels of x, in source seconds.
        std::optional<double> transientAt (float x) const
        {
            std::optional<double> found;
            float nearest = 5;
            for (const auto t : transients)
                if (const auto distance = std::abs (beatX (beatAtSource (t)) - x); distance <= nearest) { nearest = distance; found = t; }
            return found;
        }
        // The movable marker within a few pixels of x, or -1.
        int markerAt (float x) const
        {
            for (size_t i = 0; i < clip.warpMarkers.size(); ++i)
                if (! (i == 0 && clip.warpMarkers[i].beat == 0) && std::abs (beatX (clip.warpMarkers[i].beat) - x) <= 5) return (int) i;
            return -1;
        }
        // Double-clicking the warped waveform adds a marker where it is, on the transient there if
        // one is close, or removes the marker there.
        void mouseDoubleClick (const juce::MouseEvent& e) override
        {
            if (envelope.active() || ! markersEditable() || ! waveBounds().contains (e.getPosition())) return;
            auto markers = clip.warpMarkers;
            if (const auto hit = markerAt (e.position.x); hit >= 0) markers.erase (markers.begin() + hit);
            else
            {
                const auto transient = transientAt (e.position.x);
                const auto beat = transient ? beatAtSource (*transient) : xBeat (e.position.x);
                if (beat <= 0) return;
                Session::WarpMarker added { transient ? *transient : sourceAt (beat), beat };
                if (added.sourceSeconds <= 0 || added.sourceSeconds >= clip.sourceLength) return;
                markers.insert (std::lower_bound (markers.begin(), markers.end(), added, [] (const auto& a, const auto& b) { return a.beat < b.beat; }), added);
            }
            owner.report (owner.session.setAudioClipWarpMarkers (clip.id, markers)); owner.refresh(); sync();
        }
        // The warp commands, after the reference's sample display menu: Warp From Here (Straight) at
        // the clicked point, and Warp as a loop of the bars its length suggests.
        int loopBarsGuess() const
        {
            const auto seconds = clip.sourceLength > 0 ? std::min (clip.sourceLength, clip.lengthBeats * 60 / std::max (1.0, clip.warp.bpm)) : 0.0;
            const auto beats = Session::estimateClipTempo (seconds) * seconds / 60;
            return juce::jmax (1, juce::roundToInt (beats / std::max (1.0, owner.state.timeSignature.beatsPerBar())));
        }
        void warpCommand (int item, double sourceSeconds)
        {
            if (item == 1) owner.report (owner.session.warpFromHere (clip.id, sourceSeconds), "Warped from here.");
            else if (item == 2) owner.report (owner.session.warpAsLoop (clip.id, loopBarsGuess()));
            owner.refresh(); sync();
        }
        void showWarpMenu (float x)
        {
            const auto at = sourceAt (xBeat (x));
            juce::PopupMenu menu;
            menu.addItem (1, "Warp From Here (Straight)", markersEditable());
            const int bars = loopBarsGuess();
            menu.addItem (2, "Warp as " + juce::String (bars) + "-Bar Loop");
            auto safe = juce::Component::SafePointer<AudioClipView> (this);
            menu.showMenuAsync (juce::PopupMenu::Options().withTargetComponent (this).withMousePosition(),
                                [safe, at] (int chosen) { if (safe != nullptr && chosen > 0) safe->warpCommand (chosen, at); });
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            if (e.mods.isPopupMenu() && clip.warp.mode != Session::WarpMode::off && waveBounds().contains (e.getPosition())) { showWarpMenu (e.position.x); return; }
            // With an envelope shown, the waveform edits it instead of the warp markers.
            if (envelope.active() && waveBounds().contains (e.getPosition()))
            {
                const auto [first, length] = envelopeBeats();
                envelope.mouseDown (e, envelopeArea(), clip, [this] (double b) { return envelopeX (b); }, [this] (float x) { return envelopeBeat (x); }, first + length);
                editingEnvelope = true; repaint(); return;
            }
            // The loop brace along the top and the start marker along the bottom drag, as in the note editor.
            if (clip.canLoop && (braceDrag = braceAt (e.position)) != 0)
            {
                // The view follows the loop as it changes, so the drag keeps the scale it began with.
                braceOrigin = clip.loop; startOrigin = clip.contentStartBeat; braceDownX = e.position.x; draggedMarker = -1;
                braceBeatsPerPixel = visibleBeats().second / std::max (1.0f, (float) waveBounds().getWidth());
                return;
            }
            draggedMarker = markersEditable() && waveBounds().contains (e.getPosition()) ? markerAt (e.position.x) : -1;
            if (draggedMarker >= 0) { owner.session.beginEditGesture ("Move warp marker"); gesture = true; repaint(); }
        }
        // The clip's own grid at the view's zoom and width, as the note editor's is.
        GridPlace gridPlace() const
        {
            const auto [first, beats] = visibleBeats();
            const auto width = juce::jmax (1, waveBounds().getWidth());
            const auto* clip = owner.selectedAudioClip();
            return { clip != nullptr ? clip->id : juce::String(), width / std::max (1e-9, beats), beats, width };
        }
        double snapGrid() const { return owner.gridBeatsAt (gridPlace()); }
        bool snapsMarkers (juce::ModifierKeys mods) const { return owner.gridAt (gridPlace()).snap != bypassesGrid (mods); }
        // Dragging a marker moves its beat between its neighbours, snapped to the grid unless the bypass modifier is held.
        void mouseDrag (const juce::MouseEvent& e) override
        {
            if (editingEnvelope)
            {
                const auto [first, length] = envelopeBeats();
                envelope.mouseDrag (e, envelopeArea(), [this] (float x) { return envelopeBeat (x); }, first + length);
                repaint(); return;
            }
            if (braceDrag != 0)
            {
                const auto delta = (e.position.x - braceDownX) * braceBeatsPerPixel;
                const auto snap = [&] (double beat) { return ! snapsMarkers (e.mods) ? beat : std::round (beat / snapGrid()) * snapGrid(); };
                const double shortest = ! snapsMarkers (e.mods) ? 1.0 / 64 : snapGrid(), audioEnd = sourceBeats (clip);
                auto loop = braceOrigin;
                auto start = startOrigin;
                if (braceDrag == 1)
                {
                    const auto end = braceOrigin.start + braceOrigin.length;
                    loop.start = juce::jlimit (0.0, end - shortest, snap (braceOrigin.start + delta)); loop.length = end - loop.start;
                }
                else if (braceDrag == 2) loop.length = juce::jlimit (shortest, audioEnd - loop.start, snap (braceOrigin.start + braceOrigin.length + delta) - loop.start);
                else if (braceDrag == 3)
                {
                    loop.start = juce::jlimit (0.0, std::max (0.0, audioEnd - loop.length), snap (braceOrigin.start + delta));
                    start = startOrigin + loop.start - braceOrigin.start;
                }
                else start = juce::jlimit (0.0, audioEnd - 1.0 / 64, snap (startOrigin + delta));
                if (loop.on) start = juce::jlimit (loop.start, loop.start + loop.length - 1.0 / 1024, start);
                if (loop == clip.loop && std::abs (start - clip.contentStartBeat) < 1e-9) return;
                if (! gesture) { owner.session.beginEditGesture (braceDrag == 4 ? "Move clip start" : "Move clip loop"); gesture = true; }
                owner.report (owner.session.setClipLoop (clip.id, loop, start)); owner.refresh(); sync();
                return;
            }
            if (draggedMarker < 0 || draggedMarker >= (int) clip.warpMarkers.size()) return;
            auto markers = clip.warpMarkers;
            auto beat = xBeat (e.position.x);
            if (snapsMarkers (e.mods)) { const auto grid = snapGrid(); beat = std::round (beat / grid) * grid; }
            const auto gap = std::min (1.0 / 64, snapGrid() / 4);
            const auto low = draggedMarker > 0 ? markers[(size_t) draggedMarker - 1].beat + gap : gap;
            const auto high = draggedMarker + 1 < (int) markers.size() ? markers[(size_t) draggedMarker + 1].beat - gap : 1e6;
            markers[(size_t) draggedMarker].beat = std::clamp (beat, low, std::max (low, high));
            if (markers == clip.warpMarkers) return;
            owner.report (owner.session.setAudioClipWarpMarkers (clip.id, markers)); owner.refresh(); sync();
        }
        void mouseUp (const juce::MouseEvent&) override
        {
            if (editingEnvelope) { editingEnvelope = false; envelope.mouseUp (clip); repaint(); return; }
            if (gesture) { owner.session.endEditGesture(); gesture = false; }
            draggedMarker = -1; braceDrag = 0; repaint();
        }
        // The clip's content beats over the waveform, where its envelopes' points lie: from its
        // offset into the content, for its length.
        std::pair<double, double> envelopeBeats() const
        {
            const auto first = owner.beatsAt (clip.start) - owner.beatsAt (std::max (0.0, clip.start - clip.sourceOffset));
            return { first, std::max (1e-6, owner.beatsAt (clip.start + clip.length) - owner.beatsAt (clip.start)) };
        }
        juce::Rectangle<float> envelopeArea() const { return waveBounds().reduced (0, 6).toFloat(); }
        float envelopeX (double beat) const
        {
            const auto [first, length] = envelopeBeats(); const auto area = envelopeArea();
            return area.getX() + (float) ((beat - first) / length) * area.getWidth();
        }
        double envelopeBeat (float x) const
        {
            const auto [first, length] = envelopeBeats(); const auto area = envelopeArea();
            return first + (x - area.getX()) / std::max (1.0f, area.getWidth()) * length;
        }
        EnvelopeEditor envelope { owner };
        juce::ComboBox envelopeChoice;
    private:
        int draggedMarker = -1;
        // A drag of the loop brace (1 its start, 2 its end, 3 all of it) or the start marker (4).
        int braceDrag = 0;
        Session::ClipLoop braceOrigin;
        double startOrigin = 0;
        float braceDownX = 0;
        double braceBeatsPerPixel = 0;
        int braceAt (juce::Point<float> p) const
        {
            const auto wave = waveBounds().toFloat();
            if (! wave.contains (p)) return 0;
            if (std::abs (p.x - beatX (clip.contentStartBeat)) <= 6 && p.y >= wave.getBottom() - 12) return 4;
            if (! clip.loop.on || p.y > wave.getY() + 8) return 0;
            const auto from = beatX (clip.loop.start), to = beatX (clip.loop.start + clip.loop.length);
            if (std::abs (p.x - from) <= 4) return 1;
            if (std::abs (p.x - to) <= 4) return 2;
            return p.x > from && p.x < to ? 3 : 0;
        }
        bool editingEnvelope = false;
        static constexpr int envelopeChoiceBase = 1000;
        std::vector<EnvelopeChoice> envelopeList;
        juce::StringArray envelopeSignature;
    };

    class PianoRoll final : public juce::Component, private juce::ScrollBar::Listener
    {
    public:
        explicit PianoRoll (Impl& o) : owner (o)
        {
            setName ("Piano roll editor");
            setWantsKeyboardFocus (true);
            for (auto* c : std::initializer_list<juce::Component*> { &gridButton, &noteLength, &velocity, &noteTools, &laneChoice, &laneView, &foldButton, &scaleButton, &scaleRoot, &scaleMode, &horizontal, &vertical, &previewSwitch }) addAndMakeVisible (c);
            foldButton.setName ("Fold"); foldButton.setClickingTogglesState (true); foldButton.setTooltip ("Fold: show only the rows with notes  |  F");
            foldButton.setColour (juce::TextButton::buttonOnColourId, orange); foldButton.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            foldButton.setWantsKeyboardFocus (false); foldButton.setMouseClickGrabsKeyboardFocus (false);
            foldButton.onClick = [this] { owner.setFold (foldButton.getToggleState(), owner.foldToScale); };
            previewSwitch.setTooltip ("Preview: hear notes as you click the keys, add, select and move them; with the track armed, step record held keys with the arrow keys");
            previewSwitch.onClick = [this] { silence(); owner.session.setNotePreview (previewSwitch.getToggleState()); };
            scaleButton.setName ("Scale"); scaleButton.setClickingTogglesState (true); scaleButton.setTooltip ("Scale: highlight this clip's scale in the note editor");
            scaleButton.setColour (juce::TextButton::buttonOnColourId, orange); scaleButton.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            scaleButton.setWantsKeyboardFocus (false); scaleButton.setMouseClickGrabsKeyboardFocus (false);
            scaleRoot.setName ("Scale root"); scaleMode.setName ("Scale mode");
            for (int r = 0; r < 12; ++r) scaleRoot.addItem (pitchName (r).dropLastCharacters (2), r + 1);
            for (int m = 0; m < Session::scaleModeCount; ++m) scaleMode.addItem (Session::scaleModeName (m), m + 1);
            scaleButton.onClick = [this] { editScale(); };
            scaleRoot.onChange = [this] { editScale(); };
            scaleMode.onChange = [this] { editScale(); };
            laneChoice.setName ("Lane"); laneChoice.setTooltip ("The lane under the notes: velocities or a MIDI controller. Draw points with the mouse; double-click or right-click a point to delete it.");
            laneChoice.onChange = [this]
            {
                const auto id = laneChoice.getSelectedId();
                laneView.setVisible (id != hiddenLane);
                laneView.envelope.choice.reset(); laneView.expression.reset();
                if (juce::isPositiveAndBelow (id - envelopeChoiceBase, (int) envelopeChoices.size())) laneView.envelope.choice = envelopeChoices[(size_t) (id - envelopeChoiceBase)];
                else if (id >= expressionChoice && id < expressionChoice + 3) laneView.expression = static_cast<Session::NoteExpression> (id - expressionChoice);
                else if (id != hiddenLane) laneView.lane = laneForChoice (id);
                resized(); repaint();
            };
            refreshLaneChoices (nullptr);
            // The clip's own grid, shown and chosen as the Arrangement's is.
            gridButton.setName ("Note grid");
           #if JUCE_MAC
            gridButton.setTooltip ("The clip's editing grid; click for its settings. Cmd+1 to 5 change it; hold Cmd while dragging to bypass snapping.");
           #else
            gridButton.setTooltip ("The clip's editing grid; click for its settings. Ctrl+1 to 5 change it; hold Alt while dragging to bypass snapping.");
           #endif
            gridButton.onClick = [this]
            {
                juce::PopupMenu menu; const auto place = gridPlace(); owner.addGridItems (menu, place);
                auto safe = juce::Component::SafePointer<Impl> (&owner);
                menu.showMenuAsync (juce::PopupMenu::Options().withTargetComponent (&gridButton), [safe, place] (int choice) { if (safe != nullptr) safe->gridItem (choice, place); });
            };
            noteLength.addItem ("1/16", 1); noteLength.addItem ("1/8", 2); noteLength.addItem ("1/4", 3); noteLength.addItem ("1/2", 4); noteLength.addItem ("1 bar", 5);
            noteLength.setName ("New note length");
            noteLength.getProperties().set ("readWhenUsed", true); // Set Fixed Length reads it (defaultLength).
            noteLength.setSelectedId (3); noteLength.setTooltip ("The length Transform > Set Fixed Length gives the notes");
            velocity.setName ("Note velocity");
            velocity.setSliderStyle (juce::Slider::LinearHorizontal);
            velocity.setRange (0.01, 1.0, 0.01); velocity.setValue (0.8);
            velocity.setTextBoxStyle (juce::Slider::TextBoxRight, false, 44, 23);
            velocity.textFromValueFunction = [] (double value) { return juce::String ((int) std::round (value * 100.0)) + "%"; };
            velocity.valueFromTextFunction = [] (const juce::String& text) { return text.getDoubleValue() / 100.0; };
            velocity.updateText();
            velocity.setTooltip ("Set velocity for all selected notes, or for the next note you draw");
            velocity.onDragStart = [this] { endGesture(); owner.session.beginEditGesture ("Note velocity"); gesture = true; };
            velocity.onDragEnd = [this] { endGesture(); };
            velocity.onValueChange = [this]
            {
                drawVelocity = (float) velocity.getValue();
                if (const auto* clip = owner.currentMidiClip())
                {
                    auto notes = selectedNotes();
                    for (auto& note : notes) note.velocity = drawVelocity;
                    updateNotes (clip->id, notes, "Note velocity");
                }
            };
            noteTools.setName ("Note tools"); noteTools.setTooltip ("Transform selected notes, or all clip notes when none are selected. Cmd/Ctrl+U quantizes starts.");
            noteTools.onClick = [this] { showNoteMenu(); };
            horizontal.addListener (this); vertical.addListener (this);
        }
        ~PianoRoll() override
        {
            endGesture(); horizontal.removeListener (this); vertical.removeListener (this);
        }
        void sync()
        {
            const auto* clip = owner.currentMidiClip();
            auto id = clip == nullptr ? juce::String() : clip->id;
            if (id != loadedClip)
            {
                endGesture(); loadedClip = id; clearSelection(); originalNotes.clear(); marquee = false; viewBeat = 0; insertionBeat = 0; timeRange.reset();
                if (clip != nullptr && ! clip->notes.empty())
                {
                    int high = 60; for (const auto& note : clip->notes) high = juce::jmax (high, note.pitch);
                    topPitch = juce::jlimit (36, 127, high + 10);
                }
                else topPitch = 77;
                fit();
            }
            if (! gesture) updateRows();
            std::unordered_set<juce::String> liveIds;
            if (clip != nullptr)
            {
                insertionBeat = juce::jlimit (0.0, contentEndBeat (*clip), insertionBeat);
                liveIds.reserve (clip->notes.size());
                for (const auto& note : clip->notes) liveIds.insert (note.id);
            }
            std::erase_if (selectedNoteIds, [&] (const auto& noteId) { return ! liveIds.contains (noteId); });
            std::erase_if (originalNotes, [&] (const auto& note) { return ! selectedNoteIds.contains (note.id); });
            if (! selectedNoteIds.contains (selectedNoteId))
            {
                selectedNoteId.clear();
                if (clip != nullptr) for (const auto& note : clip->notes)
                    if (selectedNoteIds.contains (note.id)) { selectedNoteId = note.id; break; }
            }
            if (const auto* note = selectedNote()) { drawVelocity = note->velocity; velocity.setValue (note->velocity, juce::dontSendNotification); }
            const bool active = clip != nullptr;
            previewSwitch.setToggleState (owner.session.notePreview(), juce::dontSendNotification);
            gridButton.setEnabled (active); updateGridButton(); noteLength.setEnabled (active); velocity.setEnabled (active); noteTools.setEnabled (active); laneChoice.setEnabled (active);
            refreshLaneChoices (clip);
            const auto scale = clip != nullptr ? clip->scale : Session::ScaleSettings {};
            scaleButton.setToggleState (scale.enabled, juce::dontSendNotification);
            scaleRoot.setSelectedId (scale.root + 1, juce::dontSendNotification); scaleMode.setSelectedId (scale.mode + 1, juce::dontSendNotification);
            for (auto* c : std::initializer_list<juce::Component*> { &scaleButton, &scaleRoot, &scaleMode }) c->setEnabled (active);
            updateScroll(); repaint(); laneView.repaint();
        }
        void zoom (double factor)
        {
            pixelsPerBeat = juce::jlimit (12.0, 240.0, pixelsPerBeat * factor);
            updateScroll(); updateGridButton(); repaint();
        }
        void fit()
        {
            const auto* clip = owner.currentMidiClip();
            viewBeat = 0;
            // Fits the edited clip and the shown clips after it.
            auto length = clip != nullptr ? contentEndBeat (*clip) : 16.0;
            if (clip != nullptr) for (const auto* other : owner.extraMidiClips()) length = juce::jmax (length, other->startBeat - clip->startBeat + other->lengthBeats);
            pixelsPerBeat = juce::jlimit (12.0, 240.0, gridBounds().getWidth() / juce::jmax (4.0, length));
            updateScroll(); updateGridButton(); repaint();
        }
        void resized() override
        {
            // The header flows left to right. A narrower editor (beside the Groove and Launch boxes)
            // shortens the clip name, then the widest controls.
            const int tier = getWidth() >= 1216 ? 0 : getWidth() >= 940 ? 1 : 2;
            const int velocityWidth = std::array { 142, 104, 80 }[(size_t) tier], laneWidth = std::array { 116, 100, 90 }[(size_t) tier];
            const int modeWidth = std::array { 132, 108, 96 }[(size_t) tier], toolsWidth = std::array { 100, 88, 76 }[(size_t) tier];
            const int fixed = 7 + 34 + 66 + 8 + 48 + 76 + 12 + 56 + velocityWidth + 12 + toolsWidth + 12 + 32 + laneWidth + 10 + 44 + 50 + 54 + modeWidth;
            nameWidth = juce::jlimit (0, 225, getWidth() - 24 - fixed);
            if (nameWidth < 40) nameWidth = 0;
            int x = nameWidth > 0 ? 12 + nameWidth + 7 : 8;
            labelX[0] = x; x += 34; gridButton.setBounds (x, 7, 66, 23); x += 66 + 8; updateGridButton();
            labelX[1] = x; x += 48; noteLength.setBounds (x, 7, 76, 23); x += 76 + 12;
            labelX[2] = x; x += 56; velocity.setBounds (x, 5, velocityWidth, 27); x += velocityWidth + 12;
            noteTools.setBounds (x, 7, toolsWidth, 23); x += toolsWidth + 12;
            labelX[3] = x; x += 32; laneChoice.setBounds (x, 7, laneWidth, 23); x += laneWidth + 10;
            foldButton.setBounds (x, 7, 40, 23); x += 44;
            scaleButton.setBounds (x, 7, 48, 23); x += 50; scaleRoot.setBounds (x, 7, 52, 23); x += 54; scaleMode.setBounds (x, 7, modeWidth, 23);
            infoX = x + modeWidth + 6;
            if (laneView.isVisible()) laneView.setBounds (0, getHeight() - scrollSize - laneHeight, getWidth() - scrollSize, laneHeight);
            horizontal.setBounds (keysWidth, getHeight() - scrollSize, getWidth() - keysWidth - scrollSize, scrollSize);
            vertical.setBounds (getWidth() - scrollSize, gridTop, scrollSize, gridBounds().getHeight());
            previewSwitch.setBounds (4, headerHeight + 3, keysWidth - 8, rulerHeight - 6); // Above the keys, as the reference's.
            updateScroll();
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (background);
            g.setColour (panel); g.fillRect (0, 0, getWidth(), headerHeight);
            g.setColour (ink); g.setFont (font (11.5f, true));
            const auto* clip = owner.currentMidiClip();
            if (nameWidth > 0) g.drawText (clip == nullptr ? "SELECT A MIDI CLIP" : clip->name, 12, 0, nameWidth, headerHeight, juce::Justification::centredLeft, true);
            g.setColour (muted); g.setFont (font (10.0f));
            g.drawText ("Grid", labelX[0], 0, 32, headerHeight, juce::Justification::centredLeft);
            g.drawText ("Length", labelX[1], 0, 45, headerHeight, juce::Justification::centredLeft);
            g.drawText ("Velocity", labelX[2], 0, 52, headerHeight, juce::Justification::centredLeft);
            g.drawText ("Lane", labelX[3], 0, 30, headerHeight, juce::Justification::centredLeft);
            g.drawText ((typedVelocity.isNotEmpty() ? "Velocity " + typedVelocity + "_  |  " : juce::String())
                        + (selectedNoteIds.empty() ? juce::String() : juce::String ((int) selectedNoteIds.size()) + " selected  |  ")
                        + "Insert " + juce::String (insertionBeat + 1, 2), infoX, 0, juce::jmax (0, getWidth() - infoX - 14), headerHeight, juce::Justification::centredRight);
            if (clip == nullptr)
            {
                g.setColour (muted); g.setFont (font (14.0f));
                const auto message = owner.showSession
                    ? "Select a MIDI slot in Session.\nDouble-click an empty MIDI slot or use + MIDI Clip to start writing notes."
                    : "Create a MIDI track to start writing notes.\nDouble-click a MIDI clip in Arrangement to edit it here.";
                g.drawFittedText (message, getLocalBounds().withTrimmedTop (headerHeight).reduced (35), juce::Justification::centred, 3);
                return;
            }
            const auto grid = gridBounds();
            g.saveState(); g.reduceClipRegion (0, gridTop, getWidth() - scrollSize, grid.getHeight());
            const auto first = topRow();
            for (int row = 0; row <= grid.getHeight() / rowHeight && first + row < (int) rows.size(); ++row)
            {
                const int pitch = rows[(size_t) (first + row)];
                const int semitone = pitch % 12;
                const bool black = semitone == 1 || semitone == 3 || semitone == 6 || semitone == 8 || semitone == 10;
                const int y = gridTop + row * rowHeight;
                // A clip's scale marks its keys; Scale Highlighting also lights its rows (the root most)
                // and dims the rest, and marks the root's key more strongly, as the reference's does.
                const bool scaled = clip->scale.enabled, member = scaled && Session::inScale (clip->scale, pitch), root = member && semitone == clip->scale.root;
                const bool lit = scaled && owner.scaleHighlighting;
                g.setColour (lit ? (member ? (root ? themes::colour (0xff474038) : themes::colour (0xff3c3c3c)) : themes::colour (0xff272727))
                                 : black ? themes::colour (0xff2a2a2a) : themes::colour (0xff353535));
                g.fillRect (keysWidth, y, grid.getWidth(), rowHeight);
                g.setColour (black ? themes::colour (0xff232323) : themes::colour (0xffc6c6c6));
                g.fillRect (0, y, black ? keysWidth - 14 : keysWidth, rowHeight);
                if (member) { g.setColour (orange.withAlpha (lit && root ? 1.0f : .6f)); g.fillRect (keysWidth - 5, y + 1, lit && root ? 5 : 3, rowHeight - 2); }
                g.setColour (line); g.drawHorizontalLine (y + rowHeight - 1, 0.0f, (float) getWidth());
                if (semitone == 0)
                {
                    g.setColour (themes::colour (0xff344149)); g.setFont (font (9.5f, true));
                    g.drawText (pitchName (pitch), 7, y, 32, rowHeight, juce::Justification::centredLeft); // C3 is note 60, as on the notes.
                }
            }
            if (timeRange)
            {
                const auto from = (float) (keysWidth + (timeRange->first - viewBeat) * pixelsPerBeat), to = (float) (keysWidth + (timeRange->second - viewBeat) * pixelsPerBeat);
                g.setColour (orange.withAlpha (0.10f)); g.fillRect (juce::Rectangle<float>::leftTopRightBottom (from, (float) gridTop, to, (float) grid.getBottom()));
            }
            for (double beat = std::floor (viewBeat / snapBeats()) * snapBeats(); beat <= viewBeat + grid.getWidth() / pixelsPerBeat; beat += snapBeats())
            {
                const auto x = (int) std::round (keysWidth + (beat - viewBeat) * pixelsPerBeat);
                const auto barBeats = owner.state.timeSignature.beatsPerBar();
                const bool bar = std::abs (beat / barBeats - std::round (beat / barBeats)) < 0.001;
                g.setColour (bar ? themes::colour (0xff6e6e6e) : themes::colour (0xff434343));
                g.drawVerticalLine (x, (float) gridTop, (float) grid.getBottom());
            }
            // Content the clip does not play is dimmed: before its start (or loop) and after its end.
            const auto clipEnd = (float) (keysWidth + (contentEndBeat (*clip) - viewBeat) * pixelsPerBeat);
            if (clipEnd < grid.getRight()) { g.setColour (background.withAlpha (0.7f)); g.fillRect (clipEnd, (float) gridTop, grid.getRight() - clipEnd, (float) grid.getHeight()); }
            const auto played = clip->loop.on ? std::min (clip->loop.start, clip->contentStartBeat) : clip->contentStartBeat;
            const auto clipStart = (float) (keysWidth + (played - viewBeat) * pixelsPerBeat);
            if (clipStart > keysWidth) { g.setColour (background.withAlpha (0.7f)); g.fillRect ((float) keysWidth, (float) gridTop, clipStart - keysWidth, (float) grid.getHeight()); }
            g.reduceClipRegion (grid);
            // Other shown clips' notes, dimmed, where they fall against this clip.
            for (const auto* other : owner.extraMidiClips())
            {
                const auto from = (float) (keysWidth + (other->startBeat - clip->startBeat - viewBeat) * pixelsPerBeat);
                g.setColour (themes::colour (0xffffffff).withAlpha (0.035f)); g.fillRect (from, (float) gridTop, (float) (other->lengthBeats * pixelsPerBeat), (float) grid.getHeight());
                for (const auto& note : other->notes)
                {
                    const auto r = ghostBounds (*other, note);
                    g.setColour (themes::colour (0xff5d6e6a).withAlpha (note.active ? 0.75f : 0.35f)); g.fillRect (r);
                    g.setColour (themes::colour (0xff2a3633)); g.drawRect (r, 1.0f);
                }
            }
            for (const auto& note : clip->notes)
            {
                auto r = noteBounds (note);
                const bool selected = selectedNoteIds.contains (note.id);
                const auto noteColour = note.active ? (selected ? orange : themes::colour (0xff8cc4b5)).withAlpha (0.48f + note.velocity * 0.52f)
                                                    : themes::colour (0xff5c5c5c);
                g.setColour (noteColour); g.fillRect (r);
                g.setColour (selected ? (note.active ? ink : orange) : themes::colour (0xff203d36)); g.drawRect (r, 1.0f);
                if (r.getWidth() > 22)
                {
                    g.setColour (note.active ? themes::colour (0xff21342f) : ink); g.setFont (font (9.0f));
                    g.drawText ((note.active ? juce::String() : juce::String("OFF / ")) + pitchName (note.pitch), r.reduced (4, 0), juce::Justification::centredLeft, true);
                }
                if (selected) { g.setColour (ink); g.fillRect (r.getRight() - 4, r.getY() + 3, 2.0f, r.getHeight() - 6); }
                // An MPE note's pitch bend, in semitone rows from its centre.
                if (! note.pitchBend.empty())
                {
                    juce::Path bend;
                    const auto centre = r.getCentreY();
                    const auto at = [&] (double beat) { return (float) (keysWidth + (note.startBeat + beat - viewBeat) * pixelsPerBeat); };
                    bend.startNewSubPath (at (0), centre - note.pitchBend.front().value * rowHeight);
                    for (const auto& point : note.pitchBend) bend.lineTo (at (point.beat), centre - point.value * rowHeight);
                    bend.lineTo (at (note.lengthBeats), centre - note.pitchBend.back().value * rowHeight);
                    g.setColour (themes::colour (0xffffffff).withAlpha (0.8f)); g.strokePath (bend, juce::PathStrokeType (1.5f));
                }
            }
            if (marquee)
            {
                g.setColour (orange.withAlpha (0.13f)); g.fillRect (marqueeBounds);
                g.setColour (orange); g.drawRect (marqueeBounds, 1.0f);
            }
            const auto* launched = owner.editedLauncherSlot();
            const auto into = owner.beatsAt (owner.state.position) - clip->startBeat;
            const auto beatPosition = launched != nullptr ? launched->playPositionBeats : into >= 0 && into <= clip->lengthBeats ? contentBeatAt (*clip, into) : -1.0;
            const auto playhead = (float) (keysWidth + (beatPosition - viewBeat) * pixelsPerBeat);
            if (beatPosition >= 0 && (owner.selectedLauncherClipId.isEmpty() || launched != nullptr)) { g.setColour (ink); g.drawLine (playhead, (float) gridTop, playhead, (float) grid.getBottom(), 1.2f); }
            const auto insertX = (float) (keysWidth + (insertionBeat - viewBeat) * pixelsPerBeat);
            if (insertX >= grid.getX() && insertX <= grid.getRight())
            {
                const float dashes[] { 3, 4 };
                g.setColour (orange.withAlpha (0.65f));
                g.drawDashedLine ({ insertX, (float) gridTop, insertX, (float) grid.getBottom() }, dashes, 2);
            }
            g.restoreState();
            g.setColour (raised); g.fillRect (0, headerHeight, getWidth(), rulerHeight);
            g.setColour (muted); g.setFont (font (10.0f));
            const auto barBeats = owner.state.timeSignature.beatsPerBar();
            for (double beat = std::floor (viewBeat / barBeats) * barBeats; beat <= viewBeat + grid.getWidth() / pixelsPerBeat; beat += barBeats)
                g.drawText (juce::String (juce::roundToInt (beat / barBeats) + 1), (int) (keysWidth + (beat - viewBeat) * pixelsPerBeat) + 4, headerHeight, 45, rulerHeight, juce::Justification::centredLeft);
            g.setColour (line); g.drawHorizontalLine (headerHeight, 0.0f, (float) getWidth());
            // The loop brace across the ruler and the start marker.
            {
                g.saveState(); g.reduceClipRegion (keysWidth, headerHeight, grid.getWidth(), rulerHeight);
                if (clip->loop.on)
                {
                    const auto from = (float) (keysWidth + (clip->loop.start - viewBeat) * pixelsPerBeat), to = (float) (keysWidth + (clip->loop.start + clip->loop.length - viewBeat) * pixelsPerBeat);
                    g.setColour (themes::colour (0xffb4b4b4)); g.fillRect (from, (float) headerHeight + 1, to - from, 4.0f);
                }
                const auto startX = (float) (keysWidth + (clip->contentStartBeat - viewBeat) * pixelsPerBeat);
                juce::Path flag; flag.addTriangle (startX, (float) gridTop - 10, startX + 8, (float) gridTop - 5, startX, (float) gridTop);
                g.setColour (ink); g.fillPath (flag);
                g.restoreState();
            }
            if (insertX >= grid.getX() && insertX <= grid.getRight())
            {
                juce::Path marker;
                marker.addTriangle (insertX - 5, (float) gridTop - 8, insertX + 5, (float) gridTop - 8, insertX, (float) gridTop);
                g.setColour (orange); g.fillPath (marker);
            }
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr) return;
            if (e.x < keysWidth)
            {
                // A key sounds its pitch while held (with Preview on); Shift-clicking one adds its
                // notes to the selection, or takes them out if they all were selected.
                if (e.y < gridTop || e.y >= gridBounds().getBottom() || e.mods.isPopupMenu()) return;
                grabKeyboardFocus(); endGesture();
                keyPitch = pitchAt ((float) e.y);
                if (e.mods.isShiftDown())
                {
                    std::vector<juce::String> ids;
                    for (const auto& note : clip->notes) if (note.pitch == keyPitch) ids.push_back (note.id);
                    const bool all = ! ids.empty() && std::all_of (ids.begin(), ids.end(), [&] (const auto& id) { return selectedNoteIds.contains (id); });
                    for (const auto& id : ids) if (all) selectedNoteIds.erase (id); else selectedNoteIds.insert (id);
                    if (! ids.empty()) sync();
                }
                sound ({ { keyPitch, keyVelocity } });
                return;
            }
            // The loop brace and the start marker drag; the rest of the ruler places the insert marker.
            if (const int grabbed = braceAt (*clip, e.position); grabbed != 0)
            {
                grabKeyboardFocus(); endGesture();
                braceDrag = grabbed; braceOrigin = clip->loop; startOrigin = clip->contentStartBeat; dragOrigin = e.position; dragClipId = clip->id;
                return;
            }
            if (e.y >= headerHeight && e.y < gridTop)
            {
                grabKeyboardFocus(); endGesture(); clearSelection();
                insertionBeat = juce::jlimit (0.0, contentEndBeat (*clip), std::round (beatAt (e.x) / snapBeats()) * snapBeats());
                // Launcher playback has a clip-local clock. Its insertion cursor
                // must not seek unrelated arrangement transport state.
                if (owner.selectedLauncherClipId.isEmpty())
                    owner.session.seek (owner.secondsAt (clip->startBeat + beatsInAt (*clip, juce::jmax (0.0, beatAt (e.x)))));
                owner.refresh(); return;
            }
            if (! gridBounds().contains (e.getPosition())) return;
            grabKeyboardFocus();
            endGesture(); originalNotes.clear(); drawing = false; marquee = false; erasing = false; velocityDrag = copyDrag = false;
            // As in the reference: in Draw Mode a click on a note deletes it and a drag elsewhere draws
            // notes (drawNotes); without it, a double-click adds a note (addNote) or deletes one.
            const bool plain = ! e.mods.isPopupMenu() && ! e.mods.isShiftDown();
            const bool draw = owner.drawMode && plain, second = ! owner.drawMode && plain && e.getNumberOfClicks() >= 2;
            // A note of another shown clip makes that clip the edited one, with the note selected,
            // keeping the view where it was.
            if (std::none_of (clip->notes.begin(), clip->notes.end(), [&] (const auto& n) { return noteBounds (n).contains (e.position); }))
                for (const auto* other : owner.extraMidiClips())
                    for (const auto& note : other->notes)
                        if (ghostBounds (*other, note).contains (e.position))
                        {
                            const auto otherId = other->id, noteId = note.id;
                            const auto shift = other->startBeat - clip->startBeat;
                            owner.focusMidiClip (otherId);
                            viewBeat = juce::jmax (0.0, viewBeat - shift);
                            selectedNoteIds = { noteId }; selectedNoteId = noteId;
                            updateScroll(); repaint(); return;
                        }
            for (auto it = clip->notes.rbegin(); it != clip->notes.rend(); ++it)
                if (noteBounds (*it).contains (e.position))
                {
                    if (draw || second)
                    {
                        // The note goes; in Draw Mode, so do those the drag goes on to cross.
                        owner.session.beginEditGesture ("Delete MIDI notes"); gesture = true;
                        dragClipId = clip->id; erasing = draw; eraseAt (e.position);
                        return;
                    }
                    const auto note = *it;
                    if (e.mods.isShiftDown() && ! e.mods.isPopupMenu())
                    {
                        if (selectedNoteIds.contains (note.id))
                        {
                            selectedNoteIds.erase (note.id); sync(); return;
                        }
                        selectedNoteIds.insert (note.id);
                    }
                    else if (! selectedNoteIds.contains (note.id)) selectOnly (note.id);
                    selectedNoteId = note.id; original = note; originalNotes = selectedNotes();
                    previewDelta = 0; if (! e.mods.isPopupMenu()) sound ({ { note.pitch, note.velocity } });
                    dragOrigin = e.position; dragClipId = clip->id;
                    // As in the reference, Cmd (Alt elsewhere) held at the press makes a vertical drag change
                    // the selected notes' velocity, and Option (Ctrl elsewhere) drags copies of them.
                    velocityDrag = bypassesGrid (e.mods) && ! e.mods.isShiftDown() && ! e.mods.isPopupMenu();
                    copyDrag = ! velocityDrag && copiesOnDrag (e.mods) && ! e.mods.isPopupMenu(); copied = false;
                    resizeNote = ! velocityDrag && e.x >= noteBounds (note).getRight() - 8;
                    if (e.mods.isPopupMenu()) { showNoteMenu(); return; }
                    sync(); return;
                }
            if (e.mods.isShiftDown() && ! e.mods.isPopupMenu())
            {
                // Keep direct drawing on ordinary clicks. Shift-drag adds a box
                // selection; a Shift-click on empty space clears the selection.
                marquee = true; marqueeBase = selectedNoteIds; dragOrigin = e.position;
                dragClipId = clip->id; marqueeBounds = {}; repaint(); return;
            }
            clearSelection();
            if (e.mods.isPopupMenu()) { repaint(); return; }
            if (draw) { drawNotes (e, true); return; }
            if (second) { addNote (*clip, e); return; }
            // A click places the insert marker, and a drag selects the notes it encloses.
            insertionBeat = juce::jlimit (0.0, contentEndBeat (*clip), std::round (beatAt (e.x) / snapBeats()) * snapBeats());
            marquee = true; marqueeBase.clear(); dragOrigin = e.position; dragClipId = clip->id; marqueeBounds = {}; repaint();
        }
        void mouseDrag (const juce::MouseEvent& e) override
        {
            if (keyPitch >= 0)
            {
                // Dragging along the keys plays each one it reaches.
                const auto pitch = pitchAt ((float) juce::jlimit (gridTop, gridBounds().getBottom() - 1, e.y));
                if (pitch != keyPitch) { keyPitch = pitch; sound ({ { pitch, keyVelocity } }); }
                return;
            }
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr || clip->id != dragClipId || e.mods.isPopupMenu() || ! e.mouseWasDraggedSinceMouseDown()) return;
            if (erasing) { eraseAt (e.position); return; }
            if (drawing) { drawNotes (e, false); return; }
            if (braceDrag != 0)
            {
                // Ends resize the loop, its middle moves it with the start, and the start marker moves
                // alone; on the note grid unless Alt is held. The start stays in the loop.
                const auto delta = (e.position.x - dragOrigin.x) / pixelsPerBeat;
                const auto snap = [&] (double beat) { return ! snapsNotes (e.mods) ? beat : std::round (beat / snapBeats()) * snapBeats(); };
                const double shortest = ! snapsNotes (e.mods) ? 1.0 / 64 : snapBeats();
                auto loop = braceOrigin;
                auto start = startOrigin;
                if (braceDrag == 1)
                {
                    const auto end = braceOrigin.start + braceOrigin.length;
                    loop.start = juce::jlimit (0.0, end - shortest, snap (braceOrigin.start + delta)); loop.length = end - loop.start;
                }
                else if (braceDrag == 2) loop.length = std::max (shortest, snap (braceOrigin.start + braceOrigin.length + delta) - loop.start);
                else if (braceDrag == 3) { loop.start = std::max (0.0, snap (braceOrigin.start + delta)); start = startOrigin + loop.start - braceOrigin.start; }
                else start = std::max (0.0, snap (startOrigin + delta));
                if (loop.on) start = juce::jlimit (loop.start, loop.start + loop.length - 1.0 / 1024, start);
                if (loop == clip->loop && std::abs (start - clip->contentStartBeat) < 1e-9) return;
                if (! gesture) { owner.session.beginEditGesture (braceDrag == 4 ? "Move clip start" : "Move clip loop"); gesture = true; }
                owner.report (owner.session.setClipLoop (clip->id, loop, start)); owner.refresh();
                return;
            }
            if (marquee)
            {
                marqueeBounds = juce::Rectangle<float>::leftTopRightBottom (juce::jmin (dragOrigin.x, e.position.x), juce::jmin (dragOrigin.y, e.position.y),
                                                                           juce::jmax (dragOrigin.x, e.position.x), juce::jmax (dragOrigin.y, e.position.y)).getIntersection (gridBounds().toFloat());
                selectedNoteIds = marqueeBase;
                for (const auto& note : clip->notes) if (marqueeBounds.intersects (noteBounds (note))) selectedNoteIds.insert (note.id);
                // The drag selects its timespan too, on the note grid unless snapping is bypassed, as the reference's does.
                const auto snapped = [&] (double beat) { return juce::jlimit (0.0, contentEndBeat (*clip), snapsNotes (e.mods) ? std::round (beat / snapBeats()) * snapBeats() : beat); };
                const auto from = snapped (std::min (beatAt (dragOrigin.x), beatAt (e.position.x))), to = snapped (std::max (beatAt (dragOrigin.x), beatAt (e.position.x)));
                timeRange.reset();
                if (to > from + 1.0e-9) { timeRange = std::pair { from, to }; insertionBeat = from; }
                sync(); return;
            }
            if (originalNotes.empty() || selectedNoteIds.empty()) return;
            if (velocityDrag)
            {
                // One velocity step a pixel, the same change for every selected note.
                if (! gesture) { owner.session.beginEditGesture ("Note velocity"); gesture = true; }
                const auto steps = juce::roundToInt (dragOrigin.y - e.position.y);
                auto notes = originalNotes;
                for (auto& note : notes) note.velocity = (float) juce::jlimit (1, 127, juce::roundToInt (note.velocity * 127.0f) + steps) / 127.0f;
                updateNotes (dragClipId, notes, "Note velocity");
                return;
            }
            if (! gesture) { owner.session.beginEditGesture (copyDrag ? "Copy MIDI notes" : resizeNote ? "Resize MIDI notes" : "Move MIDI notes"); gesture = true; }
            if (copyDrag && ! copied)
            {
                // The copies stay where the notes were, and the selected notes move on.
                copied = true;
                auto copies = originalNotes;
                for (auto& note : copies) note.id.clear();
                juce::StringArray inserted;
                owner.report (owner.session.addMidiNotes (dragClipId, copies, inserted));
            }
            double beatDelta = (e.x - dragOrigin.x) / pixelsPerBeat;
            if (resizeNote)
            {
                auto length = original.lengthBeats + beatDelta;
                if (snapsNotes (e.mods)) length = std::round (length / snapBeats()) * snapBeats();
                // Preserve valid model notes shorter than the mouse resize floor.
                // Every selected note must admit the same length delta.
                double minimum = juce::jmin (0.03125, originalNotes.front().lengthBeats) - originalNotes.front().lengthBeats;
                double maximum = contentEndBeat (*clip) - originalNotes.front().startBeat - originalNotes.front().lengthBeats;
                for (const auto& note : originalNotes)
                {
                    minimum = juce::jmax (minimum, juce::jmin (0.03125, note.lengthBeats) - note.lengthBeats);
                    maximum = juce::jmin (maximum, contentEndBeat (*clip) - note.startBeat - note.lengthBeats);
                }
                if (minimum > maximum || ! std::isfinite (minimum) || ! std::isfinite (maximum)) return;
                const auto lengthDelta = juce::jlimit (minimum, maximum, length - original.lengthBeats);
                auto notes = originalNotes;
                for (auto& note : notes) note.lengthBeats += lengthDelta;
                updateNotes (dragClipId, notes, "Resize MIDI notes");
            }
            else
            {
                if (snapsNotes (e.mods)) beatDelta = std::round ((original.startBeat + beatDelta) / snapBeats()) * snapBeats() - original.startBeat;
                // Rows, not semitones: folded, a note moves to the next row shown.
                const auto rowDelta = (int) std::round ((e.y - dragOrigin.y) / rowHeight);
                const auto pitchDelta = rowIndex[(size_t) original.pitch] < 0 ? -rowDelta : pitchAtRow (rowIndex[(size_t) original.pitch] + rowDelta) - original.pitch;
                moveNotes (dragClipId, originalNotes, beatDelta, pitchDelta);
                if (pitchDelta != previewDelta)
                {
                    // Moved to another pitch, the dragged note sounds there.
                    previewDelta = pitchDelta;
                    if (const auto* moved = selectedNote()) sound ({ { moved->pitch, moved->velocity } });
                }
            }
        }
        void mouseUp (const juce::MouseEvent& e) override
        {
            silence(); keyPitch = -1;
            endGesture(); drawing = false; erasing = false; drawn.clear(); originalNotes.clear(); braceDrag = 0;
            updateRows(); updateScroll(); repaint();
            if (marquee)
            {
                if (! e.mouseWasDraggedSinceMouseDown()) { clearSelection(); timeRange.reset(); }
                marquee = false; sync();
            }
        }
        void mouseMove (const juce::MouseEvent& e) override
        {
            if (owner.drawMode && gridBounds().contains (e.getPosition())) { setMouseCursor (owner.drawCursor); return; }
            const auto* clip = owner.currentMidiClip();
            bool edge = false;
            if (clip != nullptr) for (const auto& note : clip->notes) if (noteBounds (note).contains (e.position) && e.x >= noteBounds (note).getRight() - 8) edge = true;
            setMouseCursor (edge ? juce::MouseCursor::LeftRightResizeCursor : juce::MouseCursor::NormalCursor);
        }
        void mouseWheelMove (const juce::MouseEvent& e, const juce::MouseWheelDetails& details) override
        {
            if (e.mods.isCommandDown()) { zoom (details.deltaY > 0 ? 1.1 : 1.0 / 1.1); return; }
            if (e.mods.isShiftDown() || std::abs (details.deltaX) > std::abs (details.deltaY)) viewBeat = juce::jmax (0.0, viewBeat - (details.deltaX + details.deltaY) * 8.0);
            else topPitch = pitchAtRow (topRow() - (int) std::round (details.deltaY * 20.0));
            updateScroll(); repaint();
        }
        bool keyPressed (const juce::KeyPress& key) override
        {
            // Unhandled text commands (for example Duplicate) can bubble from
            // a slider's editor. A note command must never consume text input.
            for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused != nullptr; focused = focused->getParentComponent())
                if (dynamic_cast<juce::TextEditor*> (focused) != nullptr) return false;
            if (owner.session.isExporting()) return true;
            endGesture(); originalNotes.clear(); drawing = false; marquee = false; erasing = false;
            const auto* clip = owner.currentMidiClip();
            const auto code = key.getKeyCode();
            const auto mods = key.getModifiers();
            // A velocity typed for the selected notes, as in the reference: digits, then Return.
            if (clip != nullptr && hasSelectedNote() && ! mods.isAnyModifierKeyDown() && code >= '0' && code <= '9' && (code != '0' || typedVelocity.isNotEmpty()))
            { if (typedVelocity.length() < 3) typedVelocity << juce::String::charToString ((juce::juce_wchar) code); repaint(); return true; }
            if (typedVelocity.isNotEmpty())
            {
                const auto typed = typedVelocity; typedVelocity.clear(); repaint();
                if (code == juce::KeyPress::returnKey && clip != nullptr) { setSelectedVelocity (juce::jlimit (1, 127, typed.getIntValue())); return true; }
                if (code == juce::KeyPress::escapeKey) return true;
            }
            if (code == juce::KeyPress::escapeKey) { clearSelection(); timeRange.reset(); repaint(); return true; }
            if (clip != nullptr && code == '0' && !key.getModifiers().isAnyModifierKeyDown()) { noteCommand (NoteCommand::toggleActive); return true; }
            if (clip != nullptr && timeRangeKey (key)) return true;
            if (clip != nullptr && editorKey (key)) return true;
            if ((code == juce::KeyPress::rightKey || code == juce::KeyPress::leftKey) && ! key.getModifiers().isAnyModifierKeyDown() && stepRecord (code == juce::KeyPress::rightKey)) return true;
            if (clip != nullptr && key.getModifiers().isCommandDown())
            {
                if ((code == 'E' || code == 'e') && !key.getModifiers().isShiftDown()) { noteCommand (NoteCommand::split); return true; }
                // Cmd+U quantizes with the Quantize tool's settings, and Shift+Cmd+U opens them, as the reference's keys do.
                if (code == 'U' || code == 'u')
                { if (key.getModifiers().isShiftDown()) openNoteTool (Session::NoteTool::quantize); else quantizeNotes(); return true; }
                if (code == 'C' || code == 'c') { noteCommand (NoteCommand::copy); return true; }
                if (code == 'X' || code == 'x') { noteCommand (NoteCommand::cut); return true; }
                if (code == 'V' || code == 'v') { noteCommand (NoteCommand::paste); return true; }
                if (code == 'D' || code == 'd') { noteCommand (NoteCommand::duplicate); return true; }
            }
            if (clip != nullptr && ! hasSelectedNote() && ! key.getModifiers().isCommandDown()
                && (code == juce::KeyPress::leftKey || code == juce::KeyPress::rightKey))
            {
                insertionBeat = juce::jlimit (0.0, contentEndBeat (*clip), insertionBeat + (code == juce::KeyPress::leftKey ? -snapBeats() : snapBeats()));
                revealInsertion(); repaint(); return true;
            }
            if (clip != nullptr && key.getModifiers().isCommandDown() && (code == 'A' || code == 'a')) { noteCommand (NoteCommand::selectAll); return true; }
            if (clip != nullptr && hasSelectedNote() && ! key.getModifiers().isCommandDown() && ! key.getModifiers().isAltDown()
                && (code == juce::KeyPress::leftKey || code == juce::KeyPress::rightKey || code == juce::KeyPress::upKey || code == juce::KeyPress::downKey))
            {
                double beatDelta = 0; int pitchDelta = 0;
                if (code == juce::KeyPress::leftKey) beatDelta = -snapBeats();
                if (code == juce::KeyPress::rightKey) beatDelta = snapBeats();
                if (code == juce::KeyPress::upKey) pitchDelta = key.getModifiers().isShiftDown() ? 12 : 1;
                if (code == juce::KeyPress::downKey) pitchDelta = key.getModifiers().isShiftDown() ? -12 : -1;
                moveNotes (clip->id, selectedNotes(), beatDelta, pitchDelta);
                if (pitchDelta != 0)
                {
                    // Transposed notes sound briefly.
                    std::vector<std::pair<int, float>> moved;
                    for (const auto& note : selectedNotes()) moved.push_back ({ note.pitch, note.velocity });
                    sound (moved, true);
                }
                return true;
            }
            return owner.handleKey (key);
        }
        bool hasSelectedNote() const { return selectedNote() != nullptr; }
        double insertion() const { return insertionBeat; }
        juce::String velocityTyped() const { return typedVelocity; }
        bool isNoteSelected (const juce::String& id) const { return selectedNoteIds.contains (id); }
        std::optional<std::pair<double, double>> selectedTimespan() const { return timeRange; }
        // The commands on the timespan a background drag selected, as the reference's: Cmd+L loops the clip
        // over it, Cmd+E splits the notes at its edges, Shift+Cmd+E splits an Arrangement clip there (or at
        // the insert marker without one), and Cmd+Option+J fits the selected notes into it.
        bool timeRangeKey (const juce::KeyPress& key)
        {
            const auto code = key.getKeyCode();
            const auto mods = key.getModifiers();
            if (! mods.isCommandDown()) return false;
            if ((code == 'L' || code == 'l') && ! mods.isShiftDown() && ! mods.isAltDown() && timeRange) { loopTimeRange(); return true; }
            if ((code == 'E' || code == 'e') && ! mods.isShiftDown() && ! mods.isAltDown() && timeRange) { splitNotesAtRange(); return true; }
            if ((code == 'E' || code == 'e') && mods.isShiftDown() && ! mods.isAltDown()) { owner.splitClipFromWithin(); return true; }
            if ((code == 'J' || code == 'j') && mods.isAltDown() && ! mods.isShiftDown() && timeRange) { fitNotesToRange(); return true; }
            return false;
        }
        void loopTimeRange()
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr || ! timeRange) return;
            auto start = clip->contentStartBeat;
            if (start < timeRange->first || start >= timeRange->second) start = timeRange->first;
            endGesture();
            owner.report (owner.session.setClipLoop (clip->id, { true, timeRange->first, timeRange->second - timeRange->first }, start)); owner.refresh();
        }
        void splitNotesAtRange()
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr || ! timeRange) return;
            const auto clipId = clip->id;
            endGesture();
            owner.session.beginEditGesture ("Split notes");
            for (const auto at : { timeRange->first, timeRange->second })
            {
                juce::StringArray crossing, inserted;
                if (const auto* now = owner.currentMidiClip())
                    for (const auto& note : now->notes)
                        if ((selectedNoteIds.empty() || selectedNoteIds.contains (note.id)) && note.startBeat < at - 1.0e-9 && note.startBeat + note.lengthBeats > at + 1.0e-9) crossing.add (note.id);
                if (crossing.isEmpty()) continue;
                owner.report (owner.session.splitMidiNotes (clipId, crossing, at, inserted)); owner.refresh();
            }
            owner.session.endEditGesture(); owner.refresh();
        }
        void fitNotesToRange()
        {
            const auto* clip = owner.currentMidiClip();
            auto notes = selectedNotes();
            if (clip == nullptr || ! timeRange || notes.empty()) return;
            double first = notes.front().startBeat, last = first;
            for (const auto& n : notes) { first = std::min (first, n.startBeat); last = std::max (last, n.startBeat + n.lengthBeats); }
            if (! (last > first)) return;
            const auto scale = (timeRange->second - timeRange->first) / (last - first);
            for (auto& n : notes) { n.startBeat = timeRange->first + (n.startBeat - first) * scale; n.lengthBeats = std::max (1.0 / 64, n.lengthBeats * scale); }
            updateNotes (clip->id, notes, "Fit notes to time range");
        }
        int topShownPitch() const { return pitchAtRow (topRow()); }
        double beatWidth() const { return pixelsPerBeat; }
        // The reference's other note editor keys (its shortcut list's MIDI Note Editor section): Cmd with Up
        // and Down nudges the selected notes' velocity, with Shift their velocity range and with Option
        // their chance; Option with Up and Down selects the previous or next note, and with Left and Right
        // the previous or next on the same key; Home and End take the insert marker to the content's ends;
        // Page Up and Down scroll a page (a row with Shift, sideways with Cmd); W fits the clip's width;
        // Z zooms to the selected notes and X back; Cmd+J joins the selected notes on each key.
        bool editorKey (const juce::KeyPress& key)
        {
            const auto* clip = owner.currentMidiClip();
            const auto code = key.getKeyCode();
            const auto mods = key.getModifiers();
            const bool vertical = code == juce::KeyPress::upKey || code == juce::KeyPress::downKey, up = code == juce::KeyPress::upKey;
            // The computer MIDI keyboard's own keys play it instead, as in the reference.
            if (owner.session.isComputerKeyboardEnabled() && ! mods.isCommandDown() && ! mods.isAltDown() && ComputerKeyboard::handles (key.getTextCharacter())) return false;
            if (mods.isCommandDown() && vertical && hasSelectedNote())
            {
                if (mods.isAltDown()) nudgeChance (up ? .01f : -.01f);
                else if (mods.isShiftDown()) nudgeVelocityRange (up ? 1 : -1);
                else
                {
                    auto notes = selectedNotes();
                    for (auto& note : notes) note.velocity = (float) juce::jlimit (1, 127, juce::roundToInt (note.velocity * 127.0f) + (up ? 1 : -1)) / 127.0f;
                    updateNotes (clip->id, notes, "Note velocity");
                }
                return true;
            }
            if (mods.isAltDown() && ! mods.isCommandDown() && ! mods.isShiftDown()
                && (vertical || code == juce::KeyPress::leftKey || code == juce::KeyPress::rightKey) && ! clip->notes.empty())
            {
                selectNeighbour (vertical, vertical ? ! up : code == juce::KeyPress::rightKey); return true;
            }
            if (! mods.isAnyModifierKeyDown() && (code == juce::KeyPress::homeKey || code == juce::KeyPress::endKey))
            { insertionBeat = code == juce::KeyPress::homeKey ? 0.0 : contentEndBeat (*clip); revealInsertion(); repaint(); return true; }
            if (code == juce::KeyPress::pageUpKey || code == juce::KeyPress::pageDownKey)
            {
                const auto sign = code == juce::KeyPress::pageUpKey ? -1 : 1;
                if (mods.isCommandDown()) { viewBeat = juce::jmax (0.0, viewBeat + sign * gridBounds().getWidth() / pixelsPerBeat); if (owner.state.playing) owner.setFollow (false); }
                else topPitch = pitchAtRow (topRow() + sign * (mods.isShiftDown() ? 1 : juce::jmax (1, gridBounds().getHeight() / rowHeight)));
                updateScroll(); repaint(); return true;
            }
            if (! mods.isAnyModifierKeyDown() && (code == 'W' || code == 'w')) { fit(); return true; }
            if (! mods.isAnyModifierKeyDown() && (code == 'Z' || code == 'z')) { zoomToNotes(); return true; }
            if (! mods.isAnyModifierKeyDown() && (code == 'X' || code == 'x'))
            { if (zoomBack) { std::tie (viewBeat, pixelsPerBeat, topPitch) = *zoomBack; zoomBack.reset(); updateScroll(); updateGridButton(); repaint(); } return true; }
            if (mods.isCommandDown() && ! mods.isShiftDown() && ! mods.isAltDown() && (code == 'J' || code == 'j')) { joinSelectedNotes(); return true; }
            return false;
        }
        // Edit > Select Loop here: the notes starting inside the clip's loop brace.
        void selectLoopNotes()
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr) return;
            endGesture(); clearSelection();
            for (const auto& note : clip->notes)
                if (note.startBeat >= clip->loop.start - 1.0e-9 && note.startBeat < clip->loop.start + clip->loop.length - 1.0e-9) { selectedNoteIds.insert (note.id); selectedNoteId = note.id; }
            sync();
        }
        // View's Fold to Notes and Fold to Scale, and Options' Scale Highlighting, changed.
        void foldChanged() { foldButton.setToggleState (owner.foldToNotes, juce::dontSendNotification); updateRows(); updateScroll(); repaint(); }
        int shownRows() const { return (int) rows.size(); }
        bool canPasteNotes() const { return owner.currentMidiClip() != nullptr && ! noteClipboard.empty(); }
        int selectedNoteCount() const { return (int) selectedNotes().size(); }
        // Whether every selected note is deactivated, for Edit's Activate Notes.
        bool selectionInactive() const
        {
            const auto notes = selectedNotes();
            return ! notes.empty() && std::all_of (notes.begin(), notes.end(), [] (const Session::MidiNoteInfo& n) { return ! n.active; });
        }
        // The menu bar's Edit commands on the notes, which its keys also give.
        enum class NoteCommand { cut, copy, paste, duplicate, remove, split, toggleActive, selectAll, invertSelection, quantize };
        void noteCommand (NoteCommand command)
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr) return;
            endGesture(); originalNotes.clear(); drawing = false; marquee = false; erasing = false;
            switch (command)
            {
                case NoteCommand::cut: copySelectedNotes (true); break;
                case NoteCommand::copy: copySelectedNotes (false); break;
                case NoteCommand::paste: insertNotes (noteClipboard, insertionBeat, false); break;
                case NoteCommand::duplicate:
                    if (const auto notes = selectedNotes(); ! notes.empty())
                        insertNotes (normalisedNotes (notes), std::ceil ((noteExtent (notes).second - 1.0e-9) / snapBeats()) * snapBeats(), true);
                    break;
                case NoteCommand::remove: deleteSelectedNote(); break;
                case NoteCommand::split: splitNotesAtMarker(); break;
                case NoteCommand::toggleActive: toggleSelectedNotes(); break;
                case NoteCommand::selectAll: for (const auto& note : clip->notes) selectedNoteIds.insert (note.id); sync(); break;
                case NoteCommand::invertSelection:
                    for (const auto& note : clip->notes) if (! selectedNoteIds.erase (note.id)) selectedNoteIds.insert (note.id);
                    sync(); break;
                case NoteCommand::quantize: quantizeNotes(); break;
            }
        }
        void deleteSelectedNote()
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr) return;
            const auto clipId = clip->id;
            const auto notes = selectedNotes();
            if (notes.empty()) return;
            endGesture();
            juce::StringArray ids; for (const auto& note : notes) ids.add (note.id);
            const auto result = owner.session.removeMidiNotes (clipId, ids);
            owner.report (result);
            if (result.wasOk()) clearSelection();
            owner.refresh();
        }
    private:
        Impl& owner;
        static constexpr int headerHeight = 37, rulerHeight = 23, gridTop = headerHeight + rulerHeight, keysWidth = 55, rowHeight = 15, scrollSize = 11;
        // The Preview switch, drawn as headphones, lit when on.
        struct PreviewSwitch final : juce::Button
        {
            PreviewSwitch() : juce::Button ("Preview") { setClickingTogglesState (true); setWantsKeyboardFocus (false); setMouseClickGrabsKeyboardFocus (false); }
            void paintButton (juce::Graphics& g, bool over, bool) override
            {
                const auto r = getLocalBounds().toFloat().reduced (.5f);
                const bool on = getToggleState();
                g.setColour (on ? orange : over ? themes::colour (0xff4a4a4a) : themes::colour (0xff363636)); g.fillRoundedRectangle (r, 2.0f);
                g.setColour (on ? themes::colour (0xff1a1a1a) : themes::colour (0xffb4b4b4));
                const auto c = r.getCentre(); const auto w = juce::jmin (r.getWidth(), r.getHeight()) * .62f;
                juce::Path band; band.addCentredArc (c.x, c.y + w * .12f, w * .5f, w * .5f, 0, -juce::MathConstants<float>::halfPi, juce::MathConstants<float>::halfPi, true);
                g.strokePath (band, juce::PathStrokeType (1.4f));
                g.fillRoundedRectangle (c.x - w * .5f - 1.3f, c.y + w * .08f, 2.8f, w * .46f, 1.0f);
                g.fillRoundedRectangle (c.x + w * .5f - 1.5f, c.y + w * .08f, 2.8f, w * .46f, 1.0f);
            }
        } previewSwitch;
        // With Preview on, the notes it is sounding on the clip's track until released (at most 8).
        static constexpr float keyVelocity = 100.0f / 127;
        int keyPitch = -1, previewDelta = 0;
        std::vector<int> sounding; juce::String soundingTrack;
        juce::TimedCallback previewRelease { [this] { silence(); } };
        void sound (const std::vector<std::pair<int, float>>& notes, bool briefly = false)
        {
            silence();
            const auto* track = owner.currentTrack();
            if (! owner.session.notePreview() || track == nullptr || ! track->isMidi) return;
            soundingTrack = track->id;
            for (const auto& [pitch, level] : notes)
                if (sounding.size() < 8 && owner.session.previewNote (soundingTrack, pitch, level, true).wasOk()) sounding.push_back (pitch);
            if (briefly && ! sounding.empty()) previewRelease.startTimer (200);
        }
        void silence()
        {
            previewRelease.stopTimer();
            for (const auto pitch : sounding) owner.session.previewNote (soundingTrack, pitch, 0, false);
            sounding.clear();
        }
        // A ruler drag of the loop brace (1 its start, 2 its end, 3 all of it) or the start marker (4).
        int braceDrag = 0;
        Session::ClipLoop braceOrigin;
        double startOrigin = 0;
        int braceAt (const Session::ClipInfo& clip, juce::Point<float> p) const
        {
            if (p.y < headerHeight || p.y >= gridTop) return 0;
            const auto at = [this] (double beat) { return (float) (keysWidth + (beat - viewBeat) * pixelsPerBeat); };
            if (std::abs (p.x - at (clip.contentStartBeat)) <= 5 && p.y >= gridTop - 11) return 4;
            if (! clip.loop.on || p.y > headerHeight + 8) return 0;
            const auto from = at (clip.loop.start), to = at (clip.loop.start + clip.loop.length);
            if (std::abs (p.x - from) <= 4) return 1;
            if (std::abs (p.x - to) <= 4) return 2;
            return p.x > from && p.x < to ? 3 : 0;
        }
    // The lane under the notes: note velocities as bars, or one controller lane as steps.
    // Edits preview locally and commit on release as one undo step.
    class LaneView final : public juce::Component
    {
    public:
        explicit LaneView (PianoRoll& r) : envelope (r.owner), roll (r)
        {
            setName ("Controller lane");
            envelope.gridStep = [this] { return roll.snapBeats(); };
            envelope.snaps = [this] (juce::ModifierKeys mods) { return roll.snapsNotes (mods); };
        }
        // A clip envelope when one is chosen; otherwise the lane below.
        EnvelopeEditor envelope;
        // MPE: the selected note's own pitch bend, slide or pressure when one is chosen.
        std::optional<Session::NoteExpression> expression;
        // -1 shows velocities and chanceLane note chances; otherwise a controller number or
        // Session::pitchBendLane / channelPressureLane.
        int lane = -1;
        static constexpr int chanceLane = -2;
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff262626));
            g.setColour (line); g.drawHorizontalLine (0, 0.0f, (float) getWidth());
            g.setColour (raised); g.fillRect (0, 1, keysWidth, getHeight() - 1);
            g.setColour (muted); g.setFont (font (9.5f, true));
            g.drawFittedText ((envelope.active() ? envelope.label() : expression ? expressionName (*expression) : laneName (lane)).toUpperCase(),
                              juce::Rectangle<int> (4, 4, keysWidth - 6, getHeight() - 8), juce::Justification::topLeft, 3);
            const auto* clip = roll.owner.currentMidiClip();
            if (clip == nullptr) return;
            const auto area = plot();
            g.saveState(); g.reduceClipRegion (area.withTrimmedTop (-4));
            for (double beat = std::floor (roll.viewBeat); beat <= roll.viewBeat + area.getWidth() / roll.pixelsPerBeat; beat += 1)
            {
                g.setColour (std::fmod (beat, 4.0) == 0 ? themes::colour (0xff4e4e4e) : themes::colour (0xff353535));
                g.drawVerticalLine ((int) x (beat), (float) area.getY(), (float) area.getBottom());
            }
            if (expression) paintExpression (g, area.toFloat());
            else if (envelope.active()) envelope.paint (g, area.toFloat(), *clip, [this] (double b) { return x (b); }, contentEndBeat (*clip));
            else if (lane == Session::pitchBendLane) { g.setColour (themes::colour (0xff3d3d3d)); g.drawHorizontalLine ((int) y (0), (float) area.getX(), (float) area.getRight()); }
            if (envelope.active() || expression) {}
            else if (lane < 0)
            {
                for (const auto& note : notes())
                {
                    const bool selected = roll.selectedNoteIds.contains (note.id);
                    const auto top = y (noteValue (note)), at = x (note.startBeat);
                    const auto colour = (selected ? orange : themes::colour (0xff8cc4b5)).withAlpha (note.active ? 1.0f : .35f);
                    // A velocity range shows as a lighter bar beside the velocity, reaching the range's end.
                    if (lane == -1 && note.velocityRange != 0)
                    {
                        const auto reach = y (juce::jlimit (1, 127, noteValue (note) + note.velocityRange));
                        g.setColour (colour.withMultipliedAlpha (.45f)); g.fillRect (at + 2.0f, juce::jmin (top, reach), 3.0f, std::abs (reach - top));
                    }
                    g.setColour (colour);
                    g.fillRect (at, top, 2.0f, (float) area.getBottom() - top);
                    g.fillEllipse (at - 2.5f, top - 2.5f, 6, 6);
                }
            }
            else
            {
                const auto points = this->points();
                const auto end = x (contentEndBeat (*clip));
                juce::Path steps;
                for (size_t i = 0; i < points.size(); ++i)
                {
                    const auto from = x (points[i].beat), to = i + 1 < points.size() ? x (points[i + 1].beat) : end;
                    const auto level = y (points[i].value);
                    if (i == 0) steps.startNewSubPath (from, level); else steps.lineTo (from, level);
                    steps.lineTo (to, level);
                }
                g.setColour (orange); g.strokePath (steps, juce::PathStrokeType (1.5f));
                for (size_t i = 0; i < points.size(); ++i)
                {
                    g.setColour ((int) i == dragged ? ink : orange);
                    g.fillRect (x (points[i].beat) - 3, y (points[i].value) - 3, 6.0f, 6.0f);
                }
            }
            g.restoreState();
            g.setColour (background.withAlpha (.7f));
            if (const auto end = x (contentEndBeat (*clip)); end < area.getRight()) g.fillRect (end, (float) area.getY(), area.getRight() - end, (float) area.getHeight());
        }
        void mouseDown (const juce::MouseEvent& e) override
        {
            const auto* clip = roll.owner.currentMidiClip();
            dragged = -1; velocityNote.clear(); preview.reset(); previewNotes.clear(); drawing = false; sketching = false;
            if (clip == nullptr || e.x < keysWidth) return;
            clipId = clip->id;
            if (expression) { expressionDown (e); repaint(); return; }
            if (envelope.active())
            {
                envelope.mouseDown (e, plot().toFloat(), *clip, [this] (double b) { return x (b); }, [this] (float px) { return beatAt (px); }, contentEndBeat (*clip));
                repaint(); return;
            }
            if (lane < 0 && roll.owner.drawMode && ! e.mods.isPopupMenu())
            {
                previewNotes = clip->notes; sketching = true; lastSketch.reset();
                sketchStart = { beatAt (e.position.x), valueAt (e.position.y) };
                sketchValues (e); return;
            }
            if (lane < 0)
            {
                // The nearest velocity bar within reach; selected notes follow it together.
                double best = 6;
                for (const auto& note : clip->notes)
                    if (const auto distance = std::abs (x (note.startBeat) - e.position.x); distance < best) { best = distance; velocityNote = note.id; }
                if (velocityNote.isEmpty()) return;
                // Cmd-dragging a velocity sets the note's velocity range instead, as in the reference.
                rangeDrag = lane == -1 && e.mods.isCommandDown();
                previewNotes = clip->notes; dragVelocity (e); return;
            }
            auto points = this->points();
            const int hit = pointAt (points, e.position);
            if (hit >= 0 && (e.mods.isPopupMenu() || e.getNumberOfClicks() > 1))
            {
                points.erase (points.begin() + hit); commit (points); return;
            }
            if (e.mods.isPopupMenu()) return;
            preview = points;
            if (hit >= 0) dragged = hit;
            else { drawing = true; paintPoint (e); }
            repaint();
        }
        void mouseDrag (const juce::MouseEvent& e) override
        {
            if (expression) { expressionDrag (e); repaint(); return; }
            if (envelope.active())
            {
                if (const auto* clip = roll.owner.currentMidiClip()) envelope.mouseDrag (e, plot().toFloat(), [this] (float px) { return beatAt (px); }, contentEndBeat (*clip));
                repaint(); return;
            }
            if (lane < 0) { if (sketching) sketchValues (e); else if (velocityNote.isNotEmpty()) dragVelocity (e); return; }
            if (! preview) return;
            if (drawing) { paintPoint (e); repaint(); return; }
            if (dragged < 0) return;
            auto& points = *preview;
            const auto* clip = roll.owner.currentMidiClip();
            const double low = dragged > 0 ? points[(size_t) dragged - 1].beat + 1.0 / 960 : 0;
            const double high = (size_t) dragged + 1 < points.size() ? points[(size_t) dragged + 1].beat - 1.0 / 960 : (clip ? contentEndBeat (*clip) : 0);
            points[(size_t) dragged] = { juce::jlimit (low, juce::jmax (low, high), snapped (beatAt (e.position.x), e.mods)), valueAt (e.position.y) };
            repaint();
        }
        void mouseUp (const juce::MouseEvent&) override
        {
            if (expression) { expressionUp(); repaint(); return; }
            if (envelope.active())
            {
                if (const auto* clip = roll.owner.currentMidiClip()) envelope.mouseUp (*clip);
                repaint(); return;
            }
            if (lane < 0 && sketching)
            {
                // The drawn values, one undo step.
                sketching = false;
                std::vector<Session::MidiNoteInfo> changed;
                if (const auto* clip = roll.owner.currentMidiClip(); clip != nullptr && clip->id == clipId)
                    for (const auto& note : previewNotes)
                        for (const auto& old : clip->notes)
                            if (old.id == note.id && (old.velocity != note.velocity || old.chance != note.chance)) changed.push_back (note);
                previewNotes.clear();
                if (changed.empty()) { repaint(); return; }
                if (lane == chanceLane)
                {
                    std::map<float, juce::StringArray> byChance;
                    for (const auto& note : changed) byChance[note.chance].add (note.id);
                    roll.owner.session.beginEditGesture ("Draw note chances");
                    for (const auto& [chance, ids] : byChance) roll.owner.report (roll.owner.session.setMidiNotesChance (clipId, ids, chance));
                    roll.owner.session.endEditGesture();
                    roll.owner.refresh();
                }
                else roll.updateNotes (clipId, changed, "Draw velocities");
                repaint(); return;
            }
            if (lane < 0)
            {
                if (velocityNote.isNotEmpty() && ! previewNotes.empty())
                {
                    std::vector<Session::MidiNoteInfo> changed;
                    juce::StringArray ids;
                    const bool group = roll.selectedNoteIds.contains (velocityNote);
                    for (const auto& note : previewNotes)
                        if (note.id == velocityNote || (group && roll.selectedNoteIds.contains (note.id))) { changed.push_back (note); ids.add (note.id); }
                    const auto dragged = std::find_if (previewNotes.begin(), previewNotes.end(), [this] (const auto& n) { return n.id == velocityNote; });
                    if (lane == chanceLane) roll.owner.report (roll.owner.session.setMidiNotesChance (clipId, ids, dragged->chance));
                    else if (rangeDrag) roll.owner.report (roll.owner.session.setMidiNotesVelocityRange (clipId, ids, dragged->velocityRange));
                    else roll.updateNotes (clipId, changed, "Note velocity");
                    roll.owner.refresh();
                }
                velocityNote.clear(); previewNotes.clear(); return;
            }
            if (preview) { auto points = *preview; preview.reset(); dragged = -1; drawing = false; commit (points); }
        }
        static juce::String laneName (int lane)
        {
            if (lane == chanceLane) return "Chance";
            if (lane < 0) return "Velocity";
            if (lane == Session::pitchBendLane) return "Pitch Bend";
            if (lane == Session::channelPressureLane) return "Pressure";
            if (lane == 1) return "Mod Wheel";
            if (lane == 7) return "Volume";
            if (lane == 10) return "Pan";
            if (lane == 11) return "Expression";
            if (lane == 64) return "Sustain";
            return "CC " + juce::String (lane);
        }
        static juce::String expressionName (Session::NoteExpression kind)
        { return kind == Session::NoteExpression::pitchBend ? "Note Pitch Bend" : kind == Session::NoteExpression::slide ? "Note Slide" : "Note Pressure"; }
    private:
        PianoRoll& roll;
        juce::String clipId, velocityNote;
        bool rangeDrag = false;
        // Draw Mode in the velocity and chance lanes, as the reference's: each grid step the pointer
        // passes gives its value to the notes starting in it, the selected ones when there are any.
        // Cmd (Alt elsewhere), or snapping off, sets just the notes under the pointer; Option (Alt
        // elsewhere) draws a straight line from the press, and Shift with it keeps the line level.
        bool sketching = false;
        std::pair<double, int> sketchStart;
        std::optional<std::pair<double, int>> lastSketch;
        void sketchValues (const juce::MouseEvent& e)
        {
            const auto* clip = roll.owner.currentMidiClip();
            if (clip == nullptr || clip->id != clipId) return;
            const auto beat = beatAt (e.position.x);
            const int value = valueAt (e.position.y);
            const bool chosen = std::any_of (clip->notes.begin(), clip->notes.end(), [this] (const auto& n) { return roll.selectedNoteIds.contains (n.id); });
            const auto takes = [&] (const Session::MidiNoteInfo& n) { return ! chosen || roll.selectedNoteIds.contains (n.id); };
            const auto set = [this] (Session::MidiNoteInfo& n, int v)
            { if (lane == chanceLane) n.chance = (float) juce::jlimit (0, 100, v) / 100.0f; else n.velocity = (float) juce::jlimit (1, 127, v) / 127.0f; };
            if (e.mods.isAltDown())
            {
                previewNotes = clip->notes;
                const auto [b0, v0] = sketchStart;
                const auto low = std::min (b0, beat), high = std::max (b0, beat);
                for (auto& n : previewNotes)
                    if (takes (n) && n.startBeat >= low - 1.0e-9 && n.startBeat <= high + 1.0e-9)
                        set (n, e.mods.isShiftDown() || high - low < 1.0e-9 ? v0 : juce::roundToInt (v0 + (value - v0) * (n.startBeat - b0) / (beat - b0)));
                repaint(); return;
            }
            const auto from = lastSketch.value_or (std::pair { beat, value });
            lastSketch = { beat, value };
            if (const auto step = roll.snapBeats(); step > 0 && roll.snapsNotes (e.mods))
            {
                const auto first = (long long) std::floor (from.first / step + 1.0e-9), last = (long long) std::floor (beat / step + 1.0e-9);
                const auto count = std::llabs (last - first);
                for (long long i = 0; i <= count && i < 4096; ++i)
                {
                    const auto cell = (double) (first + (last >= first ? i : -i));
                    const int v = count == 0 ? value : juce::roundToInt (from.second + (value - from.second) * (double) i / (double) count);
                    for (auto& n : previewNotes)
                        if (takes (n) && n.startBeat >= cell * step - 1.0e-9 && n.startBeat < (cell + 1) * step - 1.0e-9) set (n, v);
                }
            }
            else
            {
                const auto low = std::min (x (from.first), e.position.x) - 3, high = std::max (x (from.first), e.position.x) + 3;
                for (auto& n : previewNotes) if (takes (n) && x (n.startBeat) >= low && x (n.startBeat) <= high) set (n, value);
            }
            repaint();
        }
        // Note expression editing: points at beats from the note's start, bend -48 to 48 semitones,
        // slide and pressure 0-1, ramping between points.
        std::optional<std::vector<Session::ExpressionPoint>> expressionPreview;
        juce::String expressionNote;
        int expressionDragged = -1;
        float expressionPosition (float value) const { return *expression == Session::NoteExpression::pitchBend ? (value + 48) / 96 : value; }
        float expressionAt (float py) const
        {
            const auto a = plot().toFloat();
            const auto p = juce::jlimit (0.0f, 1.0f, (a.getBottom() - py) / a.getHeight());
            return *expression == Session::NoteExpression::pitchBend ? std::round ((p * 96 - 48) * 100) / 100 : p;
        }
        float expressionY (float value) const { const auto a = plot().toFloat(); return a.getBottom() - expressionPosition (value) * a.getHeight(); }
        std::vector<Session::ExpressionPoint> expressionPoints (const Session::MidiNoteInfo& note) const
        {
            if (expressionPreview && expressionNote == note.id) return *expressionPreview;
            return *expression == Session::NoteExpression::pitchBend ? note.pitchBend : *expression == Session::NoteExpression::slide ? note.slide : note.pressure;
        }
        void paintExpression (juce::Graphics& g, juce::Rectangle<float> area) const
        {
            const auto* note = roll.selectedNote();
            g.setColour (muted); g.setFont (font (10.0f));
            if (note == nullptr) { g.drawText ("Select a note to edit its expression", area, juce::Justification::centred); return; }
            const auto from = x (note->startBeat), to = x (note->startBeat + note->lengthBeats);
            g.setColour (themes::colour (0xffffffff).withAlpha (0.05f)); g.fillRect (juce::Rectangle<float> (from, area.getY(), to - from, area.getHeight()));
            const auto neutral = *expression == Session::NoteExpression::slide ? .5f : 0.0f;
            g.setColour (themes::colour (0x40ffffff)); g.drawHorizontalLine ((int) expressionY (neutral), from, to);
            const auto points = expressionPoints (*note);
            if (points.empty()) return;
            juce::Path curve;
            curve.startNewSubPath (from, expressionY (points.front().value));
            for (const auto& point : points) curve.lineTo (x (note->startBeat + point.beat), expressionY (point.value));
            curve.lineTo (to, expressionY (points.back().value));
            g.setColour (orange); g.strokePath (curve, juce::PathStrokeType (1.5f));
            for (size_t i = 0; i < points.size(); ++i)
            {
                g.setColour ((int) i == expressionDragged ? ink : orange);
                g.fillEllipse (x (note->startBeat + points[i].beat) - 3.5f, expressionY (points[i].value) - 3.5f, 7, 7);
            }
        }
        void expressionDown (const juce::MouseEvent& e)
        {
            expressionDragged = -1; expressionPreview.reset();
            const auto* note = roll.selectedNote();
            if (note == nullptr) return;
            expressionNote = note->id;
            auto points = expressionPoints (*note);
            int hit = -1;
            for (int i = (int) points.size(); --i >= 0;)
                if (std::abs (x (note->startBeat + points[(size_t) i].beat) - e.position.x) <= 5 && std::abs (expressionY (points[(size_t) i].value) - e.position.y) <= 6) { hit = i; break; }
            if (hit >= 0 && (e.mods.isPopupMenu() || e.getNumberOfClicks() > 1)) { points.erase (points.begin() + hit); commitExpression (points); return; }
            if (e.mods.isPopupMenu()) return;
            if (hit < 0)
            {
                const Session::ExpressionPoint point { juce::jlimit (0.0, note->lengthBeats, beatAt (e.position.x) - note->startBeat), expressionAt (e.position.y) };
                const auto at = std::lower_bound (points.begin(), points.end(), point.beat, [] (const auto& p, double b) { return p.beat < b; });
                if (at != points.end() && std::abs (at->beat - point.beat) < 1e-6) return;
                hit = (int) (at - points.begin()); points.insert (at, point);
            }
            expressionPreview = points; expressionDragged = hit;
        }
        void expressionDrag (const juce::MouseEvent& e)
        {
            const auto* note = roll.selectedNote();
            if (! expressionPreview || expressionDragged < 0 || note == nullptr || note->id != expressionNote) return;
            auto& points = *expressionPreview;
            const double low = expressionDragged > 0 ? points[(size_t) expressionDragged - 1].beat + 1.0 / 960 : 0;
            const double high = (size_t) expressionDragged + 1 < points.size() ? points[(size_t) expressionDragged + 1].beat - 1.0 / 960 : note->lengthBeats;
            points[(size_t) expressionDragged] = { juce::jlimit (low, juce::jmax (low, high), beatAt (e.position.x) - note->startBeat), expressionAt (e.position.y) };
        }
        void expressionUp()
        {
            if (expressionPreview) { auto points = *expressionPreview; expressionPreview.reset(); expressionDragged = -1; commitExpression (points); }
        }
        void commitExpression (const std::vector<Session::ExpressionPoint>& points)
        {
            if (const auto* clip = roll.owner.currentMidiClip())
                roll.owner.report (roll.owner.session.setMidiNoteExpression (clip->id, expressionNote, *expression, points));
            roll.owner.refresh(); roll.repaint();
        }
        std::optional<std::vector<Session::ControllerPoint>> preview;
        std::vector<Session::MidiNoteInfo> previewNotes;
        int dragged = -1;
        bool drawing = false;
        juce::Rectangle<int> plot() const { return { keysWidth, 6, juce::jmax (1, getWidth() - keysWidth), juce::jmax (1, getHeight() - 10) }; }
        int low() const { return lane == Session::pitchBendLane ? -8192 : lane == chanceLane ? 0 : lane < 0 ? 1 : 0; }
        int high() const { return lane == Session::pitchBendLane ? 8191 : lane == chanceLane ? 100 : 127; }
        // A note's bar in a note lane: its velocity, or its chance in percent.
        int noteValue (const Session::MidiNoteInfo& note) const
        { return lane == chanceLane ? juce::roundToInt (note.chance * 100) : juce::roundToInt (note.velocity * 127); }
        float x (double beat) const { return (float) (keysWidth + (beat - roll.viewBeat) * roll.pixelsPerBeat); }
        float y (int value) const { const auto a = plot(); return (float) a.getBottom() - (float) (value - low()) / (float) (high() - low()) * (float) a.getHeight(); }
        double beatAt (float px) const { return roll.viewBeat + (px - keysWidth) / roll.pixelsPerBeat; }
        int valueAt (float py) const { const auto a = plot(); return juce::jlimit (low(), high(), low() + juce::roundToInt ((a.getBottom() - py) / (float) a.getHeight() * (float) (high() - low()))); }
        double snapped (double beat, juce::ModifierKeys mods) const
        {
            const auto* clip = roll.owner.currentMidiClip();
            const auto grid = roll.snapBeats();
            return juce::jlimit (0.0, clip ? contentEndBeat (*clip) : 0.0, ! roll.snapsNotes (mods) ? beat : std::round (beat / grid) * grid);
        }
        std::vector<Session::MidiNoteInfo> notes() const
        {
            if (! previewNotes.empty()) return previewNotes;
            if (const auto* clip = roll.owner.currentMidiClip()) return clip->notes;
            return {};
        }
        std::vector<Session::ControllerPoint> points() const
        {
            if (preview) return *preview;
            if (const auto* clip = roll.owner.currentMidiClip())
                for (const auto& l : clip->controllers) if (l.controller == lane) return l.points;
            return {};
        }
        int pointAt (const std::vector<Session::ControllerPoint>& points, juce::Point<float> p) const
        {
            for (int i = (int) points.size(); --i >= 0;)
                if (std::abs (x (points[(size_t) i].beat) - p.x) <= 5 && std::abs (y (points[(size_t) i].value) - p.y) <= 6) return i;
            return -1;
        }
        // Drawing sets the point on the grid step under the pointer, replacing one already there.
        void paintPoint (const juce::MouseEvent& e)
        {
            auto& points = *preview;
            const auto beat = snapped (beatAt (e.position.x), e.mods);
            const Session::ControllerPoint point { beat, valueAt (e.position.y) };
            const auto at = std::lower_bound (points.begin(), points.end(), beat - 1e-9, [] (const auto& p, double b) { return p.beat < b; });
            if (at != points.end() && std::abs (at->beat - beat) < 1e-9) *at = point; else points.insert (at, point);
        }
        void dragVelocity (const juce::MouseEvent& e)
        {
            const int value = valueAt (e.position.y);
            const bool group = roll.selectedNoteIds.contains (velocityNote);
            for (auto& note : previewNotes)
                if (note.id == velocityNote || (group && roll.selectedNoteIds.contains (note.id)))
                {
                    if (lane == chanceLane) note.chance = (float) value / 100.0f;
                    else if (rangeDrag) note.velocityRange = juce::jlimit (-127, 127, value - juce::roundToInt (note.velocity * 127));
                    else note.velocity = juce::jlimit (0.01f, 1.0f, (float) value / 127.0f);
                }
            repaint();
        }
        void commit (const std::vector<Session::ControllerPoint>& points)
        {
            roll.owner.report (roll.owner.session.setMidiControllerLane (clipId, lane, points));
            roll.owner.refresh(); repaint();
        }
    };
        LaneView laneView { *this };
        juce::ComboBox noteLength, laneChoice, scaleRoot, scaleMode;
        juce::TextButton gridButton;
        int nameWidth = 225, infoX = 1210;
        std::array<int, 4> labelX { 244, 352, 488, 810 };
        juce::TextButton noteTools { "Note tools" }, scaleButton { "Scale" }, foldButton { "Fold" };
        void editScale()
        {
            const auto* clip = owner.currentMidiClip(); if (! clip) return;
            owner.report (owner.session.setClipScale (clip->id, { scaleButton.getToggleState(), scaleRoot.getSelectedId() - 1, scaleMode.getSelectedId() - 1 }));
            owner.refresh();
        }
        juce::Slider velocity;
        juce::ScrollBar horizontal { false }, vertical { true };
        juce::String loadedClip, selectedNoteId, dragClipId;
        Session::MidiNoteInfo original;
        std::unordered_set<juce::String> selectedNoteIds, marqueeBase;
        std::vector<Session::MidiNoteInfo> originalNotes, noteClipboard;
        juce::Point<float> dragOrigin;
        juce::Rectangle<float> marqueeBounds;
        double viewBeat = 0, pixelsPerBeat = 60, insertionBeat = 0;
        int topPitch = 77;
        float drawVelocity = 0.8f;
        bool gesture = false, resizeNote = false, drawing = false, marquee = false, erasing = false, pitchLocked = false, velocityDrag = false, copyDrag = false, copied = false;
        juce::String typedVelocity; // Digits typed for the selected notes' velocity, until Return.
        std::optional<std::pair<double, double>> timeRange; // The timespan a background drag selected, in content beats.
        std::optional<std::tuple<double, double, int>> zoomBack; // The view before Z, for X.
        void setSelectedVelocity (int value)
        {
            auto notes = selectedNotes();
            if (notes.empty()) return;
            for (auto& note : notes) note.velocity = (float) value / 127.0f;
            updateNotes (owner.currentMidiClip()->id, notes, "Note velocity");
        }
        // Each selected note's range or chance moved by a step, as one undo step.
        void nudgeVelocityRange (int step)
        {
            const auto clipId = owner.currentMidiClip()->id;
            std::map<int, juce::StringArray> byRange;
            for (const auto& note : selectedNotes()) byRange[juce::jlimit (-127, 127, note.velocityRange + step)].add (note.id);
            owner.session.beginEditGesture ("Velocity range");
            for (const auto& [range, ids] : byRange) owner.report (owner.session.setMidiNotesVelocityRange (clipId, ids, range));
            owner.session.endEditGesture(); owner.refresh();
        }
        void nudgeChance (float step)
        {
            const auto clipId = owner.currentMidiClip()->id;
            std::map<int, juce::StringArray> byChance;
            for (const auto& note : selectedNotes()) byChance[juce::jlimit (0, 100, juce::roundToInt ((note.chance + step) * 100.0f))].add (note.id);
            owner.session.beginEditGesture ("Note chance");
            for (const auto& [chance, ids] : byChance) owner.report (owner.session.setMidiNotesChance (clipId, ids, (float) chance / 100.0f));
            owner.session.endEditGesture(); owner.refresh();
        }
        // The next or previous note in time, or on the selected note's key, selected and shown.
        void selectNeighbour (bool anyKey, bool next)
        {
            const auto* clip = owner.currentMidiClip();
            auto notes = clip->notes;
            const auto* current = selectedNote();
            if (! anyKey && current != nullptr) std::erase_if (notes, [pitch = current->pitch] (const auto& n) { return n.pitch != pitch; });
            std::sort (notes.begin(), notes.end(), [] (const auto& a, const auto& b) { return std::tie (a.startBeat, a.pitch) < std::tie (b.startBeat, b.pitch); });
            if (notes.empty()) return;
            auto at = current == nullptr ? notes.end() : std::find_if (notes.begin(), notes.end(), [current] (const auto& n) { return n.id == current->id; });
            const auto& chosen = at == notes.end() ? (next ? notes.front() : notes.back())
                               : next ? *(std::next (at) == notes.end() ? at : std::next (at)) : *(at == notes.begin() ? at : std::prev (at));
            selectOnly (chosen.id);
            const auto visibleBeats = gridBounds().getWidth() / pixelsPerBeat;
            if (chosen.startBeat < viewBeat || chosen.startBeat > viewBeat + visibleBeats) viewBeat = juce::jmax (0.0, chosen.startBeat - visibleBeats / 4);
            const auto visibleRows = juce::jmax (1, gridBounds().getHeight() / rowHeight);
            if (rowIndex[(size_t) chosen.pitch] >= 0 && (rowIndex[(size_t) chosen.pitch] < topRow() || rowIndex[(size_t) chosen.pitch] >= topRow() + visibleRows))
                topPitch = pitchAtRow (rowIndex[(size_t) chosen.pitch] - visibleRows / 2);
            updateScroll(); sync(); sound ({ { chosen.pitch, chosen.velocity } }, true);
        }
        // Z: the view fits the selected notes, or all of them, as the reference's Zoom to Clip Selection.
        void zoomToNotes()
        {
            const auto* clip = owner.currentMidiClip();
            auto notes = selectedNotes();
            if (notes.empty()) notes = clip->notes;
            if (notes.empty()) return;
            zoomBack = std::tuple { viewBeat, pixelsPerBeat, topPitch };
            double from = notes.front().startBeat, to = from; int high = 0, low = 127;
            for (const auto& n : notes) { from = std::min (from, n.startBeat); to = std::max (to, n.startBeat + n.lengthBeats); high = std::max (high, n.pitch); low = std::min (low, n.pitch); }
            pixelsPerBeat = juce::jlimit (12.0, 240.0, gridBounds().getWidth() / juce::jmax (1.0 / 4, to - from));
            viewBeat = juce::jmax (0.0, from);
            const auto visibleRows = juce::jmax (1, gridBounds().getHeight() / rowHeight);
            if (rowIndex[(size_t) high] >= 0) topPitch = pitchAtRow (rowIndex[(size_t) high] - juce::jmax (0, (visibleRows - (rowIndex[(size_t) low] - rowIndex[(size_t) high] + 1)) / 2));
            updateScroll(); updateGridButton(); repaint();
        }
        // Cmd+J: on each key, the selected notes become one, from the first's start to the last's end.
        void joinSelectedNotes()
        {
            const auto* clip = owner.currentMidiClip();
            std::map<int, std::vector<Session::MidiNoteInfo>> byKey;
            for (const auto& note : selectedNotes()) byKey[note.pitch].push_back (note);
            std::vector<Session::MidiNoteInfo> joined; juce::StringArray gone;
            for (auto& [pitch, notes] : byKey)
            {
                if (notes.size() < 2) continue;
                std::sort (notes.begin(), notes.end(), [] (const auto& a, const auto& b) { return a.startBeat < b.startBeat; });
                auto one = notes.front();
                for (const auto& n : notes) one.lengthBeats = std::max (one.lengthBeats, n.startBeat + n.lengthBeats - one.startBeat);
                joined.push_back (one);
                for (size_t i = 1; i < notes.size(); ++i) gone.add (notes[i].id);
            }
            if (joined.empty()) return;
            const auto clipId = clip->id;
            owner.session.beginEditGesture ("Join notes");
            owner.report (owner.session.removeMidiNotes (clipId, gone));
            owner.report (owner.session.updateMidiNotes (clipId, joined));
            owner.session.endEditGesture(); owner.refresh();
        }
        // Draw Mode's notes in the drag under way, by grid step: the note's id and pitch.
        std::map<int, std::pair<juce::String, int>> drawn;
        int drawFirstStep = 0, drawLastStep = 0, drawPitch = 60;
    public:
        // The clip's grid at the editor's zoom and width.
        GridPlace gridPlace() const
        {
            const auto* clip = owner.currentMidiClip();
            const auto width = juce::jmax (1, gridBounds().getWidth());
            return { clip != nullptr ? clip->id : juce::String(), pixelsPerBeat, width / pixelsPerBeat, width };
        }
        double snapBeats() const { return owner.gridBeatsAt (gridPlace()); }
        bool snapsNotes (juce::ModifierKeys mods) const { return owner.gridAt (gridPlace()).snap != bypassesGrid (mods); }
        void updateGridButton() { gridButton.setButtonText (owner.gridNameAt (gridPlace())); }
    private:
        double defaultLength() const { return std::pow (2.0, noteLength.getSelectedId() - 3); }
        double beatAt (float x) const { return viewBeat + (x - keysWidth) / pixelsPerBeat; }
        int pitchAt (float y) const { return pitchAtRow (topRow() + (int) std::floor ((y - gridTop) / rowHeight)); }
        // The rows shown, top to bottom, and each pitch's row (-1 when folded away): every pitch, or as
        // View's Fold to Notes leaves them the pitches with notes, or as Fold to Scale leaves them the
        // clip scale's pitches and those with notes.
        std::vector<int> rows = [] { std::vector<int> all; for (int pitch = 127; pitch >= 0; --pitch) all.push_back (pitch); return all; }();
        std::array<int, 128> rowIndex = [] { std::array<int, 128> index {}; for (int pitch = 0; pitch < 128; ++pitch) index[(size_t) pitch] = 127 - pitch; return index; }();
        void updateRows()
        {
            const auto* clip = owner.currentMidiClip();
            std::array<bool, 128> used {};
            if (clip != nullptr)
            {
                for (const auto& note : clip->notes) used[(size_t) juce::jlimit (0, 127, note.pitch)] = true;
                for (const auto* other : owner.extraMidiClips()) for (const auto& note : other->notes) used[(size_t) juce::jlimit (0, 127, note.pitch)] = true;
            }
            const bool notes = owner.foldToNotes && std::find (used.begin(), used.end(), true) != used.end();
            const bool scale = ! notes && owner.foldToScale && clip != nullptr && clip->scale.enabled;
            rows.clear(); rowIndex.fill (-1);
            for (int pitch = 127; pitch >= 0; --pitch)
                if ((! notes && ! scale) || used[(size_t) pitch] || (scale && Session::inScale (clip->scale, pitch)))
                { rowIndex[(size_t) pitch] = (int) rows.size(); rows.push_back (pitch); }
        }
        // The top row: the first shown at or below topPitch.
        int topRow() const
        {
            for (int pitch = juce::jlimit (0, 127, topPitch); pitch >= 0; --pitch) if (rowIndex[(size_t) pitch] >= 0) return rowIndex[(size_t) pitch];
            return juce::jmax (0, (int) rows.size() - 1);
        }
        int pitchAtRow (int row) const { return rows.empty() ? 60 : rows[(size_t) juce::jlimit (0, (int) rows.size() - 1, row)]; }
        int rowY (int pitch) const
        {
            const auto row = rowIndex[(size_t) juce::jlimit (0, 127, pitch)];
            return row < 0 ? -100000 : gridTop + (row - topRow()) * rowHeight;
        }
        Session::MidiNoteInfo newNote (int pitch, double start, double length) const { return { {}, pitch, start, length, drawVelocity }; }
        // A double-click's note: one grid step long, on the step and at the pitch clicked, selected, so
        // the drag goes on to move it.
        void addNote (const Session::ClipInfo& clip, const juce::MouseEvent& e)
        {
            const auto grid = snapBeats();
            const auto start = std::floor (beatAt (e.x) / grid) * grid;
            if (start < 0 || start >= contentEndBeat (clip)) return;
            const auto pitch = pitchAt (e.position.y);
            const auto clipId = clip.id;
            juce::StringArray inserted;
            owner.session.beginEditGesture ("Add MIDI note"); gesture = true;
            const auto result = owner.session.addMidiNotes (clipId, { newNote (pitch, start, juce::jmin (grid, contentEndBeat (clip) - start)) }, inserted);
            owner.report (result); owner.refresh();
            if (result.failed() || inserted.isEmpty()) { endGesture(); return; }
            selectOnly (inserted[0]);
            if (const auto* note = selectedNote()) { selectedNoteId = note->id; original = *note; originalNotes = { *note }; }
            dragClipId = clipId; dragOrigin = e.position; resizeNote = false; sync();
            sound ({ { pitch, drawVelocity } });
        }
        // The topmost note under p goes, for a double-click and Draw Mode's eraser.
        void eraseAt (juce::Point<float> p)
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr || clip->id != dragClipId) return;
            for (auto it = clip->notes.rbegin(); it != clip->notes.rend(); ++it)
                if (noteBounds (*it).contains (p))
                {
                    const auto id = it->id;
                    owner.report (owner.session.removeMidiNotes (clip->id, { id })); selectedNoteIds.erase (id);
                    owner.refresh(); repaint(); return;
                }
        }
        // Draw Mode's drawing, after the reference's: a note on each grid step from the first one to the
        // pointer's, at the pitch the pointer had on it, or with Alt all at the first note's pitch. Steps
        // the pointer goes back over lose their notes, and a drawn note replaces those it covers at its pitch.
        void drawNotes (const juce::MouseEvent& e, bool first)
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr) return;
            const auto grid = snapBeats();
            const auto step = (int) std::floor (beatAt (e.position.x) / grid);
            const auto pitch = pitchAt (e.position.y);
            if (first)
            {
                if (step < 0 || step * grid >= contentEndBeat (*clip)) return;
                owner.session.beginEditGesture ("Draw MIDI notes"); gesture = true;
                drawing = true; dragClipId = clip->id; drawn.clear();
                pitchLocked = e.mods.isAltDown(); drawFirstStep = drawLastStep = step; drawPitch = pitch;
            }
            else if (! drawing || clip->id != dragClipId) return;
            const auto clipId = clip->id;
            const auto lo = std::min (drawFirstStep, step), hi = std::max (drawFirstStep, step);
            juce::StringArray gone;
            for (auto it = drawn.begin(); it != drawn.end();)
                if (it->first < lo || it->first > hi) { gone.add (it->second.first); it = drawn.erase (it); }
                else ++it;
            if (! gone.isEmpty()) owner.report (owner.session.removeMidiNotes (clipId, gone));
            // The steps from the last one reached to the pointer's, the pitch moving evenly between them.
            const auto from = drawLastStep;
            const auto fromPitch = drawn.count (from) > 0 ? drawn[from].second : drawPitch;
            const auto count = std::abs (step - from);
            for (int i = 0; i <= count; ++i)
            {
                const auto s = from + (step >= from ? i : -i);
                if (s < lo || s > hi) continue;
                const auto at = pitchLocked ? drawPitch : count == 0 ? pitch : juce::roundToInt (fromPitch + (pitch - fromPitch) * (double) i / count);
                owner.refresh();
                if (const auto* current = owner.currentMidiClip(); current != nullptr && current->id == clipId) drawStep (*current, s, at);
            }
            drawLastStep = step;
            owner.refresh(); repaint();
            if (const auto found = drawn.find (step); found != drawn.end() && found->second.second == pitch) sound ({ { pitch, drawVelocity } }, true);
        }
        void drawStep (const Session::ClipInfo& clip, int step, int pitch)
        {
            const auto grid = snapBeats(), start = step * grid;
            if (start < 0 || start >= contentEndBeat (clip) - 1.0e-9) return;
            const auto length = juce::jmin (grid, contentEndBeat (clip) - start);
            const auto found = drawn.find (step);
            if (found != drawn.end() && found->second.second == pitch) return;
            juce::StringArray replaced;
            if (found != drawn.end()) { replaced.add (found->second.first); drawn.erase (found); }
            for (const auto& note : clip.notes)
                if (note.pitch == pitch && note.startBeat < start + length - 1.0e-9 && note.startBeat + note.lengthBeats > start + 1.0e-9 && ! replaced.contains (note.id)
                    && std::none_of (drawn.begin(), drawn.end(), [&] (const auto& d) { return d.second.first == note.id; }))
                    replaced.add (note.id);
            if (! replaced.isEmpty()) owner.report (owner.session.removeMidiNotes (clip.id, replaced));
            juce::StringArray inserted;
            if (const auto result = owner.session.addMidiNotes (clip.id, { newNote (pitch, start, length) }, inserted); result.wasOk() && inserted.size() == 1)
                drawn[step] = { inserted[0], pitch };
            else owner.report (result);
        }
        juce::Rectangle<int> gridBounds() const
        { return { keysWidth, gridTop, juce::jmax (1, getWidth() - keysWidth - scrollSize), juce::jmax (1, getHeight() - gridTop - scrollSize - (laneView.isVisible() ? laneHeight : 0)) }; }
        static constexpr int laneHeight = 92, hiddenLane = 99;
        // Lane menu: velocity, common controllers, then any other controller the clip uses.
        static constexpr int commonLanes[] { Session::pitchBendLane, 1, 7, 10, 11, 64, Session::channelPressureLane };
        static constexpr int chanceChoice = 97, expressionChoice = 90;
        int laneForChoice (int id) const
        { return id == 1 ? -1 : id == chanceChoice ? LaneView::chanceLane : id >= 2 && id < 2 + (int) std::size (commonLanes) ? commonLanes[id - 2] : id - 100; }
        void refreshLaneChoices (const Session::ClipInfo* clip)
        {
            const auto common = [] (int lane) { return std::find (std::begin (commonLanes), std::end (commonLanes), lane) != std::end (commonLanes); };
            juce::Array<int> others;
            if (clip != nullptr) for (const auto& l : clip->controllers) if (! common (l.controller)) others.add (l.controller);
            const auto* track = owner.currentTrack();
            const auto envelopes = clip != nullptr && track != nullptr ? EnvelopeEditor::choices (owner, *track, owner.selectedLauncherClipId.isNotEmpty()) : std::vector<EnvelopeChoice>();
            juce::StringArray signature;
            for (const auto& c : envelopes) signature.add (c.target.pluginId + "|" + juce::String (c.target.parameter) + "|" + juce::String ((int) c.mode) + "|" + c.device + "|" + c.control);
            if (others == laneOthers && signature == envelopeSignature && laneChoice.getNumItems() > 0) return;
            laneOthers = others; envelopeSignature = signature; envelopeChoices = envelopes;
            auto keep = laneChoice.getSelectedId();
            // A shown envelope stays chosen while its control remains; otherwise the lane shows velocities.
            if (laneView.envelope.choice)
            {
                const auto shown = *laneView.envelope.choice;
                const auto at = std::find_if (envelopes.begin(), envelopes.end(), [&] (const auto& c) { return c.target == shown.target && c.mode == shown.mode; });
                keep = at != envelopes.end() ? envelopeChoiceBase + (int) (at - envelopes.begin()) : 1;
                if (at == envelopes.end()) laneView.envelope.choice.reset();
            }
            laneChoice.clear (juce::dontSendNotification);
            laneChoice.addItem ("Velocity", 1); laneChoice.addItem ("Chance", chanceChoice);
            for (int i = 0; i < (int) std::size (commonLanes); ++i) laneChoice.addItem (LaneView::laneName (commonLanes[i]), 2 + i);
            for (const auto lane : others) laneChoice.addItem (LaneView::laneName (lane), 100 + lane);
            juce::PopupMenu more;
            for (int cc = 0; cc < 120; ++cc) if (! common (cc) && ! others.contains (cc)) more.addItem (100 + cc, "CC " + juce::String (cc));
            laneChoice.getRootMenu()->addSubMenu ("Other controller", more);
            juce::PopupMenu expressions;
            for (int i = 0; i < 3; ++i) expressions.addItem (expressionChoice + i, LaneView::expressionName (static_cast<Session::NoteExpression> (i)));
            laneChoice.getRootMenu()->addSubMenu ("Note Expression (MPE)", expressions);
            // Clip envelopes, by device, for modulation and, on Session clips, automation.
            for (const auto mode : { Session::EnvelopeMode::modulation, Session::EnvelopeMode::automation })
            {
                juce::PopupMenu modeMenu, deviceMenu;
                juce::String device;
                for (size_t i = 0; i < envelopes.size(); ++i)
                {
                    if (envelopes[i].mode != mode) continue;
                    if (envelopes[i].device != device && deviceMenu.getNumItems() > 0) { modeMenu.addSubMenu (device, deviceMenu); deviceMenu = {}; }
                    device = envelopes[i].device;
                    deviceMenu.addItem (envelopeChoiceBase + (int) i, envelopes[i].control);
                }
                if (deviceMenu.getNumItems() > 0) modeMenu.addSubMenu (device, deviceMenu);
                if (modeMenu.getNumItems() > 0)
                    laneChoice.getRootMenu()->addSubMenu (mode == Session::EnvelopeMode::modulation ? "Envelope" : "Envelope automation", modeMenu);
            }
            laneChoice.addSeparator(); laneChoice.addItem ("Hide lane", hiddenLane);
            laneChoice.setSelectedId (keep > 0 && laneChoice.indexOfItemId (keep) >= 0 ? keep : 1, juce::dontSendNotification);
        }
        juce::Array<int> laneOthers;
        static constexpr int envelopeChoiceBase = 1000;
        std::vector<EnvelopeChoice> envelopeChoices;
        juce::StringArray envelopeSignature;
        juce::Rectangle<float> noteBounds (const Session::MidiNoteInfo& note) const
        {
            return { (float) (keysWidth + (note.startBeat - viewBeat) * pixelsPerBeat), (float) (rowY (note.pitch) + 1), (float) juce::jmax (3.0, note.lengthBeats * pixelsPerBeat), (float) rowHeight - 2 };
        }
        static juce::String pitchName (int pitch) { return midimonitor::noteName (pitch); } // C3 is note 60, as in the reference.
        const Session::MidiNoteInfo* selectedNote() const
        {
            if (const auto* clip = owner.currentMidiClip()) for (const auto& note : clip->notes) if (note.id == selectedNoteId) return &note;
            return nullptr;
        }
        void clearSelection() { selectedNoteIds.clear(); selectedNoteId.clear(); }
        void selectOnly (const juce::String& id) { clearSelection(); selectedNoteIds.insert (id); selectedNoteId = id; }
        std::vector<Session::MidiNoteInfo> selectedNotes() const
        {
            std::vector<Session::MidiNoteInfo> notes;
            if (const auto* clip = owner.currentMidiClip())
                for (const auto& note : clip->notes) if (selectedNoteIds.contains (note.id)) notes.push_back (note);
            return notes;
        }
        static std::pair<double, double> noteExtent (const std::vector<Session::MidiNoteInfo>& notes)
        {
            double start = notes.front().startBeat, end = start + notes.front().lengthBeats;
            for (const auto& note : notes) { start = juce::jmin (start, note.startBeat); end = juce::jmax (end, note.startBeat + note.lengthBeats); }
            return { start, end };
        }
        static std::vector<Session::MidiNoteInfo> normalisedNotes (std::vector<Session::MidiNoteInfo> notes)
        {
            if (notes.empty()) return notes;
            const auto start = noteExtent (notes).first;
            for (auto& note : notes) { note.id.clear(); note.startBeat -= start; }
            return notes;
        }
        void copySelectedNotes (bool cut)
        {
            const auto* clip = owner.currentMidiClip();
            const auto notes = selectedNotes();
            if (clip == nullptr || notes.empty()) return;
            const auto start = noteExtent (notes).first;
            auto copied = normalisedNotes (notes);
            if (cut)
            {
                juce::StringArray ids; for (const auto& note : notes) ids.add (note.id);
                const auto result = owner.session.removeMidiNotes (clip->id, ids);
                if (result.failed()) { owner.report (result); owner.refresh(); return; }
                insertionBeat = start; clearSelection();
            }
            noteClipboard = std::move (copied);
            owner.report (juce::Result::ok(), juce::String ((int) noteClipboard.size())
                          + (cut ? " notes cut. " : " notes copied. ") + "Notes clipboard stays inside Halftrack; paste at the orange ruler marker.");
            owner.refresh();
        }
        void insertNotes (const std::vector<Session::MidiNoteInfo>& relativeNotes, double atBeat, bool duplicate)
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr || relativeNotes.empty()) return;
            const auto clipId = clip->id;
            auto notes = relativeNotes;
            for (auto& note : notes) note.startBeat += atBeat;
            juce::StringArray insertedIds;
            // The facade validates the entire group before creating any undo
            // action. A rejected paste must preserve selection, cursor and redo.
            const auto result = owner.session.addMidiNotes (clipId, notes, insertedIds);
            owner.report (result, juce::String ((int) insertedIds.size()) + (duplicate ? " notes duplicated." : " notes pasted."));
            if (result.wasOk())
            {
                clearSelection();
                for (const auto& id : insertedIds) selectedNoteIds.insert (id);
                selectedNoteId = insertedIds.isEmpty() ? juce::String() : insertedIds[0];
                insertionBeat = noteExtent (notes).second;
            }
            owner.refresh();
            if (result.wasOk()) { revealInsertion(); repaint(); }
        }
        void revealInsertion()
        {
            const auto visibleBeats = gridBounds().getWidth() / pixelsPerBeat;
            if (insertionBeat < viewBeat) viewBeat = insertionBeat;
            if (insertionBeat > viewBeat + visibleBeats) viewBeat = insertionBeat - visibleBeats;
            updateScroll();
        }
        void updateNotes (juce::String clipId, const std::vector<Session::MidiNoteInfo>& notes, const juce::String& name)
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr || clip->id != clipId || notes.empty()) return;
            // Snapshot values and stable IDs survive the model changes below.
            // Refresh once after the batch, and leave drag-owned transactions open.
            const bool ownGesture = ! gesture;
            if (ownGesture) owner.session.beginEditGesture (name);
            owner.report (owner.session.updateMidiNotes (clipId, notes));
            if (ownGesture) owner.session.endEditGesture();
            owner.refresh();
        }
        void moveNotes (juce::String clipId, std::vector<Session::MidiNoteInfo> notes, double beatDelta, int pitchDelta)
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr || clip->id != clipId || notes.empty()) return;
            double minimumBeatDelta = -notes.front().startBeat;
            double maximumBeatDelta = contentEndBeat (*clip) - notes.front().startBeat - notes.front().lengthBeats;
            int minimumPitchDelta = -notes.front().pitch, maximumPitchDelta = 127 - notes.front().pitch;
            for (const auto& note : notes)
            {
                minimumBeatDelta = juce::jmax (minimumBeatDelta, -note.startBeat);
                maximumBeatDelta = juce::jmin (maximumBeatDelta, contentEndBeat (*clip) - note.startBeat - note.lengthBeats);
                minimumPitchDelta = juce::jmax (minimumPitchDelta, -note.pitch);
                maximumPitchDelta = juce::jmin (maximumPitchDelta, 127 - note.pitch);
            }
            // Loaded clips may retain offscreen notes. An impossible interval
            // must not turn a group edit into per-note clamping or partial repair.
            if (minimumBeatDelta > maximumBeatDelta || ! std::isfinite (minimumBeatDelta) || ! std::isfinite (maximumBeatDelta)) return;
            beatDelta = juce::jlimit (minimumBeatDelta, maximumBeatDelta, beatDelta);
            pitchDelta = juce::jlimit (minimumPitchDelta, maximumPitchDelta, pitchDelta);
            for (auto& note : notes) { note.startBeat += beatDelta; note.pitch += pitchDelta; }
            updateNotes (clipId, notes, "Move MIDI notes");
        }
        void endGesture() { if (gesture) { owner.session.endEditGesture(); gesture = false; } }
        void updateScroll()
        {
            const auto grid = gridBounds(); const auto* clip = owner.currentMidiClip();
            const auto visibleBeats = grid.getWidth() / pixelsPerBeat;
            const auto totalBeats = juce::jmax (visibleBeats, clip != nullptr ? contentEndBeat (*clip) : 16.0);
            viewBeat = juce::jlimit (0.0, juce::jmax (0.0, totalBeats - visibleBeats), viewBeat);
            horizontal.setRangeLimits (0.0, totalBeats, juce::dontSendNotification); horizontal.setCurrentRange (viewBeat, visibleBeats, juce::dontSendNotification);
            const auto visible = juce::jmax (1, grid.getHeight() / rowHeight);
            const auto top = juce::jlimit (0, juce::jmax (0, (int) rows.size() - visible), topRow());
            topPitch = pitchAtRow (top);
            vertical.setRangeLimits (0.0, (double) rows.size(), juce::dontSendNotification); vertical.setCurrentRange (top, visible, juce::dontSendNotification);
        }
        void scrollBarMoved (juce::ScrollBar* bar, double start) override
        {
            if (bar == &horizontal) { if (owner.state.playing) owner.setFollow (false); viewBeat = start; } else topPitch = pitchAtRow ((int) std::round (start));
            repaint();
        }
    public:
        // Pages the note view to keep the playhead of the edited clip in sight.
        void followPlayhead()
        {
            const auto* clip = owner.currentMidiClip();
            if (clip == nullptr) return;
            const auto* launched = owner.editedLauncherSlot();
            if (owner.selectedLauncherClipId.isNotEmpty() && launched == nullptr) return;
            const auto beat = launched != nullptr ? launched->playPositionBeats : owner.beatsAt (owner.state.position) - clip->startBeat;
            if (beat < 0 || beat > contentEndBeat (*clip)) return;
            const auto visible = gridBounds().getWidth() / pixelsPerBeat;
            const auto next = owner.session.preferences().scrollFollow ? scrolledViewStart (beat, visible) : followedViewStart (beat, viewBeat, visible);
            if (next != viewBeat) { viewBeat = next; updateScroll(); repaint(); }
        }
        double visibleStartBeat() const noexcept { return viewBeat; }
        juce::Rectangle<float> shownNoteBounds (const Session::MidiNoteInfo& note) const { return noteBounds (note); }
        // A note of another shown clip, placed against the edited clip's start.
        juce::Rectangle<float> ghostBounds (const Session::ClipInfo& other, const Session::MidiNoteInfo& note) const
        {
            const auto* clip = owner.currentMidiClip();
            return noteBounds (note).translated ((float) ((clip != nullptr ? other.startBeat - clip->startBeat : 0.0) * pixelsPerBeat), 0);
        }
    private:
    public:
        // A note tool's settings, applied to the selected notes (or every note) each time Apply is pressed.
        class NoteToolPanel final : public juce::Component
        {
        public:
            NoteToolPanel (PianoRoll& r, Session::NoteToolSettings initial) : roll (&r), settings (initial)
            {
                const auto tool = settings.tool;
                setName ("Note tool " + juce::String (notetools::name (tool)));
                const auto fields = notetools::fields (tool);
                for (size_t i = 0; i < fields.size(); ++i)
                {
                    const auto& f = fields[i];
                    auto& label = labels[i]; label.setText (f.label, juce::dontSendNotification); label.setColour (juce::Label::textColourId, ink); addAndMakeVisible (label);
                    if (f.choices)
                    {
                        auto& box = choices[i]; box.setName (f.label); box.addItemList (juce::StringArray::fromTokens (f.choices, "|", ""), 1);
                        box.setSelectedId ((int) settings.values[i] + 1, juce::dontSendNotification);
                        box.onChange = [this, i] { settings.values[i] = choices[i].getSelectedId() - 1; remember(); };
                        addAndMakeVisible (box);
                    }
                    else
                    {
                        auto& slider = sliders[i]; slider.setName (f.label); slider.setSliderStyle (juce::Slider::LinearBar);
                        slider.setRange (f.minimum, f.maximum, f.integer ? 1.0 : 0.0); slider.setValue (settings.values[i], juce::dontSendNotification);
                        slider.setTextValueSuffix (f.unit); slider.setNumDecimalPlacesToDisplay (f.integer ? 0 : 3); slider.updateText();
                        slider.setColour (juce::Slider::trackColourId, themes::colour (0xff59606a)); slider.setColour (juce::Slider::textBoxTextColourId, ink);
                        slider.onValueChange = [this, i] { settings.values[i] = sliders[i].getValue(); remember(); };
                        addAndMakeVisible (slider);
                    }
                }
                rows = (int) fields.size();
                apply.setName ("Apply note tool");
                apply.setButtonText (notetools::generates (tool) ? "Generate" : "Transform");
                apply.onClick = [this] { if (roll != nullptr) roll->applyNoteTool (settings); };
                addAndMakeVisible (apply);
                hint.setText (notetools::generates (tool) ? "Fills the clip, replacing any selected notes." : "Reshapes the selected notes, or every note when none is selected.",
                              juce::dontSendNotification);
                hint.setColour (juce::Label::textColourId, muted); hint.setFont (font (10.5f)); addAndMakeVisible (hint);
            }
            static int heightFor (Session::NoteTool tool) { return 78 + 28 * (int) notetools::fields (tool).size(); }
            void resized() override
            {
                auto area = getLocalBounds().reduced (12, 10);
                for (int i = 0; i < rows; ++i)
                {
                    auto row = area.removeFromTop (28).withTrimmedBottom (4);
                    labels[(size_t) i].setBounds (row.removeFromLeft (90));
                    choices[(size_t) i].setBounds (row); sliders[(size_t) i].setBounds (row);
                }
                area.removeFromTop (6);
                auto buttons = area.removeFromBottom (26);
                apply.setBounds (buttons.removeFromRight (110));
                hint.setBounds (area);
            }
            Session::NoteToolSettings settings;
            juce::TextButton apply;
        private:
            // The tool keeps its settings for the next time, as Edit > Quantize uses Quantize's.
            void remember() { if (roll != nullptr) roll->toolSettings[(int) settings.tool] = settings; }
            juce::Component::SafePointer<PianoRoll> roll;
            std::array<juce::Label, 8> labels;
            std::array<juce::ComboBox, 8> choices;
            std::array<juce::Slider, 8> sliders;
            juce::Label hint;
            int rows = 0;
        };
        // Each tool's settings as last chosen, or its defaults.
        std::map<int, Session::NoteToolSettings> toolSettings;
        Session::NoteToolSettings toolSettingsFor (Session::NoteTool tool) const
        {
            const auto found = toolSettings.find ((int) tool);
            return found != toolSettings.end() ? found->second : notetools::defaults (tool);
        }
        // Edit > Quantize, as the reference's: the Quantize tool's settings, applied to the selected notes or every note.
        void quantizeNotes() { applyNoteTool (toolSettingsFor (Session::NoteTool::quantize)); }
        void openNoteTool (Session::NoteTool tool)
        {
            auto initial = toolSettingsFor (tool);
            // Fit to Scale starts from the clip's own scale.
            if (const auto* clip = owner.currentMidiClip(); clip && tool == Session::NoteTool::fitToScale && clip->scale.enabled)
            { initial.values[0] = clip->scale.root; initial.values[1] = clip->scale.mode; }
            owner.showDialog (juce::String (notetools::name (tool)), std::make_unique<NoteToolPanel> (*this, initial), 340, NoteToolPanel::heightFor (tool));
        }
        void applyNoteTool (const Session::NoteToolSettings& settings)
        {
            const auto* clip = owner.currentMidiClip(); if (! clip) return;
            endGesture();
            const bool generator = notetools::generates (settings.tool);
            juce::StringArray ids;
            for (const auto& note : clip->notes)
                if (selectedNoteIds.empty() ? ! generator : selectedNoteIds.contains (note.id)) ids.add (note.id);
            juce::StringArray created;
            const auto result = owner.session.applyNoteTool (clip->id, ids, settings, created, snapBeats());
            owner.report (result); owner.refresh();
            if (result.wasOk())
            {
                clearSelection();
                for (const auto& id : created) selectedNoteIds.insert (id);
                if (! created.isEmpty()) selectedNoteId = created[0];
            }
            repaint();
        }
    private:
        void transformSelected (Session::NoteTransform operation)
        {
            const auto* clip = owner.currentMidiClip(); if (! clip) return;
            const auto clipId = clip->id;
            auto notes = selectedNotes(); if (notes.empty()) notes = clip->notes;
            juce::StringArray ids; for (const auto& note : notes) ids.add (note.id);
            endGesture();
            owner.report (owner.session.transformMidiNotes (clipId, ids, operation,
                operation == Session::NoteTransform::fixedLength ? defaultLength() : snapBeats()));
            owner.refresh();
        }
        void splitNotesAtMarker()
        {
            const auto* clip=owner.currentMidiClip();if(!clip)return;
            const auto id=clip->id;juce::StringArray selected;
            for(const auto& note:clip->notes)if(selectedNoteIds.empty()||selectedNoteIds.contains(note.id))selected.add(note.id);
            endGesture();juce::StringArray inserted;
            const auto result=owner.session.splitMidiNotes(id,selected,insertionBeat,inserted);owner.report(result);
            if(result.wasOk()&&!inserted.isEmpty())
            {clearSelection();for(const auto& note:inserted)selectedNoteIds.insert(note);selectedNoteId=inserted[0];}
            owner.refresh();
        }
        // MIDI step recording, as the reference's: with the clip's track armed and the transport
        // stopped, Right Arrow adds the notes held on the track's inputs at the insert marker for a
        // grid step and moves the marker on; held through another Right Arrow they lengthen by a step;
        // Left Arrow, still holding them, takes them out again. Each is one undo step.
        bool stepRecord (bool forward)
        {
            const auto* clip = owner.currentMidiClip(); const auto* track = owner.currentTrack();
            if (clip == nullptr || track == nullptr || ! track->armed || ! owner.session.notePreview() || owner.state.playing) return false;
            const auto held = owner.session.heldInputNotes (track->id);
            if (held.empty()) return false;
            std::vector<int> pitches; for (const auto& note : held) pitches.push_back (note.pitch);
            // Steps stop at the end of the clip's content, where the insert marker stops.
            const auto clipId = clip->id; const auto end = contentEndBeat (*clip);
            const auto step = juce::jmin (snapBeats(), end - insertionBeat);
            // The notes the last step added, if they are the ones still held and end at the marker.
            std::vector<Session::MidiNoteInfo> previous;
            for (const auto& note : clip->notes) if (stepNoteIds.contains (note.id)) previous.push_back (note);
            const bool continuing = stepClipId == clipId && pitches == stepPitches && ! previous.empty() && (int) previous.size() == stepNoteIds.size()
                                 && std::all_of (previous.begin(), previous.end(), [&] (const auto& n) { return std::abs (n.startBeat + n.lengthBeats - insertionBeat) < 1e-6; });
            if (! forward)
            {
                if (! continuing) return false;
                owner.report (owner.session.removeMidiNotes (clipId, stepNoteIds));
                insertionBeat = previous.front().startBeat;
                stepNoteIds.clear(); stepPitches.clear(); owner.refresh(); repaint(); return true;
            }
            if (step < 1e-9) return false;
            if (continuing)
            {
                for (auto& note : previous) note.lengthBeats += step;
                owner.report (owner.session.updateMidiNotes (clipId, previous));
            }
            else
            {
                std::vector<Session::MidiNoteInfo> notes;
                for (const auto& note : held) notes.push_back ({ {}, note.pitch, insertionBeat, step, juce::jlimit (1, 127, note.velocity) / 127.0f });
                juce::StringArray added;
                owner.report (owner.session.addMidiNotes (clipId, notes, added));
                stepNoteIds = added; stepPitches = pitches; stepClipId = clipId;
            }
            insertionBeat += step;
            owner.refresh(); repaint(); return true;
        }
        juce::StringArray stepNoteIds; std::vector<int> stepPitches; juce::String stepClipId;
        void toggleSelectedNotes()
        {
            const auto* clip = owner.currentMidiClip();
            if (!clip) return;
            const auto clipId = clip->id;
            const auto selected = selectedNotes();
            juce::StringArray ids;
            bool activate = false;
            for (const auto& note : selected) { ids.add (note.id); activate = activate || !note.active; }
            endGesture();
            owner.report (owner.session.setMidiNotesActive (clipId, ids, activate));
            owner.refresh();
        }
        void showNoteMenu()
        {
            juce::PopupMenu popup;
            const auto* clip = owner.currentMidiClip();
            const bool hasNotes = clip && ! clip->notes.empty();
            popup.addSectionHeader (selectedNoteIds.empty() ? "Transform all clip notes" : "Transform selected notes");
            const char* names[] { "Quantize Starts to Grid", "Quantize Ends to Grid", "Reverse Time", "Invert Pitch", "Legato",
                                  "Compress Time by Half", "Stretch Time to Double", "Set Fixed Length" };
            for (int i=0;i<8;++i) popup.addItem (10+i, names[i], hasNotes);
            popup.addSeparator();
            juce::PopupMenu transforms, generators;
            for (int t = 0; t < Session::noteToolCount; ++t)
            {
                const auto tool = static_cast<Session::NoteTool> (t);
                (notetools::generates (tool) ? generators : transforms).addItem (100 + t, juce::String (notetools::name (tool)) + "...", notetools::generates (tool) ? clip != nullptr : hasNotes);
            }
            popup.addSubMenu ("Transform", transforms, hasNotes); popup.addSubMenu ("Generate", generators, clip != nullptr);
            popup.addSeparator();
            popup.addItem (2, "Copy Notes", hasSelectedNote()); popup.addItem (3, "Cut Notes", hasSelectedNote());
            popup.addItem (4, "Paste Notes at Marker", ! noteClipboard.empty()); popup.addItem (5, "Duplicate Notes");
            popup.addItem (7, "Split Notes at Marker", hasNotes);
            const auto selected = selectedNotes();
            const bool activate = std::any_of (selected.begin(), selected.end(), [] (const auto& note) { return !note.active; });
            popup.addItem (8, activate ? "Activate Selected Notes" : "Deactivate Selected Notes", !selected.empty());
            popup.addSeparator(); popup.addItem (1, "Delete Selected Notes");
            popup.addSeparator(); popup.addItem (6, "Notes clipboard: Halftrack only", false);
            auto safe = juce::Component::SafePointer<PianoRoll> (this);
            const auto clipId = loadedClip; const auto ids = selectedNoteIds; const auto marker=insertionBeat;
            popup.showMenuAsync (juce::PopupMenu::Options(), [safe, clipId, ids, marker] (int result)
            {
                if (safe == nullptr || safe->loadedClip != clipId || safe->selectedNoteIds != ids) return;
                if (result >= 10 && result <= 17) safe->transformSelected (static_cast<Session::NoteTransform> (result-10));
                if (result >= 100 && result < 100 + Session::noteToolCount) safe->openNoteTool (static_cast<Session::NoteTool> (result - 100));
                if (result == 1) safe->deleteSelectedNote();
                if (result == 7 && safe->insertionBeat==marker) safe->splitNotesAtMarker();
                if (result == 8) safe->toggleSelectedNotes();
                const char command = result == 2 ? 'C' : result == 3 ? 'X' : result == 4 ? 'V' : result == 5 ? 'D' : 0;
                if (command != 0) safe->keyPressed (juce::KeyPress (command, juce::ModifierKeys (juce::ModifierKeys::commandModifier), 0));
            });
        }
    };

    // A Sampler's sample: waveform with draggable start/end markers, file loading and drops.
    class SampleView final : public juce::Component, public juce::FileDragAndDropTarget, private juce::ChangeListener
    {
    public:
        explicit SampleView (Impl& o) : owner (o), thumbnail (512, o.formats, o.thumbnailCache)
        {
            setName ("Sampler sample");
            load.setName ("Load sample"); load.setTooltip ("Choose an audio file for this Sampler. You can also drop one here.");
            load.setWantsKeyboardFocus (false); load.setMouseClickGrabsKeyboardFocus (false);
            load.onClick = [this] { choose(); };
            addAndMakeVisible (load);
            thumbnail.addChangeListener (this);
        }
        ~SampleView() override { thumbnail.removeChangeListener (this); if (gesture) owner.session.endEditGesture(); }
        void show (const Session::PluginInfo& info)
        {
            plugin = info;
            if (info.sample != shown) { shown = info.sample; thumbnail.setSource (shown.existsAsFile() ? new juce::FileInputSource (shown) : nullptr); }
            load.setEnabled (! owner.session.isExporting());
            repaint();
        }
        void resized() override { load.setBounds (getWidth() - 62, 3, 58, 18); }
        void paint (juce::Graphics& g) override
        {
            g.setColour (themes::colour (0xff1c1c1c)); g.fillRect (getLocalBounds());
            g.setColour (ink); g.setFont (font (10.5f, true));
            g.drawText (shown == juce::File() ? juce::String ("No sample") : shown.getFileName(), 6, 3, getWidth() - 74, 18, juce::Justification::centredLeft, true);
            const auto wave = waveBounds();
            if (thumbnail.getTotalLength() <= 0)
            {
                g.setColour (muted); g.setFont (font (10.0f));
                g.drawFittedText ("Drop an audio file here", wave, juce::Justification::centred, 2);
                g.setColour (line); g.drawRect (wave); return;
            }
            g.setColour (owner.selectedTrackColour().withAlpha (0.85f));
            thumbnail.drawChannels (g, wave.reduced (0, 4), 0, thumbnail.getTotalLength(), 0.95f);
            const auto& v = plugin.effect.values;
            const auto x = [&] (float fraction) { return wave.getX() + (int) std::lround (fraction * wave.getWidth()); };
            const auto start = std::min (v[instruments::sampler::start], v[instruments::sampler::end]), end = std::max (v[instruments::sampler::start], v[instruments::sampler::end]);
            // Outside the played region is dimmed, as are the markers' handles.
            g.setColour (themes::colour (0x99000000));
            g.fillRect (wave.withRight (x (start))); g.fillRect (wave.withLeft (x (end)));
            g.setColour (themes::colour (0xffffab3d));
            for (const auto f : { start, end }) { g.drawVerticalLine (x (f), (float) wave.getY(), (float) wave.getBottom()); g.fillRect (x (f) - (f == start ? 0 : 6), wave.getY(), 6, 6); }
            if (v[instruments::sampler::mode] == 0 && v[instruments::sampler::loop] == 1)
            {
                const auto loopX = x (start + v[instruments::sampler::loopStart] * (end - start));
                g.setColour (themes::colour (0xff48d17e)); g.drawVerticalLine (loopX, (float) wave.getY(), (float) wave.getBottom());
                g.drawText ("L", loopX + 2, wave.getBottom() - 14, 12, 12, juce::Justification::centredLeft);
            }
            g.setColour (line); g.drawRect (wave);
        }
        // Dragging a marker edits Start or End as one undo step.
        void mouseDown (const juce::MouseEvent& event) override
        {
            dragging = -1;
            if (thumbnail.getTotalLength() <= 0 || ! waveBounds().contains (event.getPosition())) return;
            const auto& v = plugin.effect.values; const auto wave = waveBounds();
            const auto distance = [&] (size_t index) { return std::abs (event.x - (wave.getX() + v[index] * wave.getWidth())); };
            dragging = distance (instruments::sampler::start) <= distance (instruments::sampler::end) ? (int) instruments::sampler::start : (int) instruments::sampler::end;
            owner.session.beginEditGesture ("Sample region"); gesture = true;
            mouseDrag (event);
        }
        void mouseDrag (const juce::MouseEvent& event) override
        {
            if (dragging < 0) return;
            const auto wave = waveBounds();
            auto settings = plugin.effect;
            settings.values[(size_t) dragging] = juce::jlimit (0.0f, 1.0f, (float) (event.x - wave.getX()) / (float) juce::jmax (1, wave.getWidth()));
            if (settings == plugin.effect) return;
            owner.report (owner.session.setNativeEffectSettings (plugin.id, settings)); owner.refresh();
        }
        void mouseUp (const juce::MouseEvent&) override { if (gesture) owner.session.endEditGesture(); gesture = false; dragging = -1; }
        bool isInterestedInFileDrag (const juce::StringArray& files) override { return files.size() == 1 && isAudio (juce::File (files[0])); }
        void filesDropped (const juce::StringArray& files, int, int) override { loadFile (juce::File (files[0])); }
        void loadFile (const juce::File& file)
        {
            if (const auto* track = owner.currentTrack(); track != nullptr && track->isMidi) { owner.report (owner.session.setInstrumentSample (track->id, file)); owner.refresh(); }
        }
        juce::Rectangle<int> waveBounds() const { return getLocalBounds().withTrimmedTop (24).reduced (4, 4); }
    private:
        Impl& owner;
        juce::AudioThumbnail thumbnail;
        juce::File shown;
        Session::PluginInfo plugin;
        juce::TextButton load { "Load..." };
        std::unique_ptr<juce::FileChooser> chooser;
        int dragging = -1;
        bool gesture = false;
        void choose()
        {
            chooser = std::make_unique<juce::FileChooser> ("Load sample", shown.existsAsFile() ? shown.getParentDirectory() : juce::File(), "*.wav;*.aif;*.aiff;*.flac;*.ogg;*.mp3");
            auto safe = juce::Component::SafePointer<SampleView> (this);
            chooser->launchAsync (juce::FileBrowserComponent::openMode | juce::FileBrowserComponent::canSelectFiles,
                                  [safe] (const juce::FileChooser& c) { if (safe != nullptr && c.getResult() != juce::File()) safe->loadFile (c.getResult()); });
        }
        void changeListenerCallback (juce::ChangeBroadcaster*) override { repaint(); }
    };

    // A Drum Sampler's 4x4 pad grid (pad 1, C1, bottom left) with the selected pad's controls.
    class DrumPanel final : public juce::Component, public juce::FileDragAndDropTarget
    {
    public:
        static constexpr int padWidth = 56, padHeight = 40, gridWidth = 4 * padWidth, controlsWidth = 300;
        explicit DrumPanel (Impl& o) : owner (o)
        {
            setName ("Drum pads");
            for (int i = 0; i < 4; ++i)
            {
                auto& knob = knobs[(size_t) i]; addAndMakeVisible (knob);
                knob.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag); knob.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 58, 15);
                knob.setColour (juce::Slider::textBoxOutlineColourId, juce::Colours::transparentBlack);
                knob.onDragStart = [this] { owner.session.beginEditGesture ("Drum pad"); gesture = true; };
                knob.onDragEnd = [this] { if (gesture) owner.session.endEditGesture(); gesture = false; };
                knob.onValueChange = [this, i] { change ((size_t) i, (float) knobs[(size_t) i].getValue()); };
            }
            knobs[0].setName ("Pad tune"); knobs[0].setRange (-48, 48, .01); knobs[0].setDoubleClickReturnValue (true, 0);
            knobs[0].textFromValueFunction = [] (double v) { return juce::String (v, 2) + " st"; };
            knobs[1].setName ("Pad length"); knobs[1].setRange (.01, 1, .001); knobs[1].setDoubleClickReturnValue (true, 1);
            knobs[1].textFromValueFunction = [] (double v) { return juce::String (v * 100, 1) + "%"; };
            knobs[2].setName ("Pad level"); knobs[2].setRange (0, 1, .001); knobs[2].setDoubleClickReturnValue (true, 1);
            knobs[2].textFromValueFunction = [] (double v) { return juce::String (v * 100, 1) + "%"; };
            knobs[3].setName ("Pad pan"); knobs[3].setRange (-1, 1, .01); knobs[3].setDoubleClickReturnValue (true, 0);
            knobs[3].textFromValueFunction = [] (double v) { return Session::panText ((float) v); };
            for (auto& knob : knobs) knob.updateText();
            choke.setName ("Pad choke"); choke.setTooltip ("Pads in the same choke group silence each other");
            for (auto* text : { "No choke", "Choke 1", "Choke 2", "Choke 3", "Choke 4" }) choke.addItem (text, choke.getNumItems() + 1);
            choke.onChange = [this] { change (instruments::drumSampler::choke, (float) (choke.getSelectedId() - 1)); };
            clear.setName ("Clear pad"); clear.setTooltip ("Remove this pad's sample");
            clear.onClick = [this] { if (const auto* track = owner.currentTrack()) { owner.report (owner.session.setDrumPadSample (track->id, selected, {})); owner.refresh(); } };
            for (auto* c : std::initializer_list<juce::Component*> { &choke, &clear }) addAndMakeVisible (c);
        }
        ~DrumPanel() override { if (gesture) owner.session.endEditGesture(); }
        void show (const Session::PluginInfo& info)
        {
            plugin = info;
            const auto base = (size_t) selected * instruments::drumSampler::padStride;
            for (size_t i = 0; i < knobs.size(); ++i)
                if (! knobs[i].isMouseButtonDown()) knobs[i].setValue (plugin.effect.values[base + i], juce::dontSendNotification);
            for (auto& knob : knobs) knob.updateText();
            choke.setSelectedId (juce::roundToInt (plugin.effect.values[base + instruments::drumSampler::choke]) + 1, juce::dontSendNotification);
            clear.setEnabled (padFile (selected) != juce::File() && ! owner.session.isExporting());
            repaint();
        }
        int selectedPad() const noexcept { return owner.selectedDrumPad; }
        // Pad 1 is bottom left and pads count left to right, bottom to top.
        juce::Rectangle<int> padBounds (int pad) const { return { 4 + (pad % 4) * padWidth, 4 + (3 - pad / 4) * padHeight, padWidth - 3, padHeight - 3 }; }
        void resized() override
        {
            auto area = getLocalBounds().withTrimmedLeft (gridWidth + 16).reduced (0, 4);
            auto name = area.removeFromTop (20); juce::ignoreUnused (name);
            auto row = area.removeFromTop (74);
            for (auto& knob : knobs) knob.setBounds (row.removeFromLeft (66).withTrimmedTop (14));
            area.removeFromTop (6);
            auto buttons = area.removeFromTop (22);
            choke.setBounds (buttons.removeFromLeft (110)); buttons.removeFromLeft (6); clear.setBounds (buttons.removeFromLeft (70));
        }
        void paint (juce::Graphics& g) override
        {
            g.setColour (themes::colour (0xff1c1c1c)); g.fillRect (getLocalBounds().withWidth (gridWidth + 8));
            static const char* names[] { "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B" };
            for (int pad = 0; pad < Session::drumPadCount; ++pad)
            {
                const auto b = padBounds (pad); const auto file = padFile (pad);
                const auto note = instruments::drumSampler::firstNote + pad;
                g.setColour (file != juce::File() ? owner.selectedTrackColour().withMultipliedSaturation (.7f) : themes::colour (0xff3a3a3a)); g.fillRect (b);
                if (pad == selected) { g.setColour (orange); g.drawRect (b, 2); }
                g.setColour (file != juce::File() ? themes::colour (0xff141414) : muted); g.setFont (font (9.5f, true));
                g.drawText (juce::String (names[note % 12]) + juce::String (note / 12 - 2), b.reduced (4, 2).removeFromTop (12), juce::Justification::topLeft);
                g.setFont (font (9.0f));
                g.drawFittedText (file != juce::File() ? file.getFileNameWithoutExtension() : juce::String ("Drop"), b.reduced (4, 2).withTrimmedTop (12), juce::Justification::centredLeft, 2);
            }
            const auto file = padFile (selected);
            g.setColour (ink); g.setFont (font (10.5f, true));
            g.drawText ("Pad " + juce::String (selected + 1) + (file != juce::File() ? "  " + file.getFileName() : juce::String ("  (empty)")),
                        gridWidth + 16, 4, getWidth() - gridWidth - 20, 18, juce::Justification::centredLeft, true);
            g.setColour (muted); g.setFont (font (9.5f));
            const char* labels[] { "Tune", "Length", "Level", "Pan" };
            for (size_t i = 0; i < knobs.size(); ++i) g.drawText (labels[i], knobs[i].getX(), knobs[i].getY() - 14, knobs[i].getWidth(), 13, juce::Justification::centred);
        }
        void mouseDown (const juce::MouseEvent& event) override
        { for (int pad = 0; pad < Session::drumPadCount; ++pad) if (padBounds (pad).contains (event.getPosition())) { selected = pad; show (plugin); return; } }
        bool isInterestedInFileDrag (const juce::StringArray& files) override { return files.size() == 1 && isAudio (juce::File (files[0])); }
        void filesDropped (const juce::StringArray& files, int x, int y) override
        {
            for (int pad = 0; pad < Session::drumPadCount; ++pad)
                if (padBounds (pad).contains (x, y))
                {
                    selected = pad;
                    if (const auto* track = owner.currentTrack()) { owner.report (owner.session.setDrumPadSample (track->id, pad, juce::File (files[0]))); owner.refresh(); }
                    return;
                }
        }
    private:
        Impl& owner;
        Session::PluginInfo plugin;
        int& selected = owner.selectedDrumPad;
        bool gesture = false;
        std::array<juce::Slider, 4> knobs;
        juce::ComboBox choke;
        juce::TextButton clear { "Clear" };
        juce::File padFile (int pad) const { return pad < (int) plugin.padSamples.size() ? plugin.padSamples[(size_t) pad] : juce::File(); }
        void change (size_t control, float value)
        {
            auto settings = plugin.effect;
            settings.values[(size_t) selected * instruments::drumSampler::padStride + control] = value;
            if (settings == plugin.effect) return;
            owner.report (owner.session.setNativeEffectSettings (plugin.id, settings)); owner.refresh();
        }
    };

    class SynthPanel final : public juce::Component
    {
    public:
        explicit SynthPanel (Impl& o) : owner (o)
        {
            setName ("Halftrack synthesizer");
            waveform.setName ("Oscillator waveform");
            addAndMakeVisible (waveform); waveform.addItem ("Saw", 1); waveform.addItem ("Pulse", 2);
            waveform.addItem ("Sine", 3); waveform.addItem ("Noise", 4);
            waveform.onChange = [this]
            {
                if (const auto* track = owner.currentTrack(); track != nullptr && track->isMidi)
                { auto settings = track->synth; settings.waveform = waveform.getSelectedId() - 1; owner.report (owner.session.setSynthSettings (track->id, settings)); owner.refresh(); }
            };
            for (int i = 0; i < 8; ++i)
            {
                auto& slider = controls[(size_t) i]; addAndMakeVisible (slider);
                slider.setName (names[i]); slider.setTooltip (names[i]);
                slider.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag);
                slider.setTextBoxStyle (juce::Slider::TextBoxBelow, false, 61, 17);
                slider.onDragStart = [this] { owner.session.beginEditGesture ("Synth parameter"); };
                slider.onDragEnd = [this] { owner.session.endEditGesture(); };
            }
            controls[0].setRange (20, 20000, 1); controls[0].setSkewFactorFromMidPoint (1800); controls[0].setTextValueSuffix (" Hz");
            controls[1].setRange (0, 1, 0.01);
            controls[2].setRange (0, 10, 0.001); controls[2].setSkewFactorFromMidPoint (0.12); controls[2].setTextValueSuffix (" s");
            controls[3].setRange (0, 10, 0.001); controls[3].setSkewFactorFromMidPoint (0.25); controls[3].setTextValueSuffix (" s");
            controls[4].setRange (0, 1, 0.01);
            controls[5].setRange (0, 20, 0.001); controls[5].setSkewFactorFromMidPoint (0.4); controls[5].setTextValueSuffix (" s");
            controls[6].setRange (0, 1, 0.01);
            controls[7].setRange (0, 100, 1); controls[7].setTextValueSuffix (" %");
            for (int i = 0; i < 8; ++i) controls[(size_t) i].onValueChange = [this, i] { changeParameter (i, (float) controls[(size_t) i].getValue()); };
            instrument.setName ("Track instrument"); instrument.setTooltip ("Choose the sound source for this MIDI track. Changing it is one undo step.");
            instrument.addItem ("Halftrack Synth", 1);
            for (int kind = 0; kind < Session::deviceKindCount; ++kind)
                if (effectIsInstrument ((Session::EffectKind) kind) && ! Session::isRackKind ((Session::EffectKind) kind))
                    instrument.addItem (effectName ((Session::EffectKind) kind), 2 + kind - (int) Session::EffectKind::polySynth);
            for (const auto kind : { Session::EffectKind::instrumentRack, Session::EffectKind::drumRack })
                instrument.addItem (effectName (kind), 2 + (int) kind - (int) Session::EffectKind::polySynth);
            instrument.addSeparator(); instrument.addItem ("No Instrument", noInstrumentId);
            instrument.onChange = [this]
            {
                const auto* track = owner.currentTrack(); if (track == nullptr || ! track->isMidi) return;
                const int id = instrument.getSelectedId();
                if (id == noInstrumentId) { owner.report (owner.session.removeTrackInstrument (track->id)); owner.refresh(); return; }
                const std::optional<Session::EffectKind> kind = id <= 1 ? std::nullopt
                    : std::optional<Session::EffectKind> ((Session::EffectKind) ((int) Session::EffectKind::polySynth + id - 2));
                owner.report (owner.session.setTrackInstrument (track->id, kind)); owner.refresh();
            };
            addAndMakeVisible (instrument);
            edit.setName ("Edit instrument"); edit.setTooltip ("Open every control of this instrument.");
            edit.onClick = [this] { owner.report (owner.session.showInstrumentEditor (owner.selectedTrack)); };
            addChildComponent (edit);
            group.setName ("Group instrument"); group.setTooltip ("Group this instrument and the built-in effects after it into an Instrument Rack");
            group.onClick = [this] { if (const auto* track = owner.currentTrack()) { juce::String rack; owner.report (owner.session.groupInstrument (track->id, rack)); owner.refresh(); } };
            addChildComponent (group);
            addChildComponent (sample);
            addChildComponent (drumPads);
        }
        void sync()
        {
            const auto* track = owner.currentTrack();
            if (track == nullptr || ! track->isMidi) { setVisible (false); return; }
            setVisible (true);
            empty = ! track->hasInstrument;
            native = ! empty && track->instrument.isNativeEffect; nativeSettings = track->instrument.effect;
            // The Drum Sampler's pad grid replaces the generic control layout.
            if (! native || drumSampler()) { nativeEditor.reset(); nativeEditorId.clear(); }
            else if (nativeEditorId != track->instrument.id)
            {
                const auto automation = [safe = juce::Component::SafePointer<Impl> (&owner)] (const juce::String& id, int parameter) { if (safe != nullptr) safe->showAutomation (false, id, parameter); };
                nativeEditor = track->instrument.isRack ? makeRackEditor (owner.session, track->instrument.id, automation)
                    : makeNativeEffectEditor (owner.session, track->instrument.id, true, [automation, id = track->instrument.id] (int parameter) { automation (id, parameter); });
                addAndMakeVisible (*nativeEditor); nativeEditorId = track->instrument.id;
            }
            instrument.setSelectedId (empty ? noInstrumentId : native ? 2 + (int) nativeSettings.kind - (int) Session::EffectKind::polySynth : 1, juce::dontSendNotification);
            sample.setVisible (sampler());
            if (sampler()) sample.show (track->instrument);
            drumPads.setVisible (drumSampler());
            if (drumSampler()) drumPads.show (track->instrument);
            instrument.setEnabled (! owner.session.isExporting());
            waveform.setVisible (! native && ! empty); edit.setVisible (native); group.setVisible (native);
            for (auto& control : controls) control.setVisible (! native && ! empty);
            waveform.setSelectedId (track->synth.waveform + 1, juce::dontSendNotification);
            const float values[] { track->synth.cutoffHz, track->synth.resonance, track->synth.attackSeconds, track->synth.decaySeconds, track->synth.sustain, track->synth.releaseSeconds, track->synth.level, track->synth.pulseWidth * 100 };
            for (int i = 0; i < 8; ++i) controls[(size_t) i].setValue (values[i], juce::dontSendNotification);
            controls[7].setEnabled (track->synth.waveform == 1);
            resized(); repaint(); // Layout depends on built-in versus native mode, not only size.
        }
        int preferredWidth() const
        {
            if (drumSampler()) return DrumPanel::gridWidth + DrumPanel::controlsWidth + 24;
            if (empty) return 330;
            return native && nativeEditor ? juce::jmax (330, nativeEditor->getWidth() + 4 + sampleWidth()) : 536;
        }
        bool sampler() const { return native && nativeSettings.kind == Session::EffectKind::sampler; }
        bool drumSampler() const { return native && nativeSettings.kind == Session::EffectKind::drumSampler; }
        int sampleWidth() const { return sampler() ? 250 : 0; }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff303030));
            g.setColour (themes::colour (0xff4a4a4a)); g.fillRect (0, 0, getWidth(), 26);
            g.setColour (ink); g.setFont (font (11.0f, true));
            g.drawText (empty ? juce::String ("No Instrument") : native ? juce::String (effectName (nativeSettings.kind)) : juce::String ("Halftrack Synth"), 9, 0,
                        native ? juce::jmin (185, getWidth() - 305) : 185, 26, juce::Justification::centredLeft, true);
            if (empty)
            {
                g.setColour (muted); g.setFont (font (10.5f));
                g.drawFittedText ("This MIDI track has no instrument. Choose one above, or play its MIDI to a MIDI port with MIDI To in its mixer strip.",
                                  getLocalBounds().withTrimmedTop (26).reduced (12), juce::Justification::centred, 4);
            }
            if (native || empty) { g.setColour (line); g.drawRect (getLocalBounds()); return; }
            g.setColour (muted); g.setFont (font (9.5f));
            const auto width = (getWidth() - 16) / 8;
            for (int i = 0; i < 8; ++i) g.drawText (names[i], 8 + i * width, 30, width, 14, juce::Justification::centred);
            g.setColour (line); g.drawRect (getLocalBounds());
        }
        void resized() override
        {
            waveform.setBounds (getWidth() - 118, 3, 107, 20);
            instrument.setBounds (getWidth() - (native ? 118 : empty ? 149 : 262), 3, native ? 107 : 138, 20);
            edit.setBounds (getWidth() - 236, 3, 112, 20);
            group.setBounds (getWidth() - 296, 3, 56, 20);
            sample.setBounds (2, 28, sampleWidth() - 4, juce::jmax (40, getHeight() - 30));
            drumPads.setBounds (2, 28, getWidth() - 4, juce::jmax (40, getHeight() - 30));
            if (nativeEditor) nativeEditor->setTopLeftPosition (2 + sampleWidth(), 28);
            const auto width = (getWidth() - 16) / 8;
            for (int i = 0; i < 8; ++i) controls[(size_t) i].setBounds (8 + i * width, 43, width - 2, getHeight() - 46);
        }
    private:
        Impl& owner;
        juce::ComboBox waveform, instrument;
        juce::TextButton edit { "Edit instrument..." }, group { "Group" };
        bool native = false, empty = false;
        static constexpr int noInstrumentId = 1000;
        Session::EffectSettings nativeSettings;
        std::unique_ptr<juce::Component> nativeEditor;
        juce::String nativeEditorId;
        SampleView sample { owner };
        DrumPanel drumPads { owner };
        std::array<juce::Slider, 8> controls;
        static constexpr const char* names[] { "Cutoff", "Resonance", "Attack", "Decay", "Sustain", "Release", "Level", "Pulse width" };
        void changeParameter (int index, float value)
        {
            const auto* track = owner.currentTrack(); if (track == nullptr || ! track->isMidi) return;
            auto settings = track->synth;
            switch (index)
            {
                case 0: settings.cutoffHz = value; break; case 1: settings.resonance = value; break;
                case 2: settings.attackSeconds = value; break; case 3: settings.decaySeconds = value; break;
                case 4: settings.sustain = value; break; case 5: settings.releaseSeconds = value; break;
                case 6: settings.level = value; break; case 7: settings.pulseWidth = value / 100; break; default: return;
            }
            owner.report (owner.session.setSynthSettings (track->id, settings));
            owner.refresh();
        }
    };

    class SendsPanel final : public juce::Component
    {
        class SendRow final : public juce::Component
        {
        public:
            SendRow (Impl& o, juce::String destination) : destinationId (std::move (destination)), owner (o)
            {
                addAndMakeVisible (label); addAndMakeVisible (level);
                label.setFont (font (10.5f));
                level.setSliderStyle (juce::Slider::LinearHorizontal);
                level.setNormalisableRange (Session::levelRange (true));
                level.setTextBoxStyle (juce::Slider::TextBoxRight, false, 55, 21);
                level.textFromValueFunction = [] (double v) { return v <= -100 ? juce::String ("Off") : juce::String (v, 1) + " dB"; };
                level.valueFromTextFunction = [] (const juce::String& v) { return v.trim().equalsIgnoreCase ("Off") ? -100.0 : v.getDoubleValue(); };
                level.setDoubleClickReturnValue (true, -100);
                level.onDragStart = [this] { gesture = true; owner.session.beginEditGesture ("Send level"); };
                level.onDragEnd = [this] { gesture = false; owner.session.endEditGesture(); };
                level.onValueChange = [this]
                {
                    const int index = owner.launcherIndices (sourceId, {}).first;
                    if (index >= 0) owner.report (owner.session.setTrackSendGain (index, destinationId, (float) level.getValue()));
                };
            }
            ~SendRow() override { if (gesture) owner.session.endEditGesture(); }
            void sync (const Session::TrackInfo& source, const Session::TrackInfo& destination, float value)
            {
                if (! gesture) sourceId = source.id;
                level.getProperties().set ("midiMapTarget", "send:" + sourceId + ":" + destination.id);
                label.setText (destination.name + (destination.sendMode == Session::SendMode::pre ? "  |  Pre" : "  |  Post"), juce::dontSendNotification);
                level.setName ("Send to " + destination.name);
                level.setTooltip ("Send to " + destination.name + ". Off to 0 dB. Double-click to turn off.");
                if (! level.isMouseButtonDown()) level.setValue (value, juce::dontSendNotification);
            }
            void resized() override { label.setBounds (0, 0, getWidth(), 16); level.setBounds (0, 17, getWidth(), 24); }
            const juce::String destinationId;
        private:
            Impl& owner;
            juce::String sourceId;
            juce::Label label;
            juce::Slider level;
            bool gesture = false;
        };
    public:
        explicit SendsPanel (Impl& o) : owner (o)
        {
            setName ("Track sends"); addAndMakeVisible (addReturn); addAndMakeVisible (viewport);
            addReturn.setName ("Insert return track");
            addReturn.onClick = [this] { owner.addReturnTrack(); };
            viewport.setViewedComponent (&content, false); viewport.setScrollBarsShown (true, false); viewport.setScrollBarThickness (9);
        }
        ~SendsPanel() override { viewport.setViewedComponent (nullptr, false); }
        void sync()
        {
            const auto* source = owner.selectedChain.isEmpty() ? owner.currentTrack() : nullptr;
            setVisible (source != nullptr && ! source->isReturn);
            if (! isVisible()) return;
            std::vector<const Session::TrackInfo*> returns;
            for (const auto& track : owner.state.tracks) if (track.isReturn) returns.push_back (&track);
            bool rebuild = rows.size() != returns.size();
            if (! rebuild) for (size_t i = 0; i < rows.size(); ++i) if (rows[i]->destinationId != returns[i]->id) rebuild = true;
            if (rebuild)
            {
                rows.clear();
                for (const auto* track : returns)
                {
                    auto row = std::make_unique<SendRow> (owner, track->id);
                    content.addAndMakeVisible (*row); rows.push_back (std::move (row));
                }
            }
            for (size_t i = 0; i < rows.size(); ++i)
            {
                float gainDb = -100;
                for (const auto& send : source->sends) if (send.returnTrackId == returns[i]->id) gainDb = send.gainDb;
                rows[i]->sync (*source, *returns[i], gainDb);
            }
            resized(); repaint();
        }
        void resized() override
        {
            addReturn.setBounds (getWidth() - 89, 4, 81, 23);
            viewport.setBounds (8, 32, getWidth() - 16, getHeight() - 39);
            content.setSize (viewport.getWidth() - 10, juce::jmax (viewport.getHeight(), (int) rows.size() * 44));
            for (size_t i = 0; i < rows.size(); ++i) rows[i]->setBounds (0, (int) i * 44, content.getWidth(), 42);
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (raised); g.setColour (orange); g.setFont (font (10.5f, true));
            g.drawText ("SENDS", 10, 4, 64, 23, juce::Justification::centredLeft);
            if (rows.empty())
            {
                g.setColour (muted); g.setFont (font (11.0f));
                g.drawFittedText ("Add a return track to share an effect across tracks.", 13, 42, getWidth() - 26, getHeight() - 52, juce::Justification::centred, 3);
            }
            g.setColour (line); g.drawRect (getLocalBounds());
        }
    private:
        Impl& owner;
        juce::TextButton addReturn { "+ Return" };
        juce::Viewport viewport;
        juce::Component content;
        std::vector<std::unique_ptr<SendRow>> rows;
    };

    // A hosted plug-in's controls in its panel: Configure chooses which of its parameters show here,
    // four to a column, where they can be automated and MIDI mapped like a device's own controls.
    // A plug-in with a sidechain input shows, as in the reference, its sidechain at the left: the
    // switch, the track it hears (Audio From) and that track's tap.
    class PluginControls final : public juce::Component
    {
    public:
        PluginControls (Impl& o, const juce::String& id) : owner (o), pluginId (id)
        {
            addAndMakeVisible (configure); configure.setName ("Configure plug-in");
            configure.setWantsKeyboardFocus (false);
            configure.setTooltip ("Choose which of this plug-in's parameters show here, where they can be automated and MIDI mapped.");
            configure.onClick = [this] { showConfigureMenu(); };
            for (auto* c : std::initializer_list<juce::Component*> { &sidechainOn, &sidechainSource, &sidechainTap }) { addChildComponent (c); c->setWantsKeyboardFocus (false); }
            sidechainOn.setName ("Sidechain on"); sidechainSource.setName ("Sidechain source"); sidechainTap.setName ("Sidechain tap");
            sidechainOn.setTooltip ("Feed the plug-in's sidechain input from the chosen track.");
            sidechainSource.setTooltip ("The track whose audio the plug-in's sidechain hears. It is not heard through this track.");
            sidechainTap.setTooltip ("Where that track's audio is taken: before its devices, after them, or after its mixer.");
            sidechainOn.setColour (juce::TextButton::buttonOnColourId, orange);
            int item = 1;
            for (const auto* tap : { "Pre FX", "Post FX", "Post Mixer" }) sidechainTap.addItem (tap, item++);
            sidechainOn.onClick = [this] { auto next = sidechain; next.on = ! next.on; setSidechain (next); };
            sidechainSource.onChange = [this]
            {
                // Choosing a track switches the sidechain on; No Input keeps the switch as it is.
                auto next = sidechain;
                const int index = sidechainSource.getSelectedItemIndex() - 1;
                next.sourceTrackId = juce::isPositiveAndBelow (index, sourceIds.size()) ? sourceIds[index] : juce::String();
                if (next.sourceTrackId.isNotEmpty() && next.sourceTrackId != sidechain.sourceTrackId) next.on = true;
                setSidechain (next);
            };
            sidechainTap.onChange = [this] { auto next = sidechain; next.tap = static_cast<Session::InputTap> (juce::jlimit (0, 2, sidechainTap.getSelectedId() - 1)); setSidechain (next); };
        }
        void setSidechain (const Session::SidechainSettings& next) { owner.report (owner.session.setPluginSidechain (pluginId, next)); owner.refresh(); }
        void sync (const Session::PluginInfo& info)
        {
            if (hasSidechain != info.canSidechain)
            {
                hasSidechain = info.canSidechain;
                for (auto* c : std::initializer_list<juce::Component*> { &sidechainOn, &sidechainSource, &sidechainTap }) c->setVisible (hasSidechain);
                resized();
            }
            if (hasSidechain)
            {
                sidechain = info.sidechain;
                sidechainOn.setTitle (info.name + " sidechain"); sidechainSource.setTitle (info.name + " sidechain source"); sidechainTap.setTitle (info.name + " sidechain tap");
                sidechainOn.setToggleState (sidechain.on, juce::dontSendNotification);
                // The tracks it can hear, then the current source even if it is no longer offered.
                sourceIds = owner.session.sidechainSources (pluginId);
                if (sidechain.sourceTrackId.isNotEmpty() && ! sourceIds.contains (sidechain.sourceTrackId)) sourceIds.add (sidechain.sourceTrackId);
                juce::StringArray names { "No Input" };
                for (const auto& sourceId : sourceIds)
                {
                    juce::String name = "Track";
                    for (const auto& track : owner.state.tracks) if (track.id == sourceId) name = track.name;
                    names.add (name);
                }
                if (names != sourceNames)
                {
                    sourceNames = names; sidechainSource.clear (juce::dontSendNotification);
                    for (int i = 0; i < names.size(); ++i) sidechainSource.addItem (names[i], i + 1);
                }
                sidechainSource.setSelectedItemIndex (sidechain.sourceTrackId.isEmpty() ? 0 : sourceIds.indexOf (sidechain.sourceTrackId) + 1, juce::dontSendNotification);
                sidechainTap.setSelectedId (static_cast<int> (sidechain.tap) + 1, juce::dontSendNotification);
                sidechainTap.setEnabled (sidechain.sourceTrackId.isNotEmpty());
            }
            const auto parameters = owner.session.pluginParameters (pluginId);
            if (info.configured != shown || parameters.size() != parameterCount)
            {
                shown = info.configured; parameterCount = parameters.size(); controls.clear();
                for (const auto parameter : shown)
                {
                    auto control = std::make_unique<Control>();
                    control->parameter = parameter;
                    auto& slider = control->slider;
                    slider.setSliderStyle (juce::Slider::LinearBar); slider.setRange (0.0, 1.0, 0.0); slider.setTextBoxStyle (juce::Slider::NoTextBox, true, 0, 0);
                    slider.setColour (juce::Slider::trackColourId, themes::colour (0xff5a6f78)); slider.setWantsKeyboardFocus (false);
                    slider.setName (juce::isPositiveAndBelow (parameter, (int) parameters.size()) ? parameters[(size_t) parameter].name : juce::String ("Parameter"));
                    slider.getProperties().set ("midiMapTarget", "device:" + pluginId + ":" + juce::String (parameter));
                    slider.onDragStart = [this] { owner.session.beginEditGesture ("Plug-in parameter"); };
                    slider.onDragEnd = [this] { owner.session.endEditGesture(); };
                    slider.onValueChange = [this, parameter, &slider] { owner.report (owner.session.setPluginParameterValue (pluginId, parameter, (float) slider.getValue())); };
                    control->label.setFont (font (10.0f)); control->label.setColour (juce::Label::textColourId, themes::colour (0xffb8b8b8));
                    control->label.setInterceptsMouseClicks (false, false);
                    addAndMakeVisible (slider); addAndMakeVisible (control->label);
                    controls.push_back (std::move (control));
                }
                resized();
            }
            for (auto& control : controls)
                if (juce::isPositiveAndBelow (control->parameter, (int) parameters.size()))
                {
                    const auto& parameter = parameters[(size_t) control->parameter];
                    if (! control->slider.isMouseButtonDown()) control->slider.setValue (parameter.value, juce::dontSendNotification);
                    control->label.setText (parameter.name + "  " + parameter.text, juce::dontSendNotification);
                    control->slider.setTooltip (parameter.name + ": " + parameter.text);
                }
            repaint();
        }
        int preferredWidth() const { return left() + juce::jmax (184, 8 + columns() * (controlWidth + 8)); }
        void resized() override
        {
            sidechainOn.setBounds (6, 4, sidechainWidth - 12, 20); sidechainSource.setBounds (6, 30, sidechainWidth - 12, 22); sidechainTap.setBounds (6, 56, sidechainWidth - 12, 22);
            configure.setBounds (left() + 6, 4, 76, 20);
            for (size_t i = 0; i < controls.size(); ++i)
            {
                const int column = (int) i / rows, row = (int) i % rows, x = left() + 6 + column * (controlWidth + 8), y = 30 + row * 36;
                controls[i]->label.setBounds (x, y, controlWidth, 14); controls[i]->slider.setBounds (x, y + 15, controlWidth, 16);
            }
        }
        void paint (juce::Graphics& g) override
        {
            if (hasSidechain) { g.setColour (line); g.drawVerticalLine (sidechainWidth, 4.0f, (float) getHeight() - 4.0f); }
            if (! controls.empty()) return;
            g.setColour (muted); g.setFont (font (10.5f));
            g.drawFittedText ("Configure to show this plug-in's parameters here.\nOpen its window for every control.", getLocalBounds().withTrimmedLeft (left()).withTrimmedTop (28).reduced (8), juce::Justification::centred, 4);
        }
        static constexpr int rows = 4, controlWidth = 148, sidechainWidth = 128;
    private:
        struct Control { int parameter = 0; juce::Slider slider; juce::Label label; };
        int left() const { return hasSidechain ? sidechainWidth : 0; }
        int columns() const { return ((int) controls.size() + rows - 1) / rows; }
        void showConfigureMenu()
        {
            const auto parameters = owner.session.pluginParameters (pluginId);
            juce::PopupMenu menu;
            for (size_t i = 0; i < parameters.size(); ++i)
                menu.addItem ((int) i + 1, parameters[i].name, true, std::find (shown.begin(), shown.end(), (int) i) != shown.end());
            menu.showMenuAsync (juce::PopupMenu::Options().withTargetComponent (&configure),
                                [safe = juce::Component::SafePointer<PluginControls> (this)] (int choice) { if (safe != nullptr && choice > 0) safe->toggle (choice - 1); });
        }
    public:
        // Shows a parameter that is hidden, or hides one that shows.
        void toggle (int parameter)
        {
            auto next = shown;
            if (auto at = std::find (next.begin(), next.end(), parameter); at != next.end()) next.erase (at); else next.push_back (parameter);
            owner.report (owner.session.setPluginConfiguration (pluginId, next)); owner.refresh();
        }
    private:
        Impl& owner;
        juce::String pluginId;
        juce::TextButton configure { "Configure" };
        std::vector<int> shown;
        size_t parameterCount = 0;
        std::vector<std::unique_ptr<Control>> controls;
        bool hasSidechain = false;
        Session::SidechainSettings sidechain;
        juce::TextButton sidechainOn { "Sidechain" };
        juce::ComboBox sidechainSource, sidechainTap;
        juce::StringArray sourceIds, sourceNames;
    public:
        // The sidechain controls, for the UI suite.
        juce::Button& sidechainSwitch() { return sidechainOn; }
        juce::ComboBox& sidechainSourceChooser() { return sidechainSource; }
        juce::ComboBox& sidechainTapChooser() { return sidechainTap; }
    };

    // One device in the inline chain: a title bar (on/off, name, window, remove)
    // over the device's own compact controls.
    class DevicePanel final : public juce::Component
    {
    public:
        DevicePanel (Impl& o, const Session::PluginInfo& info) : owner (o), pluginId (info.id), native (info.isNativeEffect)
        {
            for (auto* button : { &power, &open, &remove })
            { addAndMakeVisible (*button); button->setWantsKeyboardFocus (false); button->setMouseClickGrabsKeyboardFocus (false); }
            power.setClickingTogglesState (true); power.setName ("Device on");
            power.setTooltip ("Turn this device on or off (bypass)");
            power.setColour (juce::TextButton::buttonOnColourId, themes::colour (0xffffcf4a)); power.setColour (juce::TextButton::textColourOnId, themes::colour (0xff1a1a1a));
            open.setTooltip ("Open this device in its own window"); remove.setTooltip ("Remove this device");
            power.onClick = [this] { if (const int p = index(); p >= 0) owner.report (owner.session.setPluginEnabled (owner.deviceChainId(), p, power.getToggleState())); owner.refresh(); };
            open.onClick = [this] { if (const int p = index(); p >= 0) owner.report (owner.session.showPluginEditor (owner.deviceChainId(), p)); };
            remove.onClick = [this] { if (const int p = index(); p >= 0) owner.report (owner.session.removePlugin (owner.deviceChainId(), p)); owner.refresh(); };
            if (native)
            {
                const auto automation = [safe = juce::Component::SafePointer<Impl> (&owner)] (const juce::String& id, int parameter) { if (safe != nullptr) safe->showAutomation (false, id, parameter); };
                body = info.isRack ? makeRackEditor (owner.session, info.id, automation)
                                   : makeNativeEffectEditor (owner.session, info.id, true, [automation, id = info.id] (int parameter) { automation (id, parameter); });
                addAndMakeVisible (*body);
            }
            else if (! info.isUtility) { controls = std::make_unique<PluginControls> (owner, info.id); addChildComponent (*controls); }
            // The title selects the device for Cmd/Ctrl+G grouping and deletion.
            setWantsKeyboardFocus (true);
            rack = info.isRack; chains = (int) info.chains.size();
            sync (info);
        }
        const juce::String& getId() const noexcept { return pluginId; }
        int preferredWidth() const { return native && body ? body->getWidth() + 2 : controls != nullptr && ! missing ? controls->preferredWidth() + 2 : 184; }
        void sync (const Session::PluginInfo& info)
        {
            name = info.name; enabled = info.enabled; chains = (int) info.chains.size();
            midi = info.isNativeEffect && effectIsMidi (info.effect.kind);
            missing = info.missing; loadError = info.loadError;
            power.setToggleState (info.enabled, juce::dontSendNotification);
            power.getProperties().set ("midiMapTarget", "device:" + pluginId + ":on");
            power.setTitle (name + " on"); open.setTitle ("Open " + name + " in its own window"); remove.setTitle ("Remove " + name);
            open.setEnabled (! missing); open.setTooltip (missing ? "This plug-in is missing" : "Open this device in its own window");
            if (controls != nullptr) { controls->setVisible (! missing); if (! missing) controls->sync (info); }
            repaint();
        }
        void resized() override
        {
            auto title = getLocalBounds().removeFromTop (titleHeight).reduced (2);
            power.setBounds (title.removeFromLeft (18)); remove.setBounds (title.removeFromRight (18)); open.setBounds (title.removeFromRight (22));
            if (body) body->setTopLeftPosition (1, titleHeight);
            if (controls) controls->setBounds (1, titleHeight, getWidth() - 2, getHeight() - titleHeight - 1);
        }
        void paint (juce::Graphics& g) override
        {
            const bool selected = owner.selectedDevices.contains (pluginId);
            g.fillAll (themes::colour (0xff303030));
            g.setColour (selected ? themes::colour (0xff5e5e5e) : enabled ? themes::colour (0xff4a4a4a) : themes::colour (0xff383838)); g.fillRect (0, 0, getWidth(), titleHeight);
            g.setColour (enabled ? ink : muted); g.setFont (font (11.0f, true));
            g.drawText (name, 24, 0, getWidth() - 70, titleHeight, juce::Justification::centredLeft, true);
            if (! native && missing)
            {
                g.setColour (red); g.setFont (font (10.5f, true));
                auto area = getLocalBounds().withTrimmedTop (titleHeight).reduced (10);
                g.drawText ("Missing plug-in", area.removeFromTop (18), juce::Justification::centred);
                g.setColour (muted); g.setFont (font (10.0f));
                g.drawFittedText ((loadError.isNotEmpty() ? loadError + "\n" : juce::String()) + "Its settings are kept. Scan it and reopen the project.", area, juce::Justification::centredTop, 5);
            }
            else if (! native && controls == nullptr)
            {
                g.setColour (muted); g.setFont (font (10.5f));
                g.drawFittedText (enabled ? juce::String (midi ? "Processing MIDI." : "Processing audio.") + "\nOpen its window for every control." : "Bypassed.",
                                  getLocalBounds().withTrimmedTop (titleHeight).reduced (10), juce::Justification::centred, 3);
            }
            if (! enabled) { g.setColour (themes::colour (0xff000000).withAlpha (0.25f)); g.fillRect (getLocalBounds().withTrimmedTop (titleHeight)); }
            g.setColour (selected ? orange : line); g.drawRect (getLocalBounds());
        }
        bool keyPressed (const juce::KeyPress& key) override { return owner.deviceKey (key); }
        void mouseDown (const juce::MouseEvent& e) override
        {
            if (e.y > titleHeight) return;
            // Clicking the title selects the device: Shift extends the selection, Cmd/Ctrl toggles it.
            if (! e.mods.isPopupMenu()) { owner.selectDevice (pluginId, e.mods); grabKeyboardFocus(); return; }
            const int p = index(); const auto* devices = owner.chainDevices(); if (p < 0 || devices == nullptr) return;
            if (! owner.selectedDevices.contains (pluginId)) owner.selectDevice (pluginId, {});
            const bool trackChain = owner.selectedChain.isEmpty();
            juce::PopupMenu menu;
            menu.addItem (1, "Move left", p > 0); menu.addItem (2, "Move right", p + 1 < (int) devices->size());
            menu.addSeparator(); menu.addItem (3, enabled ? "Deactivate" : "Activate");
            // Grouping into racks, and presets, act on tracks' chains.
            menu.addItem (5, "Group", native && trackChain); if (rack) menu.addItem (6, "Ungroup", chains <= 1 && trackChain);
            const auto& info = (*devices)[(size_t) p];
            menu.addItem (7, "Save Preset...", trackChain && owner.userLibrary != juce::File() && ((info.isNativeEffect && ! rack) || info.isUtility || (! info.isNativeEffect && ! info.missing)));
            menu.addItem (4, "Delete");
            const auto chainId = owner.deviceChainId(), id = pluginId;
            juce::Component::SafePointer<Impl> safe (&owner);
            menu.showMenuAsync (juce::PopupMenu::Options().withTargetComponent (this), [safe, chainId, id] (int choice)
            {
                if (! safe || choice == 0) return;
                const auto* now = safe->chainDevices();
                if (now == nullptr || safe->deviceChainId() != chainId) return;
                for (int p = 0; p < (int) now->size(); ++p)
                    if ((*now)[(size_t) p].id == id)
                    {
                        const auto device = (*now)[(size_t) p];
                        if (choice <= 2) safe->report (safe->session.movePlugin (chainId, p, p + (choice == 1 ? -1 : 1)));
                        else if (choice == 3) safe->report (safe->session.setPluginEnabled (chainId, p, ! device.enabled));
                        else if (choice == 5) safe->groupSelectedDevices();
                        else if (choice == 6) { safe->report (safe->session.ungroupRack (id)); safe->selectedDevices.clear(); }
                        else if (choice == 7)
                        {
                            safe->savePresetDialog (id, device.isUtility ? juce::String ("Utility") : device.isNativeEffect ? juce::String (effectName (device.effect.kind)) : device.name);
                            return;
                        }
                        else safe->report (safe->session.removePlugin (chainId, p));
                        safe->refresh(); return;
                    }
            });
        }
        static constexpr int titleHeight = 22;
    private:
        int index() const
        {
            if (const auto* devices = owner.chainDevices())
                for (int p = 0; p < (int) devices->size(); ++p) if ((*devices)[(size_t) p].id == pluginId) return p;
            return -1;
        }
        Impl& owner;
        juce::String pluginId, name, loadError;
        bool native = false, enabled = true, midi = false, rack = false, missing = false;
        int chains = 0;
        juce::TextButton power { "" }, open { "^" }, remove { "x" };
        std::unique_ptr<juce::Component> body;
    public:
        std::unique_ptr<PluginControls> controls; // A hosted plug-in's configured parameters.
    };

    class DeviceChain final : public juce::Component
    {
    public:
        explicit DeviceChain (Impl& o) : owner (o), synthPanel (o), sendsPanel (o)
        {
            addAndMakeVisible (addButton); addAndMakeVisible (manageButton); addAndMakeVisible (automationButton); addAndMakeVisible (chainView); addAndMakeVisible (sendsPanel);
            chainView.setViewedComponent (&chain, false); chainView.setScrollBarsShown (false, true); chainView.setScrollBarThickness (8);
            chain.addAndMakeVisible (synthPanel);
            addButton.onClick = [this] { owner.addPluginMenu(); };
            manageButton.onClick = [this] { owner.showPlugins(); };
            automationButton.setName ("Track automation");
            automationButton.setTooltip ("Draw track volume, track pan, or master volume changes across the arrangement.");
            automationButton.onClick = [this] { owner.showAutomation (owner.selectedChain == Session::mainChain); };
            addAndMakeVisible(masterGain);masterGain.setName("Main volume");
            masterGain.setSliderStyle(juce::Slider::LinearVertical);masterGain.setNormalisableRange(Session::levelRange(false));
            masterGain.setTextBoxStyle(juce::Slider::TextBoxBelow,false,49,20);masterGain.setDoubleClickReturnValue(true,0);
            masterGain.setTooltip("Main output level. Double-click for 0 dB. The bottom of the fader is silence.");
            masterGain.textFromValueFunction=[](double value){return value<=-100?juce::String("-inf dB"):juce::String(value,1)+" dB";};
            masterGain.valueFromTextFunction=[this](juce::String text)
            {
                text=text.trim();if(text.endsWithIgnoreCase("dB"))text=text.dropLastCharacters(2).trim();
                if(text.equalsIgnoreCase("-inf"))return -100.0;
                const auto value=text.toStdString();char* end=nullptr;const double gain=std::strtod(value.c_str(),&end);
                return !value.empty()&&end==value.c_str()+value.size()&&std::isfinite(gain)?gain:(double)owner.state.masterGainDb;
            };
            masterGain.onDragStart = [this]
            {
                const auto current = owner.session.snapshot();
                if (masterProjectGeneration != current.projectGeneration) { owner.refresh(); return; }
                if (owner.session.isExporting()) return;
                masterGestureGeneration = current.projectGeneration; owner.session.beginEditGesture ("Main volume");
            };
            masterGain.onDragEnd = [this]
            {
                if (masterGestureGeneration == owner.session.snapshot().projectGeneration) owner.session.endEditGesture();
                masterGestureGeneration.reset();
            };
            masterGain.onValueChange = [this]
            {
                const auto generation = owner.session.snapshot().projectGeneration;
                if (masterProjectGeneration == generation && (! masterGestureGeneration || *masterGestureGeneration == generation))
                    owner.report (owner.session.setMasterGain ((float) masterGain.getValue()));
                owner.refresh();
            };
        }
        void resized() override
        {
            masterGain.setBounds(getWidth()-98,32,49,getHeight()-42);
            manageButton.setBounds (getWidth() - 212, 5, 94, 22);
            addButton.setBounds (getWidth() - 320, 5, 101, 22);
            automationButton.setBounds (getWidth() - 427, 5, 100, 22);
            sendsPanel.setBounds (9, 32, 232, getHeight() - 40);
            chainView.setBounds (chainLeft(), 32, getWidth() - chainLeft() - 114, getHeight() - 36);
            layoutChain();
        }
        void sync()
        {
            // A group's or the Main's chain has audio devices only; a track's has its instrument too.
            const auto* track = owner.selectedChain.isEmpty() ? owner.currentTrack() : nullptr;
            const auto* devices = owner.chainDevices();
            sendsPanel.sync();
            const bool projectChanged = masterProjectGeneration != owner.state.projectGeneration;
            if (projectChanged) masterGain.hideTextBox (true);
            masterProjectGeneration = owner.state.projectGeneration;
            if (projectChanged || ! masterGain.isMouseButtonDown()) masterGain.setValue (owner.state.masterGainDb, juce::dontSendNotification);
            masterGain.setEnabled (! owner.session.isExporting());
            showAutomationState (masterGain, owner.state.masterVolumeAutomation, "Main output level. Double-click for 0 dB. The bottom of the fader is silence.", "Master volume");
            masterGain.getProperties().set ("midiMapTarget", "master");
            automationButton.setEnabled (! owner.session.isExporting());
            addButton.setEnabled (devices != nullptr);
            // Rebuild panels only when the device list itself changes.
            std::vector<juce::String> ids;
            if (devices != nullptr) for (const auto& p : *devices) ids.push_back (p.id);
            bool same = ids.size() == panels.size();
            for (size_t i = 0; same && i < ids.size(); ++i) same = panels[i]->getId() == ids[i];
            if (! same)
            {
                panels.clear();
                if (devices != nullptr) for (const auto& p : *devices) { panels.push_back (std::make_unique<DevicePanel> (owner, p)); chain.addAndMakeVisible (*panels.back()); }
            }
            else if (devices != nullptr) for (size_t i = 0; i < panels.size(); ++i) panels[i]->sync ((*devices)[i]);
            synthPanel.sync(); layoutChain();
            // A frozen track's devices play from its render and cannot change until it is unfrozen.
            const bool frozen = track != nullptr && track->frozen;
            for (auto* c : std::initializer_list<juce::Component*> { &chain, &synthPanel })
            { c->setEnabled (! frozen); c->setAlpha (frozen ? .45f : 1.0f); }
            addButton.setEnabled (devices != nullptr && ! frozen);
            repaint();
        }
        void paint (juce::Graphics& g) override
        {
            g.fillAll (themes::colour (0xff262626));
            g.setColour (line); g.drawHorizontalLine (0, 0.0f, (float) getWidth());
            g.setColour (muted); g.setFont (font (10.0f, true));
            const auto* track = owner.selectedChain.isEmpty() ? owner.currentTrack() : nullptr;
            const auto* devices = owner.chainDevices();
            const auto chainName = owner.chainTitle();
            auto title = chainName.isEmpty() ? juce::String ("DEVICES") : "DEVICES  /  " + chainName.toUpperCase();
            g.drawText (title, 14, 5, juce::jmax (150, getWidth() - 455), 22, juce::Justification::centredLeft);
            if (devices == nullptr || ((track == nullptr || ! track->isMidi) && devices->empty()))
            {
                const auto hint = chainView.getBounds().reduced (6, 8);
                g.setColour (themes::colour (0xff3a3a3a)); g.drawRect (hint);
                g.setColour (muted); g.setFont (font (12.0f));
                g.drawText (devices == nullptr ? "Select a track to view its devices." : "Drop Audio Effects Here", hint.withTrimmedBottom (24), juce::Justification::centred);
                g.setFont (font (10.5f));
                g.drawText ("Use + Device or the browser. Audio flows left to right.", hint.withTrimmedTop (30), juce::Justification::centred);
            }
            paintMaster (g);
        }
    private:
        Impl& owner;
        juce::TextButton addButton { "+ Device" }, manageButton { "Manage..." }, automationButton { "Automation" };
        SynthPanel synthPanel;
        juce::Slider masterGain;
        std::optional<uint64_t> masterGestureGeneration;
        uint64_t masterProjectGeneration = 0;
        juce::Viewport chainView;
        juce::Component chain;
        std::vector<std::unique_ptr<DevicePanel>> panels;
        SendsPanel sendsPanel;
        int chainLeft() const { return sendsPanel.isVisible() ? 250 : 9; }
        // MIDI effects, then the instrument, then audio devices, left to right.
        void layoutChain()
        {
            const auto* track = owner.selectedChain.isEmpty() ? owner.currentTrack() : nullptr;
            const int height = juce::jmax (1, chainView.getHeight() - 10);
            int x = 4;
            auto place = [&] (juce::Component& c, int width) { c.setBounds (x, 2, width, height); x += width + 4; };
            size_t i = 0;
            if (track != nullptr) for (; i < panels.size() && i < track->plugins.size() && track->plugins[i].isNativeEffect && effectIsMidi (track->plugins[i].effect.kind); ++i)
                place (*panels[i], panels[i]->preferredWidth());
            // A hosted instrument plays instead of the built-in synth, and shows as its own device.
            synthPanel.setVisible (track != nullptr && track->isMidi && std::none_of (track->plugins.begin(), track->plugins.end(), [] (const auto& p) { return p.isInstrument; }));
            if (synthPanel.isVisible()) place (synthPanel, synthPanel.preferredWidth());
            for (; i < panels.size(); ++i) place (*panels[i], panels[i]->preferredWidth());
            chain.setSize (juce::jmax (x, chainView.getWidth()), height + 2);
        }
        void paintMaster (juce::Graphics& g)
        {
            auto box = getLocalBounds().removeFromRight (107).reduced (8, 8);
            g.setColour (background); g.fillRect (box);
            g.setColour (muted); g.setFont (font (9.5f, true));
            g.drawText ("MAIN", box.removeFromTop (23), juce::Justification::centred);
            auto meterArea = box.withTrimmedLeft(60).reduced(0,12);
            auto meter = [&] (float peak, int x)
            {
                auto rect = juce::Rectangle<int> (x, meterArea.getY(), 8, meterArea.getHeight() - 17);
                g.setColour (line); g.fillRect (rect);
                const auto fraction = juce::jlimit (0.0f, 1.0f, (juce::Decibels::gainToDecibels (peak, -60.0f) + 60.0f) / 60.0f);
                g.setColour (peak >= 1.0f ? red : green);
                g.fillRect (rect.removeFromBottom ((int) (rect.getHeight() * fraction)));
            };
            meter (owner.state.masterPeakL, meterArea.getX() + 2);
            meter (owner.state.masterPeakR, meterArea.getX() + 16);
            g.setColour (muted); g.setFont (font (9.0f));
            g.drawText ("L  R", meterArea.withTrimmedTop (meterArea.getHeight() - 15), juce::Justification::centredLeft);
        }
    };

