    void showComputerKeyboardRange()
    {
        status = "Computer MIDI Keyboard: A plays C" + juce::String (computerKeys.octave()) + ", velocity " + juce::String (computerKeys.velocity());
        statusFrames = 72; repaint();
    }
    // A key while the computer keyboard is on: a note key or Z X C V is played and kept from
    // other shortcuts, as in the reference.
    bool computerKeyboardKey (const juce::KeyPress& key)
    {
        if (! session.isComputerKeyboardEnabled() || key.getModifiers().isCommandDown() || key.getModifiers().isAltDown() || key.getModifiers().isCtrlDown()) return false;
        const auto character = key.getTextCharacter();
        if (! ComputerKeyboard::handles (character)) return false;
        for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
            if (dynamic_cast<juce::TextEditor*> (focused)) return false;
        const auto octave = computerKeys.octave(), velocity = computerKeys.velocity();
        if (const auto event = computerKeys.press (key.getKeyCode(), character)) report (session.computerKeyboardNote (event->note, event->velocity, true));
        if (octave != computerKeys.octave() || velocity != computerKeys.velocity()) showComputerKeyboardRange();
        return true;
    }
    void releaseComputerKeys()
    {
        if (! computerKeys.holding()) return;
        for (const auto& event : computerKeys.release ([] (int code) { return juce::KeyPress::isKeyCurrentlyDown (code); }))
            session.computerKeyboardNote (event.note, 0, false);
    }
    bool keyStateChanged (bool) override { releaseComputerKeys(); releaseMappedKeys(); releaseLatches(); return false; }
    // Momentary latching, as the reference's: A, B, S, Z, Tab and F1 to F8 act when pressed; held for
    // about 500 ms, letting go returns what they changed (Z zooming back). Their repeats while held do
    // nothing. The key state and clock can be stood in for by the tests.
    struct Latch { int code = 0, keyCode = 0; juce::uint32 pressedAt = 0; juce::KeyPress press; };
    std::vector<Latch> latches;
    bool replayingLatch = false;
    std::function<bool (int)> keyIsDown = [] (int code) { return juce::KeyPress::isKeyCurrentlyDown (code); };
    std::function<juce::uint32()> latchClock = [] { return juce::Time::getMillisecondCounter(); };
    static constexpr juce::uint32 latchMilliseconds = 500;
    // A repeat of a held latching key, consumed; otherwise nothing, the key acting as it does.
    std::optional<bool> latchKey (const juce::KeyPress& key)
    {
        if (replayingLatch || key.getModifiers().isAnyModifierKeyDown()) return std::nullopt;
        const auto keyCode = key.getKeyCode();
        const auto code = keyCode < 256 ? (int) juce::CharacterFunctions::toUpperCase ((juce::juce_wchar) keyCode) : keyCode;
        if (! (code == 'A' || code == 'B' || code == 'S' || code == 'Z' || code == juce::KeyPress::tabKey || (code >= juce::KeyPress::F1Key && code <= juce::KeyPress::F8Key)))
            return std::nullopt;
        for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
            if (dynamic_cast<juce::TextEditor*> (focused)) return std::nullopt;
        for (const auto& held : latches) if (held.code == code && keyIsDown (held.keyCode)) return true;
        std::erase_if (latches, [code] (const Latch& l) { return l.code == code; });
        // Only a key that is down can be held; a press sent without one acts and is done.
        if (keyIsDown (keyCode)) latches.push_back ({ code, keyCode, latchClock(), key });
        return std::nullopt;
    }
    void releaseLatches()
    {
        for (auto it = latches.begin(); it != latches.end();)
        {
            if (keyIsDown (it->keyCode)) { ++it; continue; }
            const auto latch = *it; it = latches.erase (it);
            if (latchClock() - latch.pressedAt < latchMilliseconds) continue;
            replayingLatch = true;
            if (latch.code == 'Z') zoomBackFromSelection(); else handleKey (latch.press);
            replayingLatch = false;
            it = latches.begin();
        }
    }
    // Mapped keys being held, by key code: a held key does not press again as it repeats, and its
    // release releases a clip slot it pressed, as the reference's keys follow a clip's Launch Mode.
    std::map<int, juce::juce_wchar> heldMappedKeys;
    void releaseMappedKeys()
    {
        for (auto held = heldMappedKeys.begin(); held != heldMappedKeys.end();)
            if (juce::KeyPress::isKeyCurrentlyDown (held->first)) ++held;
            else { report (session.releaseMappedKey (held->second)); held = heldMappedKeys.erase (held); refresh(); }
    }
    void setMidiMapMode (bool on)
    {
        if (on && keyMapMode) setKeyMapMode (false);
        midiMapMode = on;
        if (! on) session.setMidiLearnTarget ({});
        midiMapButton.setToggleState (on, juce::dontSendNotification);
        resized(); refresh();
    }
    // Key Map Mode: the overlay marks what can be mapped in orange; click a control, then press a key.
    bool keyMapMode = false;
    juce::TextButton keyMapButton { "KEY" };
    bool mapping() const noexcept { return midiMapMode || keyMapMode; }
    void setKeyMapMode (bool on)
    {
        if (on && midiMapMode) setMidiMapMode (false);
        keyMapMode = on;
        if (! on) session.setKeyLearnTarget ({});
        keyMapButton.setToggleState (on, juce::dontSendNotification);
        resized(); refresh();
    }
    // A key that Key Map Mode maps, or a mapped key that presses its target. Typing in a text field,
    // and keys with Command, Option or Control, are left alone.
    bool mappedKey (const juce::KeyPress& key)
    {
        const auto mods = key.getModifiers();
        if (mods.isCommandDown() || mods.isAltDown() || mods.isCtrlDown()) return false;
        for (auto* focused = juce::Component::getCurrentlyFocusedComponent(); focused; focused = focused->getParentComponent())
            if (dynamic_cast<juce::TextEditor*> (focused)) return false;
        if (keyMapMode && state.keyLearnTarget.isNotEmpty()
            && (key.getKeyCode() == juce::KeyPress::backspaceKey || key.getKeyCode() == juce::KeyPress::deleteKey))
        {
            report (session.removeKeyMapping (state.keyLearnTarget)); refresh(); return true;
        }
        if (keyMapMode && state.keyLearnTarget.isEmpty()) return false;
        if (heldMappedKeys.count (key.getKeyCode()) != 0) return true; // Repeating while held.
        bool used = false;
        const auto result = session.handleMappedKey (key.getTextCharacter(), used);
        if (! used) return false;
        heldMappedKeys[key.getKeyCode()] = key.getTextCharacter();
        report (result); refresh(); return true;
    }
