    void saveTemplateDialog()
    {
        if (userLibrary == juce::File()) return;
        auto* dialog = new juce::AlertWindow ("Save as Template", "Name the template. It is kept in the User Library's Templates folder.", juce::MessageBoxIconType::NoIcon);
        dialog->addTextEditor ("name", state.name, "Name");
        dialog->addButton ("Save", 1, juce::KeyPress (juce::KeyPress::returnKey)); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this); auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog] (int result)
        {
            if (! safe || ! safeDialog || result != 1) return;
            const auto name = safeDialog->getTextEditorContents ("name").trim();
            if (name.isEmpty()) { safe->report (juce::Result::fail ("A template needs a name.")); return; }
            const auto file = safe->templateFolder().getChildFile (juce::File::createLegalFileName (name) + ".halftrack");
            if (! file.exists()) { safe->report (safe->saveTemplate (file), "Saved the template " + name + "."); return; }
            // Replacing an existing template is the user's choice.
            juce::AlertWindow::showAsync (juce::MessageBoxOptions().withIconType (juce::MessageBoxIconType::QuestionIcon).withTitle ("Replace template?")
                .withMessage (name + " already exists. Replace it?").withButton ("Replace").withButton ("Cancel"),
                [safe, file, name] (int choice) { if (safe && choice == 1) safe->report (safe->saveTemplate (file), "Replaced the template " + name + "."); });
        }), true);
    }
    void openTemplate (const juce::File& file)
    {
        auto safe = juce::Component::SafePointer<Impl> (this);
        ensureSaved ([safe, file]
        {
            if (safe == nullptr) return;
            safe->session.closePluginEditors();
            safe->report (safe->session.newProjectFromDefaultSet (file)); safe->resetView();
        });
    }
    // A template's Set Default Set, as the reference's context menu has it: new projects start from it.
    void setDefaultSetFrom (const juce::File& file)
    {
        const auto target = defaultSetFile();
        if (target == juce::File()) return;
        juce::TemporaryFile temporary (target);
        if (! file.copyFileTo (temporary.getFile()) || ! temporary.overwriteTargetFileWithTemporary())
        { report (juce::Result::fail ("The default set could not be written to " + target.getFullPathName() + ".")); return; }
        report (juce::Result::ok(), file.getFileNameWithoutExtension() + " is now the default set for new projects.");
    }
    // Save as Default Audio/MIDI Track's files, where the reference keeps its own in a library.
    juce::File defaultTrackFile (bool midi) const
    {
        if (userLibrary == juce::File()) return {};
        return userLibrary.getChildFile ("Defaults").getChildFile ("Creating Tracks").getChildFile (midi ? "MIDI Track" : "Audio Track")
                          .getChildFile (midi ? "Default MIDI Track.halftrack" : "Default Audio Track.halftrack");
    }
    // Rows for a device's presets, after its own row.
    void addPresetRows (std::vector<DeviceRow>& rows, const juce::String& device, int kind, const std::function<bool (const juce::String&)>& matches)
    {
        const auto folder = presetFolder (device);
        if (! folder.isDirectory()) return;
        auto files = folder.findChildFiles (juce::File::findFiles, false, juce::String ("*") + Session::presetExtension);
        files.sort();
        for (const auto& file : files)
            if (matches (device) || matches (file.getFileNameWithoutExtension())) rows.push_back ({ file.getFileNameWithoutExtension(), false, kind, file });
    }
    void startNewProject()
    {
        // New projects start from the default set when one has been saved, and otherwise from one like
        // the reference's built-in default Set.
        const auto template_ = defaultSetFile();
        report (template_.existsAsFile() ? session.newProjectFromDefaultSet (template_) : session.newBuiltInDefaultProject()); resetView();
    }
    void savePresetDialog (const juce::String& pluginId, const juce::String& device)
    {
        if (userLibrary == juce::File()) return;
        auto* dialog = new juce::AlertWindow ("Save preset", "Name this " + device + " preset.", juce::MessageBoxIconType::NoIcon);
        dialog->addTextEditor ("name", device, "Name");
        dialog->addButton ("Save", 1, juce::KeyPress (juce::KeyPress::returnKey)); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this); auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog, pluginId, device] (int result)
        {
            if (! safe || ! safeDialog || result != 1) return;
            const auto name = safeDialog->getTextEditorContents ("name").trim();
            const auto file = safe->presetFolder (device).getChildFile (juce::File::createLegalFileName (name) + Session::presetExtension);
            if (! file.exists()) { safe->report (safe->session.saveDevicePreset (pluginId, file, name), "Saved preset " + name + "."); safe->updateBrowser(); return; }
            // Replacing an existing preset is the user's choice.
            juce::AlertWindow::showAsync (juce::MessageBoxOptions().withIconType (juce::MessageBoxIconType::QuestionIcon).withTitle ("Replace preset?")
                .withMessage (name + " already exists. Replace it?").withButton ("Replace").withButton ("Cancel"),
                [safe, pluginId, file, name] (int choice)
                { if (safe && choice == 1) { safe->report (safe->session.saveDevicePreset (pluginId, file, name, true), "Replaced preset " + name + "."); safe->updateBrowser(); } });
        }), true);
    }
    std::vector<DeviceRow> deviceItems;
    bool showPiano = false, showSession = false;
    juce::String selectedSceneId, selectedLauncherClipId;
    double viewStart = 0, pixelsPerSecond = 35, recordingStart = 0;

    void applyMetronomeMenu (int item)
    {
        auto settings=session.snapshot().metronome;
        if(item==1) settings.accent=!settings.accent;
        else if(item==2) settings.recordingOnly=!settings.recordingOnly;
        else if(item>=10 && item<=12) settings.countInBars=item-10;
        else if(item==14) settings.countInBars=4;
        else if(item>=21 && item<=25) settings.gain=(item-20)*.2f;
        else if(item>=40 && item<50) settings.rhythm=Session::metronomeRhythms()[(size_t)(item-40)].value;
        else if(item>=31 && item<31+Session::metronomeSoundCount)
        {
            auto preferences=session.preferences();preferences.metronomeSound=static_cast<Session::MetronomeSound>(item-31);
            report(session.setPreferences(preferences));refresh();return;
        }
        else return;
        report(session.setMetronome(settings));refresh();
    }
    void showMetronomeMenu()
    {
        const auto settings=session.snapshot().metronome;
        // Laid out as the reference's metronome menu: Count-In, Sound, then its switches.
        juce::PopupMenu menu, level;
        menu.addSectionHeader("Count-In");
        menu.addItem(10,"None",!state.recording,settings.countInBars==0);
        menu.addItem(11,"1 Bar",!state.recording,settings.countInBars==1);
        menu.addItem(12,"2 Bars",!state.recording,settings.countInBars==2);
        menu.addItem(14,"4 Bars",!state.recording,settings.countInBars==4);
        menu.addSectionHeader("Sound");
        const auto sound=session.preferences().metronomeSound;
        for(int i=0;i<Session::metronomeSoundCount;++i)
            menu.addItem(31+i,Session::metronomeSoundName(static_cast<Session::MetronomeSound>(i)),true,(int)sound==i);
        // Divisions that do not divide the project's bar are disabled, as the reference's are.
        menu.addSectionHeader("Rhythm");
        const auto rhythms=Session::metronomeRhythms();
        for(size_t i=0;i<rhythms.size();++i)
            menu.addItem(40+(int)i,rhythms[i].name,Session::metronomeRhythmFits(rhythms[i].value,state.timeSignature),settings.rhythm==rhythms[i].value);
        menu.addSeparator();
        menu.addItem(2,"Enable Only While Recording",true,settings.recordingOnly);
        menu.addItem(1,"Accent First Beat",true,settings.accent);
        for(int i=1;i<=5;++i)level.addItem(20+i,juce::String(i*20)+"%",true,std::abs(settings.gain-i*.2f)<.001f);
        menu.addSubMenu("Click Level",level);
        const auto safe=juce::Component::SafePointer<Impl>(this);
        menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(&clickSettingsButton),[safe](int item)
            {if(safe) safe->applyMetronomeMenu(item);});
    }
    void showSessionView()
    {
        showSession = true; showPiano = false;
        if (selectedTrack >= 0 && selectedSceneIndex() >= 0) selectLauncherSlot (selectedTrack, selectedSceneIndex());
        resized(); launcher.grabKeyboardFocus();
    }
    void closeClipView() { showPiano = false; resized(); }
    void showArrangementView()
    {
        showSession = false; showPiano = false; selectedLauncherClipId.clear(); resized();
    }
    void addSceneFromUI()
    {
        const auto result = session.addScene(); report (result); refresh();
        if (result.wasOk() && ! state.scenes.empty()) selectedSceneId = state.scenes.back().id;
        launcher.scrollSelectionIntoView();
    }
    std::pair<int, int> launcherIndices (const juce::String& trackId, const juce::String& sceneId) const
    {
        int track = -1, scene = -1;
        for (int i = 0; i < (int) state.tracks.size(); ++i) if (state.tracks[(size_t) i].id == trackId) { track = i; break; }
        for (int i = 0; i < (int) state.scenes.size(); ++i) if (state.scenes[(size_t) i].id == sceneId) { scene = i; break; }
        return { track, scene };
    }
    int selectedSceneIndex() const { return launcherIndices ({}, selectedSceneId).second; }
    const Session::SlotInfo* selectedSlot() const
    {
        const auto* track = currentTrack(); const int scene = selectedSceneIndex();
        return track != nullptr && scene >= 0 && scene < (int) track->slots.size() ? &track->slots[(size_t) scene] : nullptr;
    }
    const Session::SlotInfo* editedLauncherSlot() const
    {
        if (const auto* track = currentTrack()) for (const auto& slot : track->slots) if (slot.hasClip && slot.clip.id == selectedLauncherClipId) return &slot;
        return nullptr;
    }
    void selectLauncherSlot (int track, int scene)
    {
        if (track < 0 || track >= (int) state.tracks.size() || scene < 0 || scene >= (int) state.scenes.size()) return;
        selectTrack (track); selectedClip = -1;
        if (currentTrack()->isReturn) { selectedLauncherClipId.clear(); return; }
        selectedSceneId = state.scenes[(size_t) scene].id;
        const auto* slot = selectedSlot(); selectedLauncherClipId = slot != nullptr && slot->hasClip ? slot->clip.id : juce::String();
        pianoRoll.sync(); launcher.repaint(); deviceChain.sync();
    }
    // The selected slot's Cut (84), Copy (85), Paste (86) and Duplicate (87), as in the reference's
    // Session View. A duplicate is selected where it went.
    bool slotCommand (int command)
    {
        const auto scene = selectedSceneIndex();
        if (currentTrack() == nullptr || scene < 0 || currentTrack()->isReturn) return false;
        if (selectedSlots.size() > 1 && command != 86)
        {
            if (command == 87) return duplicateSlotGroup();
            report (session.copySlotClips (selectedSlotClips(), command == 84), command == 84 ? "Cut the clips." : "Copied the clips.");
            refresh(); return true;
        }
        if (command == 84 || command == 85) report (session.copySlotClip (selectedTrack, scene, command == 84), command == 84 ? "Cut the clip." : "Copied the clip.");
        if (command == 86) report (session.pasteSlotClip (selectedTrack, scene));
        if (command == 87)
        {
            int to = -1;
            const auto result = session.duplicateSlotClip (selectedTrack, scene, to);
            report (result);
            if (result.wasOk()) { refresh(); selectLauncherSlot (selectedTrack, to); return true; }
        }
        refresh(); selectLauncherSlot (selectedTrack, selectedSceneIndex()); return true;
    }
    void clearSelectedSlot()
    {
        if (selectedSlots.size() > 1) { report (session.clearSlots (selectedSlots)); selectedSlots.clear(); selectedLauncherClipId.clear(); refresh(); return; }
        const auto scene = selectedSceneIndex(); if (currentTrack() == nullptr || scene < 0 || currentTrack()->isReturn) return;
        report (session.clearSlot (selectedTrack, scene)); selectedLauncherClipId.clear(); refresh();
    }
    // Session slots selected together, as in the reference: Shift-click takes in the rectangle from
    // the selected slot, Cmd-click (Ctrl elsewhere) adds or removes one, and a drag from an empty slot
    // draws one. It holds the selected slot too while more than one is selected.
    std::vector<Session::SlotRef> selectedSlots;
    bool isSlotSelected (int track, int scene) const
    { return std::find (selectedSlots.begin(), selectedSlots.end(), Session::SlotRef { track, scene }) != selectedSlots.end(); }
    // The selected slots that hold clips.
    std::vector<Session::SlotRef> selectedSlotClips() const
    {
        std::vector<Session::SlotRef> clips;
        for (const auto& ref : selectedSlots)
            if (juce::isPositiveAndBelow (ref.track, (int) state.tracks.size()) && juce::isPositiveAndBelow (ref.scene, (int) state.tracks[(size_t) ref.track].slots.size())
                && state.tracks[(size_t) ref.track].slots[(size_t) ref.scene].hasClip) clips.push_back (ref);
        return clips;
    }
    // Every ordinary track's slot between two corners of the grid.
    std::vector<Session::SlotRef> slotRectangle (Session::SlotRef a, Session::SlotRef b) const
    {
        std::vector<Session::SlotRef> cells;
        for (int t = std::min (a.track, b.track); t <= std::max (a.track, b.track); ++t)
            if (juce::isPositiveAndBelow (t, (int) state.tracks.size()) && ! state.tracks[(size_t) t].isReturn)
                for (int sc = std::min (a.scene, b.scene); sc <= std::max (a.scene, b.scene); ++sc)
                    if (juce::isPositiveAndBelow (sc, (int) state.scenes.size())) cells.push_back ({ t, sc });
        return cells;
    }
    // Several selected clips duplicate into the slots below their span, which must be empty.
    bool duplicateSlotGroup()
    {
        const auto clips = selectedSlotClips();
        if (clips.empty()) return false;
        int top = clips[0].scene, bottom = clips[0].scene;
        for (const auto& ref : clips) { top = std::min (top, ref.scene); bottom = std::max (bottom, ref.scene); }
        const int height = bottom - top + 1;
        for (const auto& ref : clips)
            if (! juce::isPositiveAndBelow (ref.scene + height, (int) state.scenes.size()) || state.tracks[(size_t) ref.track].slots[(size_t) (ref.scene + height)].hasClip)
            { report (juce::Result::fail ("There is no room below the clips for their copies.")); return true; }
        const auto result = session.moveSlotClips (clips, 0, height, true);
        report (result); refresh();
        if (result.wasOk()) { for (auto& ref : selectedSlots) ref.scene += height; selectLauncherSlot (selectedTrack, selectedSceneIndex() + height); }
        return true;
    }
    void createLauncherMidiClip()
    {
        if (currentTrack() == nullptr || ! currentTrack()->isMidi) return;
        if (state.scenes.empty()) { report (session.addScene()); refresh(); }
        if (state.scenes.empty()) return;
        if (selectedSceneIndex() < 0) selectedSceneId = state.scenes.front().id;
        if (const auto* slot = selectedSlot(); slot != nullptr && slot->hasClip)
        {
            if (slot->clip.isMidi) { selectedLauncherClipId = slot->clip.id; openPianoRoll(); }
            return;
        }
        const auto track = selectedTrack, scene = selectedSceneIndex();
        const auto result = session.addMidiClipToSlot (currentTrack()->id, scene, 4.0); report (result); refresh();
        if (result.wasOk()) { selectLauncherSlot (track, scene); openPianoRoll(); pianoRoll.fit(); }
    }
    // Time signature markers, as the reference's: a lane under the bar numbers shows them while the
    // meter changes; Insert Time Signature Change adds one, and Edit Time Signature types its meter.
    static constexpr int meterLaneHeight = 16;
    bool meterLaneShown() const { return state.timeSignatures.size() > 1; }
    Session::BarInfo barAt (double beat) const { return Session::barAt (state.timeSignatures, beat); }
    // "3/4", "6 / 8": a meter as the Control Bar's field and the markers take it.
    static std::optional<Session::TimeSignature> parseMeter (const juce::String& text)
    {
        auto fields = juce::StringArray::fromTokens (text, "/", ""); fields.trim();
        if (fields.size() != 2 || fields[0].isEmpty() || fields[1].isEmpty() || ! fields[0].containsOnly ("0123456789") || ! fields[1].containsOnly ("0123456789"))
            return std::nullopt;
        return Session::TimeSignature { fields[0].getIntValue(), fields[1].getIntValue() };
    }
    static juce::String meterText (Session::TimeSignature m) { return juce::String (m.numerator) + "/" + juce::String (m.denominator); }
    // A marker at a beat with the meter already there, whose meter is then typed; at the start the
    // first marker's.
    void insertMeterChange (double beat)
    {
        if (beat > 1.0e-9)
        {
            const auto result = session.insertTimeSignatureChange (beat, barAt (beat).meter);
            report (result); refresh();
            if (result.failed()) return;
        }
        int index = 0;
        for (int i = 0; i < (int) state.timeSignatures.size(); ++i) if (state.timeSignatures[(size_t) i].beat <= beat + 1.0e-9) index = i;
        ruler.selectMeter (index);
        editMeterDialog (index);
    }
    void editMeterDialog (int index)
    {
        if (session.isExporting() || ! juce::isPositiveAndBelow (index, (int) state.timeSignatures.size())) return;
        auto* dialog = new juce::AlertWindow ("Edit Time Signature", "Type the meter from this marker on, such as 3/4 or 7/8.", juce::MessageBoxIconType::NoIcon);
        dialog->addTextEditor ("meter", meterText (state.timeSignatures[(size_t) index].meter), "Time signature");
        dialog->addButton ("Apply", 1, juce::KeyPress (juce::KeyPress::returnKey)); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this); auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog, index] (int result)
        {
            if (safe == nullptr || safeDialog == nullptr || result != 1) return;
            if (const auto meter = parseMeter (safeDialog->getTextEditorContents ("meter"))) safe->report (safe->session.setTimeSignatureChange (index, *meter));
            else safe->report (juce::Result::fail ("Type a time signature such as 3/4."));
            safe->refresh();
        }), true);
    }
    void editLocatorDialog (const juce::String& id)
    {
        if (session.isExporting()) return;
        for (const auto& marker : session.snapshot().locators) if (marker.id==id)
        {
            auto* dialog=new juce::AlertWindow ("Edit Locator","Name this song section and set its position in seconds.",juce::MessageBoxIconType::NoIcon);
            dialog->addTextEditor ("name",marker.name,"Name");dialog->addTextEditor ("position",juce::String(marker.position,6),"Position (s)");
            dialog->addButton ("Apply",1,juce::KeyPress(juce::KeyPress::returnKey));dialog->addButton ("Cancel",0,juce::KeyPress(juce::KeyPress::escapeKey));
            dialog->setLookAndFeel (&theme);alerts.emplace_back (dialog);
            auto safe=juce::Component::SafePointer<Impl>(this);auto safeDialog=juce::Component::SafePointer<juce::AlertWindow>(dialog);
            dialog->enterModalState (true,juce::ModalCallbackFunction::create ([safe,safeDialog,id](int result)
            {
                if(safe==nullptr||safeDialog==nullptr||result!=1)return;
                const auto text=safeDialog->getTextEditorContents("position").trim().toStdString();char* end=nullptr;
                const auto time=std::strtod(text.c_str(),&end);
                if(text.empty()||end!=text.c_str()+text.size()||!std::isfinite(time))
                    safe->report(juce::Result::fail("Enter a complete numeric locator position."));
                else safe->report(safe->session.updateLocator(id,safeDialog->getTextEditorContents("name"),time));
                safe->refresh();
            }),true);
            return;
        }
    }
    void clipFollowDialog (const juce::String& id)
    {
        if (session.isExporting()) return;
        Session::FollowSettings settings; bool found = false;
        for (const auto& track : state.tracks)
            for (const auto& slot : track.slots)
                if (slot.hasClip && slot.clip.id == id) { settings = slot.clip.follow; found = true; }
        if (! found) { report (juce::Result::fail ("Session clip not found.")); return; }
        auto* dialog = new juce::AlertWindow ("Clip Follow Action", "After the chosen beats, play action A (at its chance) or else action B. Next and Previous stop at the ends; Cycle wraps; Any picks any clip and Other any other clip. Empty slots are skipped.", juce::MessageBoxIconType::NoIcon, this);
        const juce::StringArray actions { "Stop", "Play again", "Previous clip", "Next clip", "First clip", "Last clip", "Cycle to next clip", "Any clip", "Other clip" };
        juce::StringArray first { "Off" }, second { "No action" }; first.addArray (actions); second.addArray (actions);
        dialog->addComboBox ("action", first, "Action A");
        dialog->getComboBoxComponent ("action")->setSelectedItemIndex ((int) settings.action, juce::dontSendNotification);
        dialog->addTextEditor ("beats", juce::String (settings.afterBeats > 0 ? settings.afterBeats : 4, 6).trimCharactersAtEnd ("0").trimCharactersAtEnd ("."), "After beats");
        dialog->addComboBox ("action-b", second, "Action B");
        dialog->getComboBoxComponent ("action-b")->setSelectedItemIndex ((int) settings.actionB, juce::dontSendNotification);
        dialog->addTextEditor ("chance", juce::String (settings.chanceA * 100, 2).trimCharactersAtEnd ("0").trimCharactersAtEnd ("."), "Chance of A (%)");
        for (const char* name : { "beats", "chance" }) dialog->getTextEditor (name)->setEnabled (settings.action != Session::FollowAction::off);
        dialog->getComboBoxComponent ("action-b")->setEnabled (settings.action != Session::FollowAction::off);
        dialog->addButton ("Apply", 1, juce::KeyPress (juce::KeyPress::returnKey));
        dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this);
        auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->getComboBoxComponent ("action")->onChange = [safeDialog]
        {
            if (! safeDialog) return;
            const bool on = safeDialog->getComboBoxComponent ("action")->getSelectedItemIndex() > 0;
            for (const char* name : { "beats", "chance" }) safeDialog->getTextEditor (name)->setEnabled (on);
            safeDialog->getComboBoxComponent ("action-b")->setEnabled (on);
        };
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog, id] (int result)
        {
            if (! safe || ! safeDialog || result != 1) return;
            const auto action = static_cast<Session::FollowAction> (safeDialog->getComboBoxComponent ("action")->getSelectedItemIndex());
            Session::FollowSettings next { action, 0 };
            if (action != Session::FollowAction::off)
            {
                const auto number = [] (const juce::String& field, double& value)
                {
                    const auto text = field.trim().toStdString(); char* end = nullptr; value = std::strtod (text.c_str(), &end);
                    return ! text.empty() && end == text.c_str() + text.size() && std::isfinite (value);
                };
                double chance = 100;
                if (! number (safeDialog->getTextEditorContents ("beats"), next.afterBeats))
                { safe->report (juce::Result::fail ("Enter a complete numeric beat duration.")); return; }
                if (! number (safeDialog->getTextEditorContents ("chance"), chance) || chance < 0 || chance > 100)
                { safe->report (juce::Result::fail ("Enter a chance for action A from 0 to 100%.")); return; }
                next.actionB = static_cast<Session::FollowAction> (safeDialog->getComboBoxComponent ("action-b")->getSelectedItemIndex());
                next.chanceA = chance / 100;
            }
            safe->report (safe->session.setClipFollowAction (id, next)); safe->refresh();
        }), true);
    }
    void renameClipDialog(const juce::String& id)
    {
        if(session.isExporting())return;
        juce::String name;bool found=false;
        for(const auto& track:state.tracks)
        {
            for(const auto& clip:track.clips)if(clip.id==id){name=clip.name;found=true;}
            for(const auto& slot:track.slots)if(slot.hasClip&&slot.clip.id==id){name=slot.clip.name;found=true;}
        }
        if(!found){report(juce::Result::fail("Clip not found."));return;}
        auto* dialog=new juce::AlertWindow("Rename clip","Enter a clip name.",juce::MessageBoxIconType::NoIcon);
        dialog->addTextEditor("name",name,"Name");
        dialog->addButton("Rename",1,juce::KeyPress(juce::KeyPress::returnKey));dialog->addButton("Cancel",0,juce::KeyPress(juce::KeyPress::escapeKey));
        dialog->setLookAndFeel(&theme);alerts.emplace_back(dialog);
        auto safe=juce::Component::SafePointer<Impl>(this);auto safeDialog=juce::Component::SafePointer<juce::AlertWindow>(dialog);
        dialog->enterModalState(true,juce::ModalCallbackFunction::create([safe,safeDialog,id](int result)
        {
            if(!safe||!safeDialog||result!=1)return;
            safe->report(safe->session.renameClip(id,safeDialog->getTextEditorContents("name")));safe->refresh();
        }),true);
    }
    void moveSceneFromUI (const juce::String& id, int delta)
    {
        const auto stableId = id;
        refresh();
        const auto index = launcherIndices ({}, stableId).second;
        if (index < 0) return;
        report (session.moveScene (stableId, index + delta));
        refresh(); launcher.scrollSelectionIntoView();
    }
    void duplicateSceneFromUI(const juce::String& id)
    {
        juce::String created;const auto result=session.duplicateScene(id,created);report(result);refresh();
        if(result.wasOk())
        {
            const auto index=launcherIndices({},created).second;
            selectedSceneId=created;
            if(selectedTrack>=0)selectLauncherSlot(selectedTrack,index);
            launcher.scrollSelectionIntoView();refresh();
        }
    }
    void renameSceneDialog (int scene)
    {
        if (scene < 0 || scene >= (int) state.scenes.size()) return;
        const auto id = state.scenes[(size_t) scene].id;
        auto* dialog = new juce::AlertWindow ("Rename Scene", "Enter a scene name.", juce::MessageBoxIconType::NoIcon);
        dialog->addTextEditor ("name", state.scenes[(size_t) scene].name, "Name");
        dialog->addButton ("Rename", 1, juce::KeyPress (juce::KeyPress::returnKey)); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this); auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog, id] (int result)
        {
            if (safe == nullptr || safeDialog == nullptr || result != 1) return;
            const int index = safe->launcherIndices ({}, id).second; if (index < 0) return;
            safe->report (safe->session.renameScene (index, safeDialog->getTextEditorContents ("name"))); safe->refresh();
        }), true);
    }
    // A scene's tempo or time signature; leaving the field empty clears it.
    void sceneSettingsDialog (int scene, bool tempo)
    {
        if (scene < 0 || scene >= (int) state.scenes.size()) return;
        const auto& info = state.scenes[(size_t) scene];
        const auto id = info.id;
        auto* dialog = new juce::AlertWindow (tempo ? "Scene Tempo" : "Scene Time Signature",
                                              tempo ? "Launching the scene sets this tempo, from 20 to 999 BPM. Leave it empty for none."
                                                    : "Launching the scene sets this time signature, such as 3/4. Leave it empty for none.",
                                              juce::MessageBoxIconType::NoIcon);
        juce::String current;
        if (tempo && info.tempo) current = juce::String (*info.tempo, 2);
        if (! tempo && info.timeSignature) current << info.timeSignature->numerator << "/" << info.timeSignature->denominator;
        dialog->addTextEditor ("value", current, tempo ? "BPM" : "Meter");
        dialog->addButton ("OK", 1, juce::KeyPress (juce::KeyPress::returnKey)); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this); auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog, id, tempo] (int result)
        {
            if (safe == nullptr || safeDialog == nullptr || result != 1) return;
            const auto text = safeDialog->getTextEditorContents ("value").trim();
            if (tempo)
            {
                // Anything but a plain number is refused by the Session with its range message.
                const bool number = text.containsOnly ("0123456789.") && text.containsAnyOf ("0123456789");
                safe->report (safe->session.setSceneTempo (id, text.isEmpty() ? std::nullopt : std::optional<double> (number ? text.getDoubleValue() : -1)));
            }
            else
            {
                const auto top = text.upToFirstOccurrenceOf ("/", false, false).trim(), bottom = text.fromFirstOccurrenceOf ("/", false, false).trim();
                const bool parts = text.contains ("/") && top.containsOnly ("0123456789") && bottom.containsOnly ("0123456789") && top.isNotEmpty() && bottom.isNotEmpty();
                safe->report (safe->session.setSceneTimeSignature (id, text.isEmpty() ? std::nullopt
                    : std::optional<Session::TimeSignature> ({ parts ? top.getIntValue() : 0, parts ? bottom.getIntValue() : 0 })));
            }
            safe->refresh();
        }), true);
    }
    void importSlotDialog (int track, int scene)
    {
        if (track < 0 || track >= (int) state.tracks.size() || scene < 0 || scene >= (int) state.scenes.size())
        { report (juce::Result::fail ("Select an empty audio slot in Session first.")); return; }
        if (state.tracks[(size_t) track].isMidi || state.tracks[(size_t) track].isReturn) { report (juce::Result::fail ("Choose an audio track to import audio into a Session slot.")); return; }
        if (scene < (int) state.tracks[(size_t) track].slots.size() && state.tracks[(size_t) track].slots[(size_t) scene].hasClip)
        { report (juce::Result::fail ("This slot already contains a clip. Clear it before importing a replacement.")); return; }
        const auto trackId = state.tracks[(size_t) track].id, sceneId = state.scenes[(size_t) scene].id;
        chooser = std::make_unique<juce::FileChooser> ("Import Audio into Session Slot", browserFolder, "*.wav;*.aif;*.aiff;*.flac;*.ogg;*.mp3");
        auto safe = juce::Component::SafePointer<Impl> (this);
        chooser->launchAsync (juce::FileBrowserComponent::openMode | juce::FileBrowserComponent::canSelectFiles,
            [safe, trackId, sceneId] (const juce::FileChooser& fc)
            {
                if (safe == nullptr || fc.getResult() == juce::File()) return;
                const auto indices = safe->launcherIndices (trackId, sceneId);
                if (indices.first >= 0 && indices.second >= 0) safe->importLauncherFiles ({ fc.getResult().getFullPathName() }, indices.first, indices.second);
            });
    }
    void importLauncherFiles (const juce::StringArray& files, int track, int firstScene)
    {
        if (track < 0 || track >= (int) state.tracks.size() || firstScene < 0) return;
        if (state.tracks[(size_t) track].isMidi || state.tracks[(size_t) track].isReturn) { report (juce::Result::fail ("Drop audio into an audio track's Session slot.")); return; }
        std::vector<juce::File> audioFiles;
        for (const auto& file : files) if (isAudio (juce::File (file))) audioFiles.emplace_back (file);
        std::sort (audioFiles.begin(), audioFiles.end(), [] (const auto& a, const auto& b) { return a.getFileName().compareNatural (b.getFileName()) < 0; });
        if (audioFiles.empty()) return;
        for (int i = 0; i < (int) audioFiles.size(); ++i)
        {
            const int scene = firstScene + i;
            if (scene < (int) state.tracks[(size_t) track].slots.size() && state.tracks[(size_t) track].slots[(size_t) scene].hasClip)
            { report (juce::Result::fail ("A destination slot already contains a clip. Clear it before importing a replacement.")); return; }
        }
        session.beginEditGesture ("Import Session clips");
        bool imported = false;
        for (int i = 0; i < (int) audioFiles.size(); ++i)
        {
            const int scene = firstScene + i;
            while (scene >= (int) state.scenes.size())
            {
                const auto result = session.addScene(); report (result); refresh();
                if (result.failed()) { session.endEditGesture(); return; }
            }
            const auto result = session.importAudioToSlot (audioFiles[(size_t) i], track, scene); report (result); refresh();
            if (result.failed()) break;
            imported = true;
        }
        session.endEditGesture();
        if (imported)
        {
            showSession = true; showPiano = false; selectLauncherSlot (track, firstScene);
            browserFolder = audioFiles.front().getParentDirectory(); browserCategory = BrowserCategory::samples; updateBrowser(); resized(); launcher.scrollSelectionIntoView();
        }
    }

    const Session::TrackInfo* currentTrack() const
    {
        return selectedTrack >= 0 && selectedTrack < (int) state.tracks.size() ? &state.tracks[(size_t) selectedTrack] : nullptr;
    }
    // The audio clip an open clip view edits: the selected arrangement clip or Session slot.
    const Session::ClipInfo* selectedAudioClip() const
    {
        const auto* track = currentTrack();
        if (track == nullptr) return nullptr;
        if (showSession) { const auto* slot = selectedSlot(); return slot != nullptr && slot->hasClip && slot->clip.isAudio ? &slot->clip : nullptr; }
        if (selectedClip < 0 || selectedClip >= (int) track->clips.size()) return nullptr;
        return track->clips[(size_t) selectedClip].isAudio ? &track->clips[(size_t) selectedClip] : nullptr;
    }
    juce::Colour selectedTrackColour() const { const auto* track = currentTrack(); return track != nullptr ? track->colour : muted; }
    // Multi-clip editing: other Arrangement MIDI clips the editor shows beside the focused one, as
    // the reference's MIDI editor does for several selected clips.
    std::vector<juce::String> extraMidiClipIds;
    bool isExtraMidiClip (const juce::String& id) const
    { return std::find (extraMidiClipIds.begin(), extraMidiClipIds.end(), id) != extraMidiClipIds.end(); }
    std::pair<int, int> locateClip (const juce::String& id) const
    {
        for (int t = 0; t < (int) state.tracks.size(); ++t)
            for (int c = 0; c < (int) state.tracks[(size_t) t].clips.size(); ++c)
                if (state.tracks[(size_t) t].clips[(size_t) c].id == id) return { t, c };
        return { -1, -1 };
    }
    std::vector<const Session::ClipInfo*> extraMidiClips() const
    {
        std::vector<const Session::ClipInfo*> result;
        const auto* focused = currentMidiClip();
        if (focused == nullptr || selectedLauncherClipId.isNotEmpty()) return result;
        for (const auto& id : extraMidiClipIds)
            if (const auto [t, c] = locateClip (id); t >= 0 && id != focused->id)
                if (const auto& clip = state.tracks[(size_t) t].clips[(size_t) c]; clip.isMidi) result.push_back (&clip);
        return result;
    }
    // Makes another shown clip the one the editor edits, keeping the one it edited in view.
    // Slice to New MIDI Track, selecting the new track.
    void sliceClip (const juce::String& id, Session::SliceBy by)
    {
        juce::String trackId;
        report (session.sliceToNewMidiTrack (id, by, trackId)); refresh();
        for (int t = 0; t < (int) state.tracks.size(); ++t) if (state.tracks[(size_t) t].id == trackId) { selectTrack (t); selectedClip = 0; refresh(); }
    }
    void focusMidiClip (const juce::String& id)
    {
        const auto [t, c] = locateClip (id);
        if (t < 0) return;
        if (const auto* focused = currentMidiClip(); focused != nullptr && focused->id != id && ! isExtraMidiClip (focused->id)) extraMidiClipIds.push_back (focused->id);
        std::erase (extraMidiClipIds, id);
        selectTrack (t); selectedClip = c; selectedLauncherClipId.clear();
        refresh();
    }
    // The Session MIDI clip an open clip view edits, which has launch settings.
    const Session::ClipInfo* sessionMidiClip() const { return showSession && selectedLauncherClipId.isNotEmpty() ? currentMidiClip() : nullptr; }
    const Session::ClipInfo* currentMidiClip() const
    {
        const auto* track = currentTrack();
        if (track == nullptr) return nullptr;
        if (selectedLauncherClipId.isNotEmpty())
        {
            for (const auto& slot : track->slots) if (slot.hasClip && slot.clip.id == selectedLauncherClipId) return slot.clip.isMidi ? &slot.clip : nullptr;
            return nullptr;
        }
        if (selectedClip < 0 || selectedClip >= (int) track->clips.size()) return nullptr;
        const auto& clip = track->clips[(size_t) selectedClip];
        return clip.isMidi ? &clip : nullptr;
    }
    // Grooves: the Groove Pool window, adding library or file grooves, and extraction from clips.
    juce::File grooveFolder() const { return userLibrary == juce::File() ? juce::File() : userLibrary.getChildFile ("Grooves"); }
    void openGroovePool()
    {
        if (groovePool != nullptr) { if (auto* window = groovePool->getTopLevelComponent()) window->toFront (true); return; }
        auto panel = std::make_unique<GroovePoolPanel> (*this);
        groovePool = panel.get();
        showDialog ("Halftrack - Groove Pool", std::move (panel), 700, 320);
    }
    // Adds a groove to the pool; from the browser it also becomes the selected MIDI clip's groove.
    void useGrooveFromUI (const Session::GrooveInfo& groove, bool applyToClip)
    {
        juce::String id;
        const auto result = session.addGroove (groove, id);
        report (result, "Added " + groove.name + " to the Groove Pool.");
        if (result.wasOk() && applyToClip) if (const auto* clip = currentMidiClip()) report (session.setClipGroove (clip->id, id));
        refresh();
    }
    void useGrooveFileFromUI (const juce::File& file, bool applyToClip)
    {
        Session::GrooveInfo groove;
        if (const auto result = Session::readGrooveFile (file, groove); result.failed()) { report (result); return; }
        useGrooveFromUI (groove, applyToClip);
    }
    void extractGrooveFromUI (const juce::String& clipId)
    {
        juce::String id;
        const auto result = session.extractGroove (clipId, id);
        report (result, "Extracted the clip's groove into the Groove Pool."); refresh();
        if (result.wasOk()) openGroovePool();
    }
    void showAddGrooveMenu (juce::Component& target)
    {
        juce::PopupMenu menu, library;
        const auto grooves = Session::grooveLibrary();
        for (int i = 0; i < (int) grooves.size(); ++i) library.addItem (i + 1, grooves[(size_t) i].name);
        menu.addSubMenu ("Halftrack Grooves", library);
        menu.addItem (1000, "Groove File...");
        const auto* clip = currentMidiClip();
        menu.addItem (1001, "Extract from Selected Clip", clip != nullptr);
        const auto clipId = clip != nullptr ? clip->id : juce::String();
        auto safe = juce::Component::SafePointer<Impl> (this);
        menu.showMenuAsync (juce::PopupMenu::Options().withTargetComponent (&target), [safe, grooves, clipId] (int choice)
        {
            if (safe == nullptr || choice == 0) return;
            if (choice == 1001) { safe->extractGrooveFromUI (clipId); return; }
            if (choice == 1000) { safe->chooseGrooveFile(); return; }
            if (juce::isPositiveAndBelow (choice - 1, (int) grooves.size())) safe->useGrooveFromUI (grooves[(size_t) choice - 1], false);
        });
    }
    void chooseGrooveFile()
    {
        chooser = std::make_unique<juce::FileChooser> ("Add a Groove File", grooveFolder().isDirectory() ? grooveFolder() : juce::File(), "*.agr");
        auto safe = juce::Component::SafePointer<Impl> (this);
        chooser->launchAsync (juce::FileBrowserComponent::openMode | juce::FileBrowserComponent::canSelectFiles,
            [safe] (const juce::FileChooser& fc) { if (safe != nullptr && fc.getResult() != juce::File()) safe->useGrooveFileFromUI (fc.getResult(), false); });
    }
    void openPianoRoll()
    {
        const auto* track = currentTrack();
        if (showSession)
        {
            const auto* slot = selectedSlot();
            selectedClip = -1;
            selectedLauncherClipId = slot != nullptr && slot->hasClip && slot->clip.isMidi ? slot->clip.id : juce::String();
        }
        if (track != nullptr && track->isMidi && currentMidiClip() == nullptr && ! showSession)
            for (int i = 0; i < (int) track->clips.size(); ++i)
                if (track->clips[(size_t) i].isMidi) { selectedClip = i; break; }
        showPiano = true; showDetail = true;
        pianoRoll.sync(); resized(); pianoRoll.grabKeyboardFocus();
    }
    void createMidiClip (double seconds)
    {
        const auto* track = currentTrack();
        if (track == nullptr || ! track->isMidi) return;
        const auto trackId = track->id;
        const auto previousIds = track->clips;
        const auto barBeats = state.timeSignature.beatsPerBar();
        const auto startBeat = std::floor (beatsAt (seconds) / barBeats + 1e-9) * barBeats;
        const auto result = session.addMidiClip (trackId, startBeat, 16.0);
        report (result); refresh();
        if (result.failed()) return;
        const auto* updated = currentTrack();
        if (updated != nullptr)
            for (int i = 0; i < (int) updated->clips.size(); ++i)
                if (std::none_of (previousIds.begin(), previousIds.end(), [&] (const auto& old) { return old.id == updated->clips[(size_t) i].id; })) { selectedClip = i; break; }
        openPianoRoll(); pianoRoll.fit();
    }
    // A new audio or MIDI track goes before the returns, so it is the last of the other tracks.
    int lastOrdinaryTrack() const
    {
        for (int i = (int) state.tracks.size(); --i >= 0;) if (! state.tracks[(size_t) i].isReturn) return i;
        return -1;
    }
    // Insert MIDI Track makes an empty MIDI track, as the reference's does: no clip, and no instrument
    // until one is dropped on it, so it shows n-MIDI. One undo step. Insert MIDI Clip adds a clip.
    void addMidiTrack()
    {
        const auto before = trackIds();
        session.beginEditGesture ("Insert MIDI Track");
        auto result = session.addMidiTrack ({}, insertionPoint (false));
        refresh();
        const int created = createdTrack (before);
        if (result.wasOk() && created >= 0) result = session.removeTrackInstrument (state.tracks[(size_t) created].id);
        session.endEditGesture(); report (result); refresh();
        if (result.wasOk()) { multiSelectedTracks.clear(); selectTrack (createdTrack (before)); }
    }
    GridPlace arrangementGrid() const { return { {}, gridPixelsPerBeat(), visibleBeats(), canvas.timelineWidth() }; }
    const Session::ClipInfo* clipById (const juce::String& id) const
    {
        for (const auto& track : state.tracks)
        {
            for (const auto& clip : track.clips) if (clip.id == id) return &clip;
            for (const auto& slot : track.slots) if (slot.hasClip && slot.clip.id == id) return &slot.clip;
        }
        return nullptr;
    }
    Session::EditGrid gridAt (const GridPlace& place) const
    {
        if (place.clipId.isEmpty()) return editGrid;
        const auto* clip = clipById (place.clipId);
        return clip != nullptr ? clip->grid : Session::EditGrid {};
    }
    Session::GridValue gridValueAt (const GridPlace& place) const { return Session::gridValue (gridAt (place), place.pixelsPerBeat, place.visibleBeats, state.timeSignature); }
    double gridBeatsAt (const GridPlace& place) const { return Session::gridValueBeats (gridValueAt (place), gridAt (place).tuplet, state.timeSignature); }
    // The readout's text: the step, or Off while snapping is off, as the reference shows it.
    juce::String gridNameAt (const GridPlace& place) const
    { return gridAt (place).snap ? Session::gridValueName (gridValueAt (place), gridAt (place).tuplet) : juce::String ("Off"); }
    // The Arrangement grid: the project's editing grid at the zoom and view width, at the playhead's tempo.
    double gridPixelsPerBeat() const { return 60.0 / state.tempo * pixelsPerSecond; }
    double visibleBeats() const { return canvas.timelineWidth() / gridPixelsPerBeat(); }
    Session::GridValue gridValue() const { return gridValueAt (arrangementGrid()); }
    double gridBeats() const { return gridBeatsAt (arrangementGrid()); }
    juce::String gridName() const { return gridNameAt (arrangementGrid()); }
    // The reference's grid commands, Cmd/Ctrl+1 to 5: Narrow and Widen Grid move an adaptive grid one
    // step, halving or doubling its spacing (never to lines 8 pixels apart or a step half the view
    // long), and walk a fixed grid along the ladder; 3 toggles triplets (not for bars), 4 snapping;
    // 5 fixes the grid at its current step, or makes it adaptive at that step's width.
    void gridCommand (int command) { gridCommand (command, arrangementGrid()); }
    void gridCommand (int command, const GridPlace& place)
    {
        auto g = gridAt (place);
        const auto ladder = Session::gridLadder();
        const auto value = gridValueAt (place);
        const auto at = (int) (std::find (ladder.begin(), ladder.end(), value) - ladder.begin());
        const auto ppb = place.pixelsPerBeat;
        if (command == 1 || command == 2)
        {
            const int next = at + (command == 1 ? 1 : -1);
            if (next < 0 || next >= (int) ladder.size()) return;
            const auto& to = ladder[(size_t) next];
            if (g.fixed) { g.numerator = to.numerator; g.denominator = to.denominator; }
            else if (command == 1 && Session::gridValueBeats (to, 2, state.timeSignature) * ppb <= Session::narrowestGrid) return;
            else if (command == 2 && Session::gridValueBeats (to, g.tuplet, state.timeSignature) >= place.visibleBeats / 2) return;
            else g.intervalPixels = command == 1 ? juce::jmax (1, g.intervalPixels / 2) : g.intervalPixels * 2;
        }
        if (command == 3) { if (value.bars()) return; g.tuplet = g.tuplet == 3 ? 2 : 3; }
        if (command == 4) g.snap = ! g.snap;
        if (command == 5)
        {
            if (! g.fixed) { g.numerator = value.numerator; g.denominator = value.denominator; }
            else
            {
                const auto width = Session::gridValueBeats (value, g.tuplet, state.timeSignature) * ppb;
                g.intervalPixels = width < Session::narrowestGrid ? Session::narrowestGrid : (int) juce::jmin (width, place.viewWidth / 2.0);
            }
            g.fixed = ! g.fixed;
        }
        setGrid (g, place);
    }
    void setGrid (const Session::EditGrid& g) { setGrid (g, arrangementGrid()); }
    void setGrid (const Session::EditGrid& g, const GridPlace& place)
    {
        report (place.clipId.isEmpty() ? session.setEditGrid (g) : session.setClipGrid (place.clipId, g));
        refresh(); canvas.repaint(); ruler.repaint(); gridReadout.repaint(); pianoRoll.updateGridButton(); pianoRoll.repaint(); audioClipView.repaint();
        status = "Grid: " + gridNameAt (place); statusFrames = 24 * 4;
    }
    // The grid section of a context menu, as the reference's: adaptive widths, fixed values, triplets
    // and snapping, from item 200.
    // Choices laid out in a menu, as the reference's grid menu lays out its adaptive widths and fixed sizes
    // (AGridContextMenu 0x10325d9b4): a label, then the choices in columns, the current one lit.
    struct ChoiceGrid final : juce::PopupMenu::CustomComponent
    {
        ChoiceGrid (juce::String label, juce::StringArray choices, int columns, int current, std::shared_ptr<int> picked)
            : CustomComponent (false), title (std::move (label)), names (std::move (choices)), across (columns), lit (current), chosen (std::move (picked))
        { setTitle (title); }
        static constexpr int cellWidth = 62, cellHeight = 18, labelWidth = 66;
        int rows() const { return (names.size() + across - 1) / across; }
        void getIdealSize (int& width, int& height) override { width = labelWidth + across * cellWidth + 8; height = rows() * cellHeight + 4; }
        juce::Rectangle<int> cellBounds (int i) const { return { labelWidth + (i % across) * cellWidth, 2 + (i / across) * cellHeight, cellWidth, cellHeight }; }
        int cellAt (juce::Point<int> at) const { for (int i = 0; i < names.size(); ++i) if (cellBounds (i).contains (at)) return i; return -1; }
        void paint (juce::Graphics& g) override
        {
            g.setFont (font (12.0f)); g.setColour (muted); g.drawText (title, 10, 2, labelWidth - 12, cellHeight, juce::Justification::centredLeft);
            for (int i = 0; i < names.size(); ++i)
            {
                const auto box = cellBounds (i).reduced (1);
                if (i == lit) { g.setColour (orange); g.fillRect (box); }
                else if (i == hovered) { g.setColour (themes::colour (0xff505050)); g.fillRect (box); }
                g.setColour (i == lit ? themes::colour (0xff1a1a1a) : ink); g.drawText (names[i], box, juce::Justification::centred);
            }
        }
        void mouseMove (const juce::MouseEvent& e) override { if (const auto i = cellAt (e.getPosition()); i != hovered) { hovered = i; repaint(); } }
        void mouseExit (const juce::MouseEvent&) override { hovered = -1; repaint(); }
        void mouseUp (const juce::MouseEvent& e) override { if (const auto i = cellAt (e.getPosition()); i >= 0) { *chosen = i; triggerMenuItem(); } }
        juce::String title;
        juce::StringArray names;
        int across = 1, lit = -1, hovered = -1;
        std::shared_ptr<int> chosen;
    };
    // The grid's items, in the reference's order (AGridContextMenu 0x10325d9b4): Snap to Grid, the adaptive
    // widths and the fixed sizes laid out in rows, Narrow and Widen Grid, and Triplet Grid.
    static constexpr int adaptiveGridItem = 230, fixedGridItem = 231, narrowGridItem = 222, widenGridItem = 223;
    mutable std::shared_ptr<int> adaptivePick = std::make_shared<int> (-1), fixedPick = std::make_shared<int> (-1);
    void addGridItems (juce::PopupMenu& menu) const { addGridItems (menu, arrangementGrid()); }
    void addGridItems (juce::PopupMenu& menu, const GridPlace& place) const
    {
        const auto g = gridAt (place);
        adaptivePick = std::make_shared<int> (-1); fixedPick = std::make_shared<int> (-1);
        juce::StringArray sizes;
        int fixedNow = -1;
        for (int i = 0; i < (int) std::size (fixedGridItems); ++i)
        {
            sizes.add (fixedGridItems[i].bars() ? juce::String (fixedGridItems[i].numerator) + (fixedGridItems[i].numerator == 1 ? " Bar" : " Bars")
                                                 : Session::gridValueName (fixedGridItems[i], 2));
            if (g.fixed && fixedGridItems[i] == Session::GridValue { g.numerator, g.denominator }) fixedNow = i;
        }
        menu.addItem (221, "Snap to Grid", true, g.snap);
        menu.addCustomItem (adaptiveGridItem, std::make_unique<ChoiceGrid> ("Adaptive", juce::StringArray { "Widest", "Wide", "Medium", "Narrow", "Narrowest" }, 3,
                                                                            g.fixed ? -1 : gridWidth (place), adaptivePick), nullptr, "Adaptive Grid");
        menu.addCustomItem (fixedGridItem, std::make_unique<ChoiceGrid> ("Fixed", sizes, 5, fixedNow, fixedPick), nullptr, "Fixed Grid");
        menu.addSeparator();
        menu.addItem (narrowGridItem, "Narrow Grid"); menu.addItem (widenGridItem, "Widen Grid");
        menu.addSeparator();
        menu.addItem (220, "Triplet Grid", ! gridValueAt (place).bars(), g.tuplet == 3);
    }
    static constexpr Session::GridValue fixedGridItems[] { { 8, 1 }, { 4, 1 }, { 2, 1 }, { 1, 1 }, { 1, 2 }, { 1, 4 }, { 1, 8 }, { 1, 16 }, { 1, 32 } };
    // The five adaptive widths, from half the view's width down to 8 pixels, each the geometric mean
    // of its neighbours as the reference computes them; the nearest is shown checked.
    std::array<int, 5> gridWidths() const { return gridWidths (arrangementGrid()); }
    static std::array<int, 5> gridWidths (const GridPlace& place)
    {
        const auto widest = juce::jmax (Session::narrowestGrid, place.viewWidth / 2);
        const auto medium = (int) (std::sqrt ((float) widest * 0.125f) * 8.0f);
        return { widest, (int) std::sqrt ((float) widest * (float) medium), medium, (int) std::sqrt (8.0f * (float) medium), Session::narrowestGrid };
    }
    int gridWidth (const GridPlace& place) const
    {
        const auto widths = gridWidths (place);
        const auto interval = (double) gridAt (place).intervalPixels;
        int nearest = 0;
        for (int i = 1; i < 5; ++i)
            if (std::abs (std::log (interval / widths[(size_t) i])) < std::abs (std::log (interval / widths[(size_t) nearest]))) nearest = i;
        return nearest;
    }
    // Choosing a width or a fixed value also turns snapping on.
    bool gridItem (int item) { return gridItem (item, arrangementGrid()); }
    bool gridItem (int item, const GridPlace& place)
    {
        if (item == adaptiveGridItem) { if (*adaptivePick < 0) return true; item = 200 + *adaptivePick; }
        if (item == fixedGridItem) { if (*fixedPick < 0) return true; item = 210 + *fixedPick; }
        if (item == narrowGridItem || item == widenGridItem) { gridCommand (item == narrowGridItem ? 1 : 2, place); return true; }
        auto g = gridAt (place);
        if (item >= 200 && item < 205) { g.fixed = false; g.intervalPixels = gridWidths (place)[(size_t) item - 200]; g.snap = true; }
        else if (item >= 210 && item < 210 + (int) std::size (fixedGridItems))
        { g.fixed = true; g.numerator = fixedGridItems[item - 210].numerator; g.denominator = fixedGridItems[item - 210].denominator; g.snap = true; }
        else if (item == 220) g.tuplet = g.tuplet == 3 ? 2 : 3;
        else if (item == 221) g.snap = ! g.snap;
        else return false;
        setGrid (g, place); return true;
    }
    // Where Cmd/Ctrl+1 to 5 apply: the clip editor with the keyboard focus, or the Arrangement.
    std::optional<GridPlace> focusedGrid() const
    {
        if (pianoRoll.isShowing() && pianoRoll.hasKeyboardFocus (true) && currentMidiClip() != nullptr) return pianoRoll.gridPlace();
        if (audioClipView.isShowing() && audioClipView.hasKeyboardFocus (true) && selectedAudioClip() != nullptr) return audioClipView.gridPlace();
        if (! showSession) return arrangementGrid();
        return std::nullopt;
    }
    // Times go through the tempo map, so the grid and bars follow tempo changes.
    double beatsAt (double seconds) const { return session.beatsAt (seconds); }
    double secondsAt (double beats) const { return session.secondsAt (beats); }
    // The nearest grid line, or with snapping off the time itself.
    double snapSeconds (double seconds) const { return editGrid.snap ? toGrid (seconds) : juce::jmax (0.0, seconds); }
    double toGrid (double seconds) const { return juce::jmax (0.0, secondsAt (gridLine (beatsAt (juce::jmax (0.0, seconds))))); }
    // A grid line near a beat: the nearest (0), the one at or before (-1) or the one at or after (+1).
    // The lines run from each bar's start, so they follow the time signature markers, as the
    // reference's grid does; a grid of a bar or more falls on bar starts.
    double gridLine (double beat, int direction = 0) const
    {
        const auto& markers = state.timeSignatures;
        const auto grid = gridBeats();
        const auto bar = Session::barAt (markers, beat);
        const auto pick = [direction, beat] (double a, double b)
        { return direction < 0 ? a : direction > 0 ? (beat - a < 1.0e-9 ? a : b) : (beat - a <= b - beat ? a : b); };
        if (grid >= bar.meter.beatsPerBar() - 1.0e-9)
        {
            const int bars = juce::jmax (1, (int) std::round (grid / bar.meter.beatsPerBar()));
            const int first = (int) std::floor ((double) bar.number / bars) * bars;
            return pick (Session::barStart (markers, first), Session::barStart (markers, first + bars));
        }
        const auto a = bar.start + std::floor ((beat - bar.start) / grid + 1.0e-9) * grid;
        return pick (a, juce::jmin (bar.start + bar.length, a + grid));
    }
    // Freeze toggles the track's freeze; Flatten replaces a frozen track with its render.
    void freezeTrackFromUI (const juce::String& trackId, bool flatten)
    {
        const auto index = launcherIndices (trackId, {}).first;
        if (index < 0) return;
        const bool frozen = state.tracks[(size_t) index].frozen;
        report (flatten ? session.flattenTrack (trackId) : session.setTrackFrozen (trackId, ! frozen)); refresh();
    }
    // Duplicates tracks and groups as the reference's Duplicate does, then selects the copies, as it
    // selects the new block: the first, with the other tracks among them. When the first lands in a
    // folded group, that group is selected instead.
    void duplicateFromUI (const juce::StringArray& ids)
    {
        juce::StringArray copies; const auto result = session.duplicateTracks (ids, copies); report (result); refresh();
        if (result.wasOk()) selectCopies (copies);
    }
    void selectCopies (const juce::StringArray& copies)
    {
        if (copies.isEmpty()) return;
        multiSelectedTracks.clear(); selectedClip = -1; selectedLauncherClipId.clear(); showPiano = false;
        const auto* group = groupInfo (copies[0]);
        const auto first = trackIndex (copies[0]);
        const auto parent = group != nullptr ? group->parentId : first >= 0 ? state.tracks[(size_t) first].groupId : juce::String();
        if (anyFolded (parent)) selectChain (parent);
        else if (group != nullptr) selectChain (group->id);
        else
        {
            for (int i = 1; i < copies.size(); ++i) if (trackIndex (copies[i]) >= 0) multiSelectedTracks.insert (copies[i]);
            selectTrack (first);
        }
        resized();
    }
    void duplicateTrackFromUI (const juce::String& trackId) { duplicateFromUI ({ trackId }); }
    // The headers' Cut, Copy and Paste: Paste puts the copied tracks right before the first selected
    // one, as the reference's does, and selects them; Cut leaves the selection as Delete does.
    void trackClipboardCommand (char command)
    {
        const auto ids = headerSelection();
        if (command == 'C') { if (session.canDuplicateTracks (ids)) report (session.copyTracks (ids)); return; }
        if (command == 'X')
        {
            if (! session.canCutTracks (ids)) return;
            if (auto copied = session.copyTracks (ids); copied.failed()) { report (copied); return; }
            deleteSelectedHeaders(); return;
        }
        if (! session.hasTrackClipboard()) return;
        juce::StringArray pasted; const auto result = session.pasteTracks (ids, pasted); report (result); refresh();
        if (result.wasOk()) selectCopies (pasted);
    }
    // The headers' Duplicate: the selected group, or the selected tracks.
    void duplicateSelectedHeaders() { if (const auto ids = headerSelection(); session.canDuplicateTracks (ids)) duplicateFromUI (ids); }
    // Halftrack's own palette for the headers' colour grid, laid out as the reference's: 5 rows of
    // 14, a hue to a column and the last column grey, lighter rows first.
    static constexpr int paletteColumns = 14, paletteRows = 5;
    static juce::Colour paletteColour (int index)
    {
        const int column = index % paletteColumns, row = juce::jlimit (0, paletteRows - 1, index / paletteColumns);
        constexpr float brightness[] { 0.92f, 0.82f, 0.72f, 0.6f, 0.46f }, saturation[] { 0.62f, 0.48f, 0.36f, 0.42f, 0.38f };
        if (column == paletteColumns - 1) return juce::Colour::greyLevel (0.86f - 0.16f * (float) row);
        return juce::Colour::fromHSV (std::fmod (0.98f + (float) column * 0.92f / (paletteColumns - 1), 1.0f), saturation[row], brightness[row], 1.0f);
    }
    struct ColourGrid final : juce::PopupMenu::CustomComponent
    {
        ColourGrid (std::vector<juce::Colour> used, std::shared_ptr<int> picked) : CustomComponent (false), inUse (std::move (used)), chosen (std::move (picked))
        { setTitle ("Track colours"); }
        static constexpr int cell = 15;
        void getIdealSize (int& width, int& height) override { width = paletteColumns * cell + 12; height = paletteRows * cell + 8; }
        int swatchAt (juce::Point<int> at) const
        {
            const int column = (at.x - 6) / cell, row = (at.y - 4) / cell;
            return at.x >= 6 && at.y >= 4 && column < paletteColumns && row < paletteRows ? row * paletteColumns + column : -1;
        }
        juce::Point<int> swatchCentre (int index) const { return { 6 + (index % paletteColumns) * cell + cell / 2, 4 + (index / paletteColumns) * cell + cell / 2 }; }
        bool marked (int index) const { return std::find (inUse.begin(), inUse.end(), paletteColour (index)) != inUse.end(); }
        void paint (juce::Graphics& g) override
        {
            for (int i = 0; i < paletteColumns * paletteRows; ++i)
            {
                const auto box = juce::Rectangle<int> (6 + (i % paletteColumns) * cell, 4 + (i / paletteColumns) * cell, cell, cell).reduced (1);
                g.setColour (paletteColour (i)); g.fillRect (box);
                if (marked (i)) { g.setColour (themes::colour (0xff141414)); g.drawRect (box.reduced (3), 2); } // In use by a selected track.
                if (i == hovered) { g.setColour (themes::colour (0xffffffff)); g.drawRect (box, 1); }
            }
        }
        void mouseMove (const juce::MouseEvent& e) override { if (const auto i = swatchAt (e.getPosition()); i != hovered) { hovered = i; repaint(); } }
        void mouseExit (const juce::MouseEvent&) override { hovered = -1; repaint(); }
        void mouseUp (const juce::MouseEvent& e) override { if (const auto i = swatchAt (e.getPosition()); i >= 0) { *chosen = i; triggerMenuItem(); } }
        std::vector<juce::Colour> inUse;
        std::shared_ptr<int> chosen;
        int hovered = -1;
    };
    const Session::TrackInfo* trackInfo (const juce::String& id) const { const auto t = trackIndex (id); return t >= 0 ? &state.tracks[(size_t) t] : nullptr; }
    // An Audio To chooser's choices, in the reference's order (0x1023ea370): the Ext. Out outputs and
    // Configure..., then Main and the group the track or group is in (named after the group), the tracks
    // it can play into, and Sends Only, with separators where the reference has its dividers.
    std::vector<OutputChoice> outputChoices (const juce::String& id, const juce::String& groupId) const
    {
        std::vector<OutputChoice> choices;
        for (const auto& name : session.outputNames())
            if (name != session.masterOutput()) choices.push_back ({ "Ext. Out " + name, Session::TrackOutput { Session::OutputKind::external, {}, name } });
        choices.push_back ({ "Configure...", std::nullopt });
        choices.push_back ({ "Main", Session::TrackOutput {}, true });
        if (const auto* g = groupInfo (groupId)) choices.push_back ({ g->name, Session::TrackOutput { Session::OutputKind::group } });
        bool first = true;
        for (const auto& destination : session.outputDestinations (id))
            if (const auto* t = trackInfo (destination)) { choices.push_back ({ t->name, Session::TrackOutput { Session::OutputKind::track, destination }, first }); first = false; }
        choices.push_back ({ "Sends Only", Session::TrackOutput { Session::OutputKind::sendsOnly }, true });
        return choices;
    }
    static bool sameOutput (const Session::TrackOutput& a, const Session::TrackOutput& b)
    {
        if (a.kind != b.kind) return false;
        if (a.kind == Session::OutputKind::track) return a.trackId == b.trackId;
        if (a.kind == Session::OutputKind::external) return a.port == b.port;
        return true;
    }
    // Fills an Audio To chooser when its choices change, and shows the current output.
    void syncOutputChooser (juce::ComboBox& box, const std::vector<OutputChoice>& choices, const Session::TrackOutput& current, juce::String& shown) const
    {
        juce::String signature;
        for (const auto& choice : choices) signature << (choice.separatorBefore ? "-|" : "") << choice.label << "\n";
        if (signature != shown)
        {
            shown = signature; box.clear (juce::dontSendNotification);
            for (int i = 0; i < (int) choices.size(); ++i)
            {
                if (choices[(size_t) i].separatorBefore) box.addSeparator();
                box.addItem (choices[(size_t) i].label, choices[(size_t) i].output ? i + 1 : configureOutputItem);
            }
        }
        int selected = 0;
        for (int i = 0; i < (int) choices.size(); ++i)
            if (const auto& o = choices[(size_t) i].output; o && sameOutput (*o, current)) selected = i + 1;
        box.setSelectedId (selected, juce::dontSendNotification);
    }
    // A choice from an Audio To chooser. Configure... opens Preferences' Audio tab, as the reference's opens
    // its output preferences, and leaves the output as it was.
    void chooseOutput (const juce::String& id, const juce::ComboBox& box, const std::vector<OutputChoice>& choices)
    {
        const int item = box.getSelectedId();
        if (item == configureOutputItem) { refresh(); showAudioSettings(); return; }
        if (juce::isPositiveAndBelow (item - 1, (int) choices.size()) && choices[(size_t) item - 1].output)
            report (session.setTrackOutput (id, *choices[(size_t) item - 1].output));
        refresh();
    }
    // The tracks of these tracks and groups, those inside the groups included, in order.
    juce::StringArray tracksWithin (const juce::StringArray& ids) const
    {
        juce::StringArray tracks;
        for (const auto& track : state.tracks)
            if (ids.contains (track.id) || std::any_of (ids.begin(), ids.end(), [&] (const juce::String& g) { return groupInfo (g) != nullptr && (track.groupId == g || groupInside (track.groupId, g)); }))
                tracks.add (track.id);
        return tracks;
    }
    // Those of the selected tracks Freeze acts on: tracks with Arrangement clips, or frozen ones.
    juce::StringArray freezableTracks (const juce::StringArray& ids) const
    {
        juce::StringArray tracks;
        for (const auto& id : ids)
            if (const auto* track = trackInfo (id); track != nullptr && ! track->isReturn && (track->frozen || ! track->clips.empty())) tracks.add (id);
        return tracks;
    }
    void freezeTracksFromUI (const juce::StringArray& ids)
    {
        bool allFrozen = true;
        for (const auto& id : ids) if (const auto* track = trackInfo (id)) allFrozen = allFrozen && track->frozen;
        for (const auto& id : ids)
            if (const auto* track = trackInfo (id); track != nullptr && track->frozen == allFrozen) { report (session.setTrackFrozen (id, ! allFrozen)); refresh(); }
    }
    // The selected tracks' take lanes.
    juce::StringArray selectedTakeLanes (const juce::StringArray& ids) const
    {
        juce::StringArray lanes;
        for (const auto& id : tracksWithin (ids)) if (const auto* track = trackInfo (id)) for (const auto& lane : track->takeLanes) lanes.add (lane.id);
        return lanes;
    }
    // Select Content, as the reference's: in the Arrangement the time the selected tracks' clips
    // cover, on those tracks; in the Session view their clips.
    bool canSelectContent (const juce::StringArray& ids, bool arrangement) const
    {
        if (! arrangement)
            return ! ids.isEmpty() && std::all_of (ids.begin(), ids.end(), [this] (const juce::String& id) { const auto* t = trackInfo (id); return t != nullptr && ! t->isReturn; });
        for (const auto& id : tracksWithin (ids)) if (const auto* track = trackInfo (id); track != nullptr && ! track->clips.empty()) return true;
        return false;
    }
    void selectContent (const juce::StringArray& ids, bool arrangement)
    {
        if (! canSelectContent (ids, arrangement)) return;
        if (! arrangement)
        {
            std::vector<Session::SlotRef> slots;
            for (const auto& id : ids)
                if (const auto t = trackIndex (id); t >= 0)
                    for (int scene = 0; scene < (int) state.tracks[(size_t) t].slots.size(); ++scene)
                        if (state.tracks[(size_t) t].slots[(size_t) scene].hasClip) slots.push_back ({ t, scene });
            if (slots.size() == 1) selectLauncherSlot (slots[0].track, slots[0].scene);
            selectedSlots = slots.size() > 1 ? slots : std::vector<Session::SlotRef>();
            launcher.repaint(); return;
        }
        TimeSelection chosen; chosen.start = std::numeric_limits<double>::max();
        for (const auto& id : tracksWithin (ids))
            if (const auto* track = trackInfo (id))
            {
                chosen.trackIds.add (id);
                for (const auto& clip : track->clips) { chosen.start = std::min (chosen.start, clip.start); chosen.end = std::max (chosen.end, clip.start + clip.length); }
            }
        timeSelection = chosen; canvas.repaint();
    }
    // Rename, for the clicked track or group: its name edits in place in the Arrangement, the header
    // editing it returned, and in a dialog from a Session title.
    juce::Component* renameHeader (const juce::String& id, bool arrangement)
    {
        if (arrangement)
        {
            for (int i = 0; i < canvas.getNumChildComponents(); ++i)
            {
                if (auto* row = dynamic_cast<TrackRow*> (canvas.getChildComponent (i)); row != nullptr && row->getTrackId() == id) { row->beginRename(); return row; }
                if (auto* header = dynamic_cast<GroupHeader*> (canvas.getChildComponent (i)); header != nullptr && header->getId() == id) { header->beginRename(); return header; }
            }
            return nullptr;
        }
        const auto* group = groupInfo (id);
        const auto* track = trackInfo (id);
        if (group == nullptr && track == nullptr) return nullptr;
        auto* dialog = new juce::AlertWindow (group != nullptr ? "Rename Group" : "Rename Track", group != nullptr ? "Enter a group name." : "Enter a track name.", juce::MessageBoxIconType::NoIcon);
        dialog->addTextEditor ("name", group != nullptr ? group->name : track->name, "Name");
        dialog->addButton ("Rename", 1, juce::KeyPress (juce::KeyPress::returnKey)); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this); auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog, id] (int result)
        {
            if (safe == nullptr || safeDialog == nullptr || result != 1) return;
            const auto name = safeDialog->getTextEditorContents ("name");
            if (safe->groupInfo (id) != nullptr) safe->report (safe->session.renameGroup (id, name));
            else if (const auto t = safe->trackIndex (id); t >= 0) safe->report (safe->session.renameTrack (t, name));
            safe->refresh();
        }), true);
        return nullptr;
    }
    // Save as Default Audio/MIDI Track: asks before replacing a default saved earlier.
    void saveDefaultTrackDialog (const juce::String& id)
    {
        const auto* track = trackInfo (id);
        if (track == nullptr) return;
        const auto file = defaultTrackFile (track->isMidi);
        if (! file.existsAsFile()) { report (session.saveTrackAsDefault (id, file)); return; }
        auto* dialog = new juce::AlertWindow (track->isMidi ? "Replace the default MIDI track?" : "Replace the default audio track?",
                                              "New " + juce::String (track->isMidi ? "MIDI" : "audio") + " tracks will start from " + track->name + " instead.", juce::MessageBoxIconType::QuestionIcon);
        dialog->addButton ("Replace", 1); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, id, file] (int result)
        { if (safe != nullptr && result == 1) safe->report (safe->session.saveTrackAsDefault (id, file)); }), true);
    }
    // Edit Info Text, for the clicked track or group: its own text for the Info view.
    // The name and info text of a track, group, clip or scene.
    std::optional<std::pair<juce::String, juce::String>> infoOf (const juce::String& id) const
    {
        if (const auto* group = groupInfo (id)) return std::pair { group->name, group->infoText };
        if (const auto* track = trackInfo (id)) return std::pair { track->name, track->infoText };
        for (const auto& scene : state.scenes) if (scene.id == id) return std::pair { scene.name, scene.infoText };
        for (const auto& track : state.tracks)
        {
            for (const auto& clip : track.clips) if (clip.id == id) return std::pair { clip.name, clip.infoText };
            for (const auto& slot : track.slots) if (slot.hasClip && slot.clip.id == id) return std::pair { slot.clip.name, slot.clip.infoText };
        }
        return std::nullopt;
    }
    void editInfoTextDialog (const juce::String& id)
    {
        const auto info = infoOf (id);
        if (! info) return;
        auto* dialog = new juce::AlertWindow ("Edit Info Text", "Shown in the Info view while pointing at " + info->first + ".", juce::MessageBoxIconType::NoIcon);
        dialog->addTextEditor ("text", info->second, "Info text");
        if (auto* editor = dialog->getTextEditor ("text")) { editor->setMultiLine (true, true); editor->setReturnKeyStartsNewLine (true); editor->setSize (300, 90); }
        dialog->addButton ("OK", 1); dialog->addButton ("Cancel", 0, juce::KeyPress (juce::KeyPress::escapeKey));
        dialog->setLookAndFeel (&theme); alerts.emplace_back (dialog);
        auto safe = juce::Component::SafePointer<Impl> (this); auto safeDialog = juce::Component::SafePointer<juce::AlertWindow> (dialog);
        dialog->enterModalState (true, juce::ModalCallbackFunction::create ([safe, safeDialog, id] (int result)
        {
            if (safe == nullptr || safeDialog == nullptr || result != 1) return;
            safe->report (safe->session.setInfoText (id, safeDialog->getTextEditorContents ("text"))); safe->refresh();
        }), true);
    }
    // A track's or group's header menu, in the reference's order (ATrackHeader::FillContextMenu): its
    // commands act on the selected tracks, Rename on the clicked one. As in the reference, a command
    // that cannot act there is left out, and a separator only comes between items. The Arrangement's
    // has the take lane and link items; the Session view's titles do not. A colour picked in the grid
    // is put in `colour`.
    enum HeaderItem { headerCut = 100, headerCopy, headerPaste, headerDuplicate = 1, headerDelete, headerRename, headerFreeze, headerBounce, headerInsertAudio, headerInsertMidi, headerInsertReturn,
                      headerGroup, headerUngroup, headerSelectContent, headerEditInfo, headerClearEnvelopes, headerAssignColour, headerDeleteUnusedTakeLanes,
                      headerSaveDefault, headerInsertTakeLane, headerShowTakeLanes, headerDeleteTakeLanes, headerLink, headerUnlink, headerColour };
    juce::PopupMenu headerMenu (const juce::String& id, bool arrangement, std::shared_ptr<int> colour, bool join) const
    {
        const auto ids = headerSelection();
        juce::PopupMenu menu;
        bool pending = false;
        const auto item = [&] (int result, const juce::String& text, bool enabled = true, bool ticked = false)
        { if (pending) menu.addSeparator(); pending = false; menu.addItem (result, text, enabled, ticked); };
        const auto separator = [&pending] { pending = true; };
        if (session.canCutTracks (ids)) item (headerCut, "Cut");
        if (session.canDuplicateTracks (ids)) item (headerCopy, "Copy");
        if (session.hasTrackClipboard()) item (headerPaste, "Paste");
        if (session.canDuplicateTracks (ids)) item (headerDuplicate, "Duplicate");
        if (session.canRemoveTracks (ids)) item (headerDelete, "Delete");
        // In Automation Mode, the selected tracks' envelopes can all go.
        if (arrangement && automationMode) { separator(); if (session.canClearAllEnvelopes (ids)) item (headerClearEnvelopes, "Clear All Envelopes"); }
        separator();
        item (headerRename, "Rename");
        item (headerEditInfo, "Edit Info Text");
        separator();
        // Freeze acts on the selected tracks that can freeze; Unfreeze when all of those are frozen.
        const auto freezable = freezableTracks (ids);
        const bool allFrozen = ! freezable.isEmpty() && std::all_of (freezable.begin(), freezable.end(), [this] (const juce::String& t) { return trackInfo (t)->frozen; });
        if (! freezable.isEmpty()) item (headerFreeze, juce::String (allFrozen ? "Unfreeze " : "Freeze ") + (freezable.size() > 1 ? "Tracks" : "Track"));
        const auto* track = trackInfo (id);
        // Bounce Track in Place, for the selected audio and MIDI tracks, as the reference's freeze list has them.
        if (session.canBounceTracksInPlace (ids))
        {
            int bounced = 0; for (const auto& t : ids) if (const auto* info = trackInfo (t); info != nullptr && ! info->isReturn) ++bounced;
            item (headerBounce, bounced > 1 ? "Bounce Tracks in Place" : "Bounce Track in Place");
        }
        separator();
        item (headerInsertAudio, "Insert Audio Track"); item (headerInsertMidi, "Insert MIDI Track");
        if (std::count_if (state.tracks.begin(), state.tracks.end(), [] (const auto& t) { return t.isReturn; }) < Session::maximumReturnTracks) item (headerInsertReturn, "Insert Return Track");
        if (session.canGroupTracks (groupingSelection())) item (headerGroup, "Group Tracks");
        if (groupInfo (selectedChain) != nullptr) item (headerUngroup, "Ungroup Tracks");
        separator();
        item (headerSelectContent, "Select Content", canSelectContent (ids, arrangement));
        if (arrangement && track != nullptr && ! track->isReturn && ! automationMode)
        {
            separator();
            const auto selected = tracksWithin (ids);
            const bool shown = std::all_of (selected.begin(), selected.end(), [this] (const juce::String& t) { return takeLanesShown.count (t) > 0; });
            item (headerInsertTakeLane, "Insert Take Lane"); item (headerShowTakeLanes, "Show Take Lanes", true, shown);
            item (headerDeleteTakeLanes, "Delete All Take Lanes", ! selectedTakeLanes (ids).isEmpty());
            item (headerDeleteUnusedTakeLanes, "Delete Unused Take Lanes", ! session.unusedTakeLanes (tracksWithin (ids)).isEmpty());
        }
        // Links join audio and MIDI tracks (Halftrack's groups do not link yet).
        if (arrangement && track != nullptr && ! track->isReturn)
        {
            separator();
            const auto selection = selectedTrackIds();
            const bool anyLinked = std::any_of (state.tracks.begin(), state.tracks.end(), [&] (const auto& t) { return selection.contains (t.id) && t.linkId.isNotEmpty(); });
            item (headerLink, "Link Tracks", selection.size() >= 2 || (join && ! selection.isEmpty()));
            item (headerUnlink, "Unlink Tracks", anyLinked);
        }
        std::vector<juce::Colour> used;
        for (const auto& t : ids)
        {
            if (const auto* g = groupInfo (t)) used.push_back (g->colour);
            else if (const auto* info = trackInfo (t)) used.push_back (info->colour);
        }
        if (pending || menu.getNumItems() > 0) menu.addSeparator();
        menu.addCustomItem (headerColour, std::make_unique<ColourGrid> (used, colour), nullptr, "Track Colours");
        // Assign Track Color to Clips, for audio, MIDI and group tracks, naming grouped tracks when a group is chosen.
        const bool assignable = ! ids.isEmpty() && std::all_of (ids.begin(), ids.end(), [this] (const juce::String& t)
        { const auto* info = trackInfo (t); return groupInfo (t) != nullptr || (info != nullptr && ! info->isReturn); });
        const bool anyGroup = std::any_of (ids.begin(), ids.end(), [this] (const juce::String& t) { return groupInfo (t) != nullptr; });
        if (assignable) { menu.addSeparator(); menu.addItem (headerAssignColour, anyGroup ? "Assign Track Color to Clips and Grouped Tracks" : "Assign Track Color to Clips"); }
        // Save as Default, for the clicked audio or MIDI track, unless it is frozen or selected with others.
        if (track != nullptr && ! track->isReturn && userLibrary != juce::File())
        {
            menu.addSeparator();
            menu.addItem (headerSaveDefault, track->isMidi ? "Save as Default MIDI Track" : "Save as Default Audio Track", ! track->frozen && selectedTrackIds().size() <= 1);
        }
        return menu;
    }
    void chooseHeaderItem (int result, const juce::String& id, bool arrangement, int colour, bool join)
    {
        const auto ids = headerSelection();
        switch (result)
        {
            case headerCut: case headerCopy: case headerPaste: trackClipboardCommand (result == headerCut ? 'X' : result == headerCopy ? 'C' : 'V'); return;
            case headerDuplicate: duplicateFromUI (ids); return;
            case headerDelete: deleteSelectedHeaders(); return;
            case headerRename: renameHeader (id, arrangement); return;
            case headerEditInfo: editInfoTextDialog (id); return;
            case headerClearEnvelopes: report (session.clearAllEnvelopes (ids)); break;
            case headerAssignColour: report (session.assignTrackColourToClips (ids, arrangement)); break;
            case headerSaveDefault: saveDefaultTrackDialog (id); return;
            case headerFreeze: freezeTracksFromUI (freezableTracks (ids)); return;
            case headerBounce: report (session.bounceTracksInPlace (ids)); break;
            case headerInsertAudio: showPiano = false; addTrack(); resized(); return;
            case headerInsertMidi: addMidiTrack(); return;
            case headerInsertReturn: addReturnTrack(); return;
            case headerGroup: groupSelectedTracks(); return;
            case headerUngroup: ungroupSelectedTrack(); return;
            case headerSelectContent: selectContent (ids, arrangement); return;
            case headerInsertTakeLane:
                for (const auto& t : tracksWithin (ids))
                    if (const auto* track = trackInfo (t); track != nullptr && ! track->isReturn) { juce::String lane; report (session.insertTakeLane (t, lane)); takeLanesShown.insert (t); }
                break;
            case headerShowTakeLanes:
            {
                const auto selected = tracksWithin (ids);
                const bool shown = std::all_of (selected.begin(), selected.end(), [this] (const juce::String& t) { return takeLanesShown.count (t) > 0; });
                for (const auto& t : selected) { if (shown) takeLanesShown.erase (t); else takeLanesShown.insert (t); }
                break;
            }
            case headerDeleteTakeLanes: report (session.removeTakeLanes (selectedTakeLanes (ids))); break;
            case headerDeleteUnusedTakeLanes: report (session.removeTakeLanes (session.unusedTakeLanes (tracksWithin (ids)))); break;
            case headerLink: linkSelectedTracks (join); return;
            case headerUnlink: unlinkSelectedTracks(); return;
            case headerColour: if (colour >= 0) report (session.setTrackColours (ids, paletteColour (colour))); break;
            default: return;
        }
        refresh(); resized();
    }
    // Right-clicking a header selects its track or group, unless it is selected (whether it exists).
    bool selectForHeaderMenu (const juce::String& id)
    {
        if (groupInfo (id) != nullptr) { if (selectedChain != id) selectChain (id); return true; }
        const auto t = trackIndex (id);
        if (t < 0) return false;
        if (! selectedTrackIds().contains (id) || groupInfo (selectedChain) != nullptr) multiSelectedTracks.clear();
        else if (const auto* current = currentTrack(); current != nullptr && current->id != id) multiSelectedTracks.insert (current->id);
        selectedChain.clear(); selectTrack (t); return true;
    }
    void showHeaderMenu (const juce::String& id, bool arrangement)
    {
        if (! selectForHeaderMenu (id)) return;
        const bool join = juce::ModifierKeys::getCurrentModifiers().isCommandDown();
        auto colour = std::make_shared<int> (-1);
        headerMenu (id, arrangement, colour, join).showMenuAsync (juce::PopupMenu::Options(), [safe = juce::Component::SafePointer<Impl> (this), id, arrangement, colour, join] (int result)
        { if (safe != nullptr) safe->chooseHeaderItem (result, id, arrangement, *colour, join); });
    }
    // Where a right-click in the Arrangement's lanes landed: its track, the clip there (if any), the time,
    // and whether on a take lane.
    struct ArrangementPlace { int track = -1; juce::String clipId; double time = 0; bool takeLane = false; };
    enum ArrangementItem { arrangementComp = 400, arrangementCut, arrangementCopy, arrangementPaste, arrangementDuplicate, arrangementDelete,
                           arrangementZoom, arrangementZoomBack, arrangementRename, arrangementGroove, arrangementActivate, arrangementSplit,
                           arrangementConsolidate, arrangementConsolidateScene, arrangementExportMidi, arrangementInsertMidi, arrangementVideo,
                           arrangementReveal, arrangementSimilar, arrangementFade, arrangementResetFades, arrangementLoop, arrangementFreeze,
                           arrangementBounceInPlace, arrangementBounceNew, arrangementCrop, arrangementReverse, arrangementColour, arrangementInfo, arrangementShowInBrowser,
                           arrangementSlice = 450 }; // Plus Session::SliceBy.
    // A right-click's selection, as the reference prepares it (0x1037c6280): an unselected clip is
    // selected alone, with the time selection on its lane at its edges; a click inside the selection keeps
    // it; elsewhere the selection gives way to the insert marker at the click.
    void prepareArrangementMenu (const ArrangementPlace& place, double snappedTime)
    {
        if (! juce::isPositiveAndBelow (place.track, (int) state.tracks.size())) return;
        const auto& track = state.tracks[(size_t) place.track];
        const bool inside = timeSelection.active() && timeSelection.trackIds.contains (track.id) && place.time >= timeSelection.start && place.time <= timeSelection.end;
        selectTrack (place.track);
        if (place.clipId.isNotEmpty())
        {
            if (isClipSelected (place.clipId) || inside) return;
            for (int c = 0; c < (int) track.clips.size(); ++c)
                if (track.clips[(size_t) c].id == place.clipId)
                {
                    selectedClipIds.clear(); selectedClip = c;
                    timeSelection = { track.clips[(size_t) c].start, track.clips[(size_t) c].start + track.clips[(size_t) c].length, { track.id } };
                }
            return;
        }
        selectedClipIds.clear();
        if (inside) return;
        timeSelection = {}; selectedClip = -1;
        session.setInsertMarker (snappedTime);
    }
    // The clips the Arrangement's menu acts on: those the time selection reaches, or the selected clips.
    std::vector<const Session::ClipInfo*> menuClips() const
    {
        std::vector<const Session::ClipInfo*> clips;
        if (timeSelection.active())
        {
            for (const auto& track : state.tracks)
                if (timeSelection.trackIds.contains (track.id))
                    for (const auto& clip : track.clips)
                        if (clip.start < timeSelection.end - 1e-9 && clip.start + clip.length > timeSelection.start + 1e-9) clips.push_back (&clip);
        }
        else if (selectedClipIds.size() > 1)
        {
            for (const auto& id : selectedClipIds) if (const auto [t, c] = arrangementClipIndex (id); t >= 0) clips.push_back (&state.tracks[(size_t) t].clips[(size_t) c]);
        }
        else if (const auto* track = currentTrack(); track != nullptr && juce::isPositiveAndBelow (selectedClip, (int) track->clips.size()))
            clips.push_back (&track->clips[(size_t) selectedClip]);
        return clips;
    }
    // The tracks with selected content, which Freeze and the bounces act on: those of the menu's clips, or
    // the lanes selected.
    juce::StringArray menuTracks() const
    {
        juce::StringArray tracks;
        for (const auto* clip : menuClips()) if (const auto [t, c] = arrangementClipIndex (clip->id); t >= 0) tracks.addIfNotAlreadyThere (state.tracks[(size_t) t].id);
        if (tracks.isEmpty()) { if (timeSelection.active()) tracks = timeSelection.trackIds; else if (const auto* track = currentTrack()) tracks.add (track->id); }
        return tracks;
    }
    // The fade the time selection makes, as the reference's menu names it (0x10379a3e4, 0x10379b5fc): a fade
    // in where it holds the start of its audio clips but not their end, a fade out where it holds their end
    // but not their start, every track agreeing. The reference's crossfades are not made here yet.
    enum class SelectionFade { none, fadeIn, fadeOut };
    SelectionFade selectionFade() const
    {
        if (! timeSelection.active()) return SelectionFade::none;
        std::optional<SelectionFade> agreed;
        for (const auto* clip : menuClips())
        {
            if (! clip->isAudio) continue;
            const auto end = clip->start + clip->length;
            const bool holdsStart = clip->start >= timeSelection.start - 1e-6, holdsEnd = end <= timeSelection.end + 1e-6;
            const auto fade = holdsStart && ! holdsEnd ? SelectionFade::fadeIn : holdsEnd && ! holdsStart ? SelectionFade::fadeOut : SelectionFade::none;
            if (fade == SelectionFade::none || ! clip->canEditAudioFades || (agreed && *agreed != fade)) return SelectionFade::none;
            agreed = fade;
        }
        return agreed.value_or (SelectionFade::none);
    }
    // Create Fade In or Out: each audio clip's fade over the selection's part of it, in one undo step.
    void createSelectionFades()
    {
        const auto fade = selectionFade();
        if (fade == SelectionFade::none) return;
        const auto clips = menuClips();
        session.beginEditGesture (fade == SelectionFade::fadeIn ? "Create fade in" : "Create fade out");
        for (const auto* clip : clips)
        {
            if (! clip->isAudio) continue;
            auto settings = clip->audio;
            const auto other = [&] (bool defaultEdge, double seconds) { return defaultEdge ? 0.0 : seconds; };
            if (fade == SelectionFade::fadeIn)
            { settings.fadeInSeconds = juce::jmin (timeSelection.end - clip->start, clip->length - other (settings.defaultFadeOut, settings.fadeOutSeconds)); settings.defaultFadeIn = false; }
            else
            { settings.fadeOutSeconds = juce::jmin (clip->start + clip->length - timeSelection.start, clip->length - other (settings.defaultFadeIn, settings.fadeInSeconds)); settings.defaultFadeOut = false; }
            report (session.setAudioClipSettings (clip->id, settings));
        }
        session.endEditGesture(); refresh();
    }
    // Reset Fades: fades of the selection's audio clips go back to the default, as Delete returns a fade
    // handle to it (0x10379bd90 enables it while one has a fade of its own).
    bool canResetFades() const
    {
        const auto clips = menuClips();
        return std::any_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c)
        { return c->isAudio && c->canEditAudioFades && ((! c->audio.defaultFadeIn && c->audio.fadeInSeconds > 0) || (! c->audio.defaultFadeOut && c->audio.fadeOutSeconds > 0)); });
    }
    void resetSelectionFades()
    {
        const bool fallback = session.preferences().createFadesOnClipEdges;
        const auto clips = menuClips();
        session.beginEditGesture ("Reset fades");
        for (const auto* clip : clips)
        {
            if (! clip->isAudio || ! clip->canEditAudioFades) continue;
            auto settings = clip->audio;
            settings.defaultFadeIn = settings.defaultFadeOut = fallback;
            if (! fallback) settings.fadeInSeconds = settings.fadeOutSeconds = 0;
            if (! (settings == clip->audio)) report (session.setAudioClipSettings (clip->id, settings));
        }
        session.endEditGesture(); refresh();
    }
    // Whether the time selection's edges, or the insert marker without one, cut a clip on the selected lanes.
    bool canSplitSelection() const
    {
        const auto cuts = [] (const Session::ClipInfo& clip, double at) { return at > clip.start + 1e-6 && at < clip.start + clip.length - 1e-6; };
        if (timeSelection.active())
        {
            for (const auto& track : state.tracks)
                if (timeSelection.trackIds.contains (track.id))
                    for (const auto& clip : track.clips) if (cuts (clip, timeSelection.start) || cuts (clip, timeSelection.end)) return true;
            return false;
        }
        if (const auto* track = currentTrack()) for (const auto& clip : track->clips) if (cuts (clip, state.insertMarker)) return true;
        return false;
    }
    // The selected lanes on MIDI tracks with no clip in the time selection, for Insert MIDI Clip.
    juce::StringArray emptyMidiLanes() const
    {
        juce::StringArray lanes;
        if (! timeSelection.active()) return lanes;
        for (const auto& track : state.tracks)
            if (timeSelection.trackIds.contains (track.id))
            {
                if (! track.isMidi || track.isReturn) return {};
                for (const auto& clip : track.clips) if (clip.start < timeSelection.end && clip.start + clip.length > timeSelection.start) return {};
                lanes.add (track.id);
            }
        return lanes;
    }
    // The Arrangement's clip and time-selection menu, in the reference's order (LArrangerControlManager
    // 0x10379c6c8): commands that cannot act are left out, while Freeze, the bounces, the fades, Crop and
    // Reverse stay, greyed when they cannot. The colour grid colours the selected clips.
    juce::PopupMenu arrangementMenu (const ArrangementPlace& place, std::shared_ptr<int> colour) const
    {
        juce::PopupMenu menu;
        bool pending = false;
        const auto item = [&] (int result, const juce::String& text, bool enabled = true, bool ticked = false)
        { if (pending) menu.addSeparator(); pending = false; menu.addItem (result, text, enabled, ticked); };
        const auto separator = [&pending] { pending = true; };
        const auto clips = menuClips();
        const bool selection = timeSelection.active() && ! state.recording, content = selection ? ! clips.empty() : clips.size() > 1;
        const bool group = ! timeSelection.active() && selectedClipIds.size() > 1;
        const auto* clicked = [&]() -> const Session::ClipInfo* { const auto [t, c] = arrangementClipIndex (place.clipId); return t >= 0 ? &state.tracks[(size_t) t].clips[(size_t) c] : nullptr; }();
        const auto* single = clips.size() == 1 ? clips.front() : nullptr;
        const auto* track = juce::isPositiveAndBelow (place.track, (int) state.tracks.size()) ? &state.tracks[(size_t) place.track] : nullptr;
        if (place.takeLane) { item (arrangementComp, "Copy to Main Lane", takeSelection.active()); separator(); }
        else
        {
            if (content || group) { item (arrangementCut, "Cut"); item (arrangementCopy, "Copy"); }
            if (track != nullptr && ! track->isReturn && (session.hasRangeClipboard() || (track->isMidi ? session.hasMidiClipClipboard() : session.hasAudioClipClipboard())))
                item (arrangementPaste, "Paste");
            if (content || group) { item (arrangementDuplicate, "Duplicate"); item (arrangementDelete, "Delete"); }
        }
        separator();
        if (selection) item (arrangementZoom, "Zoom to Arrangement Time Selection");
        if (zoomBack) item (arrangementZoomBack, "Zoom Back from Arrangement Time Selection");
        separator();
        if (! place.takeLane)
        {
            if (clicked != nullptr || single != nullptr) item (arrangementRename, "Rename");
            if (single != nullptr) item (arrangementInfo, "Edit Info Text");
            // Grooves come from MIDI clips and warped audio, as the reference's Extract Grooves takes them.
            if (! clips.empty() && std::all_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return c->isMidi || (c->isAudio && c->warp.mode != Session::WarpMode::off); }))
                item (arrangementGroove, clips.size() > 1 ? "Extract Grooves" : "Extract Groove");
            if (! clips.empty())
            {
                const bool allOff = std::all_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return ! c->active; });
                item (arrangementActivate, juce::String (allOff ? "Activate Clip" : "Deactivate Clip") + (clips.size() > 1 ? "s" : ""));
            }
            if (canSplitSelection()) item (arrangementSplit, "Split");
            if (selection && ! clips.empty()) item (arrangementConsolidate, "Consolidate");
            if (selection && state.scenes.size() < 256) item (arrangementConsolidateScene, "Consolidate Time to New Scene");
            if (single != nullptr && single->isMidi) item (arrangementExportMidi, "Export MIDI Clip...");
            if (const auto lanes = emptyMidiLanes(); ! lanes.isEmpty()) item (arrangementInsertMidi, lanes.size() > 1 ? "Insert MIDI Clips" : "Insert MIDI Clip");
           #if JUCE_MAC
            if (clicked != nullptr && clicked->videoFile != juce::File()) item (arrangementVideo, "Video Window", video::supported(), videoWindow != nullptr && videoWindow->isVisible());
           #endif
            // The sample's file.
            if (single != nullptr && single->isAudio && single->file.existsAsFile())
            {
                separator(); item (arrangementShowInBrowser, "Show in Browser"); item (arrangementReveal, "Reveal in Finder");
                item (arrangementSimilar, "Show Similar Files", browserFolder != juce::File());
            }
            separator();
            // The fades, for audio tracks that are not frozen.
            const auto tracks = selection ? timeSelection.trackIds : menuTracks();
            if (std::any_of (tracks.begin(), tracks.end(), [this] (const juce::String& id) { const auto* t = trackInfo (id); return t != nullptr && ! t->isMidi && ! t->isReturn && ! t->frozen; }))
            {
                const auto fade = selectionFade();
                item (arrangementFade, fade == SelectionFade::fadeIn ? "Create Fade In" : fade == SelectionFade::fadeOut ? "Create Fade Out" : "Create Fade", fade != SelectionFade::none);
                item (arrangementResetFades, "Reset Fades", canResetFades());
            }
        }
        // The loop brace: to the selection, or switched on or off.
        const bool onLoop = selection && std::abs (timeSelection.start - state.loopStart) < 1e-6 && std::abs (timeSelection.end - state.loopEnd) < 1e-6;
        item (arrangementLoop, selection && ! onLoop ? "Loop Selection" : state.looping ? "Deactivate Loop" : "Activate Loop");
        if (! place.takeLane)
        {
            separator();
            const auto tracks = menuTracks();
            const auto freezable = freezableTracks (tracks);
            const bool allFrozen = ! freezable.isEmpty() && std::all_of (freezable.begin(), freezable.end(), [this] (const juce::String& t) { return trackInfo (t)->frozen; });
            const auto plural = [&] (const juce::String& one, const juce::String& many) { return tracks.size() > 1 ? many : one; };
            item (arrangementFreeze, juce::String (allFrozen ? "Unfreeze " : "Freeze ") + (freezable.size() > 1 ? "Tracks" : "Track"), ! freezable.isEmpty());
            item (arrangementBounceInPlace, plural ("Bounce Track in Place", "Bounce Tracks in Place"), session.canBounceTracksInPlace (tracks));
            const bool bounceable = selection && session.canBounceToNewTracks (timeSelection.trackIds, timeSelection.start, timeSelection.end);
            item (arrangementBounceNew, plural ("Bounce to New Track", "Bounce to New Tracks"), bounceable);
            if (clicked != nullptr)
            {
                separator();
                item (arrangementCrop, clips.size() > 1 ? "Crop Clips" : "Crop Clip", selection && session.canCropRange (timeSelection.trackIds, timeSelection.start, timeSelection.end));
                item (arrangementReverse, "Reverse Clip", selection && std::any_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return c->isMidi || c->canReverse; }));
            }
            // Slice to New MIDI Track, for one audio clip, by transients, warp markers or a division of its beats.
            if (single != nullptr && single->isAudio)
            {
                const bool warped = single->warp.mode != Session::WarpMode::off, markers = warped && single->warpMarkers.size() >= 2;
                if (single->canEditAudioRange || warped)
                {
                    juce::PopupMenu slices;
                    slices.addItem (arrangementSlice + (int) Session::SliceBy::transients, "Transients", ! markers);
                    slices.addItem (arrangementSlice + (int) Session::SliceBy::warpMarkers, "Warp Markers", markers);
                    const std::pair<Session::SliceBy, const char*> divisions[] { { Session::SliceBy::sixteenth, "1/16" }, { Session::SliceBy::eighth, "1/8" }, { Session::SliceBy::quarter, "1/4" },
                                                                                  { Session::SliceBy::half, "1/2" }, { Session::SliceBy::bar, "1 Bar" } };
                    for (const auto& [by, text] : divisions) slices.addItem (arrangementSlice + (int) by, text, ! markers);
                    pending = false;
                    menu.addSeparator(); menu.addSubMenu ("Slice to New MIDI Track", slices);
                }
            }
        }
        if (clicked == nullptr) { if (menu.getNumItems() > 0) menu.addSeparator(); pending = false; addGridItems (menu); }
        else
        {
            std::vector<juce::Colour> used;
            for (const auto* clip : clips) used.push_back (clip->colour);
            menu.addSeparator();
            menu.addCustomItem (arrangementColour, std::make_unique<ColourGrid> (used, colour), nullptr, "Clip Colours");
        }
        return menu;
    }
    void chooseArrangementItem (int result, const ArrangementPlace& place, int colour)
    {
        if (gridItem (result)) return;
        const auto clips = menuClips();
        const bool group = ! timeSelection.active() && selectedClipIds.size() > 1;
        const auto* single = clips.size() == 1 ? clips.front() : nullptr;
        const auto clipIds = [&] { juce::StringArray ids; for (const auto* c : clips) ids.add (c->id); return ids; }();
        const auto [start, end] = std::pair { timeSelection.start, timeSelection.end };
        if (result >= arrangementSlice && result <= arrangementSlice + (int) Session::SliceBy::bar)
        { if (single != nullptr) sliceClip (single->id, static_cast<Session::SliceBy> (result - arrangementSlice)); return; }
        switch (result)
        {
            case arrangementComp: compSelectedTake(); break;
            case arrangementCut: if (group) clipGroupCommand ('X'); else selectionCommand (82); break;
            case arrangementCopy: if (group) clipGroupCommand ('C'); else selectionCommand (81); break;
            case arrangementPaste:
                if (session.hasRangeClipboard()) selectionCommand (83);
                else if (const auto* track = currentTrack()) { if (track->isMidi) pasteMidi (track->id, state.insertMarker); else pasteAudio (track->id, state.insertMarker); }
                break;
            case arrangementDuplicate: if (group) clipGroupCommand ('D'); else selectionCommand (77); break;
            case arrangementDelete: if (group) deleteSelectedClip(); else { selectionCommand (78); timeSelection = {}; } break;
            case arrangementZoom: zoomToSelection(); break;
            case arrangementZoomBack: zoomBackFromSelection(); break;
            case arrangementRename: renameClipDialog (place.clipId.isNotEmpty() ? place.clipId : single != nullptr ? single->id : juce::String()); return;
            case arrangementInfo: if (single != nullptr) editInfoTextDialog (single->id); return;
            case arrangementGroove: for (const auto* clip : clips) extractGrooveFromUI (clip->id); break;
            case arrangementActivate:
            {
                const bool activate = std::all_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return ! c->active; });
                session.beginEditGesture (activate ? "Activate clips" : "Deactivate clips");
                for (const auto& id : clipIds) report (session.setClipActive (id, activate));
                session.endEditGesture(); break;
            }
            case arrangementSplit:
                if (timeSelection.active()) selectionCommand (76);
                else if (const auto* track = currentTrack())
                    for (const auto& clip : track->clips)
                        if (state.insertMarker > clip.start + 1e-6 && state.insertMarker < clip.start + clip.length - 1e-6)
                        {
                            juce::String right;
                            report (clip.isMidi ? session.splitMidiClip (clip.id, state.insertMarker, right) : session.splitAudioClip (clip.id, state.insertMarker, right));
                            break;
                        }
                break;
            case arrangementConsolidate: selectionCommand (80); break;
            case arrangementConsolidateScene: menuItemSelected (88, 0); return;
            case arrangementExportMidi: if (single != nullptr) { selectArrangementClip (single->id); exportMidiDialog(); } return;
            case arrangementInsertMidi:
            {
                const auto lanes = emptyMidiLanes();
                session.beginEditGesture (lanes.size() > 1 ? "Insert MIDI clips" : "Insert MIDI clip");
                for (const auto& id : lanes) report (session.addMidiClip (id, beatsAt (start), beatsAt (end) - beatsAt (start)));
                session.endEditGesture(); break;
            }
            case arrangementVideo: toggleVideoWindow(); break;
            case arrangementShowInBrowser: if (single != nullptr) showInBrowser (single->file); return;
            case arrangementReveal: if (single != nullptr) single->file.revealToUser(); return;
            case arrangementSimilar: if (single != nullptr) showSimilarFiles (single->file); return;
            case arrangementFade: createSelectionFades(); return;
            case arrangementResetFades: resetSelectionFades(); return;
            case arrangementLoop:
                if (timeSelection.active() && ! (std::abs (start - state.loopStart) < 1e-6 && std::abs (end - state.loopEnd) < 1e-6)) selectionCommand (79);
                else session.setLoop (! state.looping, state.loopStart, state.loopEnd);
                break;
            case arrangementFreeze: freezeTracksFromUI (freezableTracks (menuTracks())); return;
            case arrangementBounceInPlace: report (session.bounceTracksInPlace (menuTracks())); break;
            case arrangementBounceNew:
            {
                juce::StringArray made;
                const auto bounced = session.bounceToNewTracks (timeSelection.trackIds, start, end, made);
                report (bounced, made.size() > 1 ? "Bounced the selection to new tracks." : "Bounced the selection to a new track.");
                break;
            }
            case arrangementCrop: report (session.cropRange (timeSelection.trackIds, start, end)); break;
            case arrangementReverse: report (session.reverseRange (timeSelection.trackIds, start, end)); break;
            case arrangementColour:
                if (colour >= 0) report (session.setClipColours (group ? selectedClipIds : clipIds, paletteColour (colour)));
                break;
            default: return;
        }
        refresh();
    }
    // The Session slots a slot menu acts on: the selected slots, or the selected one.
    std::vector<Session::SlotRef> menuSlots() const
    {
        if (selectedSlots.size() > 1) return selectedSlots;
        if (const auto scene = selectedSceneIndex(); scene >= 0 && juce::isPositiveAndBelow (selectedTrack, (int) state.tracks.size())) return { { selectedTrack, scene } };
        return {};
    }
    std::vector<const Session::ClipInfo*> menuSlotClips() const
    {
        std::vector<const Session::ClipInfo*> clips;
        for (const auto& ref : menuSlots())
            if (juce::isPositiveAndBelow (ref.track, (int) state.tracks.size()) && juce::isPositiveAndBelow (ref.scene, (int) state.tracks[(size_t) ref.track].slots.size()))
                if (const auto& slot = state.tracks[(size_t) ref.track].slots[(size_t) ref.scene]; slot.hasClip) clips.push_back (&slot.clip);
        return clips;
    }
    // The selected empty slots, when all are on MIDI tracks, for Insert MIDI Clip.
    std::vector<Session::SlotRef> emptyMidiSlots() const
    {
        std::vector<Session::SlotRef> slots;
        for (const auto& ref : menuSlots())
        {
            if (! juce::isPositiveAndBelow (ref.track, (int) state.tracks.size())) return {};
            const auto& track = state.tracks[(size_t) ref.track];
            if (! juce::isPositiveAndBelow (ref.scene, (int) track.slots.size()) || track.slots[(size_t) ref.scene].hasClip) continue;
            if (! track.isMidi || track.isReturn) return {};
            slots.push_back (ref);
        }
        return slots;
    }
    enum SlotItem { slotCut = 500, slotCopy, slotPaste, slotDuplicate, slotDelete, slotClearEnvelopes, slotRename, slotGroove, slotActivate, slotExportMidi,
                    slotReveal, slotSimilar, slotFreeze, slotBounceInPlace, slotBounceNew, slotInsertMidi, slotColour, slotInfo, slotStopButton, slotCrop, slotShowInBrowser };
    // A Session slot's menu, in the reference's order (LSlotManager 0x103a38ce4): commands that cannot act
    // are left out, while Freeze and the bounces stay, greyed when they cannot act.
    juce::PopupMenu slotContextMenu (std::shared_ptr<int> colour) const
    {
        juce::PopupMenu menu;
        bool pending = false;
        const auto item = [&] (int result, const juce::String& text, bool enabled = true, bool ticked = false)
        { if (pending) menu.addSeparator(); pending = false; menu.addItem (result, text, enabled, ticked); };
        const auto separator = [&pending] { pending = true; };
        const auto clips = menuSlotClips();
        const bool hasClip = ! clips.empty();
        const auto* single = clips.size() == 1 && menuSlots().size() == 1 ? clips.front() : nullptr;
        if (hasClip) { item (slotCut, "Cut"); item (slotCopy, "Copy"); }
        if (selectedSlot() != nullptr && session.hasSlotClipboard() && ! state.recording) item (slotPaste, "Paste");
        if (hasClip) { item (slotDuplicate, "Duplicate"); item (slotDelete, "Delete"); }
        if (std::any_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return ! c->envelopes.empty(); })) item (slotClearEnvelopes, "Clear All Envelopes");
        separator();
        if (single != nullptr) { item (slotRename, "Rename"); item (slotInfo, "Edit Info Text"); }
        if (hasClip && std::all_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return c->isMidi || (c->isAudio && c->warp.mode != Session::WarpMode::off); }))
            item (slotGroove, clips.size() > 1 ? "Extract Grooves" : "Extract Groove");
        if (hasClip)
        {
            const bool allOff = std::all_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return ! c->active; });
            item (slotActivate, juce::String (allOff ? "Activate Clip" : "Deactivate Clip") + (clips.size() > 1 ? "s" : ""));
        }
        if (single != nullptr && single->isMidi) item (slotExportMidi, "Export MIDI Clip...");
        if (single != nullptr && single->isAudio && single->file.existsAsFile())
        { separator(); item (slotShowInBrowser, "Show in Browser"); item (slotReveal, "Reveal in Finder"); item (slotSimilar, "Show Similar Files", browserFolder != juce::File()); }
        if (hasClip)
        {
            separator();
            juce::StringArray tracks, clipIds;
            for (const auto& ref : menuSlots()) tracks.addIfNotAlreadyThere (state.tracks[(size_t) ref.track].id);
            for (const auto* c : clips) clipIds.add (c->id);
            const auto freezable = freezableTracks (tracks);
            const bool allFrozen = ! freezable.isEmpty() && std::all_of (freezable.begin(), freezable.end(), [this] (const juce::String& t) { return trackInfo (t)->frozen; });
            item (slotFreeze, juce::String (allFrozen ? "Unfreeze " : "Freeze ") + (freezable.size() > 1 ? "Tracks" : "Track"), ! freezable.isEmpty());
            item (slotBounceInPlace, tracks.size() > 1 ? "Bounce Tracks in Place" : "Bounce Track in Place", session.canBounceTracksInPlace (tracks));
            item (slotBounceNew, tracks.size() > 1 ? "Bounce to New Tracks" : "Bounce to New Track", session.canBounceSlotsToNewTracks (clipIds));
        }
        // Crop Clip, always there and greyed on an empty slot, as the reference adds it.
        {
            juce::StringArray clipIds; for (const auto* c : clips) clipIds.add (c->id);
            separator(); item (slotCrop, clips.size() > 1 ? "Crop Clips" : "Crop Clip", session.canCropSessionClips (clipIds));
        }
        separator();
        // Add or Remove Stop Button: Remove while any selected slot has one (0x103a3ce34).
        if (const auto slots = menuSlots(); ! slots.empty())
            item (slotStopButton, std::any_of (slots.begin(), slots.end(), [this] (const Session::SlotRef& r) { return state.tracks[(size_t) r.track].slots[(size_t) r.scene].stopButton; })
                                      ? "Remove Stop Button" : "Add Stop Button");
        if (const auto empty = emptyMidiSlots(); ! empty.empty()) item (slotInsertMidi, empty.size() > 1 ? "Insert MIDI Clips" : "Insert MIDI Clip");
        if (hasClip)
        {
            std::vector<juce::Colour> used;
            for (const auto* c : clips) used.push_back (c->colour);
            menu.addSeparator();
            menu.addCustomItem (slotColour, std::make_unique<ColourGrid> (used, colour), nullptr, "Clip Colours");
        }
        return menu;
    }
    void chooseSlotItem (int result, int colour)
    {
        const auto clips = menuSlotClips();
        const auto* single = clips.size() == 1 ? clips.front() : nullptr;
        juce::StringArray clipIds; for (const auto* c : clips) clipIds.add (c->id);
        juce::StringArray tracks; for (const auto& ref : menuSlots()) tracks.addIfNotAlreadyThere (state.tracks[(size_t) ref.track].id);
        switch (result)
        {
            case slotCut: slotCommand (84); return;
            case slotCopy: slotCommand (85); return;
            case slotPaste: slotCommand (86); return;
            case slotDuplicate: slotCommand (87); return;
            case slotDelete: clearSelectedSlot(); return;
            case slotClearEnvelopes:
                session.beginEditGesture ("Clear all envelopes");
                for (const auto* c : clips) for (auto envelope : c->envelopes) { envelope.points.clear(); report (session.setClipEnvelope (c->id, envelope)); }
                session.endEditGesture(); break;
            case slotRename: if (single != nullptr) renameClipDialog (single->id); return;
            case slotInfo: if (single != nullptr) editInfoTextDialog (single->id); return;
            case slotGroove: for (const auto& id : clipIds) extractGrooveFromUI (id); break;
            case slotActivate:
            {
                const bool activate = std::all_of (clips.begin(), clips.end(), [] (const Session::ClipInfo* c) { return ! c->active; });
                session.beginEditGesture (activate ? "Activate clips" : "Deactivate clips");
                for (const auto& id : clipIds) report (session.setClipActive (id, activate));
                session.endEditGesture(); break;
            }
            case slotExportMidi: exportMidiDialog(); return;
            case slotShowInBrowser: if (single != nullptr) showInBrowser (single->file); return;
            case slotReveal: if (single != nullptr) single->file.revealToUser(); return;
            case slotSimilar: if (single != nullptr) showSimilarFiles (single->file); return;
            case slotFreeze: freezeTracksFromUI (freezableTracks (tracks)); return;
            case slotBounceInPlace: report (session.bounceTracksInPlace (tracks)); break;
            case slotBounceNew:
            {
                juce::StringArray made;
                report (session.bounceSlotsToNewTracks (clipIds, made), made.size() > 1 ? "Bounced the clips to new tracks." : "Bounced the clip to a new track.");
                break;
            }
            case slotInsertMidi:
            {
                const auto empty = emptyMidiSlots();
                session.beginEditGesture (empty.size() > 1 ? "Insert MIDI clips" : "Insert MIDI clip");
                for (const auto& ref : empty) report (session.addMidiClipToSlot (state.tracks[(size_t) ref.track].id, ref.scene, 4.0));
                session.endEditGesture(); break;
            }
            case slotColour: if (colour >= 0) report (session.setClipColours (clipIds, paletteColour (colour))); break;
            case slotCrop: report (session.cropSessionClips (clipIds)); break;
            case slotStopButton:
            {
                const auto slots = menuSlots();
                const bool any = std::any_of (slots.begin(), slots.end(), [this] (const Session::SlotRef& r) { return state.tracks[(size_t) r.track].slots[(size_t) r.scene].stopButton; });
                report (session.setSlotStopButtons (slots, ! any)); break;
            }
            default: return;
        }
        refresh();
    }
    void showSlotMenu()
    {
        auto colour = std::make_shared<int> (-1);
        auto menu = slotContextMenu (colour);
        if (menu.getNumItems() == 0) return;
        menu.showMenuAsync (juce::PopupMenu::Options(), [safe = juce::Component::SafePointer<Impl> (this), colour] (int result)
        { if (safe != nullptr && result != 0) safe->chooseSlotItem (result, *colour); });
    }
    // Insert Scene, after the reference's: a new scene below the selected one, selected.
    void insertSceneFromUI()
    {
        const auto at = selectedSceneIndex();
        session.beginEditGesture ("Insert scene");
        auto result = session.addScene();
        if (result.wasOk()) { refresh(); if (at >= 0 && at + 1 < (int) state.scenes.size() - 1) result = session.moveScene (state.scenes.back().id, at + 1); }
        session.endEditGesture();
        report (result); refresh();
        if (result.wasOk()) selectedSceneId = at >= 0 && at + 1 < (int) state.scenes.size() ? state.scenes[(size_t) at + 1].id : state.scenes.back().id;
        launcher.scrollSelectionIntoView();
    }
